// 当前主题：0 暗 1 浅。ico() 要按它选图，所以声明放在这里而不是调色板之后。
// g_themeMode：0 跟随系统 / 1 浅色 / 2 深色，g_theme 是由它算出来的实际值。
static int g_theme = 0;
static int g_themeMode = 0;
// 具体配色方案（在「深色 / 浅色」基础上再分几套皮肤）；真假见 g_themes
static int g_themeStyle = 0;
// 与 g_themes 同序：1＝这套是暗色。theme_refresh() 在调色板定义之前，
// 又要判断风格和明暗是否匹配，所以单独放一份最小表。
static const int THEME_DARK[6] = { 1, 0, 1, 1, 0, 1 };
// 当前皮肤到底是不是暗底（图标按它选提亮版，比 g_theme 更贴近实际配色）
static int g_uiDark = 1;
static const wchar_t* THEME_MODE_NAMES[3] = { L"跟随系统", L"浅色", L"深色" };
// 设置页里也要用（跟随系统的说明文字），保留这个名字表供状态/提示复用
static void theme_refresh()
{
    if (g_themeMode == 0) {
        DWORD v = (DWORD)(g_theme ? 1 : 0), sz = sizeof(v);
        HKEY hk = NULL;
        if (RegOpenKeyExW(HKEY_CURRENT_USER,
                L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize",
                0, KEY_QUERY_VALUE, &hk) == ERROR_SUCCESS) {
            RegQueryValueExW(hk, L"AppsUseLightTheme", NULL, NULL, (LPBYTE)&v, &sz);
            RegCloseKey(hk);
        }
        g_theme = v ? 1 : 0;
        g_themeStyle = g_theme ? 1 : 0;          // 跟随系统只用默认深/浅
    } else {
        g_theme = (g_themeMode == 1) ? 1 : 0;
        if (g_themeStyle < 0 || g_themeStyle >= 6) g_themeStyle = g_theme ? 1 : 0;
        if ((g_theme == 0) != (THEME_DARK[g_themeStyle] != 0))
            g_themeStyle = g_theme ? 1 : 0;      // 明暗对不上就退回默认那套
    }
}

