// 图标库（assets/icons）拿到的是「浅色主题」那套 PNG：字形一律 #202020 深灰，
// 靠 alpha 做抗锯齿。直接画在暗色工具条（#262626）或面板（#1E1E1E）上，
// 两边的亮度只差 6 级，看起来就是「一坨黑的看不清」。
// 所以加载时按主题各备一份：暗色那份把近中性的深色像素提亮成浅墨色，
// alpha 与原有的浓淡层次都不动；彩色图标（新建的绿、保存的蓝、停止的红）
// 在暗底上本来够亮，保持原样，免得被提成怪色。
static Bitmap* icon_lift(Bitmap* src)
{
    if (!src) return NULL;
    int w = (int)src->GetWidth(), h = (int)src->GetHeight();
    if (w <= 0 || h <= 0) return NULL;
    Bitmap* dst = new Bitmap(w, h, PixelFormat32bppARGB);
    if (dst->GetLastStatus() != Ok) { delete dst; return NULL; }
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            Color c(0, 0, 0, 0);
            src->GetPixel(x, y, &c);
            int r = c.GetR(), g = c.GetG(), b = c.GetB();
            int mx = std::max(r, std::max(g, b));
            int mn = std::min(r, std::min(g, b));
            if (mx - mn <= 28) {                     // 近似中性＝单色字形
                int lum = (r * 299 + g * 587 + b * 114) / 1000;
                int v = 150 + lum * 2;               // #202020 → #D6D6D6
                if (v > 236) v = 236;
                c = Color::MakeARGB(c.GetA(), v, v, v);
            }
            dst->SetPixel(x, y, c);
        }
    }
    return dst;
}

static void icons_load()
{
    for (int i = 0; i < ICON_MAP_N; ++i) {
        std::wstring p = g_iconDir;
        for (const char* c = ICON_MAP[i].file; *c; ++c) p += (wchar_t)*c;
        p += L".png";
        Bitmap* b = new Bitmap(p.c_str());
        if (b->GetLastStatus() == Ok) {
            g_icons[ICON_MAP[i].logical] = b;
            Bitmap* d = icon_lift(b);
            if (d) g_iconsDark[ICON_MAP[i].logical] = d;
        } else {
            delete b;
        }
    }
    // EPP logo 原图：金属质感不能被 icon_lift 重上色，单独存一份原样画
    {
        Bitmap* lb = new Bitmap((g_iconDir + L"epp_logo.png").c_str());
        if (lb->GetLastStatus() == Ok) g_logoBmp = lb;
        else delete lb;
    }
}

// 按当前实际底色取图：暗底用提亮版，浅底用原图。
// 以前判 g_theme，自定义皮肤/跟随系统一错位，深色底上就会画出深灰图标（等于隐形）。
static Bitmap* icon_pick(const char* key)
{
    if (g_uiDark) {
        std::map<std::string, Bitmap*>::iterator d = g_iconsDark.find(key);
        if (d != g_iconsDark.end()) return d->second;
    }
    std::map<std::string, Bitmap*>::iterator it = g_icons.find(key);
    return it == g_icons.end() ? NULL : it->second;
}

static void ico(HDC dc, const char* key, RECT r, bool enabled = true)
{
    Bitmap* bmp = icon_pick(key);
    if (!bmp || r.right <= r.left) {
        fillR(dc, r, 2, RGB(0x4C, 0x50, 0x58));
        return;
    }
    Graphics g(dc);
    g.SetInterpolationMode(InterpolationModeHighQualityBicubic);
    g.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    if (enabled) {
        g.DrawImage(bmp, Rect(r.left, r.top, r.right - r.left, r.bottom - r.top));
    } else {
        Gdiplus::ImageAttributes attr;
        Gdiplus::ColorMatrix cm;
        memset(&cm, 0, sizeof(cm));
        cm.m[0][0] = 0.3f;  cm.m[0][1] = 0.3f;  cm.m[0][2] = 0.3f;
        cm.m[1][0] = 0.59f; cm.m[1][1] = 0.59f; cm.m[1][2] = 0.59f;
        cm.m[2][0] = 0.11f; cm.m[2][1] = 0.11f; cm.m[2][2] = 0.11f;
        cm.m[3][3] = 0.4f;
        cm.m[4][4] = 1.0f;
        attr.SetColorMatrix(&cm);
        g.DrawImage(bmp, Rect(r.left, r.top, r.right - r.left, r.bottom - r.top),
                    0, 0, bmp->GetWidth(), bmp->GetHeight(), Gdiplus::UnitPixel, &attr);
    }
}

// 浅色窗体（设计器里的 #F0F0F0 窗体面）上必须用原图那份深灰字形，
// 暗色主题的提亮版（#D6D6D6）贴在白底上等于隐形。
static void ico_raw(HDC dc, const char* key, RECT r)
{
    std::map<std::string, Bitmap*>::iterator it = g_icons.find(key);
    if (it == g_icons.end() || !it->second || r.right <= r.left) {
        fillR(dc, r, 2, RGB(0x9A, 0x9A, 0xA2));
        return;
    }
    Graphics g(dc);
    g.SetInterpolationMode(InterpolationModeHighQualityBicubic);
    g.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    g.DrawImage(it->second, Rect(r.left, r.top, r.right - r.left, r.bottom - r.top));
}
// ══════════════════════════════════════════════════════════════════
// 主题令牌（§7.1 暗色 / §7.2 浅色）
// ══════════════════════════════════════════════════════════════════

struct Pal {
    COLORREF window, panel, elevated, canvas, border, borderSoft;
    COLORREF accent, accentSubtle;
    COLORREF text, textDim, textFaint;
    COLORREF ok, warn, error;
    COLORREF formSurface, formCaption;
    COLORREF popup, hover, input, bar;
    COLORREF frame, inner;
    // 面板之间的分隔线：比 border 亮一档，1px 也看得出边界（border 是卡片描边）
    COLORREF split;
    // 设计器辅助线：准心线（跟随鼠标的十字）与对齐吸附线（拖动时和别组件的对齐位置）。
    // 两条必须不同色，否则分不清“我现在指在哪”和“我即将和谁对齐”。
    COLORREF guideLine, snapLine;
};

// 令牌来源：tools/ref/vs2026-dark.png（官方 2496x1664 截图）用
// tools/measure-ref.ps1 逐像素统计出来的众数颜色，不是照文档猜的。
//   #1e1e1e 461289px  编辑区/画布底
//   #282828 211036px  工具窗口卡片
//   #1f1f1f  98078px  卡片内深一层
//   #1c1c1c  61105px  标题行 / 层间缝隙
//   #262626  32122px  工具条 / 页签条
//   #141414  21463px  窗口外框
//   #2b2b2b  15209px  悬停
//   #3a3a3a            卡片 1px 描边
//   #9184ee   3353px  accent（该截图是紫色系主题）
//   #e6e6e6 / #a0a0a0 / #8a8a8a  三级文字
static Pal pal_dark()
{
    Pal p;
    p.window       = RGB(0x1C, 0x1C, 0x1C);
    p.panel        = RGB(0x28, 0x28, 0x28);
    p.elevated     = RGB(0x2B, 0x2B, 0x2B);
    p.canvas       = RGB(0x1E, 0x1E, 0x1E);
    p.border       = RGB(0x3A, 0x3A, 0x3A);
    p.borderSoft   = RGB(0x33, 0x33, 0x33);
    p.accent       = RGB(0x91, 0x84, 0xEE);
    p.accentSubtle = RGB(0x3A, 0x32, 0x66);
    p.text         = RGB(0xE6, 0xE6, 0xE6);
    p.textDim      = RGB(0xA0, 0xA0, 0xA0);
    p.textFaint    = RGB(0x8A, 0x8A, 0x8A);
    p.ok           = RGB(0x57, 0xA6, 0x4A);
    p.warn         = RGB(0xD7, 0xBA, 0x7D);
    p.error        = RGB(0xF4, 0x87, 0x71);
    p.formSurface  = RGB(0xF0, 0xF0, 0xF0);
    p.formCaption  = RGB(0x3B, 0x3B, 0x3B);
    p.popup        = RGB(0x25, 0x25, 0x26);
    p.hover        = RGB(0x2B, 0x2B, 0x2B);
    p.input        = RGB(0x1B, 0x1B, 0x1B);
    p.bar          = RGB(0x26, 0x26, 0x26);
    p.frame        = RGB(0x1C, 0x1C, 0x1C);
    p.inner        = RGB(0x1E, 0x1E, 0x1E);
    // 分隔线：暗色里 #3a3a3a 贴到 #1e1e1e 面板上几乎糊成一片，往上提到 #4a4a4a
    p.split        = RGB(0x4A, 0x4A, 0x4C);
    p.guideLine    = RGB(0x6E, 0x74, 0x84);   // 准心线：比 accent 暗，不抢选中框
    p.snapLine     = RGB(0xFF, 0x5C, 0x8A);   // 对齐吸附线：洋红，和别的东西不撞色
    return p;
}
// 浅色主题同样取自 tools/ref/vs2026-light.png 的众数：
//   #ffffff 475774px / #f9f9f9 210090px / #f5f5f5 112899px / #eeeeee 61163px
//   accent #5649b0 3353px
static Pal pal_light()
{
    Pal p;
    // 浅色最容易「一片白」：面板 / 卡片 / 画布 / 窗体全挤在 245~255 灰阶。
    // 这里按 VS 浅色的思路拉开层次（冷灰）：窗口底 → 工具条 → 面板 → 画布 → 白卡片，
    // 同时把描边、分隔线、悬停底色加深一档，让边界看得出来。
    p.window       = RGB(0xE8, 0xEA, 0xED);
    p.panel        = RGB(0xF4, 0xF5, 0xF7);
    p.elevated     = RGB(0xFF, 0xFF, 0xFF);   // 卡片/菜单浮起来
    p.canvas       = RGB(0xE3, 0xE6, 0xEC);   // 比面板再深一档，白色窗体才浮得起来
    p.border       = RGB(0xC7, 0xCB, 0xD3);
    p.borderSoft   = RGB(0xDD, 0xE0, 0xE6);
    p.accent       = RGB(0x56, 0x49, 0xB0);
    p.accentSubtle = RGB(0xDC, 0xD5, 0xF2);   // 选中项比面板明显
    p.text         = RGB(0x1D, 0x1D, 0x22);
    p.textDim      = RGB(0x60, 0x63, 0x6B);
    p.textFaint    = RGB(0x84, 0x88, 0x90);
    p.ok           = RGB(0x1A, 0x7F, 0x37);
    p.warn         = RGB(0x9A, 0x67, 0x00);
    p.error        = RGB(0xCF, 0x22, 0x2E);
    p.formSurface  = RGB(0xFF, 0xFF, 0xFF);   // 白色窗体浮在灰画布上
    p.formCaption  = RGB(0xDD, 0xE2, 0xEC);
    p.popup        = RGB(0xFF, 0xFF, 0xFF);
    p.hover        = RGB(0xE5, 0xE8, 0xEE);   // 悬停反馈更明显
    p.input        = RGB(0xFF, 0xFF, 0xFF);
    p.bar          = RGB(0xE4, 0xE6, 0xEB);   // 工具条/页签条比面板深
    p.frame        = RGB(0xE8, 0xEA, 0xED);
    p.inner        = RGB(0xEF, 0xF1, 0xF4);
    p.split        = RGB(0xB4, 0xB9, 0xC3);   // 主分隔线清晰但不刺眼
    p.guideLine    = RGB(0x8A, 0x8F, 0x9A);   // 浅色下比画布深两档，1px 也看得见
    p.snapLine     = RGB(0xD8, 0x2B, 0x7A);
    return p;
}

