static const int THEME_N = 6;

static Pal pal_current()
{
    int i = (g_themeStyle >= 0 && g_themeStyle < THEME_N) ? g_themeStyle : 0;
    const ThemeDef& t = g_themes[i];
    g_uiDark = t.dark ? 1 : 0;
    Pal p = t.dark ? pal_dark() : pal_light();
    if (!t.custom) return p;
    p.window = t.window;   p.frame  = t.frame;
    p.panel  = t.panel;    p.elevated = t.elevated;
    p.canvas = t.canvas;   p.inner  = t.inner;
    p.bar    = t.bar;
    p.border = t.border;   p.borderSoft = t.borderSoft; p.split = t.split;
    p.accent = t.accent;   p.accentSubtle = t.accentSubtle;
    p.text   = t.text;     p.textDim = t.textDim; p.textFaint = t.textFaint;
    p.hover  = t.hover;    p.input = t.input; p.popup = t.popup;
    // 十字准心线跟随皮肤：强调色与正文色对半混，暗肤偏亮、浅肤偏深。
    // 以前只给了基准暗/浅两套色，四套自定义皮肤全退回基准灰，跟主题不搭。
    p.guideLine = mixc(t.accent, t.text, 0.42f);
    p.snapLine  = t.accent;
    // 设计窗体永远保持浅色（易语言窗体本身就是浅灰），不跟着皮肤变
    p.formSurface = t.dark ? RGB(0xF0,0xF0,0xF0) : RGB(0xFF,0xFF,0xFF);
    p.formCaption = t.dark ? RGB(0x3B,0x3B,0x3B) : RGB(0xDD,0xE2,0xEC);
    return p;
}

// 切换当前绘制区域使用的字体组，并按需覆盖这一组的主文字颜色。
// 各绘制函数是在调用 tx/tw 时才读 g_f12 等全局量，所以这里一换就全局生效。
static void font_use(int group)
{
    if (!g_fontsBuilt || group < 0 || group >= FNT_N) return;
    g_fontGroup = group;
    HFONT* f = g_fontSets[group].f;
    g_f13 = f[0]; g_f13b = f[1]; g_f12 = f[2]; g_f12b = f[3];
    g_f11 = f[4]; g_fmono = f[5]; g_f18b = f[6];
    g_p = g_pBase;
    int ci = g_fontCfg[group].color;
    if (ci > 0 && ci < FONT_COLOR_N) {
        COLORREF c = FONT_COLORS[ci].c;
        g_p.text      = c;
        g_p.textDim   = RGB(GetRValue(c) * 3 / 4, GetGValue(c) * 3 / 4, GetBValue(c) * 3 / 4);
        g_p.textFaint = RGB(GetRValue(c) / 2,     GetGValue(c) / 2,     GetBValue(c) / 2);
    }
}

