    // IDE 不针对任何组件写死 Win32 类名或样式。"-" 表示非可视组件，不建窗口。
    std::wstring win32cls, win32style;
    int dw, dh;                                // 默认尺寸
    std::vector<LGProp> props;                 // 属性
    std::vector<LGProp> methods, evs;          // 方法/事件（只用到 name/desc/group）
