static int g_toolScroll = 0;       // 组件箱滚动位置
static int g_toolContentH = 0;     // 组件箱内容总高度
static int lg_comp_index(const wchar_t* name)
{
    for (int i = 0; i < g_comp_count(); ++i)
        if (g_comps[i].name == name) return i;
    return -1;
}
static const LGComp* lg_comp(const wchar_t* name)
{
    int i = lg_comp_index(name);
    return (i < 0) ? NULL : &g_comps[i];
}
// 找不到返回 -1（组件库换名字时不能悄悄落到第 0 个组件上）
static int kind_find_name(const wchar_t* n)
{
    for (size_t i = 0; i < KINDS.size(); ++i)
        if (wcscmp(KINDS[i].name, n) == 0) return (int)i;
    return -1;
}
[[maybe_unused]] static int kind_by_name(const wchar_t* n)
{
    for (size_t i = 0; i < KINDS.size(); ++i)
        if (wcscmp(KINDS[i].name, n) == 0) return (int)i;
    return 0;
}
// 组件箱按组件库装配：库里每个组件一条；「窗口」是窗体本身，不进组件箱
static void kinds_build()
{
    KINDS.clear();
    for (int i = 0; i < g_comp_count(); ++i) {
        const LGComp& c = g_comps[i];
        if (c.name == L"窗口") continue;
        KindInfo it;
        it.name   = c.name.c_str();
        it.cls    = c.en.empty() ? c.name.c_str() : c.en.c_str();
        it.icon   = "ctl.component";
        it.w      = (float)(c.dw > 0 ? c.dw : 96);
        it.h      = (float)(c.dh > 0 ? c.dh : 24);
        it.cat    = 0;                  // 核心组件库全放「基本组件」
        it.nonvis = 0;
        it.draw   = KPanel;
        for (int k = 0; k < KIND_STYLE_N; ++k)
            if (c.en == KIND_STYLE[k].key) {
                it.icon = KIND_STYLE[k].icon;
                it.draw = KIND_STYLE[k].draw;
                break;
            }
        it.comp   = i;
        KINDS.push_back(it);
    }
}

static const wchar_t* CAT_NAMES[3] = { L"基本组件", L"扩展组件", L"外部组件" };

struct Ctl {
    int          kind;
    std::wstring name;
    std::wstring caption;
    float        x, y, w, h;
    bool         visible, enabled;
    int          z;
    // 从 .e 的窗口 XML 里原样读到的属性/事件绑定（属性页优先显示这些真实值）
    std::map<std::wstring, std::wstring> props;
    std::map<std::wstring, std::wstring> events;   // 事件名 → 处理器（程序集::子程序）
    std::vector<std::wstring> propOrder;            // .e XML 里属性的原始顺序
};

struct Form {
    std::wstring      name, title;
    float             cw, ch;      // 客户区（DIP）
    float             caption;     // 标题条 28
    float             grid;      // 网点间隔-宽（DIP）
    float             gridY;     // 网点间隔-高（DIP）；易语言允许宽高不同
    bool              gridOn, snap, dirty;
    std::vector<Ctl>  ctl;
    std::map<std::wstring, std::wstring> props;    // .e 里的窗口属性
    std::map<std::wstring, std::wstring> events;   // 窗口事件 → 处理器
    std::vector<std::wstring> propOrder;            // .e XML 里属性的原始顺序
};

// ── 实测自原始程序 e.exe 的常量（Ghidra 反编译，地址即证据）────────────────
// PROP_SLOTS：sub_4e8a60 @0x4e8a60 的越界判断 cmp eax,0xfffffffc —— 合法索引
//             只有 -1..-12 共 12 个，描述符基址 0x66bdd8、步长 8、越界回落到
//             0x674ee0 的空串。所以每个对象有 12 个属性槽。
// PROP_RESERVED：FUN_004f6df0 的计数分支 —— 标志位 0x8000→7 行、0x2000→10 行、
//             0x10000→12 行，取名字时从第 8 个开始（前 8 个是名称/备注/左边/顶边/
//             宽度/高度/标记/可视 这类基础属性，对所有组件一视同仁）。
// PROP_LABEL_PAD：同一函数里列宽 = GetTextExtentPoint32W 的最大文本宽度 + 4。
// PROP_ROW_H  ：同一函数里行高 = 文本高度，不是固定像素。
// FORM_DEF_*  ：新建窗口的默认矩形。实测 323 个真实 .e 工程里有 28 个在 0x237 附近
//             出现 32 00 00 00 32 00 00 00 7c 01 00 00 fa 00 00 00 = (50,50,380,250)，
//             本项目自带的 新建 易程序.e 也在 0x237。原先写的 640×480 没有出处。
enum {
    PROP_SLOTS        = 12,
    PROP_RESERVED     = 8,
    PROP_LABEL_PAD    = 4,
    FORM_DEF_X        = 50,
    FORM_DEF_Y        = 50,
    FORM_DEF_CW       = 380,
    FORM_DEF_CH       = 250,
};

static std::wstring ini_file();   // 前向声明：form_starter 要用它读全局网格设置

static Form form_starter()
{
    Form f;
    // 默认窗口名/标题照易语言：_启动窗口（yc 那边默认是「主窗口 / SuLang 窗口程序」，
    // 但它的事件命名映射里同样保留了 _启动窗口 这套易语言叫法）
    f.name = L"_启动窗口";
    // 标题默认留空：设计面上的标题栏就是一条空的（标题属于属性，属性里填了才显示）。
    // 以前这里和文件名一起塞成 "_启动窗口"，看着像设计器自带的假标题。
    f.title.clear();
    f.cw = FORM_DEF_CW; f.ch = FORM_DEF_CH;
    f.caption = 28;
    // 网格设置跟「设置→设计器」保持一致：新建/重置窗口时不要把用户设的值冲掉。
    // 以前这里硬编码 8/开/开，所以设计窗口一变（新建、重置、重开）用户改过的网格就"失效"了。
    {
        std::wstring ip0 = ini_file();
        f.grid = (float)GetPrivateProfileIntW(L"ui", L"grid_size", 8, ip0.c_str());
        if (f.grid < 2 || f.grid > 64) f.grid = 8;
        f.gridY = (float)GetPrivateProfileIntW(L"ui", L"grid_size_y", (int)f.grid, ip0.c_str());
        if (f.gridY < 2 || f.gridY > 64) f.gridY = f.grid;
        f.gridOn = GetPrivateProfileIntW(L"ui", L"grid", 1, ip0.c_str()) != 0;
        f.snap   = GetPrivateProfileIntW(L"ui", L"snap", 1, ip0.c_str()) != 0;
        f.cw = (float)GetPrivateProfileIntW(L"ui", L"new_win_w", 880, ip0.c_str());
        f.ch = (float)GetPrivateProfileIntW(L"ui", L"new_win_h", 250, ip0.c_str());
        if (f.cw < 120 || f.cw > 4000) f.cw = 880;
        if (f.ch < 80  || f.ch > 3000) f.ch = 250;
    }
    f.dirty = false;

    // 纯白板：设置出厂默认属性（必须写入底层支持的索引值或真假，否则会被 _wtoi 解析成 0）
    f.props[L"边框"] = L"1";      // 1 = 普通可调边框
    f.props[L"控制按钮"] = L"真";
    f.props[L"最大化按钮"] = L"假";
    f.props[L"最小化按钮"] = L"真";
    f.props[L"位置"] = L"1";      // 1 = 居中
    f.props[L"可否移动"] = L"真";

    return f;
}

