// ══════════════════════════════════════════════════════════════════
// 菜单（P3：易语言 5.95 真实菜单树）
// ══════════════════════════════════════════════════════════════════

struct MItem {
    std::wstring          cap, sc, act, chk;
    std::vector<MItem>    kids;
    bool                  sep, off, checked;
    MItem() : sep(false), off(false), checked(false) {}
};

static MItem mi(const wchar_t* cap, const wchar_t* sc, const wchar_t* act)
{
    MItem m; m.cap = cap; m.sc = sc ? sc : L""; m.act = act ? act : L""; return m;
}
static MItem mdim(const wchar_t* cap)
{
    MItem m = mi(cap, L"", L""); m.off = true; return m;
}
static MItem mchk(const wchar_t* cap, const wchar_t* key, bool on)
{
    MItem m = mi(cap, L"", L"toggle");
    m.chk = key; m.checked = on; return m;
}
static MItem msub(const wchar_t* cap, std::vector<MItem> kids)
{
    MItem m; m.cap = cap; m.kids = kids; return m;
}
static MItem msep()
{
    MItem m; m.sep = true; return m;
}

// 「F.程序」→「程序」；去掉菜单助记符前缀（P3 §1 保留字母但界面只显示文字）
static std::wstring mtext(const MItem& m)
{
    if (m.cap.size() < 3) return m.cap;
    const wchar_t* p = m.cap.c_str();
    if (p[0] >= L'A' && p[0] <= L'Z' && p[1] == L'.') return m.cap.substr(2);
    return m.cap;
}

