// ══════════════════════════════════════════════════════════════════
// 应用状态
// ══════════════════════════════════════════════════════════════════

enum DragMode { DNone, DMove, DResize, DFormResize, DMarquee, DSplitL, DSplitR, DSplitB,
                DSetSize, DSetMove, DBgAlpha };

struct App {
    Form        form;
    std::vector<int>  sel;
    int         hoverCtl;
    std::vector<LogRow> log;

    // 面板
    int   leftW, rightW, bottomH;
    bool  showToolbox, showProps, showOutput, showLeft, showBottom;
    bool  showAI;          // 右列「AI」页（当前是占位面板）
    bool  showToolbar, showStatus, showAlignBar;
    bool  dockBottom;

    // 画布
    float zoom, panx, pany;
    bool  showGridGuides;
    int   docTab;

    // 工具条 / 组件箱
    wchar_t search[64];
    bool    searchActive;    // 搜索框正在接受输入
    bool    catOpen[3];
    int     activeCat;     // 组件箱当前分类（0 常用 1 基本组件 2 扩展组件）
    int     toolMode;      // 0 网格 1 列表
    int     toolHot;

    // 左侧竖排页签（程序 / 支持库 / 属性）
    int     leftPage;      // 0 程序 1 支持库 2 属性
    bool    leftPanelOpen; // 只收内容，竖排页签栏一直留着
    int     libScroll;     // 支持库列表滚动量（像素）
    int     libSel;        // 支持库选中行，-1 无
    bool    libGroupOpen[2]; // 已加载 / 未加载 两组是否展开（点分组头切换）
    int     progSel;       // 程序树选中节点 id，-1 无
    int     progScroll;    // 程序树纵向滚动量（像素）
    int     codeScroll;    // 表格代码页纵向滚动量（像素）
    bool    resTableOpen;  // 资源表页（双击程序树「资源表」跳转，× 关闭）
    int     propScroll;    // 属性表格滚动量（像素）

    // 属性
    int   propSel;         // 行
    int   objComboOpen;

    // 输出面板
    int   outTab;          // 页签：0 提示 1 输出 2 调用表 3 监视表 4 变量表 5 搜寻1 6 搜寻2 7 剪辑历史
    int   outMenu;         // 显示方式弹层：-1 收起
    int   outDock;         // 0 铺满 1 居中 2 靠左（右列整列留出）3 靠右（左栏整列留出）

    // 设计器这一栏的停靠位置：0 上方（占满中间区）1 下方（贴输出栏上沿）
    int   designPos;

    // 菜单
    int   menuTop;         // -1 关闭
    int   menuSub;         // -1 无二级
    int   menuHot, menuSubHot;
    RECT  popupRect, subRect;

    // 菜单的悬停展开（P3 规格：悬停展开，不是点点点）
    int   menuHoverTop;    // 指针正停在哪个标题上，-1 不在标题上
    int   menuHoverMute;   // 刚被点收起的那一项，指针离开前不许自动弹，-1 无

    // 工具条悬停提示（Tooltip）
    int   tbHotIdx;        // 指针停在第几个按钮上，-1 无
    int   tbTipIdx;        // 正在显示提示的按钮，-1 不显示
    bool  tbTipOn;

    // 交互
    DragMode drag;
    POINT    dragFrom;
    RECT     dragCtlFrom;
    std::vector<Ctl> dragSnapCtl;
    int      dragHandle;
    int      dragPanelW0, dragPanelH0;
    // 拖动设计窗口边框时记下的初值（绝对量算，避免夹紧后回弹累积）
    float    dragFormW0, dragFormH0;
    float    dragPanX0, dragPanY0;
    // 拖组件：按下瞬间的屏幕点与控件设计坐标。
    // 每帧用「起点 + 总位移」绝对定位，绝不把位移累加到控件身上再改起点——
    // 那样每次除以缩放后的小数部分都会被丢掉，人手一小步一小步拖时位移会持续
    // 被吞掉，控件越拖越落后于鼠标（这就是"拖快了跟不上/差很远"的根因）。
    POINT    dragFrom0;
    float    dragX0, dragY0, dragW0, dragH0;
    bool     dragMoved;
    bool     dragShift;     // 按下时 Shift 是否按着（松手时要据此决定"单击变单选"要不要做）

    // 行内编辑
    bool         editing;
    int          editRow;
    std::wstring editBuf;

    // 提示
    std::wstring toast;
    DWORD        toastAt;
    DWORD        msgAt;
    std::wstring message;

    // 撤销
    std::vector<Snap> undo, redo;

    bool quit;

    // 三个窗口按钮：按下先记下，松手才执行（原生 Windows 手感）
    int winBtnDown;   // -1 没按下
    int hotWinBtn;    // 指针悬停的那个，-1 无
};

static App g_a;

// 窗口属性（导入 .e 后按真实属性画标题栏按钮等）
static std::wstring form_prop(const wchar_t* name, const wchar_t* def);

// ── 每个面板各自记宽度 ──────────────────────────────────────────────
// 左栏三页（程序 / 支持库 / 属性）、右列两页（组件箱 / AI）宽度互不影响：
// 属性表要宽，程序树要窄，一套宽度套所有页签永远有一边别扭。
static int g_leftWPage[3]  = { 264, 264, 264 };
static int g_rightWPage[2] = { 288, 288 };

static int right_page() { return g_a.showToolbox ? 0 : 1; }
static int& left_w_cur()  { return g_leftWPage[(g_a.leftPage >= 0 && g_a.leftPage < 3) ? g_a.leftPage : 0]; }
static int& right_w_cur() { return g_rightWPage[right_page()]; }

// 设计器画布上的十字准心线（跟随鼠标的水平/垂直参考线）。
// 默认关：设计器里鼠标一动就横竖两条贯穿画布的线，多数时候是干扰。
// 开关在「设置 → 设计器 → 显示十字准心线」。
static bool g_showGuide = false;

// 抓"干净底图"期间抑制准心线。准心线是跟着鼠标画的，底图会整场贴在屏幕上，
// 抓进去就冻成两条死线，所以抓底图的那一帧必须不画它（框选走这条）。
static bool g_hideGuide = false;

// 组件布局辅助线（拖动组件贴近别的组件时，标出对齐位置的那条线）。
// 默认关：吸附照旧生效，只是不画线。开关在「设置 → 设计器 → 显示组件布局辅助线」。
static bool g_showSnapLine = false;
