// ─── .e 源码导入的数据模型（e-packager 解包 → 表格编辑器的地基） ───
// 参数/变量：arr=数组，byref=参考，nullable=可空，isStatic=静态（后三个供表格勾选用）
struct EArg  { std::wstring name, type, remark;
               bool arr, byref, nullable, isStatic;
               EArg() : arr(false), byref(false), nullable(false), isStatic(false) {} };
struct EStmt {
    std::wstring text; int indent;
    EStmt() : indent(0) {}
    EStmt(const std::wstring& t, int lv) : text(t), indent(lv) {}   // 一条语句（带缩进级别）
};
// 子程序：pub=公开（表格里点一下打勾/取消）；pkg=易包（文本列，可输入）
struct ESub  { std::wstring name, ret, remark, pkg;
               bool pub;
               std::vector<EArg> args, locals; std::vector<EStmt> body;
               ESub() : pub(false) {} };
struct EAsm  { std::wstring name, remark; std::vector<EArg> vars; std::vector<ESub> subs; };
struct ELib  { std::wstring fileName, name, kind, version; };

static std::vector<EAsm> g_eAsms;    // 程序集列表
