// 时间格式：像 .NET 那样用占位符自己拼，其它字符原样输出
//   yyyy 四位年  yy 两位年    MM 两位月  M 月
//   dd 两位日    d 日         HH 两位时(24)  H 时
//   mm 两位分    m 分         ss 两位秒      s 秒
//   fff 三位毫秒 ff 两位毫秒  f 一位毫秒
static std::wstring log_fmt_apply(const std::wstring& fmt, const SYSTEMTIME& st)
{
    std::wstring out;
    size_t i = 0;
    while (i < fmt.size()) {
        wchar_t c = fmt[i];
        size_t n = 1;
        while (i + n < fmt.size() && fmt[i + n] == c) ++n;   // 连续同字符的一串
        wchar_t buf[8] = { 0 };
        if (c == L'y') {
            if (n >= 4) wsprintfW(buf, L"%04d", (int)st.wYear);
            else        wsprintfW(buf, L"%02d", (int)(st.wYear % 100));
        } else if (c == L'M') {
            if (n >= 2) wsprintfW(buf, L"%02d", (int)st.wMonth); else wsprintfW(buf, L"%d", (int)st.wMonth);
        } else if (c == L'd') {
            if (n >= 2) wsprintfW(buf, L"%02d", (int)st.wDay);   else wsprintfW(buf, L"%d", (int)st.wDay);
        } else if (c == L'H') {
            if (n >= 2) wsprintfW(buf, L"%02d", (int)st.wHour);  else wsprintfW(buf, L"%d", (int)st.wHour);
        } else if (c == L'm') {
            if (n >= 2) wsprintfW(buf, L"%02d", (int)st.wMinute); else wsprintfW(buf, L"%d", (int)st.wMinute);
        } else if (c == L's') {
            if (n >= 2) wsprintfW(buf, L"%02d", (int)st.wSecond); else wsprintfW(buf, L"%d", (int)st.wSecond);
        } else if (c == L'f') {
            if (n >= 3)      wsprintfW(buf, L"%03d", (int)st.wMilliseconds);
            else if (n == 2) wsprintfW(buf, L"%02d", (int)(st.wMilliseconds / 10));
            else             wsprintfW(buf, L"%d",  (int)(st.wMilliseconds / 100));
        } else {
            for (size_t k = 0; k < n; ++k) out += c;
            i += n;
            continue;
        }
        out += buf;
        i += n;
    }
    return out;
}

static std::wstring log_stamp()
{
    if (!g_logTime) return L"";
    SYSTEMTIME st; GetLocalTime(&st);
    std::wstring fmt = g_logFmt.empty() ? std::wstring(L"H:mm:ss  fff") : g_logFmt;
    std::wstring v = log_fmt_apply(fmt, st);
    // 只有「时:分:秒.毫秒」这种短格式才在括号里留空格（易语言风格 [ 7:05:32  587 ]）。
    // 空格不能写进格式串本身——ini 读写会把它裁掉。
    bool shortStyle = (fmt.find(L'y') == std::wstring::npos &&
                       fmt.find(L'M') == std::wstring::npos &&
                       fmt.find(L'd') == std::wstring::npos);
    return shortStyle ? (L"[ " + v + L" ] ") : (L"[" + v + L"] ");
}

// 去向位：1＝提示页，2＝输出页，3＝两边都写
enum { LOG_TIP = 1, LOG_OUT = 2, LOG_BOTH = 3 };

static void elog(Lvl l, const std::wstring& s, int dest = LOG_OUT)
{
    if (s.empty()) return;
    for (int page = 0; page < 2; ++page) {
        if (!((dest >> page) & 1)) continue;         // bit0=提示页 bit1=输出页
        // 时间只加在输出页（调试用）；提示页是给人看的结论，不加时间
        std::wstring line = (page == 1) ? (log_stamp() + s) : s;
        LogRow r; r.lvl = l; r.text = line; r.page = page;   // page 0=提示 1=输出
        g_a.log.push_back(r);
    }
    if (g_a.log.size() > 1500)
        g_a.log.erase(g_a.log.begin(), g_a.log.end() - 1500);
    g_a.message = s;
    g_a.msgAt = GetTickCount();
    if (dest & 1) {                                  // 只给输出页响音，提示页不吵
        if (l == LErr)  sound_play(0);
        else if (l == LWarn) sound_play(1);
    }
}

// 旧名字保留（全工程几百处调用不用改）：输出页＝调试内容，提示页＝给人看的结论
static void log_add(Lvl l, const std::wstring& s) { elog(l, s, LOG_OUT); }
static void log_tip(Lvl l, const std::wstring& s) { elog(l, s, LOG_TIP); }
// 提示页：支持库命令签名/参数说明、选中提示这类「看一眼就够」的信息，
// 走这里，不和编译/运行输出混在一页。
// ── 提示页的表格输出 ─────────────────────────────────────────────
// 点支持库 / 点命令时，提示页除了纯文本还能画成表。宽高都跟面板走：
// 列宽按权重分剩余宽度，单元格按列宽折行，行高按内容量出来（拖窗口自动重排）。
// 每个单元格带「角色」（命令/参数/变量/返回值/注释/类型），颜色在 设置 → 提示表格 里改。
enum TipRole { TR_TEXT = 0, TR_CMD, TR_PARAM, TR_VAR, TR_RET, TR_NOTE, TR_TYPE, TR_ROLE_N };

// 一个单元格：文本 + 跨几列
struct TipCell {
    std::wstring t;
    int span;
    TipCell() : span(1) {}
    TipCell(const std::wstring& s, int sp = 1) : t(s), span(sp) {}
};

// 一段：自己一套列宽 + 若干行（行内可有标签行/数据行）
struct TipSeg {
    std::vector<float>                w;         // 列宽权重
    std::vector<int>                  colRole;   // 每列正文角色
    std::vector< std::vector<TipCell> > rows;
    std::vector<int>                  rowKind;   // 0＝数据行 1＝标签行
    std::vector<int>                  rowRole;   // 每行角色（-1＝按列）
    TipSeg() {}
};

// 一张表：标题 + 若干段。段与段之间没有间隙，共用外框和第一列宽度。
struct TipTable {
    std::wstring title;
    std::vector<TipSeg> segs;
    // ── 布局缓存 ── 量列宽/行高要跑几百次 DT_CALCRECT（长段落尤其贵），
    // 一帧一次、鼠标一动一帧，就是 CPU 大头。表内容只在 tip_begin 时重建
    // （tip_begin 清掉整个 vector，表对象都是新的），所以缓存直接挂在
    // 表对象上天然失效；只有面板宽度和字体变了才需要重量。
    bool laidOut;
    int  layW;        // 上次量时的可用宽度
    int  layLeft;     // 上次量时的表格左沿（面板横移也要重排）
    int  layEpoch;    // 上次量时的字体纪元（字体/字号重建就 +1）
    std::vector<int> xs, ws;                    // 表级列位/列宽（各段共用）
    std::vector< std::vector<int> > rowHs;      // 每段每行的行高
    TipTable() : laidOut(false), layW(0), layLeft(0), layEpoch(0) {}
};

