static void tip_fonts_build()
{
    if (g_tipF)  { DeleteObject(g_tipF);  g_tipF  = NULL; }
    if (g_tipFB) { DeleteObject(g_tipFB); g_tipFB = NULL; }
    const wchar_t* face = g_tipFace.empty() ? L"Microsoft YaHei UI" : g_tipFace.c_str();
    int sz = g_tipSize < 8 ? 8 : (g_tipSize > 32 ? 32 : g_tipSize);
    g_tipF  = mkfont((float)sz, false, face);
    g_tipFB = mkfont((float)sz, g_tipBold, face);
    ++g_tipFontEpoch;      // 字体变了，提示表的列宽/行高缓存全部作废
}

// 按当前样式/粗细造一支表格线画笔（单像素用 cosmetic pen，虚线才看得出来）
static HPEN grid_pen()
{
    if (g_gridW <= 0) g_gridW = 1;
    if (g_gridW == 1) {
        static const int st[4] = { PS_SOLID, PS_DASH, PS_DOT, PS_DASHDOT };
        return CreatePen(st[g_gridStyle < 0 || g_gridStyle > 3 ? 0 : g_gridStyle], 1, g_gridCol);
    }
    LOGBRUSH lb; lb.lbStyle = BS_SOLID; lb.lbColor = g_gridCol; lb.lbHatch = 0;
    DWORD st = PS_SOLID;
    if (g_gridStyle == 1) st = PS_DASH;
    else if (g_gridStyle == 2) st = PS_DOT;
    else if (g_gridStyle == 3) st = PS_DASHDOT;
    return ExtCreatePen(PS_GEOMETRIC | st | PS_ENDCAP_FLAT | PS_JOIN_MITER,
                        g_gridW, &lb, 0, NULL);
}
