//   ms        停留时间（毫秒）
//   snd       >=0 时播对应音效，-1＝不响
static void toast_show(const std::wstring& s, bool err = false, DWORD ms = 3200, int snd = -1)
{
    if (s.empty()) return;
    if (snd >= 0) sound_play(snd);
    g_toastMs   = ms;
    g_toastErr  = err;
    g_a.toast   = s;
    g_a.toastAt = GetTickCount();
    toast_kick();
}

