// ── 输出日志的选择 / 复制 / 清空 ──────────────────────────────────
// 输出栏不是编辑控件，但要能像文本一样拖选、全选、复制到剪贴板。
// 选择模型是「字符区间」：LogPos(row, col) 是某行文字的一个字符边界，
// A 是按下时的锚点，B 是当前光标；单击仍选整行，拖选就能只取一行里的一段。
struct LogPos { int row = -1, col = 0; };
static LogPos g_logSelA, g_logSelB, g_logAnchor;
static bool   g_logDragging = false, g_logDragMoved = false;
static POINT  g_logDragFrom = { 0, 0 };
static int    g_logTextX = 0;          // 每行文字的起点，paint_output 里量好
// 拖动时每帧都要问「鼠标在第几个字」，把量好的字宽按「行文本」缓存起来，
// 文本没变就直接复用，避免每个 WM_MOUSEMOVE 都重新做几十次 GDI 测字。
static std::map<int, std::pair<std::wstring, std::vector<int> > > g_logDx;

static bool log_pos_same(const LogPos& a, const LogPos& b)
{ return a.row == b.row && a.col == b.col; }
static bool log_pos_less(const LogPos& a, const LogPos& b)
{ return a.row < b.row || (a.row == b.row && a.col < b.col); }
static bool log_pos_valid(const LogPos& p)
{
    return p.row >= 0 && p.row < (int)g_a.log.size() &&
           p.col >= 0 && p.col <= (int)g_a.log[p.row].text.size();
}

static void log_sel_clear()
{
    g_logSelA = g_logSelB = g_logAnchor = LogPos();
    g_logDragging = g_logDragMoved = false;
}

static bool log_has_sel()
{
    return log_pos_valid(g_logSelA) && log_pos_valid(g_logSelB) &&
           !log_pos_same(g_logSelA, g_logSelB);
}

// 一行的每个字符边界（像素）：dx[0]=0，dx[n]=整行宽。绘制和鼠标命中共用一套量法。
static void log_row_dx(HDC dc, int row, std::vector<int>& dx)
{
    dx.clear();
    if (!dc || row < 0 || row >= (int)g_a.log.size()) return;
    const std::wstring& s = g_a.log[row].text;
    std::map<int, std::pair<std::wstring, std::vector<int> > >::iterator it = g_logDx.find(row);
    if (it != g_logDx.end() && it->second.first == s) {
        dx = it->second.second;
        return;
    }
    dx.assign(s.size() + 1, 0);
    HGDIOBJ o = SelectObject(dc, g_fmono);
    for (size_t i = 0; i < s.size(); ++i) {
        SIZE sz = { 0, 0 };
        GetTextExtentPoint32W(dc, s.c_str() + i, 1, &sz);
        dx[i + 1] = dx[i] + sz.cx;
    }
    // 中文回退字体让逐字累加比 DrawTextW 的实际排版略窄；用整行 CALCRECT 校正，
    // 免得拖到行尾时选区跟文字对不上。
    RECT rr = { 0, 0, 0, 0 };
    DrawTextW(dc, s.c_str(), (int)s.size(), &rr, DT_SINGLELINE | DT_CALCRECT);
    int total = rr.right - rr.left, raw = dx.back();
    if (raw > 0 && total > 0 && total != raw)
        for (size_t i = 1; i < dx.size(); ++i)
            dx[i] = (int)(dx[i] * (double)total / raw + 0.5);
    SelectObject(dc, o);
    g_logDx[row] = std::make_pair(s, dx);
}

// 鼠标 x 落在这一行哪个字符边界上（按最近的字中心取，中文/英文都能对齐）
static int log_col_at(HDC dc, int row, int x)
{
    if (row < 0 || row >= (int)g_a.log.size()) return 0;
    std::vector<int> dx;
    log_row_dx(dc, row, dx);
    int n = (int)dx.size() - 1;
    if (n <= 0) return 0;
    int px = x - g_logTextX;
    if (px <= 0) return 0;
    for (int c = 0; c < n; ++c)
        if (px < (dx[c] + dx[c + 1]) / 2) return c;
    return n;
}

// 第 row 行被选中的字符区间 [ca, cb)；这行不在选区里就返回 false
static bool log_row_sel(int row, int& ca, int& cb)
{
    ca = cb = 0;
    if (!log_has_sel() || row < 0 || row >= (int)g_a.log.size()) return false;
    bool ab = log_pos_less(g_logSelA, g_logSelB);
    const LogPos& a = ab ? g_logSelA : g_logSelB;
    const LogPos& b = ab ? g_logSelB : g_logSelA;
    if (row < a.row || row > b.row) return false;
    int n = (int)g_a.log[row].text.size();
    ca = (row == a.row) ? a.col : 0;
    cb = (row == b.row) ? b.col : n;
    ca = std::max(0, std::min(ca, n));
    cb = std::max(ca, std::min(cb, n));
    return cb > ca;
}

static void log_select_all()
{
    int first = -1, last = -1, n = 0;
    for (int i = 0; i < (int)g_a.log.size(); ++i) {
        if (g_a.log[i].page != g_a.outTab) continue;
        if (first < 0) first = i;
        last = i;
        ++n;
    }
    if (first < 0) return;
    g_logSelA = g_logAnchor = LogPos{ first, 0 };
    g_logSelB = LogPos{ last, (int)g_a.log[last].text.size() };
}

static std::wstring log_sel_text()
{
    std::wstring s;
    if (!log_has_sel()) return s;
    bool ab = log_pos_less(g_logSelA, g_logSelB);
    int a = (ab ? g_logSelA : g_logSelB).row;
    int b = (ab ? g_logSelB : g_logSelA).row;
    bool firstLine = true;
    for (int i = a; i <= b; ++i) {
        if (g_a.log[i].page != g_a.outTab) continue;   // 另一个页签的行不复制
        if (!firstLine) s += L"\r\n";
        firstLine = false;
        int ca = 0, cb = 0;
        if (log_row_sel(i, ca, cb)) s += g_a.log[i].text.substr(ca, cb - ca);
    }
    return s;
}

static void clipboard_set_text(const std::wstring& s)
{
    if (s.empty() || !g_hwnd || !OpenClipboard(g_hwnd)) return;
    EmptyClipboard();
    SIZE_T bytes = (s.size() + 1) * sizeof(wchar_t);
    HGLOBAL h = GlobalAlloc(GMEM_MOVEABLE, bytes);
    if (h) {
        wchar_t* p = (wchar_t*)GlobalLock(h);
        if (p) {
            wmemcpy(p, s.c_str(), s.size() + 1);
            GlobalUnlock(h);
            SetClipboardData(CF_UNICODETEXT, h);   // 成功后 h 归系统所有，别 Free
        } else {
            GlobalFree(h);
        }
    }
    CloseClipboard();
}

static void log_copy()
{
    std::wstring s = log_sel_text();
    if (s.empty()) return;
    clipboard_set_text(s);
}

static void log_clear_all()
{
    int tab = g_a.outTab;
    g_a.log.erase(std::remove_if(g_a.log.begin(), g_a.log.end(),
                                 [tab](const LogRow& r) { return r.page == tab; }),
                  g_a.log.end());
    log_sel_clear();
}

