// ══════════════════════════════════════════════════════════════════
// 布局
// ══════════════════════════════════════════════════════════════════

static void layout()
{
    int W = g_w, H = g_h;
    int y = 0;

    rcTitle = R(0, 0, 0, 0);
    rcTitle = R(0, 0, (float)W / g_s, 32);
    y = 32;

    // VS2026 把菜单画在标题栏这一行里，不另起一条菜单栏。
    // 依据：tools/measure-top.ps1 统计官方 tools/ref/vs2026-dark.png，
    // y=0..44 只有一种底色 #1c1c1c，而文字 ink 同时出现在左侧三分之一
    // （菜单）和中间（标题）。所以这里不画 rcMenu，直接在这一行排菜单。
    rcMenu = R(0, 0, 0, 0);
    y = 29;

    // 高度取自官方截图的实测分段（tools/measure-runs.ps1）：
    // 标题 0..44 = 29 DIP，工具条 47..88 = 28 DIP，之间 91..99 是 6 DIP 的 #1c1c1c 缝。
    if (g_a.showToolbar) {
        rcTool = R(0, 29, (float)W / g_s, 28);
        y = 63;
        rcGap = R(0, 63, (float)W / g_s, 6);
        y = 69;
    } else {
        rcTool = R(0, 29, 0, 0);
        rcGap = R(0, 29, 0, 0);
        y = 29;
    }

    // 对齐按钮直接排在主工具条末尾（见 paint_toolbar），不再单独占一条横栏：
    // 单独一条会把整个画布往下压 30 DIP，窗口矮的时候设计区明显变小。


    int statusH = g_a.showStatus ? S(24) : 0;
    rcStatus = R(0, (float)(H - statusH) / g_s, float(W) / g_s, 24);

    // 注意：这里的 y 是 DIP（上面累加的都是 32 / 29 / 63 / 69 这类 DIP 值），
    // R() 自己会把 DIP 换成像素，所以不能再除一次 g_s。
    // 早先写成 S(y / g_s)，等于把 DIP 当像素用：100% 缩放下看不出问题，
    // 到了 125% / 150% 中部整块会往上跑，正好压住工具条下半截。
    int midTop = S((float)y);
    int midBot = H - statusH;
    int midH   = midBot - midTop;

    // ── 横向分区（按人提的布局）：
    //   最左：竖排页签栏（程序 / 支持库 / 属性）
    //   其右：左侧内容面板
    //   中间：设计画布；窗口设计器贴在画布左上角
    //   右侧：组件箱（右下角的属性表已删除，属性在左侧栏里）
    // 左栏分两层：竖排页签栏（像 VS 的自动隐藏夹，一直在）+ 内容面板（可收起）。
    // 收起时只有内容面板归零，页签栏留给用户点回来，画布紧贴页签栏右沿。
    bool leftOpen = g_a.showLeft && g_a.leftPanelOpen;
    // 宽度按当前页签各自取值，同时回写 g_a 里那份，ui_sig / 状态显示继续可用
    g_a.leftW  = left_w_cur();
    g_a.rightW = right_w_cur();
    int lw = leftOpen ? S((float)g_a.leftW) : 0;
    int sw = g_a.showLeft ? S((float)SIDEBAR_W) : 0;
    // 右侧也有一条常驻的竖排页签栏（组件箱 / AI），和左侧同款。
    // 它不跟着面板一起隐藏，否则关了组件箱就没地方点回来了。
    int sbr = S((float)SIDEBAR_W);
    bool rightShown = g_a.showToolbox || g_a.showAI;
    // 右列内容：组件箱或 AI 面板，二选一
    int rw = rightShown ? S((float)g_a.rightW) : 0;

    int bh = (g_a.showOutput && g_a.showBottom) ? S((float)g_a.bottomH) : 0;
    // 面板再高也要给画布留 120 DIP，否则窗口一矮画布就被压成负高度。
    if (bh > midH - S(120)) bh = midH - S(120);
    if (bh < 0) bh = 0;

    // 输出面板的四种停靠位置（g_a.outDock）：
    //   0 铺满    —— 横跨整窗宽，左栏和右侧组件箱都把下半截让出来
    //   1 居中（原「停靠底部」） —— 只占画布正下方，两边整列不动
    //   2 靠左    —— 从窗口最左铺到右列左沿，右列（组件箱 / AI）保持整列高度，
    //                一直顶到状态条上面，等于被「留出来」一整条
    //   3 靠右    —— 从左栏右沿铺到窗口最右，左栏（程序 / 支持库 / 属性）整列留出来
    // 所以左右两列的高度得分开算，不能再用一个 colH 通吃。
    bool outFull  = (g_a.outDock == 0) && bh > 0;
    bool outLeft  = (g_a.outDock == 2) && bh > 0;
    bool outRight = (g_a.outDock == 3) && bh > 0;

    int colHL = midH, colHR = midH;
    if (outFull)       { colHL = midH - bh; colHR = midH - bh; }
    else if (outLeft)  { colHL = midH - bh; colHR = midH; }
    else if (outRight) { colHL = midH;      colHR = midH - bh; }
    if (colHL < S(80)) colHL = S(80);
    if (colHR < S(80)) colHR = S(80);

    rcSideBar    = R(0, (float)y, (float)sw / g_s, (float)colHL / g_s);
    rcLeftSplit  = R((float)sw / g_s, (float)y, leftOpen ? (float)GUT / g_s : 0, (float)colHL / g_s);
    rcLeftPanel  = R((float)(sw + (leftOpen ? GUT : 0)) / g_s, (float)y,
                     leftOpen ? (float)(lw - GUT) / g_s : 0, (float)colHL / g_s);

    rcRightSplit = R((float)(W - sbr - rw) / g_s, (float)y, (float)GUT / g_s, (float)colHR / g_s);

    // 两条竖向拖动条：左侧面板/画布之间，画布/右列之间
    rcSplitL = R((float)(sw + lw) / g_s, (float)y, 1, (float)colHL / g_s);
    rcSplitR = R((float)(W - sbr - rw) / g_s, (float)y, 1, (float)colHR / g_s);

    // 右侧竖排页签栏（贴窗口右沿）
    rcSideBarR = R((float)(W - sbr) / g_s, (float)y, (float)sbr / g_s, (float)colHR / g_s);

    // 右侧面板：整列都给当前页（组件箱 or AI）
    rcPalette    = R((float)(W - sbr - rw) / g_s, (float)y,
                     (float)(rw > GUT ? rw - GUT : 0) / g_s, (float)colHR / g_s);
    // 属性表已经不在界面上了，保留零矩形，避免旧的命中判断误伤。
    rcRightPanel = RECT{ 0, 0, 0, 0 };

    int cx = sw + lw, cw = W - sw - lw - rw - sbr;
    int cy = midTop, chh = midH;

    // 居中：只在画布正下方，两边整列不动。
    // 铺满：从窗口最左到最右。
    // 靠左：从窗口最左到右列左沿（组件箱 / AI 整列让开）。
    // 靠右：从左栏右沿到窗口最右（程序 / 支持库 / 属性整列让开）。
    int bx0 = cx, bw = cw;
    if (outFull)        { bx0 = 0;  bw = W; }
    else if (outLeft)   { bx0 = 0;  bw = W - sbr - rw; }
    else if (outRight)  { bx0 = cx; bw = W - cx; }
    if (bw < 0) bw = 0;
    rcBottomPanel = R((float)bx0 / g_s, (float)(cy + chh - bh) / g_s,
                      (float)bw / g_s, (float)bh / g_s);
    rcSplitB = R((float)bx0 / g_s, (float)(cy + chh - bh) / g_s, (float)bw / g_s, 1);

    rcTabs = R((float)cx / g_s, (float)cy / g_s, (float)cw / g_s, 30);
    rcCanvas = R((float)cx / g_s, (float)(cy + S(30)) / g_s,
                 (float)cw / g_s, (float)(chh - S(30) - bh) / g_s);

    // ── 设计器「那一栏」（窗口1/程序集1… 的页签条）停靠位置：
    //    designPos = 0 → 页签条在画布上面（默认）
    //    designPos = 1 → 页签条沉到画布下面，紧贴输出栏上沿，画布向上占满
    // 画布始终吃满整个中间区，不做整体下移，也不留空白块。
    int areaH = chh - bh;
    if (areaH < 0) areaH = 0;

    float dx = (float)cx / g_s;
    float dy = (float)cy / g_s;
    float dw = (float)cw / g_s;
    float areaD = (float)areaH / g_s;
    const float TABH = 30.0f;      // 文档页签条

    rcDesignBlank = RECT{ 0, 0, 0, 0 };
    rcDesignSplit = RECT{ 0, 0, 0, 0 };

    if (g_a.designPos == 0) {
        rcTabs   = R(dx, dy, dw, TABH);
        rcCanvas = R(dx, dy + TABH, dw, areaD - TABH);
    } else {
        rcTabs   = R(dx, dy + areaD - TABH, dw, TABH);
        rcCanvas = R(dx, dy, dw, areaD - TABH);
    }
    if (rcCanvas.bottom < rcCanvas.top) rcCanvas.bottom = rcCanvas.top;
}

// ══════════════════════════════════════════════════════════════════
// 窗体与控件的屏幕坐标
// ══════════════════════════════════════════════════════════════════

static float g_formX, g_formY;   // 窗体左上（屏幕像素）

static RECT canvas_content()
{
    // 原来为了避开上/左两条 20px 标尺，内容区要内缩一圈；
    // 标尺去掉后画布整块都能用。
    return rcCanvas;
}

// 窗口设计器的位置：贴画布左上角（易语言的设计器就是从左上角起排，
// 右对齐会让第一眼看着像「画布空了一大块」）。
// 留白只留 12 DIP：24 那圈在停靠切换后显得离边框太远，整块看着发飘。
// 画布放不下时仍然从左上角起，靠拖动/缩放把内容挪出来，位置保持可预测。
static void form_origin()
{
    RECT c = canvas_content();
    g_formX = c.left + S(12) + g_a.panx;
    // 页签条沉到画布下方时，设计窗体顶边与左栏「程序」表头的上边线取齐
    // （不再留 12 DIP；页签条在上方时画布顶本来就被页签条占着，照旧留 12）
    int gapT = (g_a.designPos == 1) ? 0 : 12;
    g_formY = c.top + S(gapT) + g_a.pany;
}

static RECT form_rect()
{
    float z = g_a.zoom;
    return R(
        g_formX / g_s, g_formY / g_s,
        // 易语言的窗口「宽度/高度」是含标题栏和边框的整窗尺寸，
        // 客户区 = 高度 - 标题栏；这样和真机设计器里 603×354 的观感一致
        g_a.form.cw * z, g_a.form.ch * z);
}

static RECT ctl_rect(const Ctl& c)
{
    // 设计单位 → 像素的系数：设计缩放 zoom × DPI/界面缩放 g_s。
    // 位置和尺寸必须用同一个系数！
    //
    // 原来这里写的是：位置 g_formX + c.x * zoom（只乘 zoom），
    // 尺寸却是 R(..., c.w * zoom) → R 里再乘一次 g_s（等于 zoom*g_s）。
    // 在 125%/150% 缩放的机器上后果是：
    //   ① 控件越往右下画得越偏（位置按 1 倍排、窗体按 1.5 倍画）；
    //   ② 拖动时鼠标走 1px，设计位移只有 1/g_s px，控件只走 0.67px ——
    //      拖得越快差得越多。用户说的「鼠标都跑好远、控件跟不上」就是它，
    //      跟绘制快慢一点关系都没有（单帧只要 0.07ms），所以前几轮改渲染
    //      都只是「好一点」，永远治不好。
    float k = g_a.zoom * g_s;
    long x = (long)(g_formX + c.x * k + 0.5f);
    long y = (long)(g_formY + (g_a.form.caption + c.y) * k + 0.5f);
    long w = (long)(c.w * k + 0.5f);
    long h = (long)(c.h * k + 0.5f);
    return RECT{ x, y, x + w, y + h };
}

// 设计窗口边框命中：返回 0..7（和控件手柄同一套编号：
// 0 左上 1 上 2 右上 3 左 4 右 5 左下 6 下 7 右下），-1 不在边上。
// 点击和光标都走这一份，免得两处判断慢慢就对不上。
static int form_border_hit(int mx, int my)
{
    RECT f = form_rect();
    // 窗体现在只画在画布内（超出部分被裁掉），所以命中也要按"看得见的那条边"算：
    // 右边/下边超出画布时压到画布边上，否则一旦拉大就再也摸不到边框、
    // 没法往回收（只能去属性表改宽高）。
    if (f.right  > rcCanvas.right)  f.right  = rcCanvas.right;
    if (f.bottom > rcCanvas.bottom) f.bottom = rcCanvas.bottom;
    // 只开放三个手柄点：右中(4) 拉宽、下中(6) 拉高、右下(7) 同时拉宽拉高。
    // 窗口钉在画布左上角(0,0)，左边和上边往外拉会跑出画布，所以不支持；
    // 左上/右上/左下三个角同理不开放。
    int hs = S(6) / 2 + 3;
    int cx = (f.left + f.right) / 2, cy = (f.top + f.bottom) / 2;
    // 先判右下角，小窗口时三点会靠近，角优先
    POINT pts[3] = { { f.right, f.bottom }, { f.right, cy }, { cx, f.bottom } };
    int   ids[3] = { 7, 4, 6 };
    for (int i = 0; i < 3; ++i)
        if (abs(mx - pts[i].x) <= hs && abs(my - pts[i].y) <= hs) return ids[i];
    return -1;
}

// ══════════════════════════════════════════════════════════════════
// 撤销
// ══════════════════════════════════════════════════════════════════

static Snap snap_now()
{
    Snap s;
    s.ctl = g_a.form.ctl;
    s.sel = g_a.sel;
    return s;
}
static void undo_commit(const Snap& before)
{
    g_a.undo.push_back(before);
    if (g_a.undo.size() > 50) g_a.undo.erase(g_a.undo.begin());
    g_a.redo.clear();
}
static void do_undo()
{
    if (g_a.undo.empty()) return;
    Snap cur = snap_now();
    g_a.redo.push_back(cur);
    Snap s = g_a.undo.back();
    g_a.undo.pop_back();
    g_a.form.ctl = s.ctl;
    g_a.sel = s.sel;
    g_a.form.dirty = true;
}
static void do_redo()
{
    if (g_a.redo.empty()) return;
    Snap cur = snap_now();
    g_a.undo.push_back(cur);
    Snap s = g_a.redo.back();
    g_a.redo.pop_back();
    g_a.form.ctl = s.ctl;
    g_a.sel = s.sel;
    g_a.form.dirty = true;
}

// ══════════════════════════════════════════════════════════════════
// 选中
// ══════════════════════════════════════════════════════════════════

static bool is_sel(int i)
{
    for (size_t k = 0; k < g_a.sel.size(); ++k) if (g_a.sel[k] == i) return true;
    return false;
}
static void sel_only(int i)
{
    g_a.sel.clear();
    if (i >= 0) g_a.sel.push_back(i);
}
static void sel_add(int i)
{
    if (!is_sel(i)) g_a.sel.push_back(i);
}
// Shift 点击已选中的组件＝把它从选择集里摘掉（多选的标准手感）
static void sel_del(int i)
{
    for (size_t k = 0; k < g_a.sel.size(); ++k) {
        if (g_a.sel[k] == i) { g_a.sel.erase(g_a.sel.begin() + k); return; }
    }
}

// 选中变化 → 左栏强制跳回「属性」页并展开。
// 之前只在切页签时跳一次，用户手动切到「程序/支持库」后点组件就不回来了，这里补上：
// 只要在设计器页里点了组件，属性面板必须跟上（和易语言一致）。
static void props_follow_selection()
{
    if (g_a.docTab != 0) return;      // 只在设计器页生效，代码页点击不抢
    g_a.showLeft      = true;
    g_a.leftPanelOpen = true;
    g_a.leftPage      = 2;
}

// ══════════════════════════════════════════════════════════════════
// 属性表
// ══════════════════════════════════════════════════════════════════

// 基础属性用的是 e.exe 描述符池里的真实名字 0x66bdf0,0x66be04,0x66be0c,0x66be14,
// 0x66be1c,0x66be24,0x66be2c,0x66be34 —— 与 FUN_004f6df0 的「前 8 个槽」一致。
struct PropRow { const wchar_t* key; int group; };
static const PropRow PROPS[] = {
    // 保留槽：前 8 个（PROP_RESERVED）对所有组件相同
    { L"名称", 0 }, { L"标题", 0 }, { L"类名", 0 },
    { L"左边", 1 }, { L"顶边", 1 }, { L"宽度", 1 }, { L"高度", 1 },
    { L"可视", 2 },
    // 以下为按类型追加的部分（0x8000/0x2000/0x10000 三档之外的通用项）
    { L"禁止", 2 }, { L"字体", 2 }, { L"层次", 2 },
    // 第 12 个槽：凑满 PROP_SLOTS，默认显示为空
    { L"", 3 },
};
static const int PROPS_N = 12;
static_assert(PROPS_N == PROP_SLOTS, "属性槽数必须与 sub_4e8a60 的 -12 下界一致");
// 属性页已改成表格（prop_grid_draw + win_prop_rows），这组 PROPS 只留给
// 编辑提交（prop_commit）用；GROUP_NAMES / prop_value 的展示职责已删除。

static void prop_commit(int row, const std::wstring& v)
{
    if (row < 0 || row >= PROPS_N) return;
    int i = g_a.sel.empty() ? -1 : g_a.sel[0];
    if (i < 0 || i >= (int)g_a.form.ctl.size()) return;
    Ctl& c = g_a.form.ctl[i];
    const wchar_t* k = PROPS[row].key;
    if (wcscmp(k, L"名称") == 0) c.name = v;
    else if (wcscmp(k, L"标题") == 0) c.caption = v;
    else if (wcscmp(k, L"左边") == 0) c.x = (float)_wtoi(v.c_str());
    else if (wcscmp(k, L"顶边") == 0) c.y = (float)_wtoi(v.c_str());
    else if (wcscmp(k, L"宽度") == 0) { int n = _wtoi(v.c_str()); c.w = n < 4 ? 4 : (float)n; }
    else if (wcscmp(k, L"高度") == 0) { int n = _wtoi(v.c_str()); c.h = n < 4 ? 4 : (float)n; }
    else if (wcscmp(k, L"可视") == 0) c.visible = (v == L"真" || v == L"1");
    else if (wcscmp(k, L"禁止") == 0) c.enabled = !(v == L"真" || v == L"1");
    g_a.form.dirty = true;
}

// ══════════════════════════════════════════════════════════════════
// 对齐 / 分布
//
// 全部作用在「当前选中的 2 个以上组件」上，基准取选区包围盒（左对齐＝对齐到
// 最左那个的左沿，右对齐＝最右那个的右沿…），这也是 VS / 易语言设计器的习惯：
// 心里想的是「让它们都齐到这条边」，而不是「齐到第一个选中的那个」。
// 「等宽/等高/等大小」例外 —— 必须有具体尺寸可依，取第一个选中的组件做基准。
// 水平等距/垂直等距时，首尾两个不动，中间的重排成等间隙。
// ══════════════════════════════════════════════════════════════════
enum {
    AL_LEFT = 0, AL_RIGHT, AL_TOP, AL_BOTTOM, AL_HCENTER, AL_VCENTER,
    AL_EQW, AL_EQH, AL_EQSIZE, AL_HDIST, AL_VDIST
};

static void align_apply(int op)
{
    std::vector<int> ids;
    for (size_t i = 0; i < g_a.sel.size(); ++i) {
        int k = g_a.sel[i];
        if (k >= 0 && k < (int)g_a.form.ctl.size()) ids.push_back(k);
    }
    if (ids.size() < 2) {
        toast_show(L"对齐需要先选中两个以上的组件（按住 Shift 点选，或框选）", false, 2600);
        return;
    }
    Snap before = snap_now();

    // 选区包围盒 + 基准组件（第一个选中的）
    float L = 1e9f, T = 1e9f, R = -1e9f, B = -1e9f;
    for (size_t i = 0; i < ids.size(); ++i) {
        const Ctl& c = g_a.form.ctl[ids[i]];
        if (c.x         < L) L = c.x;
        if (c.y         < T) T = c.y;
        if (c.x + c.w   > R) R = c.x + c.w;
        if (c.y + c.h   > B) B = c.y + c.h;
    }
    const Ctl base = g_a.form.ctl[ids[0]];      // 等宽/等高 的尺寸来源

    if (op == AL_HDIST || op == AL_VDIST) {
        bool hz = (op == AL_HDIST);
        std::sort(ids.begin(), ids.end(), [hz](int a, int b) {
            const Ctl& x = g_a.form.ctl[a];
            const Ctl& y = g_a.form.ctl[b];
            return hz ? (x.x < y.x) : (x.y < y.y);
        });
        // 首尾固定：总跨度减去所有组件自身尺寸，剩下的平均分给 n-1 个缝
        float span = 0, sum = 0;
        for (size_t i = 0; i < ids.size(); ++i) {
            const Ctl& c = g_a.form.ctl[ids[i]];
            sum += hz ? c.w : c.h;
        }
        span = hz ? (R - L) : (B - T);
        float gap = (span - sum) / (float)(ids.size() - 1);
        float p = hz ? L : T;
        for (size_t i = 0; i < ids.size(); ++i) {
            Ctl& c = g_a.form.ctl[ids[i]];
            if (hz) { c.x = p; p += c.w + gap; }
            else    { c.y = p; p += c.h + gap; }
        }
    } else {
        for (size_t i = 0; i < ids.size(); ++i) {
            Ctl& c = g_a.form.ctl[ids[i]];
            switch (op) {
            case AL_LEFT:    c.x = L; break;
            case AL_RIGHT:   c.x = R - c.w; break;
            case AL_TOP:     c.y = T; break;
            case AL_BOTTOM:  c.y = B - c.h; break;
            case AL_HCENTER: c.x = (L + R) / 2 - c.w / 2; break;
            case AL_VCENTER: c.y = (T + B) / 2 - c.h / 2; break;
            case AL_EQW:     c.w = base.w; break;
            case AL_EQH:     c.h = base.h; break;
            case AL_EQSIZE:  c.w = base.w; c.h = base.h; break;
            default: break;
            }
        }
    }

    g_a.form.dirty = true;
    undo_commit(before);
    if (g_hwnd) InvalidateRect(g_hwnd, &rcCanvas, FALSE);
}

// ══════════════════════════════════════════════════════════════════
// 动作
// ══════════════════════════════════════════════════════════════════

// 获取组件的出厂默认属性值（如果没有写 @default，根据易语言惯例兜底）
static std::wstring get_component_default_prop(const std::wstring& propName, const LGProp* p) {
    if (p && !p->def.empty()) return p->def;
    
    if (propName == L"可视") return L"真";
    if (propName == L"禁止") return L"假";
    if (propName == L"类型") return L"0";      // 0:通常
    if (propName == L"横向对齐方式" || propName == L"对齐方式") return L"1"; // 1:居中
    if (propName == L"纵向对齐方式") return L"1"; // 1:居中
    if (propName == L"输入方式") return L"0";  // 0:通常
    if (propName == L"转换方式" || propName == L"调节器方式") return L"0";
    if (propName == L"最大允许长度") return L"0";
    if (propName == L"字体" || propName == L"字体名") return L"Microsoft YaHei UI";
    if (propName == L"字号") return L"9";
    
    // 如果有选项（@options 或 @choices），默认选第一个
    if (p) {
        if (!p->opts.empty()) {
            size_t bar = p->opts.find(L'|');
            std::wstring first = p->opts.substr(0, bar);
            // 如果是 "0:通常" 这种格式，只取冒号后面的文本，或者保留纯数字
            return first;
        }
        if (!p->choices.empty()) {
            std::wstring s = p->choices;
            size_t end = s.find_first_of(L"／/");
            std::wstring first = s.substr(0, end);
            size_t colon = first.find(L':');
            if (colon != std::wstring::npos) return first.substr(0, colon); // 返回序号
            return first;
        }
    }
    return L"";
}

static void add_control(int k)
{
    Snap before = snap_now();
    Ctl c;
    c.kind = (int)k;
    c.caption = KINDS[k].name;
    int n = 0;
    for (size_t i = 0; i < g_a.form.ctl.size(); ++i)
        if (g_a.form.ctl[i].kind == (int)k) ++n;
    c.name = std::wstring(KINDS[k].name) + wnum(n + 1);
    c.x = 24 + (float)(g_a.form.ctl.size() % 5) * 16;
    c.y = 200 + (float)(g_a.form.ctl.size() % 5) * 16;
    c.w = KINDS[k].w;
    c.h = KINDS[k].h;
    c.visible = true;
    c.enabled = true;
    c.z = (int)g_a.form.ctl.size();

    // 注入支持库声明的默认属性（出厂设置）
    const LGComp* lc = NULL;
    for (int i = 0; i < g_comp_count(); ++i) {
        // 兼容英文名(button)或中文名(按钮)匹配
        if (_wcsicmp(g_comps[i].en.c_str(), KINDS[k].cls) == 0 || 
            g_comps[i].name == KINDS[k].name) {
            lc = &g_comps[i];
            break;
        }
    }

    if (lc) {
        for (size_t i = 0; i < lc->props.size(); ++i) {
            const LGProp& p = lc->props[i];
            // 如果 @default 为空，用我们内置的出厂最优默认值兜底
            std::wstring defVal = get_component_default_prop(p.name, &p);
            if (!defVal.empty()) {
                c.props[p.name] = defVal;
            }
            // 标题为空则用组件名
            if (p.name == L"标题" && c.props[p.name].empty()) {
                c.props[p.name] = KINDS[k].name;
            }
        }
    }

    g_a.form.ctl.push_back(c);
    sel_only((int)g_a.form.ctl.size() - 1);
    g_a.form.dirty = true;
    undo_commit(before);
}

// 构建器实现在支持库段之后（要用 exe_dir / read_text_file 等）
static void build_compile_run(bool run);
static bool g_isRunning = false;
// 当前构建/调试流程的日志前缀：按 F5 跑调试版是 [调试]，发布版是 [发布]，点编译是 [编译]
// 编译器的错误/警告仍统一用 [编译器]，与流程标记区分开
static std::wstring g_buildTag = L"[编译]";
static const UINT_PTR TIMER_RUN_CHECK = 12; // 检测生成的程序是否已关闭
static const UINT_PTR TIMER_CENTER_EXPLORER = 13; // 打开目录后把 explorer 窗口居中
static DWORD g_centerExplorerDeadline = 0;
static void build_stop();

static std::map<std::wstring, std::wstring> g_propOverride;

// 新建项目统一走「新建项目」向导（要命名 + 查重名）；实现见向导那一节
static void project_wizard_open();

// 代码页交互实现在文件后段：主菜单 / 工具栏的「全选、撤销、重做」在代码页
// 也要路由到代码页自己的选区和撤销栈（不能落到设计器那套）。
static bool code_tab_active();
static void code_select_all_page();
static void code_undo_from_action();   // 实现在后：要先落当前格再撤销
static void code_redo_from_action();

static void do_action(const std::wstring& a)
{
    if (a.empty()) return;

    // 对齐 / 分布：工具条和对齐工具条都走这一条通道
    if (a.compare(0, 8, L"alignop:") == 0) {
        align_apply(_wtoi(a.c_str() + 8));
        return;
    }
    if (a == L"align.left")   { align_apply(AL_LEFT);    return; }
    if (a == L"align.center") { align_apply(AL_HCENTER); return; }

    if (a.compare(0, 4, L"ins.") == 0) {
        int k = _wtoi(a.c_str() + 4);
        if (k >= 0 && k < kind_count()) add_control(k);
        return;
    }
    if (wcscmp(a.c_str(), L"toggle") == 0) return;  // 开关在菜单里直接翻

    if (a == L"new") {
        // 以前这里直接把设计器清成白板：工程名/目录还是原来那个，
        // 自动保存一跑就把旧工程的 .epp 覆盖成空工程（源码没了），
        // 而且程序树、支持库页还挂着旧工程。改成走向导：重新命名 + 重名检查。
        project_wizard_open();
        return;
    } else if (a == L"open") {
    } else if (a == L"save") {
        g_a.form.dirty = false;
    } else if (a == L"save_as") {
        g_a.form.dirty = false;
    } else if (a == L"close") {
    } else if (a == L"quit") {
        g_a.quit = true;
    } else if (a == L"undo") {
        // 代码页走自己的撤销栈；设计器页才走设计器那套
        if (code_tab_active()) code_undo_from_action();
        else do_undo();
    } else if (a == L"redo") {
        if (code_tab_active()) code_redo_from_action();
        else do_redo();
    } else if (a == L"cut" || a == L"copy") {
    } else if (a == L"paste") {
    } else if (a == L"delete") {
        if (!g_a.sel.empty()) {
            Snap before = snap_now();
            std::vector<Ctl> keep;
            for (size_t i = 0; i < g_a.form.ctl.size(); ++i)
                if (!is_sel((int)i)) keep.push_back(g_a.form.ctl[i]);
            int n = (int)g_a.form.ctl.size() - (int)keep.size();
            g_a.form.ctl = keep;
            g_a.sel.clear();
            g_a.form.dirty = true;
            undo_commit(before);
        }
    } else if (a == L"select_all") {
        if (code_tab_active()) { code_select_all_page(); return; }
        g_a.sel.clear();
        for (size_t i = 0; i < g_a.form.ctl.size(); ++i) g_a.sel.push_back((int)i);
    } else if (a == L"zoom_in") {
        g_a.zoom = std::min(4.0f, g_a.zoom + 0.25f);
    } else if (a == L"zoom_out") {
        g_a.zoom = std::max(0.25f, g_a.zoom - 0.25f);
    } else if (a == L"zoom_reset") {
        g_a.zoom = 1.0f; g_a.panx = 0; g_a.pany = 0;
    } else if (a == L"ui_scale_in") {
        ui_scale_step(1);
    } else if (a == L"ui_scale_out") {
        ui_scale_step(-1);
    } else if (a == L"ui_scale_reset") {
        ui_scale_step(0);
    } else if (a == L"zoom_fit") {
        RECT c = canvas_content();
        float zw = (c.right - c.left) / (g_a.form.cw + 40 * g_s) * g_s;
        float zh = (c.bottom - c.top) / (g_a.form.ch + 40) * g_s;
        g_a.zoom = std::max(0.25f, std::min(4.0f, std::min(zw, zh) * g_s));
        if (g_a.zoom > 1.0f) g_a.zoom = 1.0f;
        g_a.panx = 0; g_a.pany = 0;
    } else if (a == L"theme") {
        g_themeMode = (g_themeMode + 1) % 3;
        g_themeStyle = g_theme ? 1 : 0;
        theme_refresh();
    } else if (a == L"refresh") {
    } else if (a == L"run") {
        if (g_isRunning) return;
        build_compile_run(true);
    } else if (a == L"stop") {
        if (!g_isRunning) return;
        build_stop();
    } else if (a == L"pause") {
    } else if (a == L"compile") {
        build_compile_run(false);
    } else if (a == L"about") {
    } else if (a == L"libs") {
    } else if (a == L"settings") {
    } else if (a == L"cascade") {
    } else if (a == L"tile") {
    } else {
    }
}

static void toggle_key(const std::wstring& k)
{
    if (k == L"toolbar") g_a.showToolbar = !g_a.showToolbar;
    else if (k == L"statusbar") g_a.showStatus = !g_a.showStatus;
    else if (k == L"dock.left") g_a.showLeft = !g_a.showLeft;
    else if (k == L"dock.bottom") g_a.showBottom = !g_a.showBottom;
    else if (k == L"toolbox") {
        g_a.showToolbox = !g_a.showToolbox;
        if (g_a.showToolbox) g_a.showAI = false;   // 右列一次只放一个页
    }
    // 右下角那块属性表已经删掉，属性只留在左侧栏。所以「属性表」这个开关
    // 改成切左栏到「属性」页：已经在属性页就收起内容，否则切过去并展开。
    else if (k == L"properties") {
        if (g_a.showLeft && g_a.leftPanelOpen && g_a.leftPage == 2) g_a.leftPanelOpen = false;
        else { g_a.showLeft = true; g_a.leftPanelOpen = true; g_a.leftPage = 2; }
    }
    else if (k == L"grid") g_a.form.gridOn = !g_a.form.gridOn;
    else if (k == L"snap") g_a.form.snap = !g_a.form.snap;
}

static bool chk_state(const std::wstring& k)
{
    if (k == L"toolbar") return g_a.showToolbar;
    if (k == L"statusbar") return g_a.showStatus;
    if (k == L"dock.left") return g_a.showLeft;
    if (k == L"dock.bottom") return g_a.showBottom;
    if (k == L"toolbox") return g_a.showToolbox;
    if (k == L"properties") return g_a.showLeft && g_a.leftPanelOpen && g_a.leftPage == 2;
    if (k == L"grid") return g_a.form.gridOn;
    if (k == L"snap") return g_a.form.snap;
    return false;
}

// ══════════════════════════════════════════════════════════════════
// 画标题栏
// ══════════════════════════════════════════════════════════════════

static const int WIN_BTN = 46;

// 菜单的点击矩形。paint_title 填，命中测试读，所以两处必须共用这一份。
static std::vector<RECT> g_menuRects;

// 三个窗口按钮的矩形：paint_title 填，命中和松手都读。
// 按钮「按下上膛、松手执行」，所以两边必须看同一份矩形。
static RECT g_winBtnR[3];

// 指针落在哪个窗口按钮上：0 最小化 1 最大化/还原 2 关闭，-1 都不是
static int win_btn_at(int mx, int my)
{
    for (int i = 0; i < 3; ++i)
        if (in(g_winBtnR[i], mx, my)) return i;
    return -1;
}

static void paint_title(HDC dc)
{
    fill(dc, rcTitle, g_p.window);

    // 左：EPP 金属字 logo（epp_logo.png 原样画，不跟主题重上色）。菜单紧跟其后。
    int logoEnd = 36;
    {
        bool drawn = false;
        if (g_logoBmp && g_logoBmp->GetLastStatus() == Ok) {
            Graphics g2(dc);
            g2.SetInterpolationMode(InterpolationModeHighQualityBicubic);
            g2.SetPixelOffsetMode(PixelOffsetModeHighQuality);
            REAL iw = g_logoBmp->GetWidth(), ih = g_logoBmp->GetHeight();
            int dh = (int)S(9), dw = (int)(dh * iw / ih);
            // 下移 0.05cm、右移 0.1cm（1cm≈38 DIP，0.05cm 取 2 DIP）
            RECT r = R(16, 9, dw, dh);
            g2.DrawImage(g_logoBmp, Rect(r.left, r.top, r.right - r.left, r.bottom - r.top),
                         0, 0, iw, ih, UnitPixel);
            logoEnd = 16 + dw;
            drawn = true;
        }
        if (!drawn) ico(dc, "ctl.form", R(12, 8, 16, 16));
    }

    // 菜单：与 paint_menubar 同一份 g_menuRects，所以命中测试不用改。
    // 整体右移约 0.4 厘米（96DPI 下 1cm≈37.8 DIP，从 1cm 缩回 0.6cm）。
    g_menuRects.clear();
    int x = logoEnd + S(8) + S(15);
    for (size_t i = 0; i < g_menu.size(); ++i) {
        std::wstring label = mtext(g_menu[i]);
        int w = tw(dc, label, g_f13) + S(16);
        // 右侧留给三个窗口按钮
        if (x + w > g_w - S(WIN_BTN * 3 + 8)) break;
        RECT r = R((float)x / g_s, 2, (float)w / g_s, 28);
        g_menuRects.push_back(r);

        bool open = (g_a.menuTop == (int)i);
        POINT mp; mouse_now(&mp);
        bool hot = in(r, mp.x, mp.y);
        // 悬停要有反馈，用户才知道「放在这里就会展开」
        if (open || hot) fillR(dc, r, 3, g_p.hover);
        tx(dc, label, r, g_p.text, g_f13,
           DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        x += w;
    }

    if (g_a.form.dirty) {
        int cx = rcTitle.right - S((float)(WIN_BTN * 3 + 14));
        HBRUSH b = br(g_p.warn);
        HGDIOBJ ob = SelectObject(dc, b);
        HGDIOBJ op = SelectObject(dc, GetStockObject(NULL_PEN));
        Ellipse(dc, cx - 3, RCY(rcTitle) - 3, cx + 3, RCY(rcTitle) + 3);
        SelectObject(dc, op);
        SelectObject(dc, ob);
    }

    // Windows 11 的窗口按钮：宽大于高，关闭键在右端会贴到圆角上。
    // 高度取整条标题栏，左下角与左上角都按 8px 半径收角。
    int bx = rcTitle.right - S((float)(WIN_BTN * 3));
    for (int i = 0; i < 3; ++i) {
        RECT r = R((float)(bx + S((float)(WIN_BTN * i))) / g_s, 0,
                   (float)S((float)WIN_BTN) / g_s, 29);
        g_winBtnR[i] = r;
        POINT mp; mouse_now(&mp);
        bool hot = in(r, mp.x, mp.y) && (g_offscreen || GetActiveWindow() == GetForegroundWindow());
        // 按下未松手：只有指针还停在这个键上才显示按下态，移开就熄灭
        bool down = (g_a.winBtnDown == i) && hot;
        if (down) {
            fillR(dc, r, 0, (i == 2) ? RGB(0xC4, 0x2B, 0x1C) : RGB(0x3A, 0x3A, 0x3A));
        } else if (hot) {
            if (i == 2) fillR(dc, r, 0, RGB(0xC4, 0x2B, 0x1C));
            else fillR(dc, r, 0, g_p.hover);
        }

        COLORREF fg = (hot && i == 2) ? RGB(255, 255, 255) : g_p.textDim;
        int cx = RCX(r), cy = RCY(r);
        HGDIOBJ op = SelectObject(dc, pen(fg));
        if (i == 0) {
            MoveToEx(dc, cx - 5, cy, NULL); LineTo(dc, cx + 6, cy);
        } else if (i == 1) {
            HGDIOBJ ob = SelectObject(dc, GetStockObject(NULL_BRUSH));
            Rectangle(dc, cx - 5, cy - 5, cx + 6, cy + 6);
            SelectObject(dc, ob);
        } else {
            MoveToEx(dc, cx - 5, cy - 5, NULL); LineTo(dc, cx + 5, cy + 5);
            MoveToEx(dc, cx + 5, cy - 5, NULL); LineTo(dc, cx - 5, cy + 5);
        }
        SelectObject(dc, op);
    }
}

