static std::vector<std::pair<RECT, int>> g_tbBuildMenuHits;

static void tb_group(HDC dc, const TBtn* arr, int n, int& x, float y)
{
    for (int i = 0; i < n; ++i) {
        RECT r = R((float)x / g_s, y, 24, 24);
        POINT mp; mouse_now(&mp);
        std::wstring act = arr[i].act;

        bool disabled = false;
        if (act == L"run" && g_isRunning) disabled = true;
        if (act == L"stop" && !g_isRunning) disabled = true;

        bool hot = !disabled && in(r, mp.x, mp.y);
        bool on = false;
        if (!disabled && act.compare(0, 7, L"toggle:") == 0) on = chk_state(act.substr(7));
        
        if (hot) fillR(dc, r, 4, g_p.hover);
        else if (on) fillR(dc, r, 4, g_p.accentSubtle);
        if (on) outlineR(dc, r, 4, g_p.accent);
        
        RECT ir = R((float)(x + S(4)) / g_s, y + 4, 16, 16);
        ico(dc, arr[i].icon, ir, !disabled);
        
        if (disabled) act = L"";
        g_tbHits.push_back(TbHit{ r, act, std::wstring(arr[i].tip ? arr[i].tip : L"") });
        x += S(24) + S(4);
    }
}

static void paint_tb_build_menu(HDC dc)
{
    if (!g_tbBuildMenu) return;
    POINT mp; mouse_now_real(&mp);
    
    // 阴影效果
    RECT sh = g_tbBuildPopup;
    OffsetRect(&sh, 0, S(3));
    fillR(dc, sh, 6, g_p.frame);
    
    fillR(dc, g_tbBuildPopup, 6, g_p.elevated);
    outlineR(dc, g_tbBuildPopup, 6, g_p.border);
    
    for (size_t i = 0; i < g_tbBuildMenuHits.size(); ++i) {
        RECT ir = g_tbBuildMenuHits[i].first;
        // 限制在弹层内部绘制，避免溢出
        if (ir.right > g_tbBuildPopup.right) ir.right = g_tbBuildPopup.right;
        if (ir.left < g_tbBuildPopup.left) ir.left = g_tbBuildPopup.left;
        
        bool hot = in(ir, mp.x, mp.y);
        if (hot) fillR(dc, ir, 4, g_p.hover);
        int idx = g_tbBuildMenuHits[i].second;
        const wchar_t* txt = L"";
        bool cur = false;
        if (g_tbBuildMenu == 1) {
            txt = (idx == 0) ? L"调试版" : L"发布版";
            cur = (g_buildMode == idx);
        } else {
            txt = (idx == 0) ? L"x86" : L"x64";
            cur = (g_buildArch == idx);
        }
        if (cur) {
            HGDIOBJ op = SelectObject(dc, pen(g_p.accent));
            int cxk = ir.left + S(14), cyk = RCY(ir);
            MoveToEx(dc, cxk - S(4), cyk, NULL);
            LineTo(dc, cxk, cyk + S(4));
            LineTo(dc, cxk + S(5), cyk - S(5));
            SelectObject(dc, op);
        }
        tx(dc, txt, RECT{ ir.left + S(28), ir.top, ir.right - S(8), ir.bottom }, cur ? g_p.text : g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    }
}

static void paint_toolbar(HDC dc)
{
    // 注意：清空命中表必须在「工具条关掉就返回」之前，否则关掉工具条后
    // 旧矩形还留着，点击和提示都会落在看不见的按钮上。
    g_tbHits.clear();
    g_tipHits.clear();
    if (!g_a.showToolbar) return;
    fill(dc, rcTool, g_p.bar);
    hline(dc, rcTool.left, rcTool.right, rcTool.bottom - 1, g_p.border);

    int x = S(8);
    float y = (float)(29 + (28 - 24) / 2);

    tb_group(dc, TB_GROUP1, 4, x, y);
    // 分隔
    vline(dc, x + S(5), S(29 + 6), S(29 + 22), g_p.borderSoft);
    x += S(13);
    tb_group(dc, TB_GROUP2, 2, x, y);
    vline(dc, x + S(5), S(29 + 6), S(29 + 22), g_p.borderSoft);
    x += S(13);
    tb_group(dc, TB_GROUP3, 4, x, y);
    vline(dc, x + S(5), S(29 + 6), S(29 + 22), g_p.borderSoft);
    x += S(13);
    tb_group(dc, TB_GROUP4, 4, x, y);
    vline(dc, x + S(5), S(29 + 6), S(29 + 22), g_p.borderSoft);
    x += S(13);
    tb_group(dc, TB_GROUP5, (int)(sizeof(TB_GROUP5) / sizeof(TB_GROUP5[0])), x, y);

    // 构建配置下拉框
    x += S(20); // 稍微往后挪一点
    POINT mp; mouse_now(&mp);
    int tbw = S(100), tbh = S(24); // 拉长到 100，更饱满
    
    // 模式
    RECT mrect = R((float)x / g_s, y, (float)tbw / g_s, (float)tbh / g_s);
    g_tbBuildRects[0] = mrect;
    bool mhot = in(mrect, mp.x, mp.y) || (g_tbBuildMenu == 1);
    fillR(dc, mrect, 4, mhot ? g_p.accentSubtle : g_p.input);
    outlineR(dc, mrect, 4, mhot ? g_p.accent : g_p.borderSoft);
    const wchar_t* mstr = (g_buildMode == 0) ? L"调试版" : L"发布版";
    tx(dc, mstr, RECT{ mrect.left + S(10), mrect.top, mrect.right - S(20), mrect.bottom }, mhot ? g_p.accent : g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    HGDIOBJ op = SelectObject(dc, pen(g_p.textDim));
    int cx = mrect.right - S(12), cy = RCY(mrect);
    MoveToEx(dc, cx - S(4), cy - S(2), NULL);
    LineTo(dc, cx, cy + S(2));
    LineTo(dc, cx + S(4), cy - S(2));
    SelectObject(dc, op);
    x += tbw + S(12); // 拉开一点，显得不挤

    // 架构
    RECT arect = R((float)x / g_s, y, (float)tbw / g_s, (float)tbh / g_s);
    g_tbBuildRects[1] = arect;
    bool ahot = in(arect, mp.x, mp.y) || (g_tbBuildMenu == 2);
    fillR(dc, arect, 4, ahot ? g_p.accentSubtle : g_p.input);
    outlineR(dc, arect, 4, ahot ? g_p.accent : g_p.borderSoft);
    const wchar_t* astr = (g_buildArch == 0) ? L"x86" : L"x64";
    tx(dc, astr, RECT{ arect.left + S(10), arect.top, arect.right - S(20), arect.bottom }, ahot ? g_p.accent : g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    op = SelectObject(dc, pen(g_p.textDim));
    cx = arect.right - S(12); cy = RCY(arect);
    MoveToEx(dc, cx - S(4), cy - S(2), NULL);
    LineTo(dc, cx, cy + S(2));
    LineTo(dc, cx + S(4), cy - S(2));
    SelectObject(dc, op);
    x += tbw;

    // 计算弹层位置
    if (g_tbBuildMenu > 0) {
        RECT anchor = g_tbBuildRects[g_tbBuildMenu - 1];
        int rowH = S(24); // 恢复标准行高，文字就不会被拉伸变形了
        // 动态计算最大所需宽度，确保绝对不截断
        int popW = tbw; // 弹层宽度直接等于上方按钮宽度，非常对齐
        int ph = S(8) + rowH * 2 + S(4);
        int px = anchor.left;
        int py = anchor.bottom + S(2);
        if (px + popW > g_w - S(8)) px = g_w - S(8) - popW;
        g_tbBuildPopup = RECT{ px, py, px + popW, py + ph };
        g_tbBuildMenuHits.clear();
        int iy = py + S(6);
        for (int i = 0; i < 2; ++i) {
            RECT ir = RECT{ px, iy, px + popW, iy + rowH };
            g_tbBuildMenuHits.push_back(std::make_pair(ir, i));
            iy += rowH;
        }
    }

    // 对齐 / 分布：接在工具条末尾，中间隔开几个按钮位（不是同一类操作，贴太近容易误按）。
    // 只在设计器页出现；切到程序集表格代码页时整组不画、不进命中表。
    if (!code_tab_active()) {
        x += S(24) * 2;          // 空出两格
        tb_align_group(dc, x, y);
    }

    // 右侧不再放缩放框和「− / ＋」小按钮：缩放统一走 Ctrl++ / Ctrl+- / Ctrl+0，
    // 当前比例仍在状态栏与文档页签栏右侧显示。
}

// ══════════════════════════════════════════════════════════════════
// 对齐 / 分布按钮（画在主工具条末尾）
//
// 一、只在设计器页显示：切到程序集表格代码页时这一组整个不画，
//     也不进命中表 —— 代码页上对齐组件毫无意义，还占位置。
// 二、图标是现画的矢量图形，不用图片资源：
//     一条实杠表示「基准边」，旁边几条短杠表示被对齐的组件。
//       左对齐 = 左边一条竖杠 + 往右伸三条横杠
//       右对齐 = 右边一条竖杠 + 往左伸三条横杠
//       顶对齐 = 上面一条横杠 + 往下伸三条竖杠
//       底对齐 = 下面一条横杠 + 往上伸三条竖杠
//     居中是基准杠在中间、短杠从中间往两边伸；等宽/等高/等大小画成两个同尺寸方块；
//     等距画成三条等间隙的杠。
// 三、选中不足 2 个时整组置灰且不响应点击（不隐藏：隐藏会让人以为功能没了）。
// ══════════════════════════════════════════════════════════════════
static void tb_align_icon(HDC dc, const RECT& ir, int op, bool on)
{
    // 颜色必须跟着主题走：暗色/午夜蓝/森屿绿 用浅字，浅色/暖砂 用深字，
    // 写死一个灰在换皮后必然有一半主题看不见。
    // 禁用态＝文字色往面板色里退 55%：既明显比可用态淡，又保留形状轮廓
    // （之前直接退到 textFaint，1px 细杠就碎成一串点，看着像虚线）。
    auto mix = [](COLORREF a, COLORREF b, int t) {
        return RGB(GetRValue(a) + (GetRValue(b) - GetRValue(a)) * t / 100,
                   GetGValue(a) + (GetGValue(b) - GetGValue(a)) * t / 100,
                   GetBValue(a) + (GetBValue(b) - GetBValue(a)) * t / 100);
    };
    COLORREF c = on ? g_p.text : mix(g_p.text, g_p.panel, 55);
    int l = ir.left + S(2), t = ir.top + S(2), r = ir.right - S(2), b = ir.bottom - S(2);
    if (r - l < S(8)) return;
    int cx = (l + r) / 2, cy = (t + b) / 2;

    int T  = S(2.6f); if (T < 2) T = 2;          // 普通杠粗（100% ≈ 3px）
    int G  = S(1.6f); if (G < 1) G = 1;          // 杠之间的间隙
    // 三条杠必须塞进图标高度里：塞不下就把杠和缝都收一档，否则最下面那条会被裁掉半截
    while (3 * T + 2 * G > b - t && (T > 2 || G > 1)) {
        if (T > 2) --T;
        if (G > 1) --G;
    }
    int TB = T + (T + 1) / 2;                    // 基准杠再粗一档，一眼看出「对齐到哪条边」
    int SP = 3 * T + 2 * G;                      // 三条杠的总跨度
    int top = cy - SP / 2, left = cx - SP / 2;

    // 三条等距横杠 / 竖杠
    auto barsH = [&](int x1, int x2, int y0) {
        for (int i = 0; i < 3; ++i) {
            int y = y0 + i * (T + G);
            fill(dc, RECT{ x1, y, x2, y + T }, c);
        }
    };
    auto barsV = [&](int y1, int y2, int x0) {
        for (int i = 0; i < 3; ++i) {
            int x = x0 + i * (T + G);
            fill(dc, RECT{ x, y1, x + T, y2 }, c);
        }
    };

    switch (op) {
    case AL_LEFT:
        fill(dc, RECT{ l, t, l + TB, b }, c);           // 左边一条粗竖杠
        barsH(l + TB + G, r, top);                       // 往里三条横杠
        break;
    case AL_RIGHT:
        fill(dc, RECT{ r - TB, t, r, b }, c);            // 右边一条粗竖杠
        barsH(l, r - TB - G, top);
        break;
    case AL_TOP:
        fill(dc, RECT{ l, t, r, t + TB }, c);            // 上面一条粗横杠
        barsV(t + TB + G, b, left);
        break;
    case AL_BOTTOM:
        fill(dc, RECT{ l, b - TB, r, b }, c);            // 下面一条粗横杠
        barsV(t, b - TB - G, left);
        break;
    case AL_HCENTER:                                     // 中间一条粗竖杠，横杠贯穿
        barsH(l, r, top);
        fill(dc, RECT{ cx - TB / 2, t, cx - TB / 2 + TB, b }, c);
        break;
    case AL_VCENTER:                                     // 中间一条粗横杠，竖杠贯穿
        barsV(t, b, left);
        fill(dc, RECT{ l, cy - TB / 2, r, cy - TB / 2 + TB }, c);
        break;
    case AL_EQW: {                                       // 左边粗竖杠 + 两个等宽实心块
        fill(dc, RECT{ l, t, l + TB, b }, c);
        int x1 = l + TB + G;
        int hh = (b - t - G) / 2;
        fill(dc, RECT{ x1, t, r, t + hh }, c);
        fill(dc, RECT{ x1, t + hh + G, r, t + hh + G + hh }, c);
        break;
    }
    case AL_EQH: {                                       // 上面粗横杠 + 两个等高实心块
        fill(dc, RECT{ l, t, r, t + TB }, c);
        int y1 = t + TB + G;
        int ww = (r - l - G) / 2;
        fill(dc, RECT{ l, y1, l + ww, b }, c);
        fill(dc, RECT{ l + ww + G, y1, l + ww + G + ww, b }, c);
        break;
    }
    case AL_EQSIZE: {                                    // 两个一样大的实心块
        int ww = (r - l - G) / 2;
        fill(dc, RECT{ l, t, l + ww, b }, c);
        fill(dc, RECT{ l + ww + G, t, r, b }, c);
        break;
    }
    case AL_HDIST:                                       // 三条竖杠，间隙相等
        fill(dc, RECT{ l, t, l + T, b }, c);
        fill(dc, RECT{ cx - T / 2, t, cx - T / 2 + T, b }, c);
        fill(dc, RECT{ r - T, t, r, b }, c);
        break;
    case AL_VDIST:                                       // 三条横杠，间隙相等
        fill(dc, RECT{ l, t, r, t + T }, c);
        fill(dc, RECT{ l, cy - T / 2, r, cy - T / 2 + T }, c);
        fill(dc, RECT{ l, b - T, r, b }, c);
        break;
    default: break;
    }
}

static void tb_align_group(HDC dc, int& x, float y)
{
    static const struct { int op; const wchar_t* tip; } A[] = {
        { AL_LEFT,    L"左对齐" },
        { AL_RIGHT,   L"右对齐" },
        { AL_TOP,     L"顶对齐" },
        { AL_BOTTOM,  L"底对齐" },
        { AL_HCENTER, L"水平居中" },
        { AL_VCENTER, L"垂直居中" },
        { AL_EQW,     L"等宽" },
        { AL_EQH,     L"等高" },
        { AL_EQSIZE,  L"等大小" },
        { AL_HDIST,   L"水平等距" },
        { AL_VDIST,   L"垂直等距" },
    };
    int nSel = 0;
    for (size_t i = 0; i < g_a.sel.size(); ++i)
        if (g_a.sel[i] >= 0 && g_a.sel[i] < (int)g_a.form.ctl.size()) ++nSel;
    bool on = nSel >= 2;
    const int n = (int)(sizeof(A) / sizeof(A[0]));
    for (int i = 0; i < n; ++i) {
        // 等宽/等高/等大小 和 等距 之间断开，方便一眼分组
        if (i == 6 || i == 9) {
            vline(dc, x + S(5), S(29 + 7), S(29 + 21), g_p.borderSoft);
            x += S(13);
        }
        RECT r = R((float)x / g_s, y, 24, 24);
        POINT mp; mouse_now(&mp);
        bool hot = on && in(r, mp.x, mp.y);
        if (hot) fillR(dc, r, 4, g_p.hover);
        RECT ir = R((float)(x + S(4)) / g_s, y + 4, 16, 16);
        tb_align_icon(dc, ir, A[i].op, on);

        // 提示：可用 / 灰掉（静止）两种状态都要有，但只写「这是什么」，
        // 不写「选中两个以上才可用」这类解释 —— 用户明确不要那半句。
        //   可用   → 进 g_tbHits（点一下派发 alignop:N + 悬停提示）；
        //   灰掉   → 只进 g_tipHits（只出提示、不派发，点了照旧没反应）。
        wchar_t act[32];
        swprintf(act, 32, L"alignop:%d", A[i].op);
        if (on) g_tbHits.push_back(TbHit{ r, act, std::wstring(A[i].tip) });
        else    g_tipHits.push_back(TbHit{ r, L"", std::wstring(A[i].tip) });
        x += S(24) + S(4);
    }
}

// ══════════════════════════════════════════════════════════════════
// 文档页签
// ══════════════════════════════════════════════════════════════════

// 设计器那一栏标题最右端的「位置切换」按钮：点一下就在代码编辑器上方/下方之间挪。
static RECT g_designPosBtn = RECT{ 0, 0, 0, 0 };

// 文档页签动态表：0 = 窗口1（设计器）；之后每个程序集一个表格代码页签。
static int tab_count()
{
    return 1 + (int)g_eAsms.size();
}
static std::wstring tab_name(int i)
{
    if (i <= 0) return L"_启动窗口";
    int a = i - 1;
    if (a >= 0 && a < (int)g_eAsms.size()) return g_eAsms[a].name;
    return L"?";
}
static bool code_tab_active()   // 当前页签是不是程序集表格代码页
{
    return g_a.docTab >= 1 && g_a.docTab - 1 < (int)g_eAsms.size();
}

static void paint_tabs(HDC dc)
{
    if (rcTabs.bottom <= rcTabs.top) { g_designPosBtn = RECT{ 0, 0, 0, 0 }; return; }
    fill(dc, rcTabs, g_p.bar);
    // 页签条沉到画布下方时，分隔线改画在它的顶边，否则会跟输出栏顶边重叠成一条
    if (g_a.designPos == 0) {
        hline(dc, rcTabs.left, rcTabs.right, rcTabs.bottom - 1, g_p.split);
    } else {
        hline(dc, rcTabs.left, rcTabs.right, rcTabs.top, g_p.split);
    }

    int x = rcTabs.left;
    for (int i = 0; i < tab_count(); ++i) {
        std::wstring name = tab_name(i);
        int w = tw(dc, name.c_str(), g_f12) + S(52);
        RECT r = R((float)x / g_s, (float)rcTabs.top / g_s, (float)w / g_s, 30);
        bool cur = (g_a.docTab == i);
        if (cur) {
            fill(dc, r, g_p.inner);
        }
        tx(dc, name.c_str(), R((float)(x + S(14)) / g_s, (float)rcTabs.top / g_s,
                            (float)(w - S(40)) / g_s, 30),
           cur ? g_p.text : g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        // 关闭叉
        RECT cr = R((float)(x + w - S(22)) / g_s, (float)(rcTabs.top + S(10)) / g_s, 12, 12);
        HGDIOBJ op = SelectObject(dc, pen(cur ? g_p.textDim : g_p.textFaint));
        MoveToEx(dc, cr.left + S(3), cr.top + S(3), NULL);
        LineTo(dc, cr.right - S(3), cr.bottom - S(3));
        MoveToEx(dc, cr.right - S(3), cr.top + S(3), NULL);
        LineTo(dc, cr.left + S(3), cr.bottom - S(3));
        SelectObject(dc, op);
        x += w;
        if (i != tab_count() - 1) vline(dc, x, rcTabs.top + S(7), rcTabs.bottom - S(7), g_p.borderSoft);
    }

    // 最右侧：位置切换箭头。当前在上方时给「下箭头」（点了沉到画布下方），
    // 已经沉到下方时给「上箭头」（点了回到画布上方），一个按钮两个方向，不留歧义。
    RECT b = RECT{ rcTabs.right - S(8) - S(24), rcTabs.top + S(4),
                   rcTabs.right - S(8), rcTabs.bottom - S(5) };
    g_designPosBtn = b;
    // 只登记到提示表，不参与点击派发（点击在命中表里单独判断）
    g_tipHits.push_back(TbHit{ b, std::wstring(L"design_pos"),
                               std::wstring(g_a.designPos == 0 ? L"移动到下方" : L"移动到上方") });

    // 画布信息（尺寸 / 缩放 / 网格）从画布右上角的浮层挪到标题栏右侧：
    // 原来那个浮层算成了 cc.right + 20 DIP，整体探出画布压在组件箱上。
    // 标题栏宽度不够时自动不画，别跟页签打架。
    {
        std::wstring info = wnum((int)g_a.form.cw) + L" × " + wnum((int)g_a.form.ch) +
                            L"   ·   画布 " + wnum((int)(g_a.zoom * 100)) + L"%   ·   网格 " +
                            wnum((int)g_a.form.grid);
        int bw = tw(dc, info, g_f11);
        int rx = b.left - S(8);          // 紧贴箭头成一组，别往左飘得太散
        if (rx - bw > x + S(16)) {
            RECT ir = RECT{ rx - bw, rcTabs.top + S(4), rx, rcTabs.bottom - S(5) };
            tx(dc, info, ir, g_p.textFaint, g_f11,
               DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
        }
    }

    {
        POINT mp;
        mouse_now(&mp);
        bool hot = in(b, mp.x, mp.y);
        if (hot) fillR(dc, b, 4, g_p.hover);
        COLORREF ac = hot ? g_p.text : g_p.textDim;
        HGDIOBJ op = SelectObject(dc, pen(ac));
        int cx = RCX(b), cy = RCY(b);
        if (g_a.designPos == 0) {
            // 下箭头：把这一栏沉到画布下方
            MoveToEx(dc, cx - S(5), cy - S(3), NULL);
            LineTo(dc, cx, cy + S(2));
            LineTo(dc, cx + S(5), cy - S(3));
        } else {
            // 上箭头：回到画布上方
            MoveToEx(dc, cx - S(5), cy + S(3), NULL);
            LineTo(dc, cx, cy - S(2));
            LineTo(dc, cx + S(5), cy + S(3));
        }
        SelectObject(dc, op);
    }
}

// ══════════════════════════════════════════════════════════════════
// 面板外框（标题 + 图标 + 折叠）
// ══════════════════════════════════════════════════════════════════

static void panel_head(HDC dc, RECT r, const char* icon, const wchar_t* title,
                       bool chevron = true)
{
    RECT h = r;
    h.bottom = h.top + S(28);
    // 表头用比页签条/竖排栏更亮的底色，下边线也加深：浅色主题下
    // 左栏表头、文档页签条、竖排栏原来都是 bar 同色，连成一片看不出边界。
    fill(dc, h, g_p.panel);
    hline(dc, h.left, h.right, h.bottom - 1, g_p.border);
    if (icon) ico(dc, icon, R((float)(h.left + S(8)) / g_s, (float)(h.top + S(6)) / g_s, 16, 16));
    tx(dc, title,
       R((float)(h.left + S(30)) / g_s, (float)h.top / g_s, (float)(h.right - h.left - S(60)) / g_s, 28),
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    // 折叠箭头（AI 页不用：这个位置给了「新建会话」的圆圈加号）
    if (chevron) {
        RECT ar = R((float)(h.right - S(22)) / g_s, (float)(h.top + S(10)) / g_s, 10, 10);
        HGDIOBJ op = SelectObject(dc, pen(g_p.textFaint));
        MoveToEx(dc, ar.left, ar.top + S(3), NULL);
        LineTo(dc, RCX(ar), ar.bottom - S(3));
        LineTo(dc, ar.right, ar.top + S(3));
        SelectObject(dc, op);
    }
}

