// 整个 IDE 的界面缩放（VSCode 的 Ctrl++ / Ctrl+- 那种）：
// 所有面板、菜单、图标、文字都走 S() 与 mkfonts()，所以只要改 DIP→像素系数
// 并重建字体，一处的改动全局生效。窗口物理尺寸不变，各面板按新尺寸重新排布。
// dir: +1 / -1 = 每次 5%，0 = 回到 100%。当前值先吸附到 5% 网格，
// 保证 100% 一定是可达档位（旧配置里 95/104 这种脏值也不会卡住）。
static void ui_scale_step(int dir)
{
    int cur = (int)(g_uiScale * 100 + 0.5f);
    cur = ((cur + 2) / 5) * 5;
    int pct = (dir == 0) ? 100 : cur + dir * 5;
    pct = std::max(80, std::min(200, pct));
    std::wstring msg = L"界面缩放 " + wnum(pct) + L"%   ·   Ctrl+0 回到 100%";
    if (pct == (int)(g_uiScale * 100 + 0.5f)) return;
    g_uiScale = (float)pct / 100.0f;
    g_s = g_dpiScale * g_uiScale;
    fonts_rebuild();
    g_logDx.clear();       // 输出日志字宽是按旧字体量的，字体变了必须作废
    if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
    ui_save();
}

static void libs_save_state()
{
    if (g_libs.empty()) return;   // 没扫到库就别动配置，免得把上次的记录覆盖成空
    std::wstring v;
    for (size_t i = 0; i < g_libs.size(); ++i) {
        if (!g_libs[i].loaded) continue;
        if (!v.empty()) v += L"|";
        v += g_libs[i].file;
    }
    // 一个都不加载也要写出来。写成空串会被下次启动当成「没有配置」，
    // 又把默认那几个库勾回去，用户明明全取消了却复活。
    if (v.empty()) v = L"none";
    WritePrivateProfileStringW(L"libs", L"loaded", v.c_str(), ini_file().c_str());
}

static void libs_load_state()
{
    std::wstring ini = ini_file();
    std::vector<wchar_t> buf(16384, 0);
    GetPrivateProfileStringW(L"libs", L"loaded", L"", buf.data(), 16380, ini.c_str());
    std::wstring s = buf.data();

    if (s == L"none") return;    // 用户上次把所有库都取消了
    if (s.empty()) {
        // 第一次运行：运行环境自带的库全部置为已加载（核心支持库必载）
        for (size_t i = 0; i < g_libs.size(); ++i) g_libs[i].loaded = true;
        return;
    }

    size_t p = 0;
    int matched = 0;
    while (p <= s.size()) {
        size_t q = s.find(L'|', p);
        std::wstring one = s.substr(p, (q == std::wstring::npos ? s.size() : q) - p);
        if (!one.empty()) {
            for (size_t i = 0; i < g_libs.size(); ++i)
                if (_wcsicmp(g_libs[i].file.c_str(), one.c_str()) == 0) { g_libs[i].loaded = true; ++matched; }
        }
        if (q == std::wstring::npos) break;
        p = q + 1;
    }
    // 旧配置里记的库一个都不存在（库集合换过）：按首次运行处理，全部加载，
    // 并把 ini 自愈成新库名，免得每次启动都走这个兜底
    if (matched == 0) {
        for (size_t i = 0; i < g_libs.size(); ++i) g_libs[i].loaded = true;
        libs_save_state();
    }
}

// ── 库文件定位与解析 ────────────────────────────────────────────────
// 优先 <exe>\lib（运行环境是扁平结构），回落 <exe>\..\lib。
static bool dir_exists(const std::wstring& d)
{
    DWORD a = GetFileAttributesW(d.c_str());
    return a != INVALID_FILE_ATTRIBUTES && (a & FILE_ATTRIBUTE_DIRECTORY);
}

static std::wstring lib_core_dir()
{
    std::wstring base = exe_dir();
    std::wstring d = base + L"\\lib";
    if (dir_exists(d)) return d;
    d = base + L"\\..\\lib";
    if (dir_exists(d)) return d;
    return L"";
}

static std::wstring lib_static_dir()
{
    std::wstring base = exe_dir();
    std::wstring d = base + L"\\static_lib";
    if (dir_exists(d)) return d;
    d = base + L"\\..\\static_lib";
    if (dir_exists(d)) return d;
    return L"";
}

static std::wstring trim_ws(const std::wstring& t)
{
    size_t a = 0, b = t.size();
    while (a < b && (t[a] == L' ' || t[a] == L'\t' || t[a] == L'\r' || t[a] == L'\n')) ++a;
    while (b > a && (t[b - 1] == L' ' || t[b - 1] == L'\t' || t[b - 1] == L'\r' || t[b - 1] == L'\n')) --b;
    return t.substr(a, b - a);
}

// 按分隔符拆（保留空段）
static void split_str(const std::wstring& t, wchar_t sep, std::vector<std::wstring>& out)
{
    size_t a = 0;
    while (true) {
        size_t b = t.find(sep, a);
        out.push_back(t.substr(a, (b == std::wstring::npos ? t.size() : b) - a));
        if (b == std::wstring::npos) break;
        a = b + 1;
    }
}

// ── 组件库：读 运行环境\组件库\*.ectl ────────────────────────────────
// 格式：
//   @组件 按钮
//   英文名=Button
//   @属性 名称|类型|种类|可选值(;分隔)|说明
//   @事件 名称|说明
static bool comp_dir_path(std::wstring& out)
{
    std::wstring base = exe_dir();
    std::wstring d = base + L"\\组件库";
    if (dir_exists(d)) { out = d; return true; }
    d = base + L"\\..\\组件库";
    if (dir_exists(d)) { out = d; return true; }
    return false;
}

// 组件库：每个子目录 = 一个组件支持库（运行环境\组件库\<库名>\include\*.h）。
// 支持库用 @component / @name / @type / @default / @group 注解 + SULANG_MFC_* 宏
// 声明组件、属性、方法、事件。IDE 启动时直接解析这些头文件：
// 支持库更新后只要替换文件、重启 IDE，新组件/新属性/新事件就自动出现，不用改 IDE。
static std::wstring comp_unquote(const std::wstring& s)
{
    if (s.size() >= 2 && s[0] == L'"' && s[s.size() - 1] == L'"')
        return s.substr(1, s.size() - 2);
    return s;
}

// ── 库清单 .sulib（SuLang manifest v2 风格）──────────────────────────────
// 只取库名/版本/头文件列表这几个字段，够用；不引第三方 JSON。
// 清单让「一个目录 = 一个支持库」这件事带上了 id/版本/能力声明，
// 组件箱、支持库页、构建参数都能从同一份清单读，跟苏浪的做法一致。
static std::wstring json_get_str(const std::wstring& js, const std::wstring& key)
{
    std::wstring pat = L"\"" + key + L"\"";
    size_t p = 0;
    while ((p = js.find(pat, p)) != std::wstring::npos) {
        size_t q = p + pat.size();
        while (q < js.size() && (js[q] == L' ' || js[q] == L'\t' || js[q] == L'\r' || js[q] == L'\n')) ++q;
        if (q >= js.size() || js[q] != L':') { p = q; continue; }
        ++q;
        while (q < js.size() && (js[q] == L' ' || js[q] == L'\t' || js[q] == L'\r' || js[q] == L'\n')) ++q;
        if (q < js.size() && js[q] == L'"') {
            ++q;
            std::wstring out;
            while (q < js.size() && js[q] != L'"') {
                if (js[q] == L'\\' && q + 1 < js.size()) {
                    ++q;
                    if (js[q] == L'n') out += L'\n';
                    else if (js[q] == L't') out += L'\t';
                    else out += js[q];
                } else out += js[q];
                ++q;
            }
            return out;
        }
        size_t e = q;
        while (e < js.size() && js[e] != L',' && js[e] != L'}' && js[e] != L'\n') ++e;
        return trim_ws(js.substr(q, e - q));
    }
    return L"";
}

// 读清单里的字符串数组字段：headers:["a","b"] → {"a","b"}
static std::vector<std::wstring> json_get_list(const std::wstring& js, const std::wstring& key)
{
    std::vector<std::wstring> out;
    std::wstring pat = L"\"" + key + L"\"";
    size_t p = js.find(pat);
    if (p == std::wstring::npos) return out;
    p = js.find(L'[', p);
    if (p == std::wstring::npos) return out;
    size_t e = js.find(L']', p);
    if (e == std::wstring::npos) e = js.size();
    size_t q = p;
    while (q < e) {
        size_t a = js.find(L'"', q);
        if (a == std::wstring::npos || a >= e) break;
        size_t b = js.find(L'"', a + 1);
        if (b == std::wstring::npos || b > e) break;
        out.push_back(js.substr(a + 1, b - a - 1));
        q = b + 1;
    }
    return out;
}

static bool file_exists(const std::wstring& p)
{
    DWORD a = GetFileAttributesW(p.c_str());
    return a != INVALID_FILE_ATTRIBUTES && !(a & FILE_ATTRIBUTE_DIRECTORY);
}

// 属性在属性表里用什么控件：0 文本 1 真假 2 下拉 3 资源
// 全按支持库头文件里写的 @type 决定：带「(选择)」就是下拉（候选值来自 @options），
// 只有图片/图标/字体/光标/音乐/文件这类要挑资源的才走 3；颜色当文本，直接填 #RRGGBB。
// IDE 不针对任何单个组件写规则，组件库加新组件不用改这里。
enum PValKind { PVText, PVCombo, PVBool, PVFile, PVColor, PVCursor };

static bool g_colorPickerOpen = false;
static RECT g_colorPickerAnchor = { 0, 0, 0, 0 };
static const wchar_t* g_colorPickerName = NULL;
