// ── 左侧竖排页签：程序 / 支持库 / 属性（不画图标，直接竖着排字）────────
static const wchar_t* PAGE_NAMES[3] = { L"程序", L"支持库", L"属性" };
static const char* PAGE_ICONS[3] = { "panel.programTree", "tree.module", "panel.properties" };

static void paint_sidebar(HDC dc)
{
    if (!g_a.showLeft) { g_settingsBtn = RECT{ 0, 0, 0, 0 }; return; }
    fill(dc, rcSideBar, g_p.bar);
    // 竖排页签栏与内容面板之间的那条线：原来用 frame 画，和两侧底色几乎一样，等于没画
    vline(dc, rcSideBar.right - 1, rcSideBar.top, rcSideBar.bottom, g_p.split);

    g_sideHits.clear();
    POINT mp;
    mouse_now(&mp);

    float y = (float)rcSideBar.top / g_s + 6;
    for (int i = 0; i < 3; ++i) {
        int n = (int)wcslen(PAGE_NAMES[i]);
        float w = (float)SIDEBAR_W - 6;
        float h = (float)n * 15.0f + 14.0f;
        RECT r = R((float)rcSideBar.left / g_s + 3, y, w, h);
        bool act = (g_a.leftPage == i);
        bool open = act && g_a.leftPanelOpen;
        bool hot = in(r, mp.x, mp.y);
        if (open) {
            RECT bar = RECT{ rcSideBar.left, r.top + S(3), rcSideBar.left + S(2), r.bottom - S(3) };
            fill(dc, bar, g_p.accent);
            fillR(dc, r, 4, g_p.accentSubtle);
        } else if (hot) {
            fillR(dc, r, 4, g_p.hover);
        }
        // 中文竖排就是一列一字，比转 90° 好读
        for (int c = 0; c < n; ++c) {
            RECT cr = RECT{ r.left, r.top + S(7 + c * 15), r.right, r.top + S(7 + (c + 1) * 15) };
            tx(dc, std::wstring(1, PAGE_NAMES[i][c]), cr,
               (act || hot) ? g_p.text : g_p.textDim, g_f12,
               DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        }
        g_sideHits.push_back(std::make_pair(r, i));
        y += h + 6;
    }

    // 最下边常驻的设置齿轮：点开就弹设置面板
    {
        RECT s = RECT{ rcSideBar.left + S(3), rcSideBar.bottom - S(38),
                       rcSideBar.right - S(3), rcSideBar.bottom - S(6) };
        g_settingsBtn = s;
        bool hot = in(s, mp.x, mp.y) || g_settingsOpen;
        if (hot) fillR(dc, s, 4, g_p.hover);
        if (g_settingsOpen) {
            RECT bar = RECT{ rcSideBar.left, s.top + S(3),
                             rcSideBar.left + S(2), s.bottom - S(3) };
            fill(dc, bar, g_p.accent);
        }
        ico(dc, "cmd.settings",
            R((float)(RCX(s) - S(9)) / g_s, (float)(RCY(s) - S(9)) / g_s, 18, 18));
        g_tipHits.push_back(TbHit{ s, std::wstring(), std::wstring(L"设置") });
    }
}

// ── 右侧竖排页签栏（组件箱 / AI）─────────────────────────────────
// 中文竖排（一列一字），但「AI」这种拉丁词不拆字，整词横排居中——
// 拆成 A 一行 I 一行就认不出来了。
static std::vector<std::pair<RECT, int> > g_rsideHits;
static const wchar_t* RPAGE_NAMES[2] = { L"组件箱", L"AI" };

static void paint_sidebar_r(HDC dc)
{
    if (rcSideBarR.right <= rcSideBarR.left) { g_rsideHits.clear(); return; }
    fill(dc, rcSideBarR, g_p.bar);
    vline(dc, rcSideBarR.left, rcSideBarR.top, rcSideBarR.bottom, g_p.split);

    g_rsideHits.clear();
    POINT mp;
    mouse_now(&mp);

    bool shown[2] = { g_a.showToolbox, g_a.showAI };
    float y = (float)rcSideBarR.top / g_s + 6;
    for (int i = 0; i < 2; ++i) {
        int n = (int)wcslen(RPAGE_NAMES[i]);
        bool latin = true;
        for (int c = 0; c < n; ++c)
            if (RPAGE_NAMES[i][c] > 0x7F) { latin = false; break; }

        float w = (float)SIDEBAR_W - 6;
        float h = latin ? 22.0f : (float)n * 15.0f + 14.0f;
        RECT r = R((float)rcSideBarR.left / g_s + 3, y, w, h);
        bool act = shown[i];
        bool hot = in(r, mp.x, mp.y);
        if (act) {
            RECT bar = RECT{ rcSideBarR.right - S(2), r.top + S(3),
                             rcSideBarR.right, r.bottom - S(3) };
            fill(dc, bar, g_p.accent);
            fillR(dc, r, 4, g_p.accentSubtle);
        } else if (hot) {
            fillR(dc, r, 4, g_p.hover);
        }
        COLORREF tc = (act || hot) ? g_p.text : g_p.textDim;
        if (latin) {
            tx(dc, RPAGE_NAMES[i], r, tc, g_f12, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        } else {
            for (int c = 0; c < n; ++c) {
                RECT cr = RECT{ r.left, r.top + S(7 + c * 15), r.right,
                                r.top + S(7 + (c + 1) * 15) };
                tx(dc, std::wstring(1, RPAGE_NAMES[i][c]), cr, tc, g_f12,
                   DT_CENTER | DT_VCENTER | DT_SINGLELINE);
            }
        }
        g_rsideHits.push_back(std::make_pair(r, i));
        y += h + 6;
    }
}

