// 折行测量：返回排版后的实际宽高（像素）
static void ai_measure(HDC dc, const std::wstring& s, HFONT f, int w, int* ow, int* oh)
{
    HGDIOBJ o = SelectObject(dc, f);
    RECT r = { 0, 0, w, 0 };
    DrawTextW(dc, s.c_str(), (int)s.size(), &r, DT_WORDBREAK | DT_CALCRECT | DT_NOPREFIX);
    SelectObject(dc, o);
    if (ow) *ow = r.right - r.left;
    if (oh) *oh = r.bottom - r.top;
}

static void paint_ai(HDC dc)
{
    RECT zr = RECT{ 0, 0, 0, 0 };
    g_aiGear = g_aiNewBtn = g_aiModelBtn = g_aiInputBox = g_aiSendBtn = zr;
    g_aiChipHits.clear();
    g_aiModelHits.clear();
    if (!g_a.showAI) { g_aiMenu = false; g_aiInputActive = false; return; }
    if (rcPalette.right <= rcPalette.left) return;
    if (g_aiMsgText.empty()) {           // 首次进入先铺三条演示消息
        for (int i = 0; i < AI_DEMO_N; ++i) {
            g_aiMsgText.push_back(AI_DEMO[i].text);
            g_aiMsgMe.push_back(AI_DEMO[i].me);
        }
    }

    fill(dc, rcRightSplit, g_p.split);
    fill(dc, rcPalette, g_p.inner);
    panel_head(dc, rcPalette, "tree.method", L"AI 助手", false);

    POINT mp;
    mouse_now(&mp);

    // 标题栏右侧（和原来的箭头/齿轮对调后）：
    //   左：圆圈加号＝新建会话（原来的向下箭头位置换成它）
    //   右：齿轮＝AI 设置（挪到了原来箭头的位置）
    RECT hd = RECT{ rcPalette.left, rcPalette.top, rcPalette.right, rcPalette.top + S(28) };
    g_aiNewBtn = RECT{ hd.right - S(54), hd.top + S(5), hd.right - S(36), hd.bottom - S(5) };
    g_aiGear   = RECT{ hd.right - S(26), hd.top + S(6), hd.right - S(10), hd.bottom - S(6) };
    if (in(g_aiNewBtn, mp.x, mp.y)) fillR(dc, g_aiNewBtn, 9, g_p.hover);
    if (in(g_aiGear, mp.x, mp.y)) fillR(dc, g_aiGear, 4, g_p.hover);
    {
        // 圆圈里边一个加号
        HGDIOBJ op = SelectObject(dc, pen(g_p.textDim));
        HGDIOBJ ob = SelectObject(dc, GetStockObject(NULL_BRUSH));
        Ellipse(dc, g_aiNewBtn.left, g_aiNewBtn.top, g_aiNewBtn.right, g_aiNewBtn.bottom);
        SelectObject(dc, ob);
        SelectObject(dc, op);
        int cx = RCX(g_aiNewBtn), cy = RCY(g_aiNewBtn);
        HGDIOBJ op2 = SelectObject(dc, pen(g_p.text));
        MoveToEx(dc, cx - S(4), cy, NULL);          LineTo(dc, cx + S(4), cy);
        MoveToEx(dc, cx, cy - S(4), NULL);          LineTo(dc, cx, cy + S(4));
        SelectObject(dc, op2);
    }
    ico(dc, "cmd.settings", g_aiGear);

    float x0 = (float)rcPalette.left / g_s + 10.0f;
    float x1 = (float)rcPalette.right / g_s - 10.0f;
    float cw = x1 - x0;
    // 标题是「AI 助手」，顶部不单独放按钮行，对话区直接从标题下开始
    float y  = (float)(rcPalette.top + S(28)) / g_s + 8.0f;
    float yb = (float)rcPalette.bottom / g_s;

    // ── 自下往上排版：快捷键行与输入框先定位，剩下的都留给对话区 ──
    float chipH = 22.0f, cgap = 6.0f;
    int rows = 1;
    {
        float used = 0;
        for (int i = 0; i < AI_CHIP_N; ++i) {
            float w = (float)twd(dc, AI_CHIPS[i], g_f11) / g_s + 18.0f;
            if (used > 0 && used + w > cw) { rows++; used = 0; }
            used += w + cgap;
        }
    }
    float chipsH = (float)rows * chipH + (float)(rows - 1) * cgap;
    float rowH   = 22.0f;          // 底行：模型下拉（左）+ 提示（右）
    float inH    = 58.0f;
    float rowY   = yb - 10.0f - rowH;
    float inY    = rowY - 6.0f - inH;
    float chipsY = inY - 8.0f - chipsH;

    // ── 对话气泡 ───────────────────────────────────────────────
    float msgW = cw - 26.0f;
    int   tpw  = S(msgW) - S(18);
    float cy = y;
    for (size_t i = 0; i < g_aiMsgText.size(); ++i) {
        const std::wstring& t = g_aiMsgText[i];
        int tw2 = 0, th2 = 0;
        ai_measure(dc, t, g_f12, tpw, &tw2, &th2);
        float bwd = (float)(tw2 + S(18)) / g_s;
        if (bwd > msgW) bwd = msgW;
        if (bwd < 44.0f) bwd = 44.0f;
        float bhd = (float)th2 / g_s + 16.0f;
        if (cy + bhd > chipsY - 6.0f) break;   // 空间不够就少画，别糊到输入框上

        bool me = g_aiMsgMe[i];
        float bl = me ? (x1 - 18.0f - 6.0f - bwd) : (x0 + 18.0f + 6.0f);
        RECT bub = R(bl, cy, bwd, bhd);
        RECT avt = me ? R(x1 - 18.0f, cy, 18.0f, 18.0f) : R(x0, cy, 18.0f, 18.0f);

        fillR(dc, bub, 7, me ? g_p.accentSubtle : g_p.elevated);
        if (!me) outlineR(dc, bub, 7, g_p.borderSoft);
        RECT tr = RECT{ bub.left + S(9), bub.top + S(8), bub.right - S(9), bub.bottom - S(8) };
        tx(dc, t, tr, g_p.text, g_f12, DT_LEFT | DT_TOP | DT_WORDBREAK | DT_NOPREFIX);

        fillR(dc, avt, 9, me ? g_p.accent : g_p.accentSubtle);
        tx(dc, me ? L"我" : L"AI", avt, me ? RGB(0xFF, 0xFF, 0xFF) : g_p.accent,
           g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);

        cy += bhd + 10.0f;
    }

    // ── 快捷指令（窄了就换行）──────────────────────────────────
    {
        float cx = x0, cyy = chipsY;
        for (int i = 0; i < AI_CHIP_N; ++i) {
            float w = (float)twd(dc, AI_CHIPS[i], g_f11) / g_s + 18.0f;
            if (cx > x0 && cx + w > x1) { cx = x0; cyy += chipH + cgap; }
            RECT cr = R(cx, cyy, w, chipH);
            bool hot = in(cr, mp.x, mp.y);
            fillR(dc, cr, 11, hot ? g_p.accentSubtle : g_p.elevated);
            outlineR(dc, cr, 11, hot ? g_p.accent : g_p.borderSoft);
            tx(dc, AI_CHIPS[i], cr, hot ? g_p.text : g_p.textDim, g_f11,
               DT_CENTER | DT_VCENTER | DT_SINGLELINE);
            g_aiChipHits.push_back(std::make_pair(cr, i));
            cx += w + cgap;
        }
    }

    // ── 输入框 + 发送 ──────────────────────────────────────────
    g_aiInputBox = R(x0, inY, cw, inH);
    fillR(dc, g_aiInputBox, 6, g_p.input);
    outlineR(dc, g_aiInputBox, 6, g_aiInputActive ? g_p.accent : g_p.border);
    RECT txr = RECT{ g_aiInputBox.left + S(9), g_aiInputBox.top + S(8),
                     g_aiInputBox.right - S(34), g_aiInputBox.bottom - S(8) };
    if (g_aiInput.empty()) {
        tx(dc, L"给 AI 发消息…（演示界面）", txr, g_p.textFaint, g_f12,
           DT_LEFT | DT_TOP | DT_WORDBREAK);
    } else {
        tx(dc, g_aiInput, txr, g_p.text, g_f12, DT_LEFT | DT_TOP | DT_WORDBREAK);
    }
    if (g_aiInputActive) {
        // 光标：按最后一行文字宽度定位，只是示意，不做真编辑
        std::wstring last = g_aiInput;
        size_t p = last.find_last_of(L'\n');
        if (p != std::wstring::npos) last = last.substr(p + 1);
        int lines = 1;
        for (size_t k = 0; k < g_aiInput.size(); ++k) if (g_aiInput[k] == L'\n') lines++;
        int cxp = txr.left + twd(dc, last, g_f12) + S(1);
        if (cxp > txr.right) cxp = txr.right;
        int cyp = txr.top + S(17) * (lines - 1);
        vline(dc, cxp, cyp, cyp + S(15), g_p.accent);
    }

    g_aiSendBtn = R(x1 - 28.0f, inY + inH - 30.0f, 22.0f, 22.0f);
    bool empty = g_aiInput.empty();
    bool shot = in(g_aiSendBtn, mp.x, mp.y);
    fillR(dc, g_aiSendBtn, 11, empty ? g_p.elevated : (shot ? g_p.accent : g_p.accentSubtle));
    {
        COLORREF ac = empty ? g_p.textFaint : (shot ? RGB(0xFF, 0xFF, 0xFF) : g_p.accent);
        HGDIOBJ op = SelectObject(dc, pen(ac));
        int cxs = RCX(g_aiSendBtn), cys = RCY(g_aiSendBtn);
        MoveToEx(dc, cxs, cys + S(5), NULL);
        LineTo(dc, cxs, cys - S(5));
        MoveToEx(dc, cxs - S(4), cys - S(1), NULL);
        LineTo(dc, cxs, cys - S(5));
        LineTo(dc, cxs + S(4), cys - S(1));
        SelectObject(dc, op);
    }
    // ── 底行：模型下拉（左）。（提示文字挪走：288 宽的面板扣掉模型钮
    //    只剩 80 来 DIP，Enter 发送那一长串放不下，右对齐会从左边裁掉。）──
    float mbW = (cw < 200.0f) ? cw : 170.0f;
    g_aiModelBtn = R(x0, rowY, mbW, rowH);
    {
        bool mhot = in(g_aiModelBtn, mp.x, mp.y) || g_aiMenu;
        fillR(dc, g_aiModelBtn, 5, mhot ? g_p.elevated : g_p.panel);
        outlineR(dc, g_aiModelBtn, 5, g_aiMenu ? g_p.accent : g_p.border);
        tx(dc, AI_MODELS[g_aiModel], R(x0 + 8.0f, rowY, mbW - 24.0f, rowH),
           g_p.text, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        int ax = g_aiModelBtn.right - S(12), ay = RCY(g_aiModelBtn);
        HGDIOBJ op = SelectObject(dc, pen(g_p.textDim));
        MoveToEx(dc, ax - S(4), ay - S(2), NULL);
        LineTo(dc, ax, ay + S(2));
        LineTo(dc, ax + S(4), ay - S(2));
        SelectObject(dc, op);
    }

    // ── 模型下拉（向上弹，压在输入框/对话区上面，最后画）───────
    if (g_aiMenu) {
        int ihh = S(26);
        int ph = S(8) + ihh * AI_MODEL_N;
        RECT pop = RECT{ g_aiModelBtn.left,
                         g_aiModelBtn.top - S(2) - ph,
                         g_aiModelBtn.right,
                         g_aiModelBtn.top - S(2) };
        fillR(dc, pop, 5, g_p.elevated);
        outlineR(dc, pop, 5, g_p.border);
        for (int i = 0; i < AI_MODEL_N; ++i) {
            RECT ir = RECT{ pop.left + S(4), pop.top + S(4) + ihh * i,
                            pop.right - S(4), pop.top + S(4) + ihh * (i + 1) };
            if (in(ir, mp.x, mp.y)) fillR(dc, ir, 3, g_p.hover);
            if (i == g_aiModel) {
                HGDIOBJ op = SelectObject(dc, pen(g_p.accent));
                int cxk = ir.left + S(9), cyk = RCY(ir) + S(1);
                MoveToEx(dc, cxk - S(3), cyk - S(1), NULL);
                LineTo(dc, cxk, cyk + S(2));
                LineTo(dc, cxk + S(4), cyk - S(4));
                SelectObject(dc, op);
            }
            tx(dc, AI_MODELS[i], RECT{ ir.left + S(18), ir.top, ir.right - S(4), ir.bottom },
               i == g_aiModel ? g_p.text : g_p.textDim, g_f12,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            g_aiModelHits.push_back(std::make_pair(ir, i));
        }
    }
}

// ── 页签 1：程序（程序数据树）──────────────────────────────────────
struct PNode {
    std::wstring text;
    const char* icon;
    int  id;
    bool open;
    std::vector<PNode> kids;
};

static std::vector<PNode> g_prog;

static PNode pnode(const wchar_t* t, const char* ic, int id, bool open)
{
    PNode n;
    n.text = t;
    n.icon = ic;
    n.id = id;
    n.open = open;
    return n;
}

static void prog_build()
{
    if (!g_prog.empty()) return;
    PNode root = pnode(L"程序数据", "panel.programTree", 0, true);

    // .e 源码导入内容（严格照易语言的程序数据树：第一层固定「程序数据」，
    // 程序集直接挂根下、按 .e 原始顺序，分类节点全部默认收起）
    if (!g_eAsms.empty()) {
        root.text = L"程序数据";   // 易语言里没有「项目名」这一层，根就是程序数据

        // ── 程序集（每个直接挂根下，收起，原始顺序；没有「程序集」夹层）──
        for (size_t i = 0; i < g_eAsms.size(); ++i) {
            PNode a = pnode(g_eAsms[i].name.c_str(), "tree.class", 100 + (int)i, false);
            for (size_t j = 0; j < g_eAsms[i].subs.size(); ++j) {
                std::wstring t = g_eAsms[i].subs[j].name;
                if (!g_eAsms[i].subs[j].ret.empty()) t += L" (" + g_eAsms[i].subs[j].ret + L")";
                a.kids.push_back(pnode(t.c_str(), "tree.method", 100000 + (int)i * 1000 + (int)j, false));
            }
            root.kids.push_back(a);
        }

        // ── 全局变量 ──
        PNode catGv = pnode(L"全局变量", "tree.field", 22, false);
        for (size_t j = 0; j < g_eGlobals.size(); ++j) {
            std::wstring t = g_eGlobals[j].name;
            if (!g_eGlobals[j].type.empty()) t += L"，" + g_eGlobals[j].type;
            catGv.kids.push_back(pnode(t.c_str(), "tree.property", 9000 + (int)j, false));
        }
        root.kids.push_back(catGv);

        // ── 自定义数据类型 ──
        PNode catTp = pnode(L"自定义数据类型", "tree.class", 24, false);
        for (size_t j = 0; j < g_eTypes.size(); ++j)
            catTp.kids.push_back(pnode(g_eTypes[j].c_str(), "tree.class", 9200 + (int)j, false));
        root.kids.push_back(catTp);

        // ── 窗口 ──
        PNode catWin = pnode(L"窗口", "ctl.form", 20, false);
        for (size_t j = 0; j < g_eWindows.size(); ++j)
            catWin.kids.push_back(pnode(g_eWindows[j].c_str(), "ctl.form", 2000 + (int)j, false));
        root.kids.push_back(catWin);

        // ── 常量表...（叶子，双击以后跳常量表页）──
        root.kids.push_back(pnode(L"常量表...", "tree.constant", 23, false));

        // ── 资源表：里面永远只有默认两行——一个声音、一个图片或图片组
        //     （同易语言；具体资源不往树里摆）──
        PNode catRs = pnode(L"资源表", "tree.field", 26, false);
        catRs.kids.push_back(pnode(L"声音...", "tree.property", 9750, false));
        catRs.kids.push_back(pnode(L"图片或图片组...", "ctl.picture", 9751, false));
        root.kids.push_back(catRs);

        // ── 模块引用表：只有源码里有 .ec 模块才有内容；
        //     .fne 支持库不进来（那些归「支持库」页管）──
        PNode catMd = pnode(L"模块引用表", "tree.module", 5, false);
        for (size_t j = 0; j < g_eLibs.size(); ++j)
            if (g_eLibs[j].kind != L"elib")
                catMd.kids.push_back(pnode(g_eLibs[j].name.c_str(), "tree.module", 9100 + (int)j, false));
        root.kids.push_back(catMd);

        // ── 外部文件记录表（叶子）──
        root.kids.push_back(pnode(L"外部文件记录表", "tree.property", 6, false));

        g_prog.push_back(root);
        return;
    }

    PNode asm1 = pnode(L"窗口程序集_启动窗口", "tree.class", 1, true);
    asm1.kids.push_back(pnode(L"窗口", "ctl.form", 2, false));
    asm1.kids.push_back(pnode(L"常量表...", "tree.constant", 3, false));
    root.kids.push_back(asm1);
    root.kids.push_back(pnode(L"资源表", "tree.field", 4, false));
    root.kids.push_back(pnode(L"模块引用表", "tree.module", 5, false));
    root.kids.push_back(pnode(L"外部文件记录表", "tree.property", 6, false));
    g_prog.push_back(root);
}

static PNode* prog_find(std::vector<PNode>& v, int id)
{
    for (size_t i = 0; i < v.size(); ++i) {
        if (v[i].id == id) return &v[i];
        PNode* k = prog_find(v[i].kids, id);
        if (k) return k;
    }
    return NULL;
}

// 程序树内容总行数（只算展开出来的行），滚动上限用
static int prog_rows(const std::vector<PNode>& v)
{
    int n = (int)v.size();
    for (size_t i = 0; i < v.size(); ++i)
        if (v[i].open && !v[i].kids.empty()) n += prog_rows(v[i].kids);
    return n;
}

static int g_progContentH = 0;   // 内容总高（像素），滚轮算上限用
static RECT g_progSbTrack = RECT{ 0, 0, 0, 0 };   // 纵向滚动条轨道（右侧细条）
static RECT g_progSbThumb = RECT{ 0, 0, 0, 0 };   // 滑块

static void prog_draw(HDC dc, std::vector<PNode>& v, int depth, float& y,
                      float topY, float floorY)
{
    const float ROW = 22;
    for (size_t i = 0; i < v.size(); ++i) {
        PNode& n = v[i];
        bool vis = (y + ROW > topY && y < floorY);   // 滚出去的行不画、不接命中
        if (vis) {
            float ind = (float)(depth * 14);
            float L = (float)(rcLeftPanel.left + S(8)) / g_s + ind;
            float W = (float)(rcLeftPanel.right - rcLeftPanel.left - S(16)) / g_s - ind;

            RECT r = R(L, y, W, ROW);
            POINT mp;
            mouse_now(&mp);
            bool sel = (g_a.progSel == n.id);
            // 右键菜单开着时树行不做悬停高亮——不然指针划过菜单，
            // 底下的行跟着亮，看着像鼠标穿透了菜单
            if (sel) fillR(dc, r, 3, g_p.accentSubtle);
            else if (g_progMenuNode < 0 && in(r, mp.x, mp.y)) fillR(dc, r, 3, g_p.hover);

            if (!n.kids.empty()) {
                // 树形框式 ➕/➖ 小方框（不是箭头）
                RECT er = R(L + 2, y + 6, 11, 11);
                fillR(dc, er, 2, g_p.elevated);
                outlineR(dc, er, 2, g_p.textFaint);
                HGDIOBJ op = SelectObject(dc, pen(g_p.textDim));
                int bl = (int)er.left, bt = (int)er.top, br = (int)er.right, bb = (int)er.bottom;
                int mx = (bl + br) / 2, my = (bt + bb) / 2;
                MoveToEx(dc, bl + S(3), my, NULL);  LineTo(dc, br - S(2), my);   // 横线：＋和－都有
                if (!n.open) {
                    MoveToEx(dc, mx, bt + S(3), NULL); LineTo(dc, mx, bb - S(2)); // 竖线：收起时才是＋
                }
                SelectObject(dc, op);
                g_progExp.push_back(std::make_pair(er, n.id));
            }
            ico(dc, n.icon, R(L + 15, y + 3, 16, 16));
            tx(dc, n.text, R(L + 36, y, W - 36, ROW),
               (depth == 0) ? g_p.text : g_p.textDim, g_f12,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            g_progHits.push_back(std::make_pair(r, n.id));
        }
        y += ROW;
        // 滚动后视口外整段子树可以整枝跳过（行高固定 22，一段的高 = 行数×22）
        if (n.open && !n.kids.empty()) {
            if (y < topY && y + prog_rows(n.kids) * ROW < topY) {
                y += prog_rows(n.kids) * ROW;   // 整段都在视口上方，直接跳
            } else {
                prog_draw(dc, n.kids, depth + 1, y, topY, floorY);
            }
        }
    }
}

// 左栏底行的矩形（paint_left_bottom / paint_left_program / paint_left_lib 都要用，
// 这里先给个声明，定义在「左栏底行」那一节）
static RECT left_bottom_row();

static void paint_left_program(HDC dc)
{
    prog_build();
    float topY = (float)(rcLeftPanel.top + S(32)) / g_s;
    // 底行（搜索框）占了 30，树别画进去
    float floorY = (float)left_bottom_row().top / g_s - S(6);
    float viewH = floorY - topY;

    // 纵向滚动：内容超出视口才有得滚；收起节点后每帧把滚动量收紧
    int rows = prog_rows(g_prog);
    g_progContentH = (int)(rows * 22 * g_s);
    int viewPx = (int)(viewH * g_s);
    int maxS = std::max(0, g_progContentH - viewPx);
    if (g_a.progScroll > maxS) g_a.progScroll = maxS;
    if (g_a.progScroll < 0) g_a.progScroll = 0;
    float scroll = (float)g_a.progScroll / g_s;

    // 树只在页签标题下面这块里画：滚到一半的行不能糊到面板标题、底行上
    int saved = SaveDC(dc);
    IntersectClipRect(dc, rcLeftPanel.left, (int)(topY * g_s) - 1,
                      rcLeftPanel.right, (int)(floorY * g_s) + 1);
    float y = topY - scroll;
    prog_draw(dc, g_prog, 0, y, topY, floorY);
    RestoreDC(dc, saved);

    // 纵向滚动条（右侧细条）：内容超高才出现，滑块按比例缩放
    g_progSbTrack = g_progSbThumb = RECT{ 0, 0, 0, 0 };
    if (maxS > 0) {
        int trackTop = rcLeftPanel.top + S(34), trackBot = (int)(floorY * g_s) - S(2);
        int bx = rcLeftPanel.right - S(6);
        g_progSbTrack = RECT{ bx, trackTop, bx + S(4), trackBot };
        int track = trackBot - trackTop;
        int thumbH = std::max(S(24), (int)((float)track * viewPx / g_progContentH + 0.5f));
        int ty = trackTop + (int)((float)(track - thumbH) * g_a.progScroll / maxS + 0.5f);
        g_progSbThumb = RECT{ bx, ty, bx + S(4), ty + thumbH };
        fillR(dc, g_progSbTrack, 2, g_p.panel);
        POINT mp; mouse_now(&mp);
        bool hot = in(g_progSbTrack, mp.x, mp.y);
        fillR(dc, g_progSbThumb, 2, hot ? g_p.accent : g_p.border);
    }
}

// ══════════════════════════════════════════════════════════════════
// 左栏底行（三页共用）
//   程序页 / 支持库页：搜索框（支持库页输入即过滤 + 自动定位到命令）
//   属性页：组件事件下拉（选了只改显示，不生成事件代码）
// 内容区下沿一律取这行的上沿：设计器页签条沉底（designPos=1）时，
// 这条线正好和下沉页签条的底边、输出栏顶边取齐。
// ══════════════════════════════════════════════════════════════════
static RECT g_leftSearchRect = RECT{ 0, 0, 0, 0 };
static bool g_progSearchActive = false, g_libSearchActive = false;
static wchar_t g_progSearch[61] = { 0 }, g_libSearch[61] = { 0 };
// IME 组字中的拼音/候选：叠加到查询与显示上，提交后由 WM_CHAR 落进 g_libSearch
static std::wstring g_libImeComp;
// 左栏搜索框：程序页 / 支持库页共用一套光标与选区状态（同时只有一个框激活）
static int   g_srCaret  = 0;      // 插入点（字符下标）
static int   g_srAnchor = -1;     // 选区锚点，-1＝无选区
static bool  g_srBlink  = true;   // 光标闪烁
static bool  g_srDrag   = false;  // 鼠标拖选中
static const UINT_PTR TIMER_SR_CARET = 8;   // 光标闪烁定时器
// 搜索范围下拉（贴在搜索框右边）：按钮矩形 + 弹出项命中表
static bool  g_libComboOpen = false;
static RECT  g_libComboRect = RECT{ 0, 0, 0, 0 };
static std::vector<std::pair<RECT, int> > g_libComboHits;
// 当前生效的查询（已去首尾空白 + 小写）。绘制过滤、扁平表、搜索定位全用它，
// 保证三处规则永远一致。
static std::wstring lib_query()
{
    // IME 组字中的拼音只显示在框里，不参与查询（拼音串匹配不到中文命令名）；
    // 提交成汉字后由 WM_CHAR 落进 g_libSearch，那时才重算结果。
    std::wstring q = g_libSearch;
    q = trim_ws(q);
    for (size_t i = 0; i < q.size(); ++i) q[i] = (wchar_t)towlower(q[i]);
    return q;
}
static RECT g_eventBtn = RECT{ 0, 0, 0, 0 };              // 属性页「事件」下拉按钮
static std::vector<std::pair<RECT, int> > g_eventHits;   // 事件下拉项
static int  g_eventSel  = 0;                              // 当前事件（纯界面状态）
static bool g_eventMenu = false;

// 窗口的常见事件（按易语言 IDE 事件下拉的顺序取的子集）
// 属性页当前对应的组件元数据：选中组件就是它，否则是「窗口」。
// 属性表格、事件下拉都从这里取——不针对单个组件 / 单个支持库写专用代码，
// 支持库里有什么属性、什么事件，界面就出什么。
static const LGComp* prop_comp_now()
{
    if (!g_a.sel.empty() && g_a.sel[0] >= 0 && g_a.sel[0] < (int)g_a.form.ctl.size()) {
        int k = g_a.form.ctl[g_a.sel[0]].kind;
        if (k >= 0 && k < kind_count() && KINDS[k].comp >= 0 && KINDS[k].comp < g_comp_count())
            return &g_comps[KINDS[k].comp];
        return NULL;
    }
    return lg_comp(L"窗口");
}

// 事件名列表（同一份数据，绘制下拉和点击取项共用）
static const std::vector<std::wstring>& prop_event_names()
{
    static std::vector<std::wstring> names;
    names.clear();
    const LGComp* g = prop_comp_now();
    if (g)
        for (size_t i = 0; i < g->evs.size(); ++i) names.push_back(g->evs[i].name);
    if (names.empty()) names.push_back(L"（无事件）");
    return names;
}

static RECT left_bottom_row()
{
    RECT r = rcLeftPanel;
    // 30 = 文档页签条（TABH）同高：页签条沉底时两条线上下取齐，不再一头高一头矮
    r.top = r.bottom - S(30);
    return r;
}

// ── 支持库树键盘导航 ────────────────────────────────────────────────
// 绘制用的 g_libNodes 只装屏幕内的行；↑↓ 需要「全部逻辑可见行」的顺序表
// （含滚出屏幕的）。每次按键现算，规则与 paint_left_lib 完全同构：同样的
// 已加载/未加载 分组、同样的 open 状态与搜索过滤，行高共用 LIB_* 常量。
// 成员分组的显示顺序：易语言原版树里是「命令（方法）在最前面，然后属性，最后事件」。
// LType 内部按 props/evts/meths 存，sec 编号也是 0 属性 / 1 事件 / 2 方法（图标、
// 选中态 kind=5/6/7 都跟着 sec 走），所以这里只给一份「显示序」，
// 遍历按它走，sec 仍然拿真实编号——排列变了，编号和图标不乱。
static const int LIB_MEM_SEC_ORDER[3] = { 2, 0, 1 };   // 方法 → 属性 → 事件

static void lib_flat_build()
{
    g_libFlat.clear();
    if (g_libs.empty() || !g_libNote.empty()) return;
    std::vector<int> on, off;
    for (size_t i = 0; i < g_libs.size(); ++i)
        (g_libs[i].loaded ? on : off).push_back((int)i);
    std::wstring q = lib_query();
    bool qw = !q.empty();
    auto add = [](int kind, int lib, int cat, int cmd, float y, float h) {
        LibNode n; n.kind = kind; n.lib = lib; n.cat = cat; n.cmd = cmd;
        n.r = RECT{ 0, (int)y, 0, (int)(y + h) };   // DIP 布局坐标，不随滚动变
        g_libFlat.push_back(n);
    };
    float y = 4;                                     // 绘制 cy = top + 4 - scroll
    for (int grp = 0; grp < 2; ++grp) {
        const std::vector<int>& rows = (grp == 0) ? on : off;
        if (rows.empty()) continue;
        y += LIB_HDR;                                // 分组头不可选，只占位
        if (!g_a.libGroupOpen[grp] && !qw) { y += LIB_GAP; continue; }
        for (size_t k = 0; k < rows.size(); ++k) {
            const int i = rows[k];
            LibItem& lb = g_libs[i];
            add(0, i, -1, -1, y, LIB_ROW); y += LIB_ROW;
            if (!lb.open && !qw) continue;      // 搜索时库强制展开，否则命中命令画不出来
            for (size_t ci = 0; ci < lb.cats.size(); ++ci) {
                LCat& cat = lb.cats[ci];
                std::vector<int> hit;
                for (size_t ki = 0; ki < cat.cmds.size(); ++ki)
                    if (lib_cmd_match(cat.cmds[ki], q)) hit.push_back((int)ki);
                if (hit.empty()) continue;
                bool cOpen = cat.open || !q.empty();
                add(1, i, (int)ci, -1, y, LIB_CAT); y += LIB_CAT;
                if (!cOpen) continue;
                for (size_t hi = 0; hi < hit.size(); ++hi) {
                    add(2, i, (int)ci, hit[hi], y, LIB_CMD); y += LIB_CMD;
                }
            }
            // 先算命中：一条都没有就整组不画（连行高都不占），避免出现空壳分组
            std::vector<int> hitT;
            for (size_t ti = 0; ti < lb.types.size(); ++ti)
                if (lib_type_match(lb.types[ti], q)) hitT.push_back((int)ti);
            if (!hitT.empty()) {
                bool tOpen = lb.typeOpen || qw;
                add(3, i, -1, -1, y, LIB_CAT); y += LIB_CAT;
                if (tOpen) {
                    for (size_t hi = 0; hi < hitT.size(); ++hi) {
                        const int ti = hitT[hi];
                        LType& ty = lb.types[ti];
                        bool mOpen = ty.open || qw;
                        add(4, i, ti, -1, y, LIB_CMD); y += LIB_CMD;
                        if (!mOpen) continue;
                        const std::vector<LMem>* g3[3] = { &ty.props, &ty.evts, &ty.meths };
                        for (int oi = 0; oi < 3; ++oi) {
                            const int sec = LIB_MEM_SEC_ORDER[oi];   // 方法 → 属性 → 事件
                            for (size_t mi = 0; mi < g3[sec]->size(); ++mi) {
                                const LMem& mem = (*g3[sec])[mi];
                                if (!lib_mem_match(mem, q)) continue;
                                add(5 + sec, i, ti, (int)mi, y, LIB_CMD); y += LIB_CMD;
                            }
                        }
                    }
                }
            }
            std::vector<int> hitC;
            for (size_t qi = 0; qi < lb.consts.size(); ++qi)
                if (lib_const_match(lb.consts[qi], q)) hitC.push_back((int)qi);
            if (!hitC.empty()) {
                bool kOpen = lb.constOpen || qw;
                add(8, i, -1, -1, y, LIB_CAT); y += LIB_CAT;
                if (kOpen)
                    for (size_t hi = 0; hi < hitC.size(); ++hi) {
                        add(9, i, hitC[hi], -1, y, LIB_CMD); y += LIB_CMD;
                    }
            }
        }
        y += LIB_GAP;
    }
}

static int lib_flat_index_of_cur()
{
    for (size_t i = 0; i < g_libFlat.size(); ++i)
        if (lib_is_cur(g_libFlat[i].kind, g_libFlat[i].lib,
                       g_libFlat[i].cat, g_libFlat[i].cmd)) return (int)i;
    return -1;
}

static void lib_sel_clear()
{
    g_a.libSel = -1;
    g_libCmdSelLib = g_libCmdSelCat = g_libCmdSelCmd = -1;
    g_libTypeSelLib = g_libTypeSel = -1;
    g_libMemSelKind = 0; g_libMemSel = -1;
    g_libConstSelLib = g_libConstSel = -1;
}

// 选中一个节点：统一游标 + 清掉其它分支高亮 + 提示页（跟鼠标点击一个效果）。
// toggle=true 时顺带切换可展开节点的展开状态（回车 / 左右键用）。
static void lib_select_node(const LibNode& nd, bool toggle)
{
    lib_cur_set(nd);
    lib_sel_clear();
    const int i = nd.lib;
    if (i < 0 || i >= (int)g_libs.size()) return;
    LibItem& lb = g_libs[i];
    switch (nd.kind) {
    case 0:                                   // 库
        g_a.libSel = i;
        lib_info_tip(i);
        if (toggle) lb.open = !lb.open;
        break;
    case 1:                                   // 分类
        if (toggle && nd.cat >= 0 && nd.cat < (int)lb.cats.size())
            lb.cats[nd.cat].open = !lb.cats[nd.cat].open;
        break;
    case 2:                                   // 命令
        g_libCmdSelLib = i; g_libCmdSelCat = nd.cat; g_libCmdSelCmd = nd.cmd;
        lib_cmd_tip(i, nd.cat, nd.cmd);
        break;
    case 3:                                   // 数据类型（组）
        if (toggle) lb.typeOpen = !lb.typeOpen;
        break;
    case 4:                                   // 数据类型
        g_libTypeSelLib = i; g_libTypeSel = nd.cat; g_libMemSel = -1;
        lib_cmd_tip(i, -1, -1, nd.cat);
        if (toggle && nd.cat >= 0 && nd.cat < (int)lb.types.size())
            lb.types[nd.cat].open = !lb.types[nd.cat].open;
        break;
    case 5: case 6: case 7:                   // 属性 / 事件 / 方法
        g_libTypeSelLib = i; g_libTypeSel = nd.cat;
        g_libMemSelKind = nd.kind - 4;
        g_libMemSel = nd.cmd;
        lib_cmd_tip(i, -1, -1, nd.cat, nd.kind - 5, nd.cmd);
        break;
    case 8:                                   // 常量（组）
        if (toggle) lb.constOpen = !lb.constOpen;
        break;
    case 9:                                   // 常量
        g_libConstSelLib = i; g_libConstSel = nd.cat;
        lib_const_tip(i, nd.cat);
        break;
    }
}

static bool lib_node_open(const LibNode& nd)
{
    if (nd.lib < 0 || nd.lib >= (int)g_libs.size()) return false;
    const LibItem& lb = g_libs[nd.lib];
    switch (nd.kind) {
    case 0: return lb.open;
    case 1: return nd.cat >= 0 && nd.cat < (int)lb.cats.size() &&
                   (lb.cats[nd.cat].open || !lib_query().empty());
    case 3: return lb.typeOpen || !lib_query().empty();
    case 4: return nd.cat >= 0 && nd.cat < (int)lb.types.size() &&
                   (lb.types[nd.cat].open || !lib_query().empty());
    case 8: return lb.constOpen || !lib_query().empty();
    }
    return false;
}

// 把选中行滚进可视区：节点 r 里是从列表起点算的 DIP 坐标
static void lib_scroll_to(const LibNode& nd)
{
    int listTop = rcLeftPanel.top + S(LIB_HDR);
    int listBot = left_bottom_row().top - S(6);
    int rowTop  = listTop + S(4) - g_a.libScroll + S((float)nd.r.top);
    int rowBot  = rowTop + S((float)(nd.r.bottom - nd.r.top));
    if (rowTop < listTop)      lib_scroll_by(rowTop - listTop);
    else if (rowBot > listBot) lib_scroll_by(rowBot - listBot);
}

// 返回 true＝这个键已被支持库树吃掉，别再落到设计器
static bool lib_key_nav(WPARAM vk)
{
    if (g_a.leftPage != 1 || !g_a.showLeft || !g_a.leftPanelOpen) return false;
    // 启动向导的输入框是原生 EDIT 子窗口，按键不会落到主窗口，无需额外判断
    if (g_libSearchActive || g_settingsOpen || g_a.menuTop >= 0) return false;
    bool up = vk == VK_UP, down = vk == VK_DOWN;
    bool enter = vk == VK_RETURN, left = vk == VK_LEFT, right = vk == VK_RIGHT;
    bool home = vk == VK_HOME, end = vk == VK_END;
    if (!(up || down || enter || left || right || home || end)) return false;

    lib_flat_build();
    if (g_libFlat.empty()) return true;
    int idx = lib_flat_index_of_cur();
    if (idx < 0) {                            // 还没选过：定位到第一条
        lib_select_node(g_libFlat[0], false);
        lib_scroll_to(g_libFlat[0]);
        return true;
    }
    if (up || down || home || end) {
        int n = (int)g_libFlat.size();
        if (home) idx = 0;
        else if (end) idx = n - 1;
        else idx += (down ? 1 : -1);
        if (idx < 0) idx = 0;
        if (idx >= n) idx = n - 1;
        lib_select_node(g_libFlat[idx], false);
        lib_scroll_to(g_libFlat[idx]);
        return true;
    }
    const LibNode nd = g_libFlat[idx];
    bool expandable = (nd.kind <= 4 || nd.kind == 8);   // 库/分类/类型组/类型/常量组
    if (enter) {
        lib_select_node(nd, expandable);
    } else if (expandable) {
        bool open = lib_node_open(nd);
        if ((right && !open) || (left && open)) lib_select_node(nd, true);
    }
    return true;
}

// ── 支持库搜索：结果集 + 在支持库树里定位 ──────────────────────────
// 搜索只在支持库树里过滤 + 选中 + 滚到可见；提示页照常显示选中命令的
// 信息段/参数段（跟鼠标点命令一个效果），不额外画一套结果列表，省一帧绘制。
struct LibSearchHit { int kind, lib, cat, cmd, score; };   // kind 同 LibNode：2 命令 / 5·6·7 属性·事件·方法 / 9 常量
static std::vector<LibSearchHit> g_libSearchHits;
static int  g_libSearchPos = -1;

// 成员（属性/事件/方法）的匹配分数。字段分派必须跟 lib_mem_match 一致：
// 命令＝名字类（成员名、参数名），备注＝说明类（成员说明、参数说明），不限＝两边+模糊。
static int lib_mem_score(const LMem& m, const std::wstring& q)
{
    if (q.empty()) return 1;
    int s = 0;
    if (g_libSearchMode != 1) {
        int t = lib_text_score(m.name, q);
        if (t >= 2) s += (t == 4 ? 900 : t == 3 ? 500 : 300);
        else if (g_libSearchMode == 2 && t == 1) s += 150;
        for (size_t i = 0; i < m.params.size(); ++i)
            if (lib_text_score(m.params[i].name, q) >= 2) s += 50;
    }
    if (g_libSearchMode != 0) {
        if (lib_text_score(m.desc, q) >= 2) s += 60;
        for (size_t i = 0; i < m.params.size(); ++i)
            if (lib_text_score(m.params[i].desc, q) >= 2) s += 40;
    }
    return s;
}
static int lib_const_score(const LConst& c, const std::wstring& q)
{
    if (q.empty()) return 1;
    int s = 0;
    if (g_libSearchMode != 1) {
        int t = lib_text_score(c.name, q);
        if (t >= 2) s += (t == 4 ? 880 : t == 3 ? 480 : 280);
        else if (g_libSearchMode == 2 && t == 1) s += 150;
        if (lib_text_score(c.en, q) >= 2) s += 120;
    }
    if (g_libSearchMode != 0 && lib_text_score(c.desc, q) >= 2) s += 50;
    return s;
}

static std::vector<LibSearchHit> lib_search_collect(const std::wstring& q)
{
    std::vector<LibSearchHit> v;
    if (q.empty()) return v;
    for (size_t i = 0; i < g_libs.size(); ++i) {
        const LibItem& lb = g_libs[i];
        for (size_t c = 0; c < lb.cats.size(); ++c)
            for (size_t k = 0; k < lb.cats[c].cmds.size(); ++k) {
                int sc = lib_cmd_score(lb.cats[c].cmds[k], q);
                if (sc > 0) v.push_back(LibSearchHit{ 2, (int)i, (int)c, (int)k, sc });
            }
        // 数据类型下的属性/事件/方法（成员命令就在 窗口→方法 里，见 公共方法.h）
        for (size_t t = 0; t < lb.types.size(); ++t) {
            const std::vector<LMem>* g[3] = { &lb.types[t].props, &lb.types[t].evts,
                                              &lb.types[t].meths };
            for (int sec = 0; sec < 3; ++sec)
                for (size_t mi = 0; mi < g[sec]->size(); ++mi) {
                    const LMem& m = (*g[sec])[mi];
                    if (!lib_mem_match(m, q)) continue;
                    int sc = lib_mem_score(m, q);
                    v.push_back(LibSearchHit{ 5 + sec, (int)i, (int)t, (int)mi, sc > 0 ? sc : 1 });
                }
        }
        for (size_t ci = 0; ci < lb.consts.size(); ++ci) {
            if (!lib_const_match(lb.consts[ci], q)) continue;
            int sc = lib_const_score(lb.consts[ci], q);
            v.push_back(LibSearchHit{ 9, (int)i, (int)ci, -1, sc > 0 ? sc : 1 });
        }
    }
    // 高分在前（完全同名 ＞ 前缀 ＞ 子串 ＞ 模糊 ＞ 只命中注释）；
    // 同分时命令优先于数据类型成员/常量，再按库原序，稳定。
    std::stable_sort(v.begin(), v.end(), [](const LibSearchHit& a, const LibSearchHit& b) {
        if (a.score != b.score) return a.score > b.score;
        bool ca = (a.kind == 2), cb = (b.kind == 2);
        if (ca != cb) return ca;
        if (a.lib != b.lib) return a.lib < b.lib;
        if (a.kind != b.kind) return a.kind < b.kind;
        if (a.cat != b.cat) return a.cat < b.cat;
        return a.cmd < b.cmd;
    });
    return v;
}

// 定位到第 pos 条命中（越界回到 0，循环）：在支持库树里展开路径、
// 选中该节点并滚进可视区，提示页照常出详情（＝模拟鼠标点了一下）
static void lib_search_locate(int pos)
{
    if (g_libSearchHits.empty()) return;
    int n = (int)g_libSearchHits.size();
    if (pos < 0 || pos >= n) pos = 0;
    g_libSearchPos = pos;
    const LibSearchHit& h = g_libSearchHits[pos];
    if (h.lib < 0 || h.lib >= (int)g_libs.size()) return;
    LibItem& lb = g_libs[h.lib];
    g_a.leftPage = 1;
    g_a.libGroupOpen[0] = g_a.libGroupOpen[1] = true;
    lb.open = true;
    LibNode nd;
    nd.kind = h.kind; nd.lib = h.lib; nd.cat = -1; nd.cmd = -1;
    nd.r = RECT{ 0, 0, 0, 0 };
    if (h.kind == 2) {                                   // 命令
        if (h.cat < 0 || h.cat >= (int)lb.cats.size() ||
            h.cmd < 0 || h.cmd >= (int)lb.cats[h.cat].cmds.size()) return;
        lb.cats[h.cat].open = true;
        nd.cat = h.cat; nd.cmd = h.cmd;
    } else if (h.kind >= 5 && h.kind <= 7) {             // 属性 / 事件 / 方法
        if (h.cat < 0 || h.cat >= (int)lb.types.size()) return;
        lb.typeOpen = true;
        lb.types[h.cat].open = true;
        nd.cat = h.cat; nd.cmd = h.cmd;
    } else if (h.kind == 9) {                            // 常量
        if (h.cat < 0 || h.cat >= (int)lb.consts.size()) return;
        lb.constOpen = true;
        nd.cat = h.cat;
    } else return;
    lib_select_node(nd, false);            // 选中 + 提示页详情（命令信息段/参数段，成员同理）
    g_tipScroll = 0;
    lib_flat_build();                     // 扁平表带 DIP 坐标，滚到该行
    for (size_t i = 0; i < g_libFlat.size(); ++i)
        if (lib_is_cur(g_libFlat[i].kind, g_libFlat[i].lib,
                       g_libFlat[i].cat, g_libFlat[i].cmd)) {
            lib_scroll_to(g_libFlat[i]);
            break;
        }
}

// 查询变了就重算结果并自动定位第一条；清空时只清结果，不动展开状态
static void lib_search_apply()
{
    std::wstring q = lib_query();
    g_libSearchHits = lib_search_collect(q);
    g_libSearchPos = -1;
    if (!g_libSearchHits.empty()) lib_search_locate(0);
}

// 外部入口：给一个关键字就定位（命令行 / 以后代码编辑器取词查命令）
static bool lib_locate_keyword(const std::wstring& kw)
{
    lstrcpynW(g_libSearch, kw.c_str(), 61);
    g_libImeComp.clear();
    g_srCaret = (int)wcslen(g_libSearch); g_srAnchor = -1;
    g_a.leftPage = 1;
    lib_search_apply();
    return !g_libSearchHits.empty();
}

// ── 左栏搜索框：光标 / 选区 / 编辑 ──────────────────────────────────
// 程序页与支持库页共用一套状态：同一时刻只有 sr_buf() 指向的那个框激活。
static wchar_t* sr_buf()
{
    if (g_progSearchActive && g_a.leftPage == 0) return g_progSearch;
    if (g_libSearchActive  && g_a.leftPage == 1) return g_libSearch;
    return NULL;
}
static bool sr_is_lib() { return g_libSearchActive && g_a.leftPage == 1; }
static int  sr_len()    { wchar_t* b = sr_buf(); return b ? (int)wcslen(b) : 0; }
static void sr_clamp()
{
    int n = sr_len();
    if (g_srCaret < 0) g_srCaret = 0;
    if (g_srCaret > n) g_srCaret = n;
    if (g_srAnchor > n) g_srAnchor = n;
}
static bool sr_has_sel() { return g_srAnchor >= 0 && g_srAnchor != g_srCaret; }
static void sr_sel(int& a, int& b)
{
    a = g_srAnchor < g_srCaret ? g_srAnchor : g_srCaret;
    b = g_srAnchor > g_srCaret ? g_srAnchor : g_srCaret;
}
static void sr_activate(bool prog)
{
    g_progSearchActive = prog;
    g_libSearchActive  = !prog;
    g_srAnchor = -1;
    g_srCaret  = sr_len();          // 点击后 on_lbutton_down 会按 x 重新定位
    g_srBlink  = true;
    if (g_hwnd) SetTimer(g_hwnd, TIMER_SR_CARET, 530, NULL);
}
static void sr_deactivate()
{
    g_progSearchActive = g_libSearchActive = false;
    g_srAnchor = -1;
    g_srDrag   = false;
    if (g_hwnd) KillTimer(g_hwnd, TIMER_SR_CARET);
}
static void sr_after_edit()          // 文本变了：支持库页重算结果并回树里定位
{
    g_libImeComp.clear();
    if (sr_is_lib()) lib_search_apply();
}
// 删除选区；无选区时 forward＝Delete 删后一个、否则退格删前一个
static bool sr_delete(bool forward)
{
    wchar_t* b = sr_buf(); if (!b) return false;
    sr_clamp();
    std::wstring s(b);
    int a = g_srCaret, z = g_srCaret;
    if (sr_has_sel())     sr_sel(a, z);
    else if (forward)   { if (z >= (int)s.size()) return false; z = a + 1; }
    else                { if (a <= 0) return false; a = z - 1; }
    s.erase(a, z - a);
    lstrcpynW(b, s.c_str(), 61);
    g_srCaret = a; g_srAnchor = -1; g_srBlink = true;
    return true;
}
// 在光标处插入文字（有选区就先替换掉）
static void sr_insert(const std::wstring& ins)
{
    wchar_t* b = sr_buf(); if (!b) return;
    sr_clamp();
    std::wstring s(b);
    int a = g_srCaret, z = g_srCaret;
    if (sr_has_sel()) sr_sel(a, z);
    s = s.substr(0, a) + ins + s.substr(z);
    if (s.size() > 60) s.resize(60);
    lstrcpynW(b, s.c_str(), 61);
    g_srCaret = a + (int)ins.size();
    sr_clamp();
    g_srAnchor = -1; g_srBlink = true;
}
static std::wstring sr_selected_text()
{
    wchar_t* b = sr_buf(); if (!b || !sr_has_sel()) return L"";
    int a, z; sr_sel(a, z);
    return std::wstring(b).substr(a, z - a);
}
static std::wstring sr_clip_get()
{
    std::wstring out;
    if (!OpenClipboard(g_hwnd)) return out;
    HANDLE h = GetClipboardData(CF_UNICODETEXT);
    if (h) {
        const wchar_t* p = (const wchar_t*)GlobalLock(h);
        if (p) { out = p; GlobalUnlock(h); }
    }
    CloseClipboard();
    std::wstring clean;
    for (size_t i = 0; i < out.size(); ++i) if (out[i] >= 32) clean += out[i];
    return clean;
}
// 鼠标 x → 字符下标：临时取 DC 用搜索框字体逐字量
static int sr_x_to_caret(int px)
{
    wchar_t* b = sr_buf(); if (!b) return 0;
    HDC dc = GetDC(g_hwnd); if (!dc) return 0;
    HGDIOBJ old = SelectObject(dc, g_f12);
    std::wstring s(b);
    int x0 = g_leftSearchRect.left + S(26) + S(2);
    int best = 0, bestd = 0x7fffffff;
    for (int i = 0; i <= (int)s.size(); ++i) {
        SIZE sz = { 0, 0 };
        GetTextExtentPoint32W(dc, s.c_str(), i, &sz);
        int d = abs(px - (x0 + sz.cx));
        if (d < bestd) { bestd = d; best = i; }
    }
    SelectObject(dc, old);
    ReleaseDC(g_hwnd, dc);
    return best;
}
static int sr_text_w(HDC dc, const std::wstring& s, int n)
{
    if (n <= 0) return 0;
    if (n > (int)s.size()) n = (int)s.size();
    return twd(dc, s.substr(0, n).c_str(), g_f12);
}
// 搜索框按键：编辑键 + 结果导航。返回 true＝这个键已被吃掉
static bool sr_key(WPARAM vk, bool ctrl, bool shift)
{
    // 点搜索框以外会 sr_deactivate()，所以能走到这里就一定处在编辑态
    if (!sr_buf()) return false;
    if (ctrl && vk == 'A') {                       // Ctrl+A 全选
        g_srAnchor = 0; g_srCaret = sr_len(); g_srBlink = true; return true;
    }
    if (ctrl && vk == 'C') { tip_copy_text(sr_selected_text()); return true; }
    if (ctrl && vk == 'X') {
        std::wstring t = sr_selected_text();
        if (!t.empty()) { tip_copy_text(t); if (sr_delete(false)) sr_after_edit(); }
        return true;
    }
    if (ctrl && vk == 'V') {
        std::wstring t = sr_clip_get();
        if (!t.empty()) { sr_insert(t); sr_after_edit(); }
        return true;
    }
    if (vk == VK_ESCAPE) {                         // 脱选 → 再按退出编辑
        if (sr_has_sel()) { g_srAnchor = -1; return true; }
        sr_deactivate();
        return true;
    }
    if (vk == VK_BACK || vk == VK_DELETE) {        // 单删 / 删选区
        if (sr_delete(vk == VK_DELETE)) sr_after_edit();
        return true;
    }
    if (vk == VK_LEFT || vk == VK_RIGHT || vk == VK_HOME || vk == VK_END) {
        sr_clamp();
        bool had = sr_has_sel();
        int a = 0, z = 0;
        if (had) sr_sel(a, z);
        if (shift) {
            if (g_srAnchor < 0) g_srAnchor = g_srCaret;
            if (vk == VK_LEFT)  g_srCaret = std::max(0, g_srCaret - 1);
            if (vk == VK_RIGHT) g_srCaret = std::min(sr_len(), g_srCaret + 1);
            if (vk == VK_HOME)  g_srCaret = 0;
            if (vk == VK_END)   g_srCaret = sr_len();
        } else if (had) {                          // 有选区：一次只取消选择
            g_srAnchor = -1;
            g_srCaret = (vk == VK_LEFT || vk == VK_HOME) ? a : z;
            if (vk == VK_HOME) g_srCaret = 0;
            if (vk == VK_END)  g_srCaret = sr_len();
        } else {
            if (vk == VK_LEFT)  g_srCaret = std::max(0, g_srCaret - 1);
            if (vk == VK_RIGHT) g_srCaret = std::min(sr_len(), g_srCaret + 1);
            if (vk == VK_HOME)  g_srCaret = 0;
            if (vk == VK_END)   g_srCaret = sr_len();
        }
        g_srBlink = true;
        return true;
    }
    // ↑↓ / 回车 / F3：在搜索结果间定位（支持库页，树里选中并滚过去）
    if (sr_is_lib() && (vk == VK_RETURN || vk == VK_DOWN || vk == VK_UP || vk == VK_F3)) {
        if (g_libSearchHits.empty()) return true;
        int p = g_libSearchPos;
        bool back = (vk == VK_UP) || (vk == VK_F3 && shift);
        p = back ? (p <= 0 ? (int)g_libSearchHits.size() - 1 : p - 1)
                 : (p + 1) % (int)g_libSearchHits.size();
        lib_search_locate(p);
        return true;
    }
    return false;
}

// 提示面板不再为搜索单独画一套结果列表：树里定位选中后，
// 由 lib_cmd_tip 照常出命令信息段 + 参数段（与点击命令完全一致）。

static void paint_left_bottom(HDC dc)
{
    g_leftSearchRect = RECT{ 0, 0, 0, 0 };
    g_libComboRect = RECT{ 0, 0, 0, 0 };
    g_libComboHits.clear();
    g_eventBtn = RECT{ 0, 0, 0, 0 };
    g_eventHits.clear();
    RECT row = left_bottom_row();
    if (row.bottom <= row.top) return;
    fill(dc, row, g_p.bar);
    hline(dc, row.left, row.right, row.top, g_p.borderSoft);

    POINT mp;
    mouse_now_real(&mp); // 事件下拉框内部需要真实鼠标坐标来高亮
    float L = (float)(row.left + S(6)) / g_s;
    float W = (float)(row.right - row.left - S(12)) / g_s;
    // 行高缩到 30 之后，框尽量占满：上下只留 3，左右只留 6
    RECT b = R(L, (float)(row.top + S(3)) / g_s, W, 24);

    if (g_a.leftPage == 2) {
        // 组件事件下拉
        g_eventBtn = b;
        bool hot = in(b, mp.x, mp.y) || g_eventMenu;
        fillR(dc, b, 4, hot ? g_p.elevated : g_p.panel);
        outlineR(dc, b, 4, g_eventMenu ? g_p.accent : g_p.border);
        const std::vector<std::wstring>& evs = prop_event_names();
        if (g_eventSel < 0 || g_eventSel >= (int)evs.size()) g_eventSel = 0;
        tx(dc, std::wstring(L"事件：") + evs[g_eventSel],
           R(L + 8.0f, (float)(row.top + S(3)) / g_s, W - 22.0f, 24.0f),
           g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        int ax = b.right - S(13), ay = RCY(b);
        HGDIOBJ op = SelectObject(dc, pen(g_p.textDim));
        MoveToEx(dc, ax - S(4), ay - S(2), NULL);
        LineTo(dc, ax, ay + S(2));
        LineTo(dc, ax + S(4), ay - S(2));
        SelectObject(dc, op);

        if (g_eventMenu) {
            int ih = S(24);
            int topLim = rcLeftPanel.top + S(30);            // 别盖住面板标题
            int room = b.top - S(2) - topLim;
            int n = (room - S(8)) / ih;
            if (n > (int)evs.size()) n = (int)evs.size();
            if (n < 1) n = 1;
            int ph = S(8) + ih * n;
            RECT pop = RECT{ b.left, b.top - S(2) - ph, b.right, b.top - S(2) };
            fillR(dc, pop, 5, g_p.elevated);
            outlineR(dc, pop, 5, g_p.border);
            for (int i = 0; i < n; ++i) {
                RECT ir = RECT{ pop.left + S(4), pop.top + S(4) + ih * i,
                                pop.right - S(4), pop.top + S(4) + ih * (i + 1) };
                if (in(ir, mp.x, mp.y)) fillR(dc, ir, 3, g_p.hover);
                if (i == g_eventSel) {
                    HGDIOBJ op2 = SelectObject(dc, pen(g_p.accent));
                    int cxk = ir.left + S(9), cyk = RCY(ir) + S(1);
                    MoveToEx(dc, cxk - S(3), cyk - S(1), NULL);
                    LineTo(dc, cxk, cyk + S(2));
                    LineTo(dc, cxk + S(4), cyk - S(4));
                    SelectObject(dc, op2);
                }
                tx(dc, evs[i], RECT{ ir.left + S(18), ir.top, ir.right - S(4), ir.bottom },
                   i == g_eventSel ? g_p.text : g_p.textDim, g_f12,
                   DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                g_eventHits.push_back(std::make_pair(ir, i));
            }
        }
        return;
    }

    // 搜索框（程序页 / 支持库页）＋ 右侧「命令 / 备注 / 不限」下拉
    // 下拉只在支持库页出现：程序页那个搜索框还没做过滤，挂个空下拉没意义
    int comboW = (g_a.leftPage == 1) ? S(78) : 0;
    RECT cr = comboW ? RECT{ b.right - comboW, b.top, b.right, b.bottom }
                     : RECT{ 0, 0, 0, 0 };
    RECT sr = comboW ? RECT{ b.left, b.top, cr.left - S(4), b.bottom } : b;
    g_leftSearchRect = sr;
    bool act = (g_a.leftPage == 0) ? g_progSearchActive : g_libSearchActive;
    const wchar_t* txt = (g_a.leftPage == 0) ? g_progSearch : g_libSearch;
    const wchar_t* ph = (g_a.leftPage == 0) ? L"搜索子程序 / 变量" : L"搜索命令 / 注释";
    fillR(dc, sr, 4, act ? g_p.elevated : g_p.input);   // 激活时底色更亮，一眼看出点中了
    outlineR(dc, sr, 4, act ? g_p.accent : g_p.border);
    ico(dc, "cmd.search", R((float)(sr.left + S(6)) / g_s,
                            (float)(sr.top + S(4)) / g_s, 16, 16));
    // 支持库页：右边留一小块显示命中条数，组字中的拼音也跟着显示
    std::wstring shown = txt;
    if (g_a.leftPage == 1 && g_libSearchActive) shown += g_libImeComp;
    std::wstring cnt;
    int cntW = 0;
    if (g_a.leftPage == 1 && !lib_query().empty()) {
        cnt = wnum((int)g_libSearchHits.size()) + L" 条";
        cntW = twd(dc, cnt.c_str(), g_f11) + S(8);
    }
    int x0 = sr.left + S(26) + S(2);
    int xLim = sr.right - S(8) - cntW;
    SetBkMode(dc, TRANSPARENT);
    int caret = (act && g_libImeComp.empty()) ? g_srCaret : (int)shown.size();
    if (caret < 0) caret = 0;
    if (caret > (int)shown.size()) caret = (int)shown.size();
    if (shown.empty()) {
        tx(dc, ph, RECT{ x0, sr.top, xLim, sr.bottom }, g_p.textFaint, g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    } else {
        int sa = -1, sz = -1;
        if (act && sr_has_sel()) sr_sel(sa, sz);
        if (sa >= 0 && sz > sa) {              // 选区底色
            int xa = x0 + sr_text_w(dc, shown, sa);
            int xz = x0 + sr_text_w(dc, shown, sz);
            fill(dc, RECT{ xa, sr.top + S(3), xz, sr.bottom - S(3) }, g_p.accent);
        }
        auto part = [&](int from, int to, COLORREF col) {
            if (from >= to) return;
            int px = x0 + sr_text_w(dc, shown, from);
            tx(dc, shown.substr(from, to - from), RECT{ px, sr.top, xLim, sr.bottom },
               col, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
        };
        if (sa >= 0 && sz > sa) {              // 选中段反白，其余正常
            part(0, sa, g_p.text);
            part(sa, sz, g_p.panel);
            part(sz, (int)shown.size(), g_p.text);
        } else {
            part(0, (int)shown.size(), g_p.text);
        }
    }
    // 光标必须画在「有文字」分支之外——空框时原来根本没画，这是看不到光标的根因。
    // 亮相＝2px 强调色，灭相＝1px 淡色：始终可见，又有闪烁感。
    if (act) {
        int cx = x0 + sr_text_w(dc, shown, caret);
        int cwid = g_srBlink ? S(2) : S(1);
        COLORREF cc = g_srBlink ? g_p.accent : g_p.textDim;
        if (cx < xLim)
            fill(dc, RECT{ cx, sr.top + S(3), cx + cwid, sr.bottom - S(3) }, cc);
    }
    if (cntW) {
        tx(dc, cnt, R((float)(sr.right - S(6) - cntW) / g_s, (float)sr.top / g_s,
                      (float)cntW / g_s, 24),
           g_p.textFaint, g_f11, DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
    }
    // 右侧下拉按钮（弹层不在这里画：它要向下弹、压在提示面板上，
    // 必须等 paint_output 画完再单独补一层，否则会被提示面板盖掉）
    g_libComboRect = cr;
    if (comboW) {
        bool chot = in(cr, mp.x, mp.y) || g_libComboOpen;
        fillR(dc, cr, 4, chot ? g_p.elevated : g_p.input);
        outlineR(dc, cr, 4, g_libComboOpen ? g_p.accent : g_p.border);
        tx(dc, LIB_SEARCH_MODES[g_libSearchMode],
           RECT{ cr.left + S(6), cr.top, cr.right - S(16), cr.bottom },
           g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        int ax = cr.right - S(11), ay = RCY(cr);
        HGDIOBJ op = SelectObject(dc, pen(g_p.textDim));
        MoveToEx(dc, ax - S(4), ay - S(2), NULL);
        LineTo(dc, ax, ay + S(2));
        LineTo(dc, ax + S(4), ay - S(2));
        SelectObject(dc, op);
    }
}

// 搜索范围弹层：向下弹，画在总绘制最后（paint_output 之后），压在提示面板上。
// 命中表也在这里重建，on_lbutton_down 先判它，点弹层外只收起、不穿透。
static void paint_search_combo_popup(HDC dc)
{
    g_libComboHits.clear();
    if (!g_libComboOpen || g_a.leftPage != 1 ||
        g_libComboRect.right <= g_libComboRect.left) return;
    POINT mp; mouse_now_real(&mp);       // 弹层自己要正常响应悬停
    const RECT& cr = g_libComboRect;
    int ih = S(26);
    RECT pop = RECT{ cr.left, cr.bottom + S(2), cr.right,
                     cr.bottom + S(2) + ih * 3 + S(6) };
    fillR(dc, pop, 4, g_p.elevated);
    outlineR(dc, pop, 4, g_p.border);
    for (int i = 0; i < 3; ++i) {
        RECT ir = RECT{ pop.left + S(3), pop.top + S(3) + ih * i,
                        pop.right - S(3), pop.top + S(3) + ih * (i + 1) };
        if (in(ir, mp.x, mp.y) || i == g_libSearchMode)
            fillR(dc, ir, 3, i == g_libSearchMode ? g_p.accentSubtle : g_p.hover);
        tx(dc, LIB_SEARCH_MODES[i],
           RECT{ ir.left + S(10), ir.top, ir.right - S(4), ir.bottom },
           i == g_libSearchMode ? g_p.accent : g_p.text, g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        g_libComboHits.push_back(std::make_pair(ir, i));
    }
}

// ══════════════════════════════════════════════════════════════════
// 属性表格（通用绘制函数）
//   以后不同组件有不同的属性集：调用方把行数据组好传进来，
//   这里只负责画表格——固定表头、分类行、全行横线、名称/值中缝竖线、
//   悬停行高亮、视口裁剪 + 滚动。
// ══════════════════════════════════════════════════════════════════
// 易语言的属性值不全是「填一个值」：
//   PVText  文本/数值，点进去改（名称、标题、宽度…）
//   PVCombo 下拉枚举，点开选（边框、鼠标指针、背景颜色、显示位置）
//   PVBool  真假开关，双击在 真/假 之间翻
//   PVFile  要导入资源（图标），先占位不接功能
static COLORREF parse_color_str(const std::wstring& s, COLORREF def);

struct PGridRow {
    const wchar_t*  cat;
    const wchar_t*  name;
    std::wstring    value;
    PValKind        kind;
    const wchar_t** opts;   // PVCombo 的选项
    int             optN;
    std::wstring    type;   // 数据类型（如“文本型”）
    std::wstring    desc;   // 属性说明
};

// 全局记录当前鼠标悬停的属性行，-1 表示没有
static int g_propHoverIdx = -1;
static POINT g_propHoverPos = {0, 0};
static std::wstring g_propHoverType;
static std::wstring g_propHoverDesc;

static PGridRow prow_cat(const wchar_t* c)
{ return PGridRow{ c, NULL, L"", PVText, NULL, 0, L"", L"" }; }
static PGridRow prow_txt(const wchar_t* n, std::wstring v, const wchar_t* t = L"", const wchar_t* d = L"")
{ return PGridRow{ NULL, n, v, PVText, NULL, 0, t, d }; }
static PGridRow prow_combo(const wchar_t* n, std::wstring v,
                           const wchar_t** o, int cnt, const wchar_t* t = L"", const wchar_t* d = L"")
{ return PGridRow{ NULL, n, v, PVCombo, o, cnt, t, d }; }
static PGridRow prow_bool(const wchar_t* n, std::wstring v, const wchar_t* t = L"", const wchar_t* d = L"")
{ return PGridRow{ NULL, n, v, PVBool, NULL, 0, t, d }; }
static PGridRow prow_file(const wchar_t* n, std::wstring v, const wchar_t* t = L"", const wchar_t* d = L"")
{ return PGridRow{ NULL, n, v, PVFile, NULL, 0, t, d }; }
static PGridRow prow_color(const wchar_t* n, const std::wstring& v, const wchar_t* t = L"", const wchar_t* d = L"")
{ return PGridRow{ NULL, n, v, PVColor, NULL, 0, t, d }; }

static void draw_solid_down_arrow(HDC dc, RECT r, COLORREF color);
static PGridRow prow_cursor(const wchar_t* n, std::wstring v, const wchar_t* t = L"", const wchar_t* d = L"")
{ return PGridRow{ NULL, n, v, PVCursor, NULL, 0, t, d }; }

// 下拉/真假/文本里没有 form 字段的属性，改过的值存在这张表里（会话内有效）
static std::wstring prop_val(const wchar_t* name, const wchar_t* def)
{
    std::map<std::wstring, std::wstring>::iterator it = g_propOverride.find(name);
    return (it == g_propOverride.end()) ? std::wstring(def) : it->second;
}

static int g_propContentH = 0;   // 表格内容总高（像素），滚动上限用

// ── 值单元格编辑 / 下拉 ──
static int          g_propEditIdx = -1;   // 正在编辑文本值的行（rows 下标），-1 无
static std::wstring g_propEditBuf;
static RECT         g_propEditRect = RECT{ 0, 0, 0, 0 };
static std::vector<std::pair<RECT, int> > g_propValHits;    // 值格 → 行下标
static std::vector<std::pair<RECT, int> > g_propNameHits;   // 属性名称栏 → 行下标
static std::vector<std::pair<RECT, int> > g_propComboHits;  // 下拉项 → 选项下标
static int          g_propComboIdx = -1;  // 正在弹下拉的行，-1 无
static RECT         g_propComboAnchor = RECT{ 0, 0, 0, 0 };
static std::vector<PGridRow> g_propRows;  // 当前行数据（提交时查名字用）

// 自绘调色板
static void paint_color_picker(HDC dc)
{
    g_colorPickerHits.clear();
    g_colorPickerCustomBtn = RECT{ 0, 0, 0, 0 };
    if (!g_colorPickerOpen) return;

    int cellS = S(16);
    int gap = S(4);
    int cols = 8, rows = 8;
    int w = cols * cellS + (cols - 1) * gap + S(16);
    int gridH = rows * cellS + (rows - 1) * gap;
    int h = gridH + S(64); // 预留底部预览和按钮空间

    RECT pop = RECT{ g_colorPickerAnchor.left, g_colorPickerAnchor.bottom + S(2), g_colorPickerAnchor.left + w, g_colorPickerAnchor.bottom + S(2) + h };
    if (pop.bottom > rcLeftPanel.bottom - S(30)) pop.top = g_colorPickerAnchor.top - S(2) - h;
    if (pop.top < rcLeftPanel.top) pop.top = rcLeftPanel.top;
    pop.bottom = pop.top + h;

    // 阴影与边框
    RECT sh = pop; OffsetRect(&sh, S(2), S(2));
    fillR(dc, sh, 6, g_p.frame);
    fillR(dc, pop, 6, g_p.elevated);
    outlineR(dc, pop, 6, g_p.border);

    POINT mp; mouse_now_real(&mp);
    int hotIdx = -1;

    // 1. 先画所有普通格子
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            int idx = r * cols + c;
            int x = pop.left + S(8) + c * (cellS + gap);
            int y = pop.top + S(8) + r * (cellS + gap);
            RECT cr = RECT{ x, y, x + cellS, y + cellS };
            
            bool hot = in(cr, mp.x, mp.y);
            if (hot) {
                hotIdx = idx;
            } else {
                fillR(dc, cr, 2, g_palette_colors[idx]);
                outlineR(dc, cr, 2, g_p.borderSoft);
            }
            g_colorPickerHits.push_back(std::make_pair(cr, idx));
        }
    }

    // 底部分割线
    int btnY = pop.top + S(8) + gridH + S(6);
    hline(dc, pop.left + S(8), pop.right - S(8), btnY, g_p.borderSoft);

    // 2. 最后画悬停的格子，确保它盖在所有格子上，实现“放大”效果
    if (hotIdx != -1) {
        int r = hotIdx / cols;
        int c = hotIdx % cols;
        int x = pop.left + S(8) + c * (cellS + gap);
        int y = pop.top + S(8) + r * (cellS + gap);
        RECT cr = RECT{ x, y, x + cellS, y + cellS };
        
        InflateRect(&cr, S(2), S(2)); // 放大
        fillR(dc, cr, 2, g_palette_colors[hotIdx]);
        
        // 极强的视觉反馈：内圈白边 + 外圈加粗蓝边
        RECT border = cr; InflateRect(&border, -S(1), -S(1));
        outlineR(dc, border, 2, RGB(255, 255, 255));
        outlineR(dc, cr, 2, g_p.accent);
        outlineR(dc, cr, 2, g_p.accent);
    }

    // 3. 底部预览区：显示鼠标悬停的颜色色块和代码
    if (hotIdx != -1) {
        RECT pv = RECT{ pop.left + S(8), btnY + S(6), pop.left + S(28), btnY + S(26) };
        fillR(dc, pv, 2, g_palette_colors[hotIdx]);
        outlineR(dc, pv, 2, g_p.border);
        
        wchar_t hex[32];
        wsprintfW(hex, L"#%02X%02X%02X", GetRValue(g_palette_colors[hotIdx]), GetGValue(g_palette_colors[hotIdx]), GetBValue(g_palette_colors[hotIdx]));
        tx(dc, hex, RECT{ pv.right + S(8), pv.top, pop.right, pv.bottom }, g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    } else {
        tx(dc, L"选择一个颜色", RECT{ pop.left + S(8), btnY + S(6), pop.right, btnY + S(26) }, g_p.textFaint, g_f12, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    }

    // 4. 自定义按钮（下沉）
    g_colorPickerCustomBtn = RECT{ pop.left + S(8), btnY + S(30), pop.right - S(8), pop.bottom - S(6) };
    bool hotBtn = in(g_colorPickerCustomBtn, mp.x, mp.y);
    if (hotBtn) {
        fillR(dc, g_colorPickerCustomBtn, 4, g_p.hover);
    }
    tx(dc, L"🎨 自定义取色…", g_colorPickerCustomBtn, hotBtn ? g_p.accent : g_p.textDim, g_f12b, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
}

static void prop_grid_commit(const wchar_t* name, const std::wstring& v)
{
    if (wcscmp(name, L"__TAB_LINE__") == 0) { g_tableLineColor = build_color(v); InvalidateRect(g_hwnd, NULL, FALSE); return; }
    if (wcscmp(name, L"__TAB_BG__") == 0)   { g_tableBgColor = build_color(v); InvalidateRect(g_hwnd, NULL, FALSE); return; }
    if (wcscmp(name, L"__TAB_HDR__") == 0)  { g_tableHeaderColor = build_color(v); InvalidateRect(g_hwnd, NULL, FALSE); return; }

    Ctl* c = NULL;
    if (!g_a.sel.empty() && g_a.sel[0] >= 0 && g_a.sel[0] < (int)g_a.form.ctl.size())
        c = &g_a.form.ctl[g_a.sel[0]];   // 选中组件：写组件字段
    if (c) {
        if      (wcscmp(name, L"名称") == 0) { if (!v.empty()) c->name = v; }
        else if (wcscmp(name, L"标题") == 0) c->caption = v;
        else if (wcscmp(name, L"左边") == 0) c->x = (float)_wtoi(v.c_str());
        else if (wcscmp(name, L"顶边") == 0) c->y = (float)_wtoi(v.c_str());
        else if (wcscmp(name, L"宽度") == 0) c->w = (float)std::max(1, _wtoi(v.c_str()));
        else if (wcscmp(name, L"高度") == 0) c->h = (float)std::max(1, _wtoi(v.c_str()));
        else if (wcscmp(name, L"可视") == 0) c->visible = (v == L"真");
        else if (wcscmp(name, L"禁止") == 0) c->enabled = (v != L"真");
        else { c->props[name] = v; g_propOverride[name] = v; }
    } else if (wcscmp(name, L"名称") == 0) {
        if (!v.empty()) g_a.form.name = v;
    } else if (wcscmp(name, L"标题") == 0) {
        g_a.form.title = v;
    } else if (wcscmp(name, L"宽度") == 0) {
        int n = _wtoi(v.c_str());
        g_a.form.cw = (float)(n < 40 ? 40 : n);
    } else if (wcscmp(name, L"高度") == 0) {
        int n = _wtoi(v.c_str());
        g_a.form.ch = (float)(n < 40 ? 40 : n);
    } else {
        g_a.form.props[name] = v;   // 窗口属性存这里
        g_propOverride[name] = v;
        
        // 如果修改的是窗体边框，实时更新标题栏高度
        if (wcscmp(name, L"边框") == 0) {
            std::wstring bv = v;
            // 兼容带序号的下拉值，如 "0：无边框"
            size_t colon = bv.find_first_of(L"：:");
            if (colon != std::wstring::npos) bv = bv.substr(0, colon);
            
            if (bv == L"无边框" || bv == L"0") {
                g_a.form.caption = 0; // 无边框：标题栏高度归零
            } else if (bv == L"窄标题可调边框" || bv == L"窄标题固定边框" || bv == L"3" || bv == L"4") {
                g_a.form.caption = 20; // 窄标题：高度变矮
            } else {
                g_a.form.caption = 28; // 标准：恢复默认
            }
        }
    }
    g_a.form.dirty = true;

    // 修改属性后立刻强制重绘整个界面（包含画布）
    if (g_hwnd) {
        InvalidateRect(g_hwnd, NULL, FALSE);
        UpdateWindow(g_hwnd); // 立即刷新，防止延迟
    }
}

static void commit_prop_edit()
{
    if (g_propEditIdx < 0) return;
    int i = g_propEditIdx;
    g_propEditIdx = -1;
    if (i >= 0 && i < (int)g_propRows.size() && !g_propEditBuf.empty())
        prop_grid_commit(g_propRows[i].name, g_propEditBuf);
    g_propEditBuf.clear();
}

// 真假属性：双击翻面
static void prop_toggle_bool(int idx)
{
    if (idx < 0 || idx >= (int)g_propRows.size()) return;
    const PGridRow& r = g_propRows[idx];
    if (r.kind != PVBool) return;
    std::wstring nv = (r.value == L"真") ? L"假" : L"真";
    // 走正规提交管道，写回数据并触发重绘
    prop_grid_commit(r.name, nv);
}

static void prop_grid_draw(HDC dc, RECT vp, const std::vector<PGridRow>& rows, int scroll)
{
    const float HDR = 0.0f, CAT = 24.0f, RH = 24.0f, NAMEW = 0.44f;
    // 贴着左面板的边画，不再内缩 8px 再套一圈自己的外框——那样会有两层线。
    // 外围直接用面板自身的分隔线，表格只画表头线、行线和中缝。
    float L = (float)vp.left / g_s;
    float W = (float)(vp.right - vp.left) / g_s;
    float nw = W * NAMEW;

    g_propValHits.clear();
    g_propNameHits.clear();
    g_propRows = rows;
    g_propEditRect = RECT{ 0, 0, 0, 0 };
    g_propComboAnchor = RECT{ 0, 0, 0, 0 };
    g_propHoverIdx = -1; // 先清空
    POINT mp;
    mouse_now(&mp);
    // 只要有任何弹层打开，强制鼠标坐标到屏幕外，防止悬停穿透
    if (g_colorPickerOpen || g_propComboIdx >= 0 || g_libComboOpen || g_eventMenu || g_tbBuildMenu > 0) {
        mp.x = -100000; mp.y = -100000;
    }

    int saved = SaveDC(dc);
    IntersectClipRect(dc, vp.left, vp.top, vp.right, vp.bottom);


    // 行区：从表头下沿开始，向上滚。lastBot 记「最后一条真正画出来的行」的底边，
    // 中缝只到这里——空白区既没框也没中线。
    float y = (float)(vp.top + S(HDR)) / g_s - (float)scroll / g_s;
    int   yTopPx = vp.top + S(HDR);
    int   lastBot = vp.top + S(HDR);
    for (size_t i = 0; i < rows.size(); ++i) {
        const PGridRow& r = rows[i];
        float rh = r.cat ? CAT : RH;
        RECT rr = R(L, y, W, rh);
        bool visible = (rr.bottom > yTopPx && rr.top < vp.bottom);

        if (r.cat) {
            if (visible) {
                fill(dc, rr, g_p.panel);
                tx(dc, r.cat, R(L + 10.0f, y, W - 10.0f, CAT),
                   g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
                int b = S(y + CAT);
                if (b > lastBot) lastBot = b;
            }
        } else if (visible) {
            // 记录左侧名称栏的点击区域（从 L 到 L + nw）
            RECT nameRect = R(L, y, nw, RH);
            g_propNameHits.push_back(std::make_pair(nameRect, (int)i));

            bool hotName = in(nameRect, mp.x, mp.y);
            if (hotName) {
                fill(dc, rr, g_p.hover); // 整行底色高亮，但只有悬停在左侧才触发气泡
                g_propHoverIdx = (int)i;
                g_propHoverPos = mp;
                g_propHoverType = r.type;
                g_propHoverDesc = r.desc;
                // 绝对兜底
                if (g_propHoverType.empty()) g_propHoverType = L"通用型";
                if (g_propHoverDesc.empty()) g_propHoverDesc = L"未找到详细说明。";
            }
            tx(dc, r.name, R(L + 10.0f, y, nw - 12.0f, RH),
               g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
            RECT vr = R(L + nw + 2.0f, y + 1.0f, W - nw - 4.0f, RH - 2.0f);
            if (g_propEditIdx == (int)i) {
                // 文本编辑态：值格画成输入框（accent 描边 + 缓冲文本 + 光标）
                g_propEditRect = vr;
                fillR(dc, vr, 3, g_p.input);
                outlineR(dc, vr, 3, g_p.accent);
                tx(dc, g_propEditBuf,
                   R((float)(vr.left + S(6)) / g_s, y,
                     (float)(vr.right - vr.left - S(10)) / g_s, RH),
                   g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                int cxp = vr.left + S(6) + twd(dc, g_propEditBuf, g_f12) + S(1);
                if (cxp > vr.right - S(4)) cxp = vr.right - S(4);
                vline(dc, cxp, vr.top + S(3), vr.bottom - S(3), g_p.accent);
            } else {
                float vw = W - nw - 30.0f;   // 右端留给下拉箭头 / 「…」
                if (r.kind == PVColor) {
                    std::wstring showStr = (r.value == L"默认底色" || r.value.empty()) ? L"默认底色" : r.value;
                    tx(dc, showStr, R(L + nw + 6.0f, y, vw, RH), g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
                    // 绘制右侧的实心三角（硬编码右侧偏移，确保不被裁掉）
                    bool hot = in(vr, mp.x, mp.y);
                    int ax = vr.right - S(12), ay = RCY(vr);
                    POINT pts[3] = { {ax - S(4), ay - S(2)}, {ax + S(4), ay - S(2)}, {ax, ay + S(2)} };
                    HGDIOBJ oldBr = SelectObject(dc, br(hot ? g_p.accent : g_p.textDim));
                    HGDIOBJ oldPen = SelectObject(dc, GetStockObject(NULL_PEN));
                    Polygon(dc, pts, 3);
                    SelectObject(dc, oldPen);
                    SelectObject(dc, oldBr);
                } else if (r.kind == PVCombo || r.kind == PVFile) {
                    // 不画底色和边框，完全贴合表格，靠外层的整行 hover 反馈
                    bool hot = in(vr, mp.x, mp.y);
                    // 悬停时，只给右侧箭头区域一点淡色反馈
                    if (hot) {
                        RECT arrowR = RECT{ vr.right - S(20), vr.top, vr.right, vr.bottom };
                        fillR(dc, arrowR, 0, g_p.hover);
                    }
                }
                tx(dc, r.value, R(L + nw + 6.0f, y, vw, RH), g_p.text, g_f12,
                   DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                if (r.kind == PVCombo) {
                    bool hot = in(vr, mp.x, mp.y);
                    draw_solid_down_arrow(dc, RECT{ vr.right - S(16), vr.top, vr.right - S(4), vr.bottom }, hot ? g_p.accent : g_p.textDim);
                } else if (r.kind == PVFile) {
                    // 文件选择右侧：画三个排列整齐的实心圆点，悬停时变蓝
                    bool hot = in(vr, mp.x, mp.y);
                    COLORREF dotCol = hot ? g_p.accent : g_p.textDim;
                    int cx = vr.right - S(12), cy = RCY(vr);
                    int dotR = S(1.5); if (dotR < 1) dotR = 1;
                    int gap = S(4);
                    HGDIOBJ op = SelectObject(dc, br(dotCol));
                    HGDIOBJ ope = SelectObject(dc, GetStockObject(NULL_PEN));
                    Ellipse(dc, cx - gap - dotR, cy - dotR, cx - gap + dotR, cy + dotR);
                    Ellipse(dc, cx - dotR, cy - dotR, cx + dotR, cy + dotR);
                    Ellipse(dc, cx + gap - dotR, cy - dotR, cx + gap + dotR, cy + dotR);
                    SelectObject(dc, ope);
                    SelectObject(dc, op);
                }
            }
            if (g_propComboIdx == (int)i) g_propComboAnchor = vr;
            g_propValHits.push_back(std::make_pair(vr, (int)i));
            hline(dc, S(L), S(L + W), S(y + RH), g_p.borderSoft);
            int b = S(y + RH);
            if (b > lastBot) lastBot = b;
        }
        y += rh;


    }

    if (lastBot > vp.bottom) lastBot = vp.bottom;
    vline(dc, S(L + nw), vp.top, lastBot, g_p.borderSoft);
    // 不再画表格自己的外框，直接用左面板的边线，避免「两层线包裹」

    RestoreDC(dc, saved);
    g_propContentH = 0;
    for (size_t i = 0; i < rows.size(); ++i) {
        g_propContentH += (int)S(rows[i].cat ? CAT : RH);
    }
    // 不加额外缓冲，确保精确贴合
}

// 画实心小三角（用于下拉框右侧指示）
static void draw_solid_down_arrow(HDC dc, RECT r, COLORREF color) {
    int cx = RCX(r), cy = RCY(r) + S(1);
    int w = S(4), h = S(3);
    POINT pts[3] = {
        { cx - w, cy - h },
        { cx + w, cy - h },
        { cx,      cy + h }
    };
    HGDIOBJ oldBr = SelectObject(dc, br(color));
    HGDIOBJ oldPen = SelectObject(dc, GetStockObject(NULL_PEN));
    Polygon(dc, pts, 3);
    SelectObject(dc, oldPen);
    SelectObject(dc, oldBr);
}

// 属性值下拉（画在最上层，直接贴边铺开，不带阴影和圆角）
static void paint_prop_combo(HDC dc)
{
    g_propComboHits.clear();
    if (g_propComboIdx < 0 || !g_a.showLeft || !g_a.leftPanelOpen ||
        g_a.leftPage != 2 || g_propComboAnchor.right <= g_propComboAnchor.left) {
        return;
    }
    int i = g_propComboIdx;
    if (i < 0 || i >= (int)g_propRows.size()) return;
    const PGridRow& r = g_propRows[i];
    if (r.kind != PVCombo || r.optN <= 0) return;

    int ih = S(24); // 高度与表格一致
    int ph = ih * r.optN;
    int top = g_propComboAnchor.bottom;
    // 如果下面放不下，就向上弹
    if (top + ph > rcLeftPanel.bottom - S(30))
        top = g_propComboAnchor.top - ph;
    if (top < rcLeftPanel.top + S(30)) top = rcLeftPanel.top + S(30);
    
    RECT pop = RECT{ g_propComboAnchor.left, top, g_propComboAnchor.right, top + ph };
                     
    // 直接铺底色，直角，不要阴影
    fillR(dc, pop, 0, g_p.panel);
    outlineR(dc, pop, 0, g_p.borderSoft); // 极细的边框与表格融合

    POINT mp;
    mouse_now_real(&mp); // 关键修复：必须用真实坐标，否则弹层里拿不到悬停状态
    for (int k = 0; k < r.optN; ++k) {
        RECT ir = RECT{ pop.left + S(1), pop.top + ih * k, pop.right - S(1), pop.top + ih * (k + 1) };
        bool hot = in(ir, mp.x, mp.y);
        if (hot) {
            // 悬停时：明显的背景色 + 左侧高亮条
            fill(dc, ir, g_p.accentSubtle);
            fill(dc, RECT{ ir.left, ir.top, ir.left + S(3), ir.bottom }, g_p.accent);
        }
        // 底部画一条极细的分割线，模拟表格行线
        if (k < r.optN - 1) hline(dc, ir.left, ir.right, ir.bottom - 1, g_p.borderSoft);
        
        // 如果选中，左边画个蓝色的勾
        bool isSel = (r.value == r.opts[k]);
        if (!isSel) {
            std::wstring optStr = r.opts[k];
            size_t colon = optStr.find_first_of(L"：:");
            if (colon != std::wstring::npos && optStr.substr(colon + 1) == r.value) isSel = true;
        }
        if (isSel) {
            HGDIOBJ op = SelectObject(dc, pen(g_p.accent));
            int cx = ir.left + S(9), cy = RCY(ir) + S(1);
            MoveToEx(dc, cx - S(3), cy - S(1), NULL);
            LineTo(dc, cx, cy + S(2));
            LineTo(dc, cx + S(4), cy - S(4));
            SelectObject(dc, op);
        }
        
        tx(dc, r.opts[k], RECT{ ir.left + S(18), ir.top, ir.right - S(4), ir.bottom },
           r.value == r.opts[k] ? g_p.accent : (hot ? g_p.text : g_p.textDim), g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        g_propComboHits.push_back(std::make_pair(ir, k));
    }
}

// ── 真机属性表 ──
// 行数据来自 运行环境/组件库/组件库.ectl：窗口用「窗口」组件的属性，
// 选中组件用它自己组件的属性（左边/顶边/宽度/高度/标题/可视/禁止…全部真实，
// 枚举属性带真实可选值，属性说明作为提示）。已知字段映射到我们的 Ctl/Form，
// 其余属性存在 g_propOverride 里（会话内有效）。
// 下拉选项池：deque 保证 c_str() 地址稳定；每帧重建一次（指针只在绘制期间用）。
static std::deque<std::wstring> g_propOptStore;
static std::vector<std::vector<const wchar_t*> > g_propOptVec;

// 自绘调色板状态（已移至全局区域）

// 窗口在 .e 里的原始属性值（没有就给默认）
static std::wstring e_prop_raw(const wchar_t* name, const wchar_t* def)
{
    std::map<std::wstring, std::wstring>::const_iterator it = g_a.form.props.find(name);
    if (it == g_a.form.props.end() || it->second.empty()) return def;
    return it->second;
}

// 易语言 .e 属性 XML 的元信息：种类（0 文本 1 真假 2 枚举 3 资源）与枚举取值。
// 这份表属于「易语言兼容层」，随 IDE 内置——打开 .e 时属性页要照易语言原样画，
// 不能因为我们的组件支持库没声明这些属性就丢掉。
static bool e_prop_is_bool(const std::wstring& n)
{
    static const wchar_t* T[] = {
        L"可视", L"禁止", L"控制按钮", L"最大化按钮", L"最小化按钮", L"可否移动",
        L"回车下移焦点", L"Esc键关闭", L"F1键打开帮助", L"在任务条中显示", L"随意移动",
        L"总在最前", L"保持标题条激活", L"循环播放", L"隐藏选择", L"可停留焦点",
        L"是否允许多行", L"只读", L"可空", L"参考", L"数组", L"静态", L"公开",
        NULL
    };
    for (int i = 0; T[i]; ++i) if (n == T[i]) return true;
    return false;
}

static const wchar_t* e_prop_opts(const std::wstring& n)
{
    if (n == L"边框")   return L"无边框|普通可调边框|普通固定边框|固定工具窗口|可变工具窗口|悬浮窗口";
    if (n == L"位置")   return L"通常|居中|最小化|最大化";
    if (n == L"外形")   return L"矩形|圆角矩形|椭圆形";
    if (n == L"底图方式") return L"左上对齐|图片平铺|居中|拉伸";
    if (n == L"对齐方式" || n == L"横向对齐方式") return L"左对齐|居中|右对齐";
    if (n == L"纵向对齐方式") return L"顶对齐|居中|底对齐";
    if (n == L"滚动条") return L"无滚动条|横向滚动条|纵向滚动条|两者都有";
    if (n == L"鼠标指针") return L"默认型|十字型|手型|I 型|等待|禁止|上下箭头|左右箭头";
    if (n == L"输入方式") return L"通常|只读|密码";
    if (n == L"类型")   return L"普通按钮|默认按钮|取消按钮";
    if (n == L"转换方式" || n == L"调节器方式") return L"无|自动|手动";
    return NULL;
}

static bool e_prop_is_res(const std::wstring& n)
{
    static const wchar_t* T[] = {
        L"底色", L"底图", L"背景音乐", L"图标", L"图片", L"字体",
        L"文本颜色", L"背景颜色", L"前景颜色", NULL
    };
    for (int i = 0; T[i]; ++i) if (n == T[i]) return true;
    return false;
}

// 按易语言属性元信息生成一行（属性名/选项都落到持久存储里，PGridRow 只存指针）
static void prop_row_e(std::vector<PGridRow>& out, const std::wstring& name,
                       const std::wstring& shown, const std::wstring& type = L"", const std::wstring& desc = L"")
{
    g_propOptStore.push_back(name);
    const wchar_t* nm = g_propOptStore.back().c_str();
    // 只要属性名在硬编码列表里，或者它的值已经是“真/假/true/false”，就强制渲染成布尔框
    if (e_prop_is_bool(name) || shown == L"真" || shown == L"假" || shown == L"true" || shown == L"false") {
        std::wstring v = shown;
        if (v == L"true") v = L"真";
        else if (v == L"false") v = L"假";
        else if (v.empty()) v = L"假";
        out.push_back(prow_bool(nm, v, type.c_str(), desc.c_str()));
        return;
    }
    const wchar_t* optStr = e_prop_opts(name);
    if (optStr) {                                     // 枚举：真实可选值
        std::vector<const wchar_t*> arr;
        std::wstring all(optStr);
        size_t st = 0;
        while (st <= all.size()) {
            size_t bar = all.find(L'|', st);
            if (bar == std::wstring::npos) bar = all.size();
            g_propOptStore.push_back(all.substr(st, bar - st));
            arr.push_back(g_propOptStore.back().c_str());
            if (bar >= all.size()) break;
            st = bar + 1;
        }
        g_propOptVec.push_back(arr);
        const wchar_t** pa = g_propOptVec.back().empty() ? NULL : &g_propOptVec.back()[0];
        out.push_back(prow_combo(nm, shown, pa, (int)arr.size()));
        return;
    }
    if (e_prop_is_res(name)) {                        // 颜色/图片/音乐/图标
        out.push_back(prow_file(nm, shown.empty() ? L"（无）" : shown));
        return;
    }
    out.push_back(prow_txt(nm, shown));
}

// .e 里很多属性是「索引值」（边框=2、位置=1、底色=-16777216…），
// 属性页要照易语言显示成人能读的文字。未识别的原样返回。
static std::wstring e_attr_show(const std::wstring& k, const std::wstring& v)
{
    if (v.empty()) return v;
    // 如果本来就是纯中文文本，直接返回，绝对不能用 _wtoi 去解析，否则全部变 0
    for (int i = 0; i < (int)v.size(); ++i) {
        if (v[i] > 255) return v; 
    }

    struct Map { const wchar_t* key; const wchar_t* vals[8]; };
    static const Map MAPS[] = {
        { L"边框",   { L"无边框", L"普通可调边框", L"普通固定边框", L"固定工具窗口",
                       L"可变工具窗口", L"悬浮窗口", NULL } },
        { L"位置",   { L"通常", L"居中", L"最小化", L"最大化", NULL } },
        { L"外形",   { L"矩形", L"圆角矩形", L"椭圆形", NULL } },
        { L"底图方式", { L"左上对齐", L"图片平铺", L"居中", L"拉伸", NULL } },
        { L"对齐方式", { L"左对齐", L"居中", L"右对齐", NULL } },
        { L"横向对齐方式", { L"左对齐", L"居中", L"右对齐", NULL } },
        { L"纵向对齐方式", { L"顶对齐", L"居中", L"底对齐", NULL } },
        { L"滚动条", { L"无滚动条", L"横向滚动条", L"纵向滚动条", L"两者都有", NULL } },
        { L"输入方式", { L"通常", L"只读", L"密码", NULL } },
        { L"转换方式", { L"无", L"自动", L"手动", NULL } },
        { L"调节器方式", { L"无", L"自动", L"手动", NULL } },
        { L"类型", { L"普通按钮", L"默认按钮", L"取消按钮", NULL } },
    };
    for (int i = 0; i < (int)(sizeof(MAPS) / sizeof(MAPS[0])); ++i) {
        if (k != MAPS[i].key) continue;
        int idx = _wtoi(v.c_str());
        if (idx < 0) return v;
        for (int j = 0; j <= idx && MAPS[i].vals[j]; ++j)
            if (j == idx) return MAPS[i].vals[j];
        return v;
    }
    if (k == L"鼠标指针") return (v.size() < 2 || v == L"AAAAAA==") ? std::wstring(L"默认型") : v;
    if (k == L"底色" || k == L"文本颜色" || k == L"背景颜色" || k == L"前景颜色") {
        long long iv = _wtoi64(v.c_str());
        if (iv == -16777216) return std::wstring(L"默认底色");
        if (iv < 0) iv = (long long)(unsigned int)(int)iv;
        unsigned int col = (unsigned int)(iv & 0xFFFFFF);
        wchar_t buf[16];
        // 易语言颜色是 COLORREF（0x00BBGGRR），显示成 #RRGGBB
        swprintf(buf, 16, L"#%02X%02X%02X", col & 0xFF, (col >> 8) & 0xFF, (col >> 16) & 0xFF);
        return buf;
    }
    return v;
}

static void lg_rows_build(const LGComp* g, bool isForm, const Ctl* c,
                          std::vector<PGridRow>& out)
{
    g_propOptStore.clear();
    g_propOptVec.clear();
    // 注：g_propOptStore 是 deque，push_back 不会让已有元素的 c_str() 失效
    out.push_back(prow_cat(L"属性"));
    out.push_back(prow_txt(L"名称", isForm ? g_a.form.name : c->name,
                           L"文本型", L"本属性记录当前所选择对象的名称。"));
                           
    std::wstring defaultRemark = isForm ? L"在程序启动后自动调入本窗口" : L"";
    std::wstring remark = prop_val(L"备注", defaultRemark.c_str());
    out.push_back(prow_txt(L"备注", remark, L"文本型", L"本属性记录有关当前所选择对象的备注信息。"));

    // 分组标题：按支持库里属性的 @group 自动分段，加新组件不用改这里
    // 起始组就是最上面那个「属性」标题：库里标 @group 属性 的行平铺在它下面（同易语言属性表）
    std::wstring group = L"属性";
    auto open_group = [&](const std::wstring& gname) {
        if (gname.empty() || gname == group) return;
        group = gname;
        out.push_back(prow_cat(gname.c_str()));
    };

    // ── 打开 .e 的工程：属性页照易语言原样输出 ──
    // .e 的窗口/组件 XML 里就带着全套属性（名称/备注/左边/顶边/宽度/高度/标记/
    // 可视/禁止/鼠标指针/标题/边框/底色/…），顺序也就是易语言属性表的顺序。
    // 这里直接按它画，一条不漏；支持库里额外声明的（字体/字号/…）补在后面。
    {
        const std::map<std::wstring, std::wstring>* src = isForm ? &g_a.form.props
                                                                : (c ? &c->props : NULL);
        const std::vector<std::wstring>* ord = isForm ? &g_a.form.propOrder
                                                     : (c ? &c->propOrder : NULL);
        if (src && ord && ord->size() > 3) {
            for (size_t i = 0; i < ord->size(); ++i) {
                const std::wstring& k = (*ord)[i];
                if (k == L"名称") continue;                       // 表格固定行
                if (k == L"备注") continue;                       // 备注已强制固定显示
                if (k == L"扩展属性数据") continue;               // .e 内部字段
                std::map<std::wstring, std::wstring>::const_iterator it = src->find(k);
                std::wstring raw = (it == src->end()) ? std::wstring() : it->second;
                std::wstring shown;
                if (k == L"标题")      shown = isForm ? g_a.form.title : c->caption;
                else if (k == L"左边") shown = wnum((int)(isForm ? _wtoi(raw.c_str()) : c->x));
                else if (k == L"顶边") shown = wnum((int)(isForm ? _wtoi(raw.c_str()) : c->y));
                else if (k == L"宽度") shown = wnum((int)(isForm ? g_a.form.cw : c->w));
                else if (k == L"高度") shown = wnum((int)(isForm ? g_a.form.ch : c->h));
                else                   shown = e_attr_show(k, raw);
                // 用户在属性页改过的值优先（g_propOverride）
                shown = prop_val(k.c_str(), shown.c_str());
                // 去支持库里找同名的属性说明
                std::wstring typeStr, descStr;
                if (g) {
                    for (int pi = 0; pi < (int)g->props.size(); ++pi) {
                        if (g->props[pi].name == k) {
                            typeStr = g->props[pi].type;
                            descStr = g->props[pi].desc;
                            break;
                        }
                    }
                }
                // 兜底：如果是内置属性或者没找到，给个默认提示，保证气泡能弹出来
                if (typeStr.empty()) typeStr = L"通用型";
                if (descStr.empty()) descStr = L"未找到详细说明，请参考易语言官方文档。";
                prop_row_e(out, k, shown, typeStr, descStr);
            }
            // 支持库里声明、.e 里没有的属性补在「支持库」组
            if (g) {
                std::wstring grp2;
                for (int i = 0; i < (int)g->props.size(); ++i) {
                    const LGProp& p = g->props[i];
                    bool inE = false;
                    for (size_t j = 0; j < ord->size(); ++j)
                        if ((*ord)[j] == p.name) { inE = true; break; }
                    if (inE) continue;
                    if (p.name == L"备注") continue; // 备注已强制固定显示
                    // 语义重复的（.e 里叫法不同但一个意思）不再列一遍
                    {
                        const wchar_t* alias[] = { L"可见", L"启用", L"Tab 停留",
                                                   L"文字颜色", L"字体", L"内容", L"标题", NULL };
                        bool dup = false;
                        for (int ai = 0; alias[ai]; ++ai)
                            if (p.name == alias[ai]) { dup = true; break; }
                        if (dup) continue;
                    }
                    if (grp2 != p.group) {
                        grp2 = p.group;
                        out.push_back(prow_cat((std::wstring(L"支持库 · ") + grp2).c_str()));
                    }
                    // 优先读取组件自身注入的出厂默认值，其次读支持库定义
                    std::wstring v = p.def;
                    if (!isForm && c && c->props.count(p.name)) {
                        v = c->props.at(p.name);
                    } else if (isForm && g_a.form.props.count(p.name)) {
                        v = g_a.form.props.at(p.name);
                    }
                    // 必须翻译索引值（如把 1 翻译成 普通可调边框）
                    v = e_attr_show(p.name, v);
                    
                    // 最后再经过 g_propOverride 过滤（用户在面板上改过的值优先）
                    v = prop_val(p.name.c_str(), v.c_str());
                    
                    if (p.kind == 1 || v == L"真" || v == L"假" || v == L"true" || v == L"false") {
                        if (v == L"true") v = L"真"; else if (v == L"false") v = L"假";
                        else if (v.empty()) v = L"假";
                        g_propOptStore.push_back(p.name);
                        out.push_back(prow_bool(g_propOptStore.back().c_str(),
                                                v, p.type.c_str(), p.desc.c_str()));
                    } else if (p.kind == 2 && !p.opts.empty()) {
                        std::vector<const wchar_t*> arr;
                        size_t st = 0;
                        while (st <= p.opts.size()) {
                            size_t bar = p.opts.find(L'|', st);
                            if (bar == std::wstring::npos) bar = p.opts.size();
                            g_propOptStore.push_back(p.opts.substr(st, bar - st));
                            arr.push_back(g_propOptStore.back().c_str());
                            if (bar >= p.opts.size()) break;
                            st = bar + 1;
                        }
                        g_propOptVec.push_back(arr);
                        const wchar_t** pa = g_propOptVec.back().empty() ? NULL
                                                                        : &g_propOptVec.back()[0];
                        g_propOptStore.push_back(p.name);
                        out.push_back(prow_combo(g_propOptStore.back().c_str(), v, pa,
                                                 (int)arr.size(), p.type.c_str(), p.desc.c_str()));
                    } else if (p.kind == 3) {
                        g_propOptStore.push_back(p.name);
                        out.push_back(prow_file(g_propOptStore.back().c_str(),
                                                v.empty() ? L"（无）" : v, p.type.c_str(), p.desc.c_str()));
                    } else {
                        g_propOptStore.push_back(p.name);
                        out.push_back(prow_txt(g_propOptStore.back().c_str(), v, p.type.c_str(), p.desc.c_str()));
                    }
                }
            }
        }
    }

    // 通用位置属性：支持库（重写项目的 MFC 组件）没写这几项，但设计器必须有，
    // 所有组件都从这里补，不在每个组件上单独写。
    if (!isForm && c) {
        open_group(L"位置");
        out.push_back(prow_txt(L"左边", prop_val(L"左边", wnum((int)c->x).c_str()), L"整数型", L"本属性记录当前组件在窗口客户区中的左边位置。"));
        out.push_back(prow_txt(L"顶边", prop_val(L"顶边", wnum((int)c->y).c_str()), L"整数型", L"本属性记录当前组件在窗口客户区中的顶边位置。"));
        out.push_back(prow_txt(L"宽度", prop_val(L"宽度", wnum((int)c->w).c_str()), L"整数型", L"本属性记录当前组件的宽度。"));
        out.push_back(prow_txt(L"高度", prop_val(L"高度", wnum((int)c->h).c_str()), L"整数型", L"本属性记录当前组件的高度。"));
    }
    if (!g) return;

    // 按 @group 归类输出：库里属性顺序可能来回跳（基本→字体→基本），
    // 按组归拢后每个分组只出现一次标题
    std::vector<std::wstring> gorder;
    std::map<std::wstring, std::vector<int> > gidx;
    for (int i = 0; i < (int)g->props.size(); ++i) {
        const LGProp& p = g->props[i];
        if (!isForm && (p.name == L"左边" || p.name == L"顶边" ||
                        p.name == L"宽度" || p.name == L"高度")) continue;  // 上面补过
        std::wstring grp = p.group.empty() ? std::wstring(L"其他") : p.group;
        if (gidx.find(grp) == gidx.end()) gorder.push_back(grp);
        gidx[grp].push_back(i);
    }
    for (size_t gi = 0; gi < gorder.size(); ++gi) {
      open_group(gorder[gi]);
      const std::vector<int>& ids = gidx[gorder[gi]];
      for (size_t ii = 0; ii < ids.size(); ++ii) {
        const LGProp& p = g->props[ids[ii]];
        std::wstring v;
        if (p.name == L"标题")      v = isForm ? g_a.form.title : c->caption;
        else if (p.name == L"左边") v = isForm ? e_prop_raw(L"左边", L"0") : wnum((int)c->x);
        else if (p.name == L"顶边") v = isForm ? e_prop_raw(L"顶边", L"0") : wnum((int)c->y);
        else if (p.name == L"宽度") v = wnum((int)(isForm ? g_a.form.cw : c->w));
        else if (p.name == L"高度") v = wnum((int)(isForm ? g_a.form.ch : c->h));
        else if (p.name == L"可视") v = isForm ? bp(g_a.form.props, L"可视", L"真") : (c->visible ? L"真" : L"假");
        else if (p.name == L"禁止") v = isForm ? bp(g_a.form.props, L"禁止", L"假") : (c->enabled ? L"假" : L"真");
        else {
            // 优先显示 .e 里读到的真实属性（索引值转成文字）；没导入时用支持库默认值
            std::wstring dv = p.def;
            std::map<std::wstring, std::wstring>::const_iterator ci;
            bool fromE = false;
            if (!isForm && c && (ci = c->props.find(p.name)) != c->props.end()) {
                dv = ci->second;
                fromE = true;
            } else if (isForm && (ci = g_a.form.props.find(p.name)) != g_a.form.props.end()) {
                dv = ci->second;
                fromE = true;
            }
            if (fromE) dv = e_attr_show(p.name, dv);
            v = prop_val(p.name.c_str(), dv.c_str());
        }
        PValKind ek = prop_editor_kind(p);
        if (ek == PVColor) {
            out.push_back(prow_color(p.name.c_str(), v));
        } else if (ek == PVCursor) {
            std::vector<const wchar_t*> arr;
            const wchar_t* stdCursors[] = {
                L"0：标准箭头", L"1：I型文本", L"2：等待", L"3：十字", L"4：手型", 
                L"5：禁止", L"6：四向移动", L"7：水平缩放", L"8：垂直缩放", 
                L"9：斜向缩放1", L"10：斜向缩放2", L"11：向上箭头"
            };
            for (int k = 0; k < 12; ++k) {
                g_propOptStore.push_back(stdCursors[k]);
                arr.push_back(g_propOptStore.back().c_str());
            }
            g_propOptVec.push_back(arr);
            const wchar_t** pa = &g_propOptVec.back()[0];
            std::wstring showVal = v.empty() ? L"标准箭头" : v;
            // 智能匹配：底层存 "0"，属性框显示 "标准箭头"，下拉列表显示 "0：标准箭头"
            for (size_t k = 0; k < arr.size(); ++k) {
                std::wstring optStr = arr[k];
                size_t colon = optStr.find_first_of(L"：:");
                if (colon != std::wstring::npos) {
                    std::wstring numPart = optStr.substr(0, colon);
                    std::wstring textPart = optStr.substr(colon + 1);
                    if (numPart == showVal || textPart == showVal || optStr == showVal) {
                        showVal = textPart; 
                        break;
                    }
                }
            }
            out.push_back(prow_combo(p.name.c_str(), showVal, pa, (int)arr.size()));
        } else if (ek == PVBool) {
            if (v == L"true") v = L"真";
            else if (v == L"false") v = L"假";
            out.push_back(prow_bool(p.name.c_str(), v.empty() ? L"假" : v));
        } else if (ek == PVCombo) {
            std::vector<const wchar_t*> arr;
            // 优先用 @choices 解析
            if (!p.choices.empty()) {
                std::wstring s = p.choices;
                size_t start = 0;
                while (start < s.size()) {
                    size_t end = s.find_first_of(L"／/", start);
                    if (end == std::wstring::npos) end = s.size();
                    std::wstring item = s.substr(start, end - start);
                    // 统一保留序号，且把半角冒号转成全角冒号加空格，看起来更整齐
                    size_t colon = item.find(L':');
                    if (colon != std::wstring::npos) {
                        item = item.substr(0, colon) + L"：" + item.substr(colon + 1);
                    }
                    g_propOptStore.push_back(item);
                    arr.push_back(g_propOptStore.back().c_str());
                    if (end == s.size()) break;
                    start = end + 1;
                }
            } else if (!p.opts.empty()) { // 旧格式 @options
                size_t st = 0;
                while (st <= p.opts.size()) {
                    size_t bar = p.opts.find(L'|', st);
                    if (bar == std::wstring::npos) bar = p.opts.size();
                    g_propOptStore.push_back(p.opts.substr(st, bar - st));
                    arr.push_back(g_propOptStore.back().c_str());
                    if (bar >= p.opts.size()) break;
                    st = bar + 1;
                }
            }
            g_propOptVec.push_back(arr);
            const wchar_t** pa = g_propOptVec.back().empty() ? NULL : &g_propOptVec.back()[0];
            std::wstring defv = arr.empty() ? std::wstring(L"") : std::wstring(arr[0]);
            std::wstring showVal = v.empty() ? defv : v;
            // 属性框里只显示纯文字（如 "无边框"）
            for (size_t k = 0; k < arr.size(); ++k) {
                std::wstring optStr = arr[k];
                size_t colon = optStr.find_first_of(L"：:");
                if (colon != std::wstring::npos) {
                    std::wstring numPart = optStr.substr(0, colon);
                    std::wstring textPart = optStr.substr(colon + 1);
                    if (numPart == showVal || textPart == showVal || optStr == showVal) {
                        showVal = textPart; 
                        break;
                    }
                }
            }
            out.push_back(prow_combo(p.name.c_str(), showVal, pa, (int)arr.size()));
        } else if (ek == PVFile) {
            // 界面统一显示“有数据”/“（无）”，底层仍保存真实路径
            std::wstring showVal = (v.empty() || v == L"（无）" || v == L"无") ? L"（无）" : L"有数据";
            out.push_back(prow_file(p.name.c_str(), showVal));
        } else {
            out.push_back(prow_txt(p.name.c_str(), v));
        }
      }
    }

    // 支持库里没定义、但 .e 里带来的属性，统一补在「源码属性」组，一个都不丢
    {
        const std::map<std::wstring, std::wstring>* src = isForm ? &g_a.form.props
                                                                : (c ? &c->props : NULL);
        if (src) {
            std::vector<std::wstring> rest;
            for (std::map<std::wstring, std::wstring>::const_iterator it = src->begin();
                 it != src->end(); ++it) {
                if (it->first == L"名称") continue;           // 表格固定行
                bool known = false;
                for (int i = 0; i < (int)g->props.size(); ++i)
                    if (g->props[i].name == it->first) { known = true; break; }
                if (known) continue;
                rest.push_back(it->first);
            }
            if (!rest.empty()) {
                open_group(L"源码属性");
                for (size_t i = 0; i < rest.size(); ++i) {
                    std::map<std::wstring, std::wstring>::const_iterator si = src->find(rest[i]);
                    std::wstring v = e_attr_show(rest[i], si == src->end() ? std::wstring() : si->second);
                    // 属性名也要持久化：PGridRow 只存指针，rest 是本函数的局部量
                    g_propOptStore.push_back(rest[i]);
                    out.push_back(prow_txt(g_propOptStore.back().c_str(), v));
                }
            }
        }
    }
}

// 窗口属性（设计器没选中组件时）
static void win_prop_rows(std::vector<PGridRow>& out)
{
    lg_rows_build(lg_comp(L"窗口"), true, NULL, out);
    std::vector<PGridRow> clean;
    for (size_t i = 0; i < out.size(); ++i) {
        if (out[i].cat) continue;
        if (!out[i].name || wcslen(out[i].name) == 0) continue;
        clean.push_back(out[i]);
    }
    out.swap(clean);
}

// 选中组件的属性
static void ctl_prop_rows(int kindIdx, const Ctl& c, std::vector<PGridRow>& out)
{
    const LGComp* g = NULL;
    if (kindIdx >= 0 && kindIdx < kind_count() && KINDS[kindIdx].comp >= 0 &&
        KINDS[kindIdx].comp < g_comp_count())
        g = &g_comps[KINDS[kindIdx].comp];
    lg_rows_build(g, false, &c, out);
    std::vector<PGridRow> clean;
    for (size_t i = 0; i < out.size(); ++i) {
        if (out[i].cat) continue;
        if (!out[i].name || wcslen(out[i].name) == 0) continue;
        clean.push_back(out[i]);
    }
    out.swap(clean);
}


// ── 页签 2：支持库（已加载 / 未加载 两组，右键加载/卸载）──────────

static void paint_left_lib(HDC dc)
{
    float L = (float)(rcLeftPanel.left + S(8)) / g_s;
    float W = (float)(rcLeftPanel.right - rcLeftPanel.left - S(16)) / g_s;
    float top = (float)(rcLeftPanel.top + S(30)) / g_s;
    // 底行（搜索框）占了 30，列表别画进去
    float floorY = (float)left_bottom_row().top / g_s - S(6);
    g_libContentH = 0;
    std::wstring q = lib_query();
    bool qw = !q.empty();        // 搜索态：分组/库/分类强制展开，只画命中项

    if (!g_libNote.empty()) {
        tx(dc, g_libNote, R(L, top + 10, W, 40), g_p.warn, g_f12,
           DT_LEFT | DT_WORDBREAK);
        tx(dc, L"库文件放在 运行环境\\lib（*.elib），静态库在 运行环境\\static_lib。",
           R(L, top + 52, W, 60), g_p.textFaint, g_f11, DT_LEFT | DT_WORDBREAK);
        return;
    }
    if (g_libs.empty()) {
        tx(dc, L"lib 目录里没有 .epp 库文件", R(L, top + 10, W, 40),
           g_p.textDim, g_f12, DT_LEFT | DT_WORDBREAK);
        return;
    }

    std::vector<int> on, off;
    for (size_t i = 0; i < g_libs.size(); ++i)
        (g_libs[i].loaded ? on : off).push_back((int)i);

    // 视觉规格：分组头做成一条 30 高的厚条（左侧色条 + 展开三角 + 粗体标题 +
    // 计数），行高 27、圆角 4、选中和悬停都有底色。
    // 勾选框去掉了：加载/卸载走右键菜单，左键只选中。
    const float HDR = LIB_HDR, ROW = LIB_ROW, CAT = LIB_CAT, CMD = LIB_CMD, GAP = LIB_GAP;
    float scroll = (float)g_a.libScroll / g_s;
    float cy = top + 4 - scroll;
    POINT mp;
    mouse_now(&mp);
    bool inPanel = in(rcLeftPanel, mp.x, mp.y) && !g_hoverFrozen && !g_libComboOpen;

    // 列表只在页签标题下面这块里画：滚到一半的行不能糊到面板标题上
    int saved = SaveDC(dc);
    IntersectClipRect(dc, rcLeftPanel.left, rcLeftPanel.top + S(30),
                      rcLeftPanel.right, rcLeftPanel.bottom);

    for (int grp = 0; grp < 2; ++grp) {
        const std::vector<int>& rows = (grp == 0) ? on : off;
        if (rows.empty()) continue;

        // ── 分组头 ──
        RECT hr = R(L, cy, W, HDR);
        if (cy + HDR > top && cy < floorY) {
            // 右上角批量按钮：已加载组＝全部卸载，未加载组＝全部加载。
            // 只去掉了行前面的勾选框，这两个按钮按易语言原来样子保留。
            const wchar_t* act = (grp == 0) ? L"全部卸载" : L"全部加载";
            int aw = twd(dc, act, g_f11) + S(14);
            RECT ar = RECT{ hr.right - S(6) - aw, hr.top + S(4),
                            hr.right - S(6), hr.bottom - S(4) };
            bool ahot = inPanel && in(ar, mp.x, mp.y);
            bool hot = inPanel && in(hr, mp.x, mp.y) && !ahot;
            fillR(dc, hr, 5, hot ? g_p.hover : g_p.elevated);
            RECT bar = RECT{ hr.left + 1, hr.top + S(6), hr.left + S(4), hr.bottom - S(6) };
            fillR(dc, bar, 1, (grp == 0) ? g_p.ok : g_p.border);

            bool open = g_a.libGroupOpen[grp] || qw;
            int ax = hr.left + S(15), ay = RCY(hr);
            HGDIOBJ op = SelectObject(dc, pen((grp == 0) ? g_p.text : g_p.textDim));
            if (open) {
                MoveToEx(dc, ax - S(4), ay - S(2), NULL);
                LineTo(dc, ax, ay + S(2));
                LineTo(dc, ax + S(4), ay - S(2));
            } else {
                MoveToEx(dc, ax - S(2), ay - S(4), NULL);
                LineTo(dc, ax + S(2), ay);
                LineTo(dc, ax - S(2), ay + S(4));
            }
            SelectObject(dc, op);

            const wchar_t* nm = (grp == 0) ? L"已加载支持库" : L"未加载支持库";
            float titleW = (float)(ar.left - hr.left - S(30)) / g_s;
            if (titleW < 30.0f) titleW = 30.0f;
            tx(dc, nm, R((float)(hr.left + S(26)) / g_s, (float)hr.top / g_s,
                         titleW, HDR),
               (grp == 0) ? g_p.text : g_p.textDim, g_f12b,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            int nw = twd(dc, nm, g_f12b);
            if (hr.left + S(26) + nw + S(30) < ar.left) {
                tx(dc, wnum((int)rows.size()),
                   R((float)(hr.left + S(26) + nw + S(6)) / g_s, (float)hr.top / g_s,
                     (float)S(30) / g_s, HDR),
                   g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
            }

            fillR(dc, ar, 3, ahot ? g_p.hover : g_p.panel);
            outlineR(dc, ar, 3, ahot ? g_p.accent : g_p.border);
            tx(dc, act, ar, ahot ? g_p.text : g_p.textDim, g_f11,
               DT_CENTER | DT_VCENTER | DT_SINGLELINE);

            g_libGrpHits.push_back(std::make_pair(hr, grp));
            g_libActHits.push_back(std::make_pair(ar, grp));
        }
        cy += HDR;

        // ── 库树：库行 →（展开）分类行 →（展开）命令行 ──
        if (g_a.libGroupOpen[grp] || qw) {
            for (size_t k = 0; k < rows.size(); ++k) {
                const int i = rows[k];
                LibItem& lb = g_libs[i];

                // 库行：展开三角 + 图标 + 库名 + 版本/命令数
                if (cy + ROW > top && cy < floorY) {
                    RECT r = R(L + 6, cy, W - 6, ROW);
                    bool sel = (g_a.libSel == i) || lib_is_cur(0, i, -1, -1);
                    bool hot = inPanel && in(r, mp.x, mp.y);
                    if (sel) fillR(dc, r, 4, g_p.accentSubtle);
                    else if (hot) fillR(dc, r, 4, g_p.hover);
                    lib_tri(dc, r.left + S(12), RCY(r), lb.open || qw,
                            (grp == 0) ? g_p.text : g_p.textDim);
                    ico(dc, "tree.module",
                        R((float)(r.left + S(26)) / g_s, cy + (ROW - 16) / 2, 16, 16));
                    std::wstring meta = lb.ver.empty() ? L"" : (lb.ver + L" · ");
                    meta += wnum(lb.ncmd) + L" 条";
                    int mw = twd(dc, meta.c_str(), g_f11) + S(10);
                    tx(dc, lb.label,
                       R((float)(r.left + S(48)) / g_s, cy,
                         (float)(r.right - r.left - S(54) - mw) / g_s, ROW),
                       (grp == 0) ? g_p.text : g_p.textDim, g_f12b,
                       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                    tx(dc, meta,
                       R((float)(r.right - mw - S(10)) / g_s, cy,
                         (float)(mw + S(6)) / g_s, ROW),
                       g_p.textFaint, g_f11, DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
                    g_libHits.push_back(std::make_pair(r, i));
                    g_libNodes.push_back(LibNode{ 0, i, -1, -1, r });
                }
                cy += ROW;

                if (!lb.open && !qw) continue;

                for (size_t ci = 0; ci < lb.cats.size(); ++ci) {
                    LCat& cat = lb.cats[ci];
                    // 搜索过滤：分类里没有匹配命令就整条不画
                    std::vector<int> hit;
                    for (size_t ki = 0; ki < cat.cmds.size(); ++ki)
                        if (lib_cmd_match(cat.cmds[ki], q)) hit.push_back((int)ki);
                    if (hit.empty()) continue;

                    bool cOpen = cat.open || qw;   // 搜索时分类强制展开
                    if (cy + CAT > top && cy < floorY) {
                        RECT r = R(L + 16, cy, W - 16 - 4, CAT);
                        bool hot = inPanel && in(r, mp.x, mp.y);
                        if (lib_is_cur(1, i, (int)ci, -1)) fillR(dc, r, 3, g_p.accentSubtle);
                        else if (hot) fillR(dc, r, 3, g_p.hover);
                        lib_tri(dc, r.left + S(10), RCY(r), cOpen, g_p.textDim);
                        lib_ico(dc, 1, r.left + S(19), r.top + S(4));   // 分类：文件夹
                        // 有搜索词时显示命中条数（分类里只画命中的命令）
                        std::wstring cnt = wnum((int)hit.size());
                        int cw = twd(dc, cnt.c_str(), g_f11) + S(10);
                        tx(dc, cat.name,
                           R((float)(r.left + S(36)) / g_s, cy,
                             (float)(r.right - r.left - S(40) - cw) / g_s, CAT),
                           g_p.text, g_f12,
                           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                        tx(dc, cnt,
                           R((float)(r.right - cw - S(10)) / g_s, cy,
                             (float)(cw + S(6)) / g_s, CAT),
                           g_p.textFaint, g_f11, DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
                        g_libNodes.push_back(LibNode{ 1, i, (int)ci, -1, r });
                    }
                    cy += CAT;
                    if (!cOpen) continue;

                    for (size_t hi = 0; hi < hit.size(); ++hi) {
                        const int ki = hit[hi];
                        const LCmd& cm = cat.cmds[ki];
                        if (cy + CMD > top && cy < floorY) {
                            RECT r = R(L + 32, cy, W - 32 - 8, CMD);
                            bool ksel = (g_libCmdSelLib == i && g_libCmdSelCat == (int)ci &&
                                         g_libCmdSelCmd == ki);
                            bool khot = inPanel && in(r, mp.x, mp.y);
                            if (ksel || lib_is_cur(2, i, (int)ci, ki)) fillR(dc, r, 3, g_p.accentSubtle);
                            else if (khot) fillR(dc, r, 3, g_p.hover);
                            lib_ico(dc, 2, r.left + S(5), r.top + S(3));   // 命令：e 文档
                            // 搜索态右侧改显示命中原因（否则显示返回类型），
                            // 一眼就能核对这条到底是命令名命中还是注释命中
                            std::wstring right = qw ? lib_cmd_why_text(cm, q) : cm.ret;
                            int rw = right.empty() ? 0 : (twd(dc, right.c_str(), g_f11) + S(8));
                            tx(dc, cm.name,
                               R((float)(r.left + S(23)) / g_s, cy,
                                 (float)(r.right - r.left - S(27) - rw) / g_s, CMD),
                               g_p.text, g_f11,
                               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                            if (rw > 0)
                                tx(dc, right,
                                   R((float)(r.right - rw - S(10)) / g_s, cy,
                                     (float)(rw + S(6)) / g_s, CMD),
                                   g_p.textFaint, g_f11,
                                   DT_RIGHT | DT_VCENTER | DT_SINGLELINE | DT_NOCLIP);
                            g_libNodes.push_back(LibNode{ 2, i, (int)ci, ki, r });
                        }
                        cy += CMD;
                    }
                }

                // ── 数据类型（窗口组件）：库 → 数据类型 → 组件 → 属性/事件/方法 ──
                // 这一支以前整个漏掉（只读了 命令.txt），支持库里看不到组件。
                // 行高跟命令行一档（22），缩进每层多 16，层次一眼能看出来。
                // 先算命中：一条都搜不到就整组不画，避免出现空壳分组
                std::vector<int> hitT;
                for (size_t ti = 0; ti < lb.types.size(); ++ti)
                    if (lib_type_match(lb.types[ti], q)) hitT.push_back((int)ti);
                if (!hitT.empty()) {
                    bool tOpen = lb.typeOpen || qw;   // 搜索时强制展开
                    if (cy + CAT > top && cy < floorY) {
                        RECT r = R(L + 16, cy, W - 16 - 4, CAT);
                        bool hot = inPanel && in(r, mp.x, mp.y);
                        if (lib_is_cur(3, i, -1, -1)) fillR(dc, r, 3, g_p.accentSubtle);
                        else if (hot) fillR(dc, r, 3, g_p.hover);
                        lib_tri(dc, r.left + S(10), RCY(r), tOpen, g_p.textDim);
                        lib_ico(dc, 3, r.left + S(19), r.top + S(4));   // 数据类型组：文件夹
                        std::wstring cnt = wnum((int)hitT.size());   // 搜索时显示命中数
                        int cw = twd(dc, cnt.c_str(), g_f11) + S(10);
                        tx(dc, L"数据类型",
                           R((float)(r.left + S(36)) / g_s, cy,
                             (float)(r.right - r.left - S(40) - cw) / g_s, CAT),
                           g_p.text, g_f12,
                           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                        tx(dc, cnt,
                           R((float)(r.right - cw - S(10)) / g_s, cy,
                             (float)(cw + S(6)) / g_s, CAT),
                           g_p.textFaint, g_f11, DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
                        g_libNodes.push_back(LibNode{ 3, i, -1, -1, r });
                    }
                    cy += CAT;
                    if (tOpen) {
                        for (size_t hi = 0; hi < hitT.size(); ++hi) {
                            const int ti = hitT[hi];
                            LType& ty = lb.types[ti];
                            // 组件行：三角 + 名字 + 右侧「N 项」（属性条数，跟属性框一致）
                            if (cy + CMD > top && cy < floorY) {
                                RECT r = R(L + 32, cy, W - 32 - 8, CMD);
                                bool tsel = (g_libTypeSelLib == i && g_libTypeSel == (int)ti &&
                                             g_libMemSel < 0);
                                bool thot = inPanel && in(r, mp.x, mp.y);
                                if (tsel || lib_is_cur(4, i, (int)ti, -1)) fillR(dc, r, 3, g_p.accentSubtle);
                                else if (thot) fillR(dc, r, 3, g_p.hover);
                                lib_tri(dc, r.left + S(8), RCY(r), ty.open, g_p.textFaint);
                                lib_ico(dc, 4, r.left + S(17), r.top + S(3));  // 类型：立方体
                                std::wstring meta = wnum((int)ty.props.size()) + L" 项";
                                int mw = twd(dc, meta.c_str(), g_f11) + S(10);
                                tx(dc, ty.name,
                                   R((float)(r.left + S(34)) / g_s, cy,
                                     (float)(r.right - r.left - S(38) - mw) / g_s, CMD),
                                   g_p.text, g_f11,
                                   DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                                tx(dc, meta,
                                   R((float)(r.right - mw - S(8)) / g_s, cy,
                                     (float)(mw + S(4)) / g_s, CMD),
                                   g_p.textFaint, g_f11,
                                   DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
                                g_libNodes.push_back(LibNode{ 4, i, (int)ti, -1, r });
                            }
                            cy += CMD;
                            bool mOpen = ty.open || qw;   // 搜索时展开成员
                            if (!mOpen) continue;
                            // 成员顺序照原版树：命令（方法）→ 属性 → 事件
                            // （LIB_MEM_SEC_ORDER；sec 仍用真实编号，图标/选中不变）
                            for (int oi = 0; oi < 3; ++oi) {
                                const int sec = LIB_MEM_SEC_ORDER[oi];
                                const std::vector<LMem>& arr =
                                    (sec == 0) ? ty.props : (sec == 1 ? ty.evts : ty.meths);
                                for (size_t mi = 0; mi < arr.size(); ++mi) {
                                    const LMem& mem = arr[mi];
                                    // 有搜索词时只列命中的成员，别把 21 条属性全铺开
                                    if (!lib_mem_match(mem, q)) continue;
                                    if (cy + CMD > top && cy < floorY) {
                                        RECT r = R(L + 48, cy, W - 48 - 10, CMD);
                                        bool msel = (g_libTypeSelLib == i && g_libTypeSel == (int)ti &&
                                                     g_libMemSelKind == sec + 1 && g_libMemSel == (int)mi);
                                        bool mhot = inPanel && in(r, mp.x, mp.y);
                                        if (msel || lib_is_cur(5 + sec, i, (int)ti, (int)mi)) fillR(dc, r, 3, g_p.accentSubtle);
                                        else if (mhot) fillR(dc, r, 3, g_p.hover);
                                        // 右侧：属性给类型，事件/方法给类别字
                                        std::wstring right = (sec == 0) ? mem.type
                                                           : (sec == 1 ? L"事件" : L"方法");
                                        lib_ico(dc, 5 + sec, r.left + S(5), r.top + S(3));
                                        int rw = right.empty() ? 0 : (twd(dc, right.c_str(), g_f11) + S(8));
                                        tx(dc, mem.name,
                                           R((float)(r.left + S(23)) / g_s, cy,
                                             (float)(r.right - r.left - S(27) - rw) / g_s, CMD),
                                           (sec == 0) ? g_p.textDim : g_p.text, g_f11,
                                           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                                        if (rw > 0)
                                            tx(dc, right,
                                               R((float)(r.right - rw - S(10)) / g_s, cy,
                                                 (float)(rw + S(6)) / g_s, CMD),
                                               g_p.textFaint, g_f11,
                                               DT_RIGHT | DT_VCENTER | DT_SINGLELINE | DT_NOCLIP);
                                        g_libNodes.push_back(LibNode{ 5 + sec, i, (int)ti, (int)mi, r });
                                    }
                                    cy += CMD;
                                }
                            }
                        }
                    }
                }

                // ── 常量：库 → 常量（组） → 常量条目 ──
                // krnln 的 335 个常量（真假/颜色值/引号/换行符…），以前整个没读。
                std::vector<int> hitC;
                for (size_t qi = 0; qi < lb.consts.size(); ++qi)
                    if (lib_const_match(lb.consts[qi], q)) hitC.push_back((int)qi);
                if (!hitC.empty()) {
                    bool kOpen = lb.constOpen || qw;   // 搜索时强制展开
                    if (cy + CAT > top && cy < floorY) {
                        RECT r = R(L + 16, cy, W - 16 - 4, CAT);
                        bool hot = inPanel && in(r, mp.x, mp.y);
                        if (lib_is_cur(8, i, -1, -1)) fillR(dc, r, 3, g_p.accentSubtle);
                        else if (hot) fillR(dc, r, 3, g_p.hover);
                        lib_tri(dc, r.left + S(10), RCY(r), kOpen, g_p.textDim);
                        lib_ico(dc, 8, r.left + S(19), r.top + S(4));   // 常量组：文件夹
                        std::wstring cnt = wnum((int)hitC.size());   // 搜索时显示命中数
                        int cw = twd(dc, cnt.c_str(), g_f11) + S(10);
                        tx(dc, L"常量",
                           R((float)(r.left + S(36)) / g_s, cy,
                             (float)(r.right - r.left - S(40) - cw) / g_s, CAT),
                           g_p.text, g_f12,
                           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                        tx(dc, cnt,
                           R((float)(r.right - cw - S(10)) / g_s, cy,
                             (float)(cw + S(6)) / g_s, CAT),
                           g_p.textFaint, g_f11, DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
                        g_libNodes.push_back(LibNode{ 8, i, -1, -1, r });
                    }
                    cy += CAT;
                    if (kOpen) {
                        for (size_t hi = 0; hi < hitC.size(); ++hi) {
                            const int qi = hitC[hi];
                            const LConst& qc = lb.consts[qi];
                            // 只列命中的常量（名字/英文名/说明含关键字）
                            if (cy + CMD > top && cy < floorY) {
                                RECT r = R(L + 32, cy, W - 32 - 8, CMD);
                                bool qsel = (g_libConstSelLib == i && g_libConstSel == (int)qi);
                                bool qhot = inPanel && in(r, mp.x, mp.y);
                                if (qsel || lib_is_cur(9, i, (int)qi, -1)) fillR(dc, r, 3, g_p.accentSubtle);
                                else if (qhot) fillR(dc, r, 3, g_p.hover);
                                lib_ico(dc, 9, r.left + S(5), r.top + S(3));   // 常量：C 圆片
                                int rw = qc.type.empty() ? 0 : (twd(dc, qc.type.c_str(), g_f11) + S(8));
                                tx(dc, qc.name,
                                   R((float)(r.left + S(23)) / g_s, cy,
                                     (float)(r.right - r.left - S(27) - rw) / g_s, CMD),
                                   g_p.text, g_f11,
                                   DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                                if (rw > 0)
                                    tx(dc, qc.type,
                                       R((float)(r.right - rw - S(10)) / g_s, cy,
                                         (float)(rw + S(6)) / g_s, CMD),
                                       g_p.textFaint, g_f11,
                                       DT_RIGHT | DT_VCENTER | DT_SINGLELINE | DT_NOCLIP);
                                g_libNodes.push_back(LibNode{ 9, i, (int)qi, -1, r });
                            }
                            cy += CMD;
                        }
                    }
                }
            }
        }
        cy += GAP;
    }

    RestoreDC(dc, saved);
    g_libContentH = S(cy + scroll - top + 8);
}

// ── 页签 3：属性（表格化的属性页）────────────────────────────────
// 先只做窗口的属性（其它组件的属性集后补：换一组行数据传给
// prop_grid_draw 就行）。最下面是「组件事件」下拉（属性页专属）。
static void paint_left_prop(HDC dc)
{
    RECT vp = rcLeftPanel;
    vp.top = rcLeftPanel.top + S(30);
    vp.bottom = left_bottom_row().top - 1; // 无缝贴合下拉框

    // 换选中组件/换窗口时，事件下拉回到第一项（事件列表跟着组件走）
    static int s_propSig = -12345;
    int sig = -1;
    if (!g_a.sel.empty() && g_a.sel[0] >= 0 && g_a.sel[0] < (int)g_a.form.ctl.size())
        sig = g_a.sel[0] * 1000 + g_a.form.ctl[g_a.sel[0]].kind;
    if (sig != s_propSig) { s_propSig = sig; g_eventSel = 0; }

    std::vector<PGridRow> rows;
    if (!g_a.sel.empty() && g_a.sel[0] >= 0 && g_a.sel[0] < (int)g_a.form.ctl.size())
        ctl_prop_rows(g_a.form.ctl[g_a.sel[0]].kind, g_a.form.ctl[g_a.sel[0]], rows);
    else
        win_prop_rows(rows);
    prop_grid_draw(dc, vp, rows, g_a.propScroll);
}

// 左侧面板：按页签分发。窗口组件箱不在这里——它在右边。
static void paint_lib(HDC dc)
{
    if (!g_a.showLeft || !g_a.leftPanelOpen) {
        g_eventMenu = false;
        g_propComboIdx = -1;
        g_propEditIdx = -1;
        g_progSearchActive = g_libSearchActive = false;
        return;
    }
    fill(dc, rcLeftPanel, g_p.inner);
    panel_head(dc, rcLeftPanel, PAGE_ICONS[g_a.leftPage], PAGE_NAMES[g_a.leftPage]);

    g_progHits.clear();
    g_progExp.clear();
    g_libHits.clear();
    g_libGrpHits.clear();
    g_libActHits.clear();
    g_libNodes.clear();

    if (g_a.leftPage == 0) paint_left_program(dc);
    else if (g_a.leftPage == 1) paint_left_lib(dc);
    else paint_left_prop(dc);

    // 三页共用的底行：程序/支持库＝搜索框，属性＝事件下拉
    paint_left_bottom(dc);
}

// 支持库右键菜单（加载组件 / 卸载组件），画在总绘制最后，压在一切上面
static void paint_libmenu(HDC dc)
{
    g_libMenuHits.clear();
    if (g_libMenuIdx < 0) return;
    if (!g_a.showLeft || !g_a.leftPanelOpen || g_a.leftPage != 1 ||
        g_libMenuIdx >= (int)g_libs.size()) { lib_menu_close(); return; }

    const wchar_t* items[2] = { L"加载组件", L"卸载组件" };
    // 已加载的库：「加载」灰掉；未加载的库：「卸载」灰掉
    bool off[2] = { g_libs[g_libMenuIdx].loaded, !g_libs[g_libMenuIdx].loaded };
    int w = S(132), ih = S(26), ph = S(8) + ih * 2;
    int px = g_libMenuPos.x, py = g_libMenuPos.y;
    if (px + w > g_w - S(4)) px = g_w - S(4) - w;
    if (py + ph > g_h - S(4)) py = g_h - S(4) - ph;
    if (px < S(4)) px = S(4);
    if (py < S(4)) py = S(4);
    RECT pop = RECT{ px, py, px + w, py + ph };

    fillR(dc, pop, 5, g_p.elevated);
    outlineR(dc, pop, 5, g_p.border);
    POINT mp;
    mouse_now(&mp);
    for (int i = 0; i < 2; ++i) {
        RECT ir = RECT{ pop.left + S(4), pop.top + S(4) + ih * i,
                        pop.right - S(4), pop.top + S(4) + ih * (i + 1) };
        if (!off[i] && in(ir, mp.x, mp.y)) fillR(dc, ir, 3, g_p.hover);
        tx(dc, items[i], ir, off[i] ? g_p.textFaint : g_p.text, g_f12,
           DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        if (!off[i]) g_libMenuHits.push_back(std::make_pair(ir, i));
    }
}

// 程序树右键菜单：软投影 + 实底 + 大圆角（跟向导面板同一套质感）
static void paint_progmenu(HDC dc)
{
    g_progMenuHits.clear();
    if (g_progMenuNode < 0 || g_progMenuItems.empty()) return;
    if (!g_a.showLeft || !g_a.leftPanelOpen || g_a.leftPage != 0) { prog_menu_close(); return; }

    int w = S(150), ih = S(26), sep = S(9);
    int nItems = 0, nSeps = 0;
    for (size_t i = 0; i < g_progMenuItems.size(); ++i)
        g_progMenuItems[i].sep ? ++nSeps : ++nItems;
    int ph = S(10) + ih * nItems + sep * nSeps;
    int px = g_progMenuPos.x, py = g_progMenuPos.y;
    if (px + w > g_w - S(4)) px = g_w - S(4) - w;
    if (py + ph > g_h - S(4)) py = g_h - S(4) - ph;
    if (px < S(4)) px = S(4);
    if (py < S(4)) py = S(4);
    RECT pop = RECT{ px, py, px + w, py + ph };

    // 软阴影：5 层低透明度矩形逐层外扩（同向导面板），菜单才能从背景上「浮」起来
    {
        Graphics g2(dc);
        g2.SetSmoothingMode(SmoothingModeAntiAlias);
        for (int i = 5; i >= 1; --i) {
            RECT sr = pop;
            OffsetRect(&sr, 0, S(i));
            InflateRect(&sr, S(i * 2), S(i * 2));
            SolidBrush sb(Color(26 - i * 4, 0, 0, 0));
            g2.FillRectangle(&sb, Rect(sr.left, sr.top, sr.right - sr.left, sr.bottom - sr.top));
        }
    }

    // 实底 + 大圆角 + 描边。底色往文字色方向提一档：暗色主题里 popup(0x25)
    // 比面板(0x28)还暗、跟树背景(0x1E)几乎一档，看起来就像透明——这里混 ~10%
    // 文字色让它明确浮起来；浅色主题 popup 本来就是纯白，混完还是白。
    COLORREF bg = mixc(g_p.popup, g_p.text, 0.10f);
    COLORREF edge = mixc(g_p.border, g_p.text, 0.18f);
    fillR(dc, pop, 8, bg);
    outlineR(dc, pop, 8, edge);
    POINT mp;
    mouse_now(&mp);

    int iy = pop.top + S(5);
    for (size_t i = 0; i < g_progMenuItems.size(); ++i) {
        const ProgMItem& m = g_progMenuItems[i];
        if (m.sep) {
            hline(dc, pop.left + S(12), pop.right - S(12), iy + sep / 2,
                  mixc(g_p.border, g_p.text, 0.25f));
            iy += sep;
            continue;
        }
        // 悬停项：选中紫的圆角块（和树选中同一色），禁用项不给悬停不给命中
        RECT ir = RECT{ pop.left + S(6), iy, pop.right - S(6), iy + ih };
        if (!m.off && in(ir, mp.x, mp.y)) fillR(dc, ir, 5, g_p.accentSubtle);
        tx(dc, m.label.c_str(), RECT{ ir.left + S(10), ir.top, ir.right - S(8), ir.bottom },
           m.off ? g_p.textFaint : g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        if (!m.off) g_progMenuHits.push_back(std::make_pair(ir, (int)i));
        iy += ih;
    }
}

// 左栏收起后贴在窗口左边缘的召回把手：只有指针靠到左边才出现，
// 平时一点不画，画布才能真的贴住窗口边框。
static void paint_edge_tab(HDC dc)
{
    g_edgeTab = RECT{ 0, 0, 0, 0 };
    if (g_a.showLeft) return;
    POINT mp;
    mouse_now(&mp);
    if (mp.x > S(28) || !in(rcCanvas, mp.x, mp.y)) return;

    int h = S(72), w = S(14);
    int cy = (rcCanvas.top + rcCanvas.bottom) / 2;
    RECT r = RECT{ 0, cy - h / 2, w, cy + h / 2 };
    fillR(dc, r, 4, g_p.elevated);
    outlineR(dc, r, 4, g_p.border);
    HGDIOBJ op = SelectObject(dc, pen(g_p.text));
    int x = r.left + w / 2, y = RCY(r);
    MoveToEx(dc, x - S(2), y - S(6), NULL);
    LineTo(dc, x + S(3), y);
    LineTo(dc, x - S(2), y + S(6));
    SelectObject(dc, op);
    g_edgeTab = r;
}


// 右侧「组件箱」：标题行 + 搜索 + 分类页签 + 组件栅格。
// 两种模式：图标（网格卡片）/ 列表（一行一个，右侧带默认尺寸）。
static std::vector<std::pair<RECT, int> > g_modeHits;

static void paint_toolbox(HDC dc)
{
    if (!g_a.showToolbox) {
        g_toolHits.clear();
        g_catHits.clear();
        g_modeHits.clear();
        return;
    }
    // 和画布之间的竖缝：直接用分隔线色，1px 也要看得见
    fill(dc, rcRightSplit, g_p.split);
    fill(dc, rcPalette, g_p.inner);
    g_toolHits.clear();
    g_modeHits.clear();

    POINT mp;
    mouse_now(&mp);

    // ── 标题行（组件箱 + 右侧「网格 / 列表」两个模式按钮）
    RECT head = rcPalette;
    head.bottom = head.top + S(28);
    fill(dc, head, g_p.bar);
    hline(dc, head.left, head.right, head.bottom - 1, g_p.split);
    ico(dc, "panel.toolbox", R((float)(head.left + S(8)) / g_s,
                               (float)(head.top + S(6)) / g_s, 16, 16));
    tx(dc, L"组件箱",
       R((float)(head.left + S(30)) / g_s, (float)head.top / g_s,
         (float)(head.right - head.left - S(110)) / g_s, 28),
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);

    {
        int bw = S(28), bh = S(20);
        int bx = head.right - S(8) - bw * 2 - S(4);
        for (int m = 0; m < 2; ++m) {
            RECT b = RECT{ bx + m * (bw + S(4)), head.top + S(4),
                           bx + m * (bw + S(4)) + bw, head.top + S(4) + bh };
            bool act = (g_a.toolMode == m);
            bool hot = in(b, mp.x, mp.y);
            if (act) {
                fillR(dc, b, 3, g_p.accentSubtle);
                outlineR(dc, b, 3, g_p.accent);
            } else if (hot) {
                fillR(dc, b, 3, g_p.hover);
                outlineR(dc, b, 3, g_p.borderSoft);
            }
            COLORREF ic = act ? g_p.text : g_p.textDim;
            if (m == 0) {
                // 网格：2×2 小方块
                int s = S(4), gp = S(2);
                int ox = RCX(b) - s - gp / 2, oy = RCY(b) - s - gp / 2;
                for (int r = 0; r < 2; ++r) {
                    for (int c = 0; c < 2; ++c) {
                        RECT q = RECT{ ox + c * (s + gp), oy + r * (s + gp),
                                       ox + c * (s + gp) + s, oy + r * (s + gp) + s };
                        fill(dc, q, ic);
                    }
                }
            } else {
                // 列表：三条横线
                for (int r = 0; r < 3; ++r) {
                    int yy = RCY(b) - S(5) + r * S(5);
                    hline(dc, RCX(b) - S(6), RCX(b) + S(6), yy, ic);
                }
            }
            g_modeHits.push_back(std::make_pair(b, m));
            // 只登记到提示表，不参与点击派发
            g_tipHits.push_back(TbHit{ b, std::wstring(m == 0 ? L"toolbox_grid" : L"toolbox_list"),
                                       std::wstring(m == 0 ? L"图标模式" : L"列表模式") });
        }
    }

    int top = head.bottom;
    int pad = S(8);
    int wide = (int)(rcPalette.right - rcPalette.left) - pad * 2;
    float L = (float)(rcPalette.left + pad) / g_s;

    // 搜索框（34 区域，24 框），紧跟标题行
    RECT sr = R(L, (float)(top + S(5)) / g_s, (float)wide / g_s, 24);
    g_searchRect = sr;
    fillR(dc, sr, 4, g_p.input);
    outlineR(dc, sr, 4, g_a.searchActive ? g_p.accent : g_p.border);
    ico(dc, "cmd.search", R((float)(sr.left + S(6)) / g_s, (float)(sr.top + S(4)) / g_s, 16, 16));
    RECT tr = R((float)(sr.left + S(26)) / g_s, (float)sr.top / g_s,
                (float)(sr.right - sr.left - S(30)) / g_s, 24);
    std::wstring shown = g_a.search;
    if (g_a.searchActive && !g_imeComp.empty()) shown += g_imeComp;
    if (!shown.empty()) {
        tx(dc, shown, tr, g_p.text, g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    } else {
        tx(dc, L"搜索组件", tr, g_p.textFaint, g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    }
    // 激活时绘制闪烁光标
    if (g_a.searchActive && g_toolSearchBlink) {
        int textW = tw(dc, shown, g_f12);
        int caretX = sr.left + S(26) + textW;
        int caretTop = sr.top + S(4);
        int caretBot = sr.bottom - S(4);
        fill(dc, RECT{ caretX, caretTop, caretX + S(2), caretBot }, g_p.accent);
    }

    // 组件分类页签：常用 / 基本组件 / 扩展组件 / 外部组件
    g_catHits.clear();
    float cy = (float)(top + S(36)) / g_s;
    float cx0 = L;
    for (int c = 0; c < 3; ++c) {
        int wch = tw(dc, CAT_NAMES[c], g_f11) + S(12);
        RECT cr = R(cx0, cy, (float)wch / g_s, 20);
        bool act = (g_a.activeCat == c);
        bool hot = in(cr, mp.x, mp.y);
        if (act) {
            fillR(dc, cr, 4, g_p.accentSubtle);
            outlineR(dc, cr, 4, g_p.accent);
        } else if (hot) {
            fillR(dc, cr, 4, g_p.hover);
        }
        tx(dc, CAT_NAMES[c], cr, act ? g_p.text : g_p.textDim, g_f11,
           DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        g_catHits.push_back(std::make_pair(cr, c));
        cx0 += (float)(wch + S(4)) / g_s;
    }

    // 分类页签和组件区之间的横线：组件箱内部也要有层次
    int divY = top + S(60);
    hline(dc, rcPalette.left, rcPalette.right, divY, g_p.split);

    int cat = g_a.activeCat;
    bool searching = (g_a.search[0] != 0);
    float bodyTop = (float)(divY + S(6)) / g_s;
    float floorY = (float)rcPalette.bottom / g_s - S(6);

    // 计算内容总高度
    int totalH = 0;
    int cols = (int)((float)wide / g_s / 68.0f + 0.5f);
    if (cols < 2) cols = 2;
    if (cols > 6) cols = 6;
    if (g_a.toolMode == 0) {
        int count = 0;
        for (int k = 0; k < kind_count(); ++k) {
            if ((searching || KINDS[k].cat == cat) && tool_match(k)) count++;
        }
        int rows = (count + cols - 1) / cols;
        totalH = rows * 66 * g_s;
    } else {
        int count = 0;
        for (int k = 0; k < kind_count(); ++k) {
            if ((searching || KINDS[k].cat == cat) && tool_match(k)) count++;
        }
        totalH = count * S(26);
    }
    g_toolContentH = totalH;

    int viewH = (int)((floorY - bodyTop) * g_s);
    int maxS = g_toolContentH - viewH;
    if (maxS < 0) maxS = 0;
    if (g_toolScroll > maxS) g_toolScroll = maxS;
    if (g_toolScroll < 0) g_toolScroll = 0;

    int saved = SaveDC(dc);
    IntersectClipRect(dc, rcPalette.left, divY, rcPalette.right, rcPalette.bottom);

    int bodyTopPx = (int)(bodyTop * g_s);
    int floorYPx = (int)(floorY * g_s);

    if (g_a.toolMode == 0) {
        // ── 图标模式：网格卡片
        float cell = (float)wide / g_s / cols;
        float rowTop = bodyTop + 2 - (float)g_toolScroll / g_s;
        int col = 0;
        for (int k = 0; k < kind_count(); ++k) {
            if (!searching && KINDS[k].cat != cat) continue;
            if (!tool_match(k)) continue;
            float rx = L + col * cell;
            RECT r = R(rx, rowTop, cell - 2, 62);
            if (r.bottom > bodyTopPx && r.top < floorYPx) {
                bool hot = (g_a.toolHot == k);
                if (hot) {
                    fillR(dc, r, 4, g_p.hover);
                    outlineR(dc, r, 4, g_p.borderSoft);
                }
                ico(dc, KINDS[k].icon, R(rx + (cell - 2 - 24) / 2, rowTop + 8, 24, 24));
                tx(dc, KINDS[k].name, R(rx, rowTop + 38, cell - 2, 20),
                   g_p.text, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                g_toolHits.push_back(std::make_pair(r, k));
            }
            col++;
            if (col == cols) { col = 0; rowTop += 66; }
        }
    } else {
        // ── 列表模式：一行一个组件，右侧标默认尺寸
        int rowH = S(26);
        int y = divY + S(1) - g_toolScroll;
        for (int k = 0; k < kind_count(); ++k) {
            if (!searching && KINDS[k].cat != cat) continue;
            if (!tool_match(k)) continue;
            RECT r = RECT{ rcPalette.left + S(1), y, rcPalette.right - S(1), y + rowH };
            if (r.bottom > bodyTopPx && r.top < floorYPx) {
                bool hot = (g_a.toolHot == k);
                if (hot) fillR(dc, r, 3, g_p.hover);
                ico(dc, KINDS[k].icon, R((float)(r.left + S(10)) / g_s,
                                         (float)(y + S(5)) / g_s, 16, 16));
                tx(dc, KINDS[k].name,
                   R((float)(r.left + S(34)) / g_s, (float)y / g_s,
                     (float)(r.right - r.left - S(44)) / g_s, (float)rowH / g_s),
                   g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                hline(dc, r.left + S(6), r.right - S(6), y + rowH - 1,
                      g_theme == 0 ? RGB(0x2C, 0x2C, 0x2C) : g_p.borderSoft);
                g_toolHits.push_back(std::make_pair(r, k));
            }
            y += rowH;
        }
    }
    RestoreDC(dc, saved);

    // 绘制右侧滚动条
    if (maxS > 0) {
        int trackTop = (int)(bodyTop * g_s);
        int trackBot = (int)(floorY * g_s);
        int bx = rcPalette.right - S(6);
        RECT track = RECT{ bx, trackTop, bx + S(4), trackBot };
        int trackH = trackBot - trackTop;
        int thumbH = std::max(S(24), (int)((float)trackH * viewH / g_toolContentH + 0.5f));
        int ty = trackTop + (int)((float)(trackH - thumbH) * g_toolScroll / maxS + 0.5f);
        RECT thumb = RECT{ bx, ty, bx + S(4), ty + thumbH };
        fillR(dc, track, 2, g_p.panel);
        POINT mp; mouse_now(&mp);
        bool hot = in(track, mp.x, mp.y);
        fillR(dc, thumb, 2, hot ? g_p.accent : g_p.border);
    }
}

