// 输出栏：清空图标按钮 / 日志行命中 / 右键菜单（清空全部、全选、复制）
static RECT g_outClearBtn = RECT{ 0, 0, 0, 0 };
static RECT g_outListRect = RECT{ 0, 0, 0, 0 };
static std::vector<std::pair<RECT, int> > g_logRowRects;   // 日志行矩形 → g_a.log 下标
static bool  g_outMenuOpen = false;
static POINT g_outMenuPos  = { 0, 0 };
static std::vector<std::pair<RECT, int> > g_outMenuHits;   // 0 清空全部 1 全选 2 复制
static const wchar_t* OUT_MENU_ITEMS[3] = { L"清空全部", L"全选", L"复制" };

// 代码表格右键菜单：自绘（跟随主题配色），尺寸全部走 S()，
// 所以 1K / 2K / 4K、100%~200% 缩放下观感一致，不会像原生菜单那样字体跑偏。
static bool  g_codeMenuOpen = false;
static DWORD g_codeMenuAteTick = 0;    // 菜单项刚被点执行：吞掉随之而来的左键松手
static POINT g_codeMenuPos  = { 0, 0 };
static RECT  g_codeMenuRect = RECT{ 0, 0, 0, 0 };
static int   g_codeMenuHot  = -1;
static std::vector<std::pair<RECT, int> > g_codeMenuHits;   // 0 复制 1 剪切 2 粘贴 3 撤销 4 全选
static bool  g_codeMenuEn[5] = { false, false, false, false, false };   // 复制/剪切/粘贴/撤销/全选

// ── 表格块选区（在表格上按住鼠标拖动，选中一整片单元格）──
// 鼠标按下时先记 pending：不拖动 = 原来的单击行为（进编辑/切勾选），
// 拖过 4 DIP 才切换成「块选区」，这样单击手感不变、拖动又能选表格。
static bool  g_tblSelOn     = false;   // 有块选区
static int   g_tblSelARow   = -1, g_tblSelACol = 0;   // 锚点（按下的格）
static int   g_tblSelFRow   = -1, g_tblSelFCol = 0;   // 焦点（当前拖到的格）
static bool  g_tblPressPend = false;   // 已按下、还没判定是点击还是拖动
static bool  g_tblDragging  = false;   // 正在拖块选区
static int   g_tblPendRow   = -1, g_tblPendCol = 0;
static int   g_tblPendAct   = 0;       // 1 进编辑（按下已执行） 2 切勾选（抬起执行） 0 无
static POINT g_tblPendPt    = { 0, 0 };

// 清空图标：图标库里没有对应的 PNG，手绘一个小垃圾桶（细线描边）
static void out_clear_glyph(HDC dc, RECT r, COLORREF c)
{
    int x = RCX(r), y = RCY(r);
    int l = x - S(5), rr = x + S(5), t = y - S(3), b = y + S(6);
    HGDIOBJ op = SelectObject(dc, pen(c));
    HGDIOBJ ob = SelectObject(dc, GetStockObject(NULL_BRUSH));
    // 盖 + 把手
    MoveToEx(dc, l - S(2), t, NULL);  LineTo(dc, rr + S(2), t);
    MoveToEx(dc, x - S(2), t - S(2), NULL);  LineTo(dc, x + S(2), t - S(2));
    MoveToEx(dc, x - S(2), t - S(2), NULL);  LineTo(dc, x - S(2), t);
    MoveToEx(dc, x + S(2), t - S(2), NULL);  LineTo(dc, x + S(2), t);
    // 桶身（上宽下窄）+ 两道竖纹
    MoveToEx(dc, l, t, NULL);  LineTo(dc, l + S(1), b);
    LineTo(dc, rr - S(1), b);  LineTo(dc, rr, t);
    MoveToEx(dc, x - S(2), t + S(3), NULL);  LineTo(dc, x - S(2), b - S(2));
    MoveToEx(dc, x + S(2), t + S(3), NULL);  LineTo(dc, x + S(2), b - S(2));
    SelectObject(dc, ob);
    SelectObject(dc, op);
}

// 拖选时把指针 y 换算成日志行下标；拖到列表外就钳到首/末行
static int log_row_at(int y)
{
    if (g_logRowRects.empty()) return -1;
    for (size_t i = 0; i < g_logRowRects.size(); ++i)
        if (y >= g_logRowRects[i].first.top && y < g_logRowRects[i].first.bottom)
            return g_logRowRects[i].second;
    if (y < g_logRowRects.front().first.top) return g_logRowRects.front().second;
    return g_logRowRects.back().second;
}

// 指针位置 → 字符边界：横着按字宽定位，纵按行定位；拖出列表上下沿就钳到首/末
// 查找路径或 URL 在文本中的位置
static bool find_path_or_url(const std::wstring& text, size_t& start, size_t& len) {
    // 1. 匹配 URL
    const wchar_t* urlPrefixes[] = { L"http://", L"https://", L"ftp://", L"file://" };
    for (auto p : urlPrefixes) {
        size_t pos = text.find(p);
        if (pos != std::wstring::npos) {
            size_t end = pos;
            while (end < text.size()) {
                wchar_t c = text[end];
                if (iswspace(c)) break;
                if (c == L')' || c == L']' || c == L'>' || c == L'"' || c == L'\'') break;
                if (c == L'，' || c == L'。' || c == L'；' || c == L'：' || c == L'、') break;
                ++end;
            }
            start = pos; len = end - pos;
            return true;
        }
    }

    // 2. 匹配盘符路径
    for (size_t i = 0; i + 2 < text.size(); ++i) {
        if (iswalpha(text[i]) && text[i+1] == L':' && (text[i+2] == L'\\' || text[i+2] == L'/')) {
            size_t end = i;
            while (end < text.size()) {
                wchar_t c = text[end];
                if (iswspace(c)) break;
                if (c == L')' || c == L']' || c == L'>' || c == L'"' || c == L'\'') break;
                if (c == L'，' || c == L'。' || c == L'；' || c == L'：' || c == L'、') break;
                ++end;
            }
            start = i; len = end - i;
            return true;
        }
    }
    return false;
}

static std::wstring extract_path_or_url(const std::wstring& text) {
    size_t start, len;
    if (find_path_or_url(text, start, len)) return text.substr(start, len);
    return L"";
}

static LogPos log_pos_at(int mx, int my)
{
    LogPos p;
    int row = log_row_at(my);
    if (row < 0 || row >= (int)g_a.log.size()) return p;
    p.row = row;
    HWND h = g_hwnd ? g_hwnd : NULL;
    HDC dc = GetDC(h);
    if (!dc) return p;
    if (my < g_logRowRects.front().first.top)
        p.col = 0;
    else if (my >= g_logRowRects.back().first.bottom)
        p.col = (int)g_a.log[row].text.size();
    else
        p.col = log_col_at(dc, row, mx);
    ReleaseDC(h, dc);
    return p;
}

// 输出区右键菜单：画在总绘制最后一道，压在日志和其它面板上面
static void paint_outmenu(HDC dc)
{
    g_outMenuHits.clear();
    if (!g_outMenuOpen || !g_a.showBottom || !g_a.showOutput) return;

    int w = S(116), ih = S(26), ph = S(12) + ih * 3;
    int px = g_outMenuPos.x, py = g_outMenuPos.y;
    if (py + ph > g_h - S(4)) py = g_outMenuPos.y - ph;
    if (py < S(4)) py = S(4);
    if (px + w > g_w - S(4)) px = g_w - S(4) - w;
    if (px < S(4)) px = S(4);
    RECT pop = RECT{ px, py, px + w, py + ph };
    RECT sh = pop;
    OffsetRect(&sh, 0, S(3));
    fill(dc, sh, g_p.frame);
    fillR(dc, pop, 5, g_p.elevated);
    outlineR(dc, pop, 5, g_p.border);

    POINT mp;
    mouse_now(&mp);
    for (int i = 0; i < 3; ++i) {
        RECT r = RECT{ pop.left + S(4), pop.top + S(6) + i * ih,
                       pop.right - S(4), pop.top + S(6) + (i + 1) * ih };
        bool hot = in(r, mp.x, mp.y);
        if (hot) fillR(dc, r, 3, g_p.hover);
        bool dim = (i == 2 && !log_has_sel());      // 没选中时「复制」灰掉
        tx(dc, OUT_MENU_ITEMS[i],
           R((float)(r.left + S(10)) / g_s, (float)r.top / g_s,
             (float)(r.right - r.left - S(16)) / g_s,
             (float)(r.bottom - r.top) / g_s),
           dim ? g_p.textFaint : (hot ? g_p.text : g_p.textDim), g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        g_outMenuHits.push_back(std::make_pair(r, i));
    }
}

// 代码表格右键菜单（自绘）：卡片 + 主题色顶条 + 悬停高亮 + 快捷键提示。
// 全部尺寸都乘 S()，所以 1K/2K/4K 与各种界面缩放下比例一致，不会出现小字糊成一片。
// 菜单矩形与各项命中区：绘制和鼠标命中共用这一套，打开时先算好，
// 不用等下一帧 paint 才有 hits（否则右键后立刻左键点会点空）。
// ── 菜单配色：从主题色派生（不是写死灰）────────────────────────────
//   浅色皮肤：浮层色压成浅灰，只掺 3% 主题色相 → 灰但不死板；
//   深色皮肤：浮层色抬亮一档，掺 6% 主题色相 → 比背景亮、能看出是这个皮肤；
//   边框 / 分割线 / 悬停全部由卡片底色推出来，换皮肤时整块菜单跟着变。
static void code_menu_colors(COLORREF& bg, COLORREF& bd, COLORREF& hov,
                             COLORREF& fg, COLORREF& fgDim, COLORREF& sep, COLORREF& sh)
{
    COLORREF base = g_p.elevated;
    if (g_uiDark) {
        bg    = mixc(base, RGB(255, 255, 255), 0.10f);   // 比底色亮一档
        bg    = mixc(bg, g_p.accent, 0.06f);             // 掺主题色相
        bd    = mixc(bg, RGB(255, 255, 255), 0.22f);
        hov   = tint_step(bg, 0.16f);                    // 悬停再亮一档
        sep   = mixc(bg, RGB(255, 255, 255), 0.14f);
        fg    = g_p.text;
        fgDim = mixc(g_p.text, bg, 0.28f);
        sh    = mixc(bg, RGB(0, 0, 0), 0.72f);
    } else {
        bg    = mixc(base, RGB(240, 240, 242), 0.72f);   // 白卡片压成浅灰
        bg    = mixc(bg, g_p.accent, 0.035f);            // 极淡主题色
        bd    = mixc(bg, RGB(0, 0, 0), 0.16f);
        hov   = tint_step(bg, 0.09f);
        sep   = mixc(bg, RGB(0, 0, 0), 0.10f);
        fg    = g_p.text;
        fgDim = mixc(g_p.text, bg, 0.42f);
        sh    = mixc(bg, RGB(0, 0, 0), 0.38f);
    }
}

// 统一的几何：5 项（复制/剪切/粘贴/撤销 | 全选），最后一项之前留一条分隔
static const int CM_ITEM_N = 5;
static int  code_menu_item_h()  { return S(30); }
static int  code_menu_pad_t()   { return S(6); }
static int  code_menu_sep_gap() { return S(9); }
static int  code_menu_icon_w()  { return S(34); }   // 图标列宽（右边还有一条竖线）

static int code_menu_item_top(const RECT& pop, int i)
{
    return pop.top + code_menu_pad_t() + i * code_menu_item_h() +
           (i >= CM_ITEM_N - 1 ? code_menu_sep_gap() : 0);
}

static RECT code_menu_item_rect(const RECT& pop, int i)
{
    int top = code_menu_item_top(pop, i);
    return RECT{ pop.left + S(2), top, pop.right - S(2), top + code_menu_item_h() };
}

static RECT code_menu_layout()
{
    int w  = S(206);
    int ph = code_menu_pad_t() * 2 + code_menu_item_h() * CM_ITEM_N + code_menu_sep_gap();
    int px = g_codeMenuPos.x, py = g_codeMenuPos.y;
    if (px + w > g_w - S(6))  px = g_w - S(6) - w;          // 右边放不下：往左挪
    if (py + ph > g_h - S(6)) py = g_codeMenuPos.y - ph;    // 下面放不下：翻到上方
    if (px < S(6)) px = S(6);
    if (py < S(6)) py = S(6);

    RECT pop = RECT{ px, py, px + w, py + ph };
    g_codeMenuRect = pop;
    // 局部刷新时把投影一起算进去，否则悬停切换时边缘会留一圈旧阴影
    InflateRect(&g_codeMenuRect, S(2), S(6));
    g_codeMenuHits.clear();
    for (int i = 0; i < CM_ITEM_N; ++i)
        g_codeMenuHits.push_back(std::make_pair(code_menu_item_rect(pop, i), i));
    return pop;
}

// 菜单项图标（描边小图形，颜色跟着文字走，不用位图、不依赖字体符号）
static void code_menu_icon(HDC dc, int kind, RECT box, COLORREF c)
{
    int cx = RCX(box), cy = RCY(box);
    int s  = S(5);
    HPEN pen = CreatePen(PS_SOLID, std::max(1, S(1)), c);
    HGDIOBJ op = SelectObject(dc, pen);
    HGDIOBJ ob = SelectObject(dc, GetStockObject(NULL_BRUSH));
    if (kind == 0) {                       // 复制：两个错位方框
        Rectangle(dc, cx - s + S(2), cy - s + S(2), cx + s + S(2), cy + s + S(2));
        Rectangle(dc, cx - s - S(1), cy - s - S(1), cx + s - S(1), cy + s - S(1));
    } else if (kind == 1) {                // 剪切：两把刀 + 两个环
        MoveToEx(dc, cx - s, cy - s, NULL); LineTo(dc, cx + s - S(2), cy + s - S(3));
        MoveToEx(dc, cx + s, cy - s, NULL); LineTo(dc, cx - s + S(2), cy + s - S(3));
        Ellipse(dc, cx - s + S(1), cy + s - S(2), cx - s + S(5), cy + s + S(2));
        Ellipse(dc, cx + s - S(4), cy + s - S(2), cx + s, cy + s + S(2));
    } else if (kind == 2) {                // 粘贴：剪贴板 + 顶部夹子
        Rectangle(dc, cx - s + S(1), cy - s + S(2), cx + s - S(1), cy + s);
        HBRUSH hb = CreateSolidBrush(c);
        HGDIOBJ ob2 = SelectObject(dc, hb);
        Rectangle(dc, cx - S(3), cy - s, cx + S(3), cy - s + S(3));
        SelectObject(dc, ob2);
        DeleteObject(hb);
    } else if (kind == 3) {                // 撤销：向左回退箭头
        MoveToEx(dc, cx + s, cy + s - S(1), NULL);
        LineTo(dc, cx + s, cy - S(1));
        LineTo(dc, cx - s + S(2), cy - S(1));
        MoveToEx(dc, cx - s - S(1), cy - S(1), NULL);
        LineTo(dc, cx - s + S(3), cy - S(4));
        MoveToEx(dc, cx - s - S(1), cy - S(1), NULL);
        LineTo(dc, cx - s + S(3), cy + S(2));
    } else {                               // 全选：虚框 + 内部三条短线
        Rectangle(dc, cx - s, cy - s, cx + s + S(1), cy + s + S(1));
        for (int k = -1; k <= 1; ++k)
            MoveToEx(dc, cx - s + S(3), cy + k * S(3), NULL),
            LineTo(dc, cx + s - S(2), cy + k * S(3));
    }
    SelectObject(dc, ob);
    SelectObject(dc, op);
    DeleteObject(pen);
}

static void paint_code_menu(HDC dc)
{
    if (!g_codeMenuOpen) return;

    static const wchar_t* ITEM_TXT[CM_ITEM_N] = { L"复制", L"剪切", L"粘贴", L"撤销", L"全选" };
    static const wchar_t* ITEM_KEY[CM_ITEM_N] = { L"Ctrl+C", L"Ctrl+X", L"Ctrl+V", L"Ctrl+Z", L"Ctrl+A" };

    COLORREF cBg, cBd, cHov, cFg, cFgDim, cSep, cSh;
    code_menu_colors(cBg, cBd, cHov, cFg, cFgDim, cSep, cSh);

    RECT pop = code_menu_layout();

    // 投影
    RECT sh = pop;
    OffsetRect(&sh, S(1), S(3));
    fillR(dc, sh, S(7), cSh);
    // 卡片
    fillR(dc, pop, S(7), cBg);
    outlineR(dc, pop, S(7), cBd);

    // 图标列与文字之间的竖线：把「图标位」和「操作名」分开
    int iconRight = pop.left + code_menu_icon_w();
    fill(dc, RECT{ iconRight, pop.top + S(5), iconRight + 1, pop.bottom - S(5) }, cSep);

    POINT mp;
    mouse_now(&mp);
    for (size_t k = 0; k < g_codeMenuHits.size(); ++k) {
        RECT r = g_codeMenuHits[k].first;
        int  it = g_codeMenuHits[k].second;
        bool en  = g_codeMenuEn[it];
        bool hot = en && in(r, mp.x, mp.y);
        if (hot) fillR(dc, r, S(4), cHov);

        // 可用项用正常前景色（悬停时加粗区分），禁用项才降一档灰
        COLORREF fg = en ? cFg : cFgDim;
        RECT ib = RECT{ r.left, r.top, iconRight, r.bottom };
        code_menu_icon(dc, it, ib, fg);

        tx(dc, ITEM_TXT[it], RECT{ iconRight + S(10), r.top, r.right - S(74), r.bottom },
           fg, hot ? g_f12b : g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        tx(dc, ITEM_KEY[it], RECT{ r.right - S(70), r.top, r.right - S(8), r.bottom },
           cFgDim, g_f11, DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
    }

    // 分类之间的横分割线：剪贴板/撤销四项 与 全选 之间
    int sy = code_menu_item_top(pop, CM_ITEM_N - 1) - code_menu_sep_gap() / 2;
    fill(dc, RECT{ pop.left + S(8), sy, pop.right - S(8), sy + 1 }, cSep);
}

// 弹层里第 i 项的矩形；绘制和命中都用它，免得两边各算一套对不上。
// 「隐藏」前面留一道 6 DIP 的空隙，把它和三个停靠方式分开。
static RECT out_dock_item_rect(int i)
{
    RECT r = g_outDockPopup;
    int ih = S(26);
    int top = g_outDockPopup.top + S(6) + i * ih;
    if (i >= 4) top += S(6);
    r.top = top;
    r.bottom = top + ih;
    r.left += S(4);
    r.right -= S(4);
    return r;
}

static void paint_output(HDC dc)
{
    if (!g_a.showBottom || !g_a.showOutput) {
        g_outTabHits.clear();
        g_outDockBtn = RECT{ 0, 0, 0, 0 };
        g_outDockPopup = RECT{ 0, 0, 0, 0 };
        g_outClearBtn = RECT{ 0, 0, 0, 0 };
        g_outListRect = RECT{ 0, 0, 0, 0 };
        g_logRowRects.clear();
        g_outMenuOpen = false;
        return;
    }

    // 外层先当「停靠区的缝」铺一层，再在里面放一张带圆角和描边的卡片：
    // 易语言的输出/提示栏就是一块块独立面板，不是直接铺满停靠区的。
    // 贴窗口边的那一侧不能留 4px 缝（否则卡片边缘跟上方侧栏错开一截），
    // 但左边完全贴 0 会把 1px 描边切在窗口外面，看着「没有左边线」：留 2px 刚好露出线。
    // 右侧一律贴到 rcBottomPanel.right：它和文档页签条右沿、画布/右列分隔线是同一条线，
    // 这样「显示方式」的下拉箭头正好和设计器位置箭头垂直对齐。
    fill(dc, rcBottomPanel, g_p.frame);
    // 顶边那条线：画布与输出面板之间要有个明确的边界
    if (rcSplitB.right > rcSplitB.left) fill(dc, rcSplitB, g_p.split);
    RECT card = rcBottomPanel;
    // 不向左偏移，保持原始边界，防止凸起
    card.top    += S(4);
    card.right  -= 0;
    card.bottom = rcBottomPanel.bottom;
    
    // 贴边填充面板底色
    fill(dc, card, g_p.panel);
    // 画出外边框
    outline(dc, card, g_p.border);
    
    // 关键：直接用分割线的颜色覆盖左侧那条边，彻底盖住缝隙感，同时不越界
    fill(dc, RECT{ card.left, card.top, card.left + S(1), card.bottom }, g_p.split);
    // 状态栏顶边那条线是唯一分界：把卡片自己的底边线擦成卡片底色，
    // 否则两条 1px 线挨着，看上去就是「两条线」。
    if (g_a.showStatus)
        hline(dc, card.left + S(3), card.right - S(3), card.bottom - 1, g_p.panel);

    // 页签条（卡片内的顶栏，VS 工具窗口那种）
    RECT bar = card;
    bar.bottom = bar.top + S(30);
    fill(dc, bar, g_p.bar); // 彻底改为直角填充，防止圆角切角导致左侧左上角不对齐凸起
    hline(dc, bar.left + S(8), bar.right - S(8), bar.bottom - 1, g_p.borderSoft);

    POINT mp;
    mouse_now(&mp);

    // 页签：照易语言那排「提示 / 输出 / 调用表 / 监视表 / 变量表 / 搜寻1 / 搜寻2 / 剪辑历史」，
    // 只有文字、没有图标，每个页签是一个带边框的小方框。
    g_outTabHits.clear();
    int x = bar.left + S(6);
    for (int i = 0; i < OUT_TAB_N; ++i) {
        int w = tw(dc, OUT_TABS[i], g_f12) + S(24);
        if (w < S(50)) w = S(50);
        RECT r = RECT{ x, bar.top + S(3), x + w, bar.bottom - S(4) };
        bool act = (g_a.outTab == i);
        bool hot = in(r, mp.x, mp.y);
        if (act) {
            fillR(dc, r, 3, g_p.elevated);
            outlineR(dc, r, 3, g_p.border);
        } else if (hot) {
            fillR(dc, r, 3, g_p.hover);
            outlineR(dc, r, 3, g_p.border);
        } else {
            fillR(dc, r, 3, g_p.panel);
            outlineR(dc, r, 3, g_p.borderSoft);
        }
        tx(dc, OUT_TABS[i], r,
           act ? g_p.text : g_p.textDim, g_f12,
           DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        if (act) {
            RECT u = RECT{ r.left + S(4), r.bottom - S(2), r.right - S(4), r.bottom };
            fillR(dc, u, 1, g_p.accent);
        }
        g_outTabHits.push_back(std::make_pair(r, i));
        x += w + S(2);
    }

    // 右上「显示方式」：参考 VS2026 工具窗口右上那个下拉，点开选铺满 / 停靠 / 隐藏
    {
        const wchar_t* lbl = L"显示方式";
        int w = tw(dc, lbl, g_f11) + S(36);
        RECT r = RECT{ bar.right - S(8) - w, bar.top + S(4), bar.right - S(8), bar.bottom - S(4) };
        bool hot = in(r, mp.x, mp.y) || g_a.outMenu >= 0;
        if (hot) fillR(dc, r, 4, g_p.hover);
        tx(dc, lbl, R((float)(r.left + S(8)) / g_s, (float)r.top / g_s,
                      (float)(w - S(28)) / g_s, (float)(r.bottom - r.top) / g_s),
           hot ? g_p.text : g_p.textDim, g_f11,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        int cx = r.right - S(12), cy = RCY(r);
        HGDIOBJ op = SelectObject(dc, pen(hot ? g_p.text : g_p.textDim));
        MoveToEx(dc, cx - S(4), cy - S(2), NULL);
        LineTo(dc, cx, cy + S(2));
        LineTo(dc, cx + S(4), cy - S(2));
        SelectObject(dc, op);
        g_outDockBtn = r;
    }

    // 「显示方式」左侧的清空图标：只有切到「输出」页签才显示。
    // 悬停提示走 g_tipHits（和工具条按钮同一套 tooltip，不派发动作）。
    {
        RECT c = RECT{ g_outDockBtn.left - S(6) - S(22), g_outDockBtn.top,
                       g_outDockBtn.left - S(6), g_outDockBtn.bottom };
        g_outClearBtn = (g_a.outTab <= 1) ? c : RECT{ 0, 0, 0, 0 };
        if (g_a.outTab <= 1) {
            bool chot = in(c, mp.x, mp.y);
            if (chot) fillR(dc, c, 3, g_p.hover);
            out_clear_glyph(dc, c, chot ? g_p.text : g_p.textDim);
            g_tipHits.push_back(TbHit{ c, std::wstring(),
                                       g_a.outTab == 0 ? std::wstring(L"清空提示信息")
                                                       : std::wstring(L"清空历史输出信息") });
        }
    }

    // 内容区：卡片内、页签条以下
    RECT list = card;
    list.top = bar.bottom;
    list.left   += S(1);
    list.right  -= S(1);
    list.bottom -= S(1);
    g_outListRect = list;
    g_logRowRects.clear();

    // 提示页：正在预览某条备注（点表格备注格触发）—— 直接铺这段文字
    if (g_a.outTab == 0 && !g_tipNoteText.empty()) {
        RECT tr = RECT{ list.left + S(12), list.top + S(8),
                        list.right - S(12), list.bottom - S(10) };
        if (tr.bottom > tr.top) {
            HGDIOBJ of = SelectObject(dc, g_f12);
            SetTextColor(dc, g_p.text);
            SetBkMode(dc, TRANSPARENT);
            DrawTextW(dc, g_tipNoteText.c_str(), (int)g_tipNoteText.size(), &tr,
                      DT_LEFT | DT_TOP | DT_WORDBREAK | DT_NOPREFIX);
            SelectObject(dc, of);
        }
        g_outListRect = RECT{ 0, 0, 0, 0 };   // 这一段不参与日志行命中
        g_logRowRects.clear();
        return;
    }

    // 提示页表格：搜索定位选中命令后也是这张表（lib_cmd_tip 生成），全宽绘制
    if (g_a.outTab == 0 && g_tipMode == 1 && !g_tipTables.empty()) {
        tip_table_paint(dc, list);
    } else if (g_a.outTab > 1) {
        std::wstring hint = std::wstring(L"（") + OUT_TABS[g_a.outTab] + L" 暂无内容）";
        tx(dc, hint, R((float)(card.left + S(8)) / g_s,
                       (float)(list.top + S(10)) / g_s, 320, 20),
           g_p.textFaint, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    } else {
        int rowH = S(19);
        int y = list.top + S(6);
        // 两个页签各看各的：先挑出本页的行号，再按可视高度取尾部
        std::vector<int> ids;
        ids.reserve(g_a.log.size());
        for (int i = 0; i < (int)g_a.log.size(); ++i)
            if (g_a.log[i].page == g_a.outTab) ids.push_back(i);
        int firstIdx = (int)ids.size() - (list.bottom - list.top - S(10)) / rowH;
        if (firstIdx < 0) firstIdx = 0;
        g_logTextX = card.left + S(20);

        for (int k = firstIdx; k < (int)ids.size(); ++k) {
            const int i = ids[k];
            if (y + rowH > list.bottom) break;
            const LogRow& r = g_a.log[i];
            // 先把本行字宽量好（命中缓存后几乎零开销），供绘制和拖动命中共用
            std::vector<int> dx;
            log_row_dx(dc, i, dx);
            // 只给选中的那一段「文字」铺底色：行尾空白不染色，跨行中间行也一样。
            // 上下各收一点，选区看起来是贴着字的细条，不是一整块色板。
            int ca = 0, cb = 0;
            if (log_row_sel(i, ca, cb) && dx.size() > 1) {
                int x0 = g_logTextX + (ca < (int)dx.size() ? dx[ca] : dx.back());
                int x1 = g_logTextX + (cb < (int)dx.size() ? dx[cb] : dx.back());
                if (x1 > list.right - S(2)) x1 = list.right - S(2);
                if (x1 > x0)
                    fill(dc, RECT{ x0, y + S(2), x1, y + rowH - S(2) },
                         g_p.accentSubtle);
            }
            g_logRowRects.push_back(std::make_pair(
                RECT{ list.left, y, list.right, y + rowH }, i));
            // 四级颜色全部可在 设置 → 日志 里改（蓝色＝正常、绿色＝成功、橙＝警告、红＝错误）
            COLORREF c = g_logCol[r.lvl];

            HBRUSH b = br(c);
            HGDIOBJ ob = SelectObject(dc, b);
            HGDIOBJ op = SelectObject(dc, GetStockObject(NULL_PEN));
            // 圆点/文字的左基线与上面页签行的起点取齐（都在 card.left + 8 一线）
            int cx = card.left + S(9), cy = y + rowH / 2;
            Ellipse(dc, cx - S(3), cy - S(3), cx + S(3), cy + S(3));
            SelectObject(dc, op);
            SelectObject(dc, ob);

            size_t linkStart = 0, linkLen = 0;
            bool hasLink = find_path_or_url(r.text, linkStart, linkLen);
            if (!hasLink) {
                tx(dc, r.text, R((float)(card.left + S(20)) / g_s, (float)y / g_s,
                                 (float)(list.right - card.left - S(24)) / g_s, 19),
                   c, g_fmono, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            } else {
                if (linkStart > 0) {
                    std::wstring pre = r.text.substr(0, linkStart);
                    tx(dc, pre, R((float)(card.left + S(20)) / g_s, (float)y / g_s,
                                  (float)(list.right - card.left - S(24)) / g_s, 19),
                       c, g_fmono, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                }
                std::wstring link = r.text.substr(linkStart, linkLen);
                int preW = (linkStart > 0) ? tw(dc, r.text.substr(0, linkStart), g_fmono) : 0;
                int linkW = tw(dc, link, g_fmono);
                RECT lr = R((float)(card.left + S(20) + preW) / g_s, (float)y / g_s,
                            (float)linkW / g_s, 19);
                
                // 直接画文字
                tx(dc, link, lr, g_p.accent, g_fmono, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
                // 在文字底部画一条 1px 的线作为下划线
                int xUnder = card.left + S(20) + preW;
                int yUnder = y + rowH - S(4);
                hline(dc, xUnder, xUnder + linkW, yUnder, g_p.accent);

                if (linkStart + linkLen < r.text.size()) {
                    std::wstring post = r.text.substr(linkStart + linkLen);
                    tx(dc, post, R((float)(card.left + S(20) + preW + linkW) / g_s, (float)y / g_s,
                                   (float)(list.right - card.left - S(24) - preW - linkW) / g_s, 19),
                       c, g_fmono, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
                }
            }
            y += rowH;
        }
    }
}

// 显示方式弹层单独画：它会压到下面的日志区，而画布/其它面板在 paint_output
// 之后还会继续画，所以放到总绘制的最后一道。
static void paint_outdock(HDC dc)
{
    if (!g_a.showBottom || !g_a.showOutput || g_a.outMenu < 0) return;
    if (g_outDockBtn.right <= g_outDockBtn.left) return;   // 还没画过工具栏，没有锚点

    // 从按钮下沿往下弹（原来往上弹，手一松就把菜单顶到画布上了）
    int w = S(132), ih = S(26), ph = S(12) + ih * OUT_DOCK_N + S(6);
    int px = g_outDockBtn.right - w;
    int py = g_outDockBtn.bottom + S(2);
    if (py + ph > g_h - S(8)) py = g_outDockBtn.top - S(4) - ph;
    if (px < S(4)) px = S(4);
    if (px + w > g_w - S(4)) px = g_w - S(4) - w;
    g_outDockPopup = RECT{ px, py, px + w, py + ph };

    RECT sh = g_outDockPopup;
    OffsetRect(&sh, 0, S(3));
    fill(dc, sh, g_p.frame);
    fillR(dc, g_outDockPopup, 5, g_p.elevated);
    outlineR(dc, g_outDockPopup, 5, g_p.border);

    POINT mp;
    mouse_now(&mp);
    for (int i = 0; i < OUT_DOCK_N; ++i) {
        RECT ir = out_dock_item_rect(i);
        bool hot = in(ir, mp.x, mp.y);
        if (hot) fillR(dc, ir, 3, g_p.hover);
        // 当前停靠方式打勾；「隐藏」不是停靠态，永远不打勾
        bool cur = (i < 4 && i == g_a.outDock);
        if (cur) {
            HGDIOBJ op = SelectObject(dc, pen(g_p.accent));
            int cxk = ir.left + S(12), cyk = RCY(ir);
            MoveToEx(dc, cxk - S(3), cyk, NULL);
            LineTo(dc, cxk, cyk + S(3));
            LineTo(dc, cxk + S(4), cyk - S(4));
            SelectObject(dc, op);
        }
        // 文字居中（勾选标记仍然留在左边，不参与居中）
        tx(dc, OUT_DOCK_ITEMS[i],
           R((float)(ir.left + S(2)) / g_s, (float)ir.top / g_s,
             (float)(ir.right - ir.left - S(4)) / g_s, (float)(ir.bottom - ir.top) / g_s),
           cur ? g_p.text : g_p.textDim, g_f12,
           DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    }
    // 「隐藏」上面的那道分隔线
    RECT sep = out_dock_item_rect(4);
    hline(dc, g_outDockPopup.left + S(10), g_outDockPopup.right - S(10),
          sep.top - S(4), g_p.borderSoft);
}

// ══════════════════════════════════════════════════════════════════
// 状态栏
// ══════════════════════════════════════════════════════════════════

static void seg(HDC dc, int& x, const std::wstring& s, COLORREF c, HFONT f)
{
    int w = tw(dc, s, f);
    RECT r = R((float)(x + S(8)) / g_s, (float)rcStatus.top / g_s, (float)w / g_s, 24);
    tx(dc, s, r, c, f, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    x += w + S(8);
}
static void seg_div(HDC dc, int& x)
{
    vline(dc, x + S(4), rcStatus.top + S(6), rcStatus.top + S(18), g_p.border);
    x += S(9);
}

static void paint_status(HDC dc)
{
    if (!g_a.showStatus) { g_statusOutBtn = RECT{ 0, 0, 0, 0 }; return; }
    fill(dc, rcStatus, g_p.bar);
    hline(dc, rcStatus.left, rcStatus.right, rcStatus.top, g_p.border);

    int x = rcStatus.left;
    // 状态点
    HBRUSH b = br(g_p.ok);
    HGDIOBJ ob = SelectObject(dc, b);
    HGDIOBJ op = SelectObject(dc, GetStockObject(NULL_PEN));
    int cy = RCY(rcStatus);
    Ellipse(dc, rcStatus.left + S(10), cy - S(3), rcStatus.left + S(16), cy + S(3));
    SelectObject(dc, op);
    SelectObject(dc, ob);
    x = rcStatus.left + S(22);

    // 状态栏不再挂"就绪"这类空话，只显示真正有用的信息（选中组件/网格/缩放）

    if (!g_a.sel.empty()) {
        int i = g_a.sel[0];
        if (i < (int)g_a.form.ctl.size()) {
            const Ctl& c = g_a.form.ctl[i];
            seg(dc, x, c.name, g_p.text, g_f12);
            seg_div(dc, x);
            seg(dc, x, wnum((int)c.w) + L"×" + wnum((int)c.h), g_p.text, g_f12);
            seg_div(dc, x);
            seg(dc, x, L"X " + wnum((int)c.x) + L"  Y " + wnum((int)c.y), g_p.textDim, g_f12);
            seg_div(dc, x);
        }
    }
    seg(dc, x, L"界面 " + wnum((int)(g_uiScale * 100 + 0.5f)) + L"%", g_p.textDim, g_f12);
    seg_div(dc, x);
    seg(dc, x, L"网点 " + wnum((int)g_a.form.grid) + L"×" + wnum((int)g_a.form.gridY) +
              (g_a.form.snap ? L" 吸附" : L""), g_p.textDim, g_f12);
    seg_div(dc, x);
    seg(dc, x, g_theme ? L"浅色" : L"深色", g_p.textDim, g_f12);

    // 右侧：保存状态与控件数。（原来的「输出面板」开关去掉了：
    // 工具条上本来就有输出栏开关，两边重复还占地方。）
    int rx = rcStatus.right - S(16);

    std::wstring dt = g_a.form.dirty ? L"未保存" : L"已保存";
    int dw = tw(dc, dt, g_f12);
    tx(dc, dt, R((float)(rx - dw) / g_s, (float)rcStatus.top / g_s, (float)dw / g_s, 24),
       g_a.form.dirty ? g_p.warn : g_p.textFaint, g_f12,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    rx -= dw + S(10);
    vline(dc, rx, rcStatus.top + S(6), rcStatus.top + S(18), g_p.border);
    rx -= S(8);
    std::wstring line = wnum((int)g_a.form.ctl.size()) + L" 个控件";
    int lw2 = tw(dc, line, g_f12);
    tx(dc, line, R((float)(rx - lw2) / g_s, (float)rcStatus.top / g_s, (float)lw2 / g_s, 24),
       g_p.textFaint, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
}

