static const UINT_PTR TIMER_CODE_AUTOSCROLL = 15; // 拖选出视口边缘的自动滚动（30ms）

static bool is_code_dark_theme() {
    int lum = (GetRValue(g_p.panel) * 299 + GetGValue(g_p.panel) * 587 + GetBValue(g_p.panel) * 114) / 1000;
    return lum < 128;
}

