// 表格勾选列的「对勾」：两条加粗折线，比字体里的 ✓ 更大、更清楚
static void code_check_glyph(HDC dc, RECT box, COLORREF c)
{
    int cx = (box.left + box.right) / 2;
    int cy = (box.top + box.bottom) / 2;
    int u  = S(3);
    if (u < 2) u = 2;
    HPEN pen = CreatePen(PS_SOLID, std::max(2, S(2)), c);
    HGDIOBJ op = SelectObject(dc, pen);
    MoveToEx(dc, cx - u * 2, cy - u / 2, NULL);
    LineTo(dc, cx - u / 2, cy + u * 2);
    LineTo(dc, cx + u * 2, cy - u * 2);
    SelectObject(dc, op);
    DeleteObject(pen);
}
static const COLORREF C_CARET  = RGB(0, 102, 204);    // 编辑框光标

// ── 声明表类型（真机默认程序集页实测，2026-11-15 截图逐像素取样）──
// 五张表列数/列头各自独立：程序集名表与程序集变量表列边界完全相同、
// 上下紧贴连成一块（截图 x=510/743/906 两张表头同一套竖线），paint 里
// 两表列宽逐列取最大值后共用；其余各表按内容自适应、互不相干。
enum { TT_ASM = 0, TT_ASMVAR, TT_SUB, TT_PARAM, TT_VAR, TT_N };

// ══════════════════════════════════════════════════════════════════
// 表格结构体：一张表 = 一串「列定义」，画表 / 命中 / 编辑 / 写回全按它自动适配。
// 加一列、改一列的行为（文本 / 勾选 / 只读）只改这里，别再散落到各处判列号。
// ══════════════════════════════════════════════════════════════════
enum CodeField {                    // 列的语义：读数据、写回都认这个 ID
    CFD_NONE = 0, CFD_NAME, CFD_TYPE, CFD_REMARK,
    CFD_PUB, CFD_PKG, CFD_BYREF, CFD_NULLABLE, CFD_ARRAY, CFD_STATIC,
    CFD_MAX
};
enum CodeColKind {
    CCOL_TEXT  = 0,                 // 单击进编辑、可输入
    CCOL_CHECK = 1,                 // 单击打勾 / 再点取消（红色对勾）
    CCOL_LOCK  = 2                  // 单击给光标，但只读不收字符（真机「保 留」列）
};
struct CodeColDef {
    const wchar_t* title;           // 表头文字
    int            w;               // 兜底最小宽度（DIP，真机量得）
    int            kind;            // CodeColKind
    int            field;           // CodeField
};
struct CodeTableDef {
    int               tt;           // TT_*
    const CodeColDef* cols;
    int               n;
};

static const CodeColDef kColsAsm[] = {          // 第一张：窗口程序集
    { L"窗口程序集名", 123, CCOL_TEXT,  CFD_NAME   },
    { L"保 留",         58, CCOL_LOCK,  CFD_NONE   },
    { L"保 留",         41, CCOL_LOCK,  CFD_NONE   },
    { L"备 注",        180, CCOL_TEXT,  CFD_REMARK },
};
static const CodeColDef kColsAsmVar[] = {       // 程序集变量（与上一张竖线贯通）
    { L"变量名", 123, CCOL_TEXT,  CFD_NAME   },
    { L"类 型",   58, CCOL_TEXT,  CFD_TYPE   },
    { L"数组",    41, CCOL_CHECK, CFD_ARRAY  },
    { L"备 注",  180, CCOL_TEXT,  CFD_REMARK },
};
static const CodeColDef kColsSub[] = {          // 子程序
    { L"子程序名",   123, CCOL_TEXT,  CFD_NAME   },
    { L"返回值类型",  70, CCOL_TEXT,  CFD_TYPE   },
    { L"公开",        35, CCOL_CHECK, CFD_PUB    },
    { L"易包",        35, CCOL_TEXT,  CFD_PKG    },
    { L"备 注",      160, CCOL_TEXT,  CFD_REMARK },
};
static const CodeColDef kColsParam[] = {        // 参数
    { L"参数名", 120, CCOL_TEXT,  CFD_NAME     },
    { L"类 型",   72, CCOL_TEXT,  CFD_TYPE     },
    { L"参考",    36, CCOL_CHECK, CFD_BYREF    },
    { L"可空",    36, CCOL_CHECK, CFD_NULLABLE },
    { L"数组",    36, CCOL_CHECK, CFD_ARRAY    },
    { L"备 注",  200, CCOL_TEXT,  CFD_REMARK   },
};
static const CodeColDef kColsVar[] = {          // 局部变量
    { L"变量名",  64, CCOL_TEXT,  CFD_NAME   },
    { L"类 型",   47, CCOL_TEXT,  CFD_TYPE   },
    { L"静态",    35, CCOL_CHECK, CFD_STATIC },
    { L"数组",    35, CCOL_CHECK, CFD_ARRAY  },
    { L"备 注",  160, CCOL_TEXT,  CFD_REMARK },
};
static const CodeTableDef kCodeTables[TT_N] = {
    { TT_ASM,    kColsAsm,    4 },
    { TT_ASMVAR, kColsAsmVar, 4 },
    { TT_SUB,    kColsSub,    5 },
    { TT_PARAM,  kColsParam,  6 },
    { TT_VAR,    kColsVar,    5 },
};
static const CodeTableDef& code_tbl(int tt)
{
    return kCodeTables[(tt >= 0 && tt < TT_N) ? tt : 0];
}
static int code_col_n(int tt) { return code_tbl(tt).n; }
static const CodeColDef* code_col(int tt, int c)
{
    const CodeTableDef& t = code_tbl(tt);
    return (c >= 0 && c < t.n) ? &t.cols[c] : NULL;
}
static int  code_col_field(int tt, int c)      { const CodeColDef* d = code_col(tt, c); return d ? d->field : CFD_NONE; }
static bool code_col_is_check(int tt, int c)   { const CodeColDef* d = code_col(tt, c); return d && d->kind == CCOL_CHECK; }
static bool code_col_is_lock(int tt, int c)    { const CodeColDef* d = code_col(tt, c); return d && d->kind == CCOL_LOCK; }
static bool code_col_editable(int tt, int c)   { const CodeColDef* d = code_col(tt, c); return d && d->kind != CCOL_CHECK; }
// 备注列下标（绿字、无下划线），没有返回 -1
static int  code_col_remark(int tt)
{
    for (int k = 0; k < code_col_n(tt); ++k)
        if (code_col_field(tt, k) == CFD_REMARK) return k;
    return -1;
}
// 行写回目标（CRow::dst）：0 程序集名 / 1 子程序头 / 2 参数 / 3 局部变量 / 5 程序集变量
static int code_tbl_dst(int tt)
{
    switch (tt) {
    case TT_ASM:    return 0;
    case TT_SUB:    return 1;
    case TT_PARAM:  return 2;
    case TT_VAR:    return 3;
    case TT_ASMVAR: return 5;
    }
    return 0;
}

// 表头底色：真机三色分组（截图取样），设置页可整体覆盖。
static COLORREF code_hdr_bg(int tt)
{
    if (g_tableHeaderColor != 0) return g_tableHeaderColor;
    switch (tt) {
        case TT_ASM:
        case TT_ASMVAR: return C_HDRGRAY;  // #ECECEC 灰
        case TT_SUB:    return C_HDRBG;    // #E6EDE4 灰绿
        case TT_PARAM:
        case TT_VAR:    return C_HDRBLU;   // #D9E3F0 淡蓝
    }
    return C_HDRGRAY;
}

// 当前正在编辑的行是否为隐藏结构行（paint 与编辑层共用，一次遍历每帧都刷新）
static bool g_stmtRowEdit = false;

struct CRow {
    int  kind;      // 0 表头 1 数据行 2 语句行
    int  tt;        // kind!=2：所属声明表类型 TT_*
    std::wstring c[6];
    int  level;     // 语句行缩进层级
    bool sep;       // 表前留白
    bool hidden;    // 结构隐藏行：不显示文字，只由流程线表达（否则/如果结束）
    bool disp;      // 语句原文带前导点（表格模式不显示点，存储/编辑保留）
    int  dst;       // 写回目标：0 程序集名 1 子程序头 2 参数 3 局部变量 4 语句 5 程序集变量
    int  sub, idx;  // 所属子程序下标 / 元素下标（空子程序占位行 idx=-1）
    CRow() : kind(0), tt(TT_ASM), level(0), sep(false), hidden(false), disp(false), dst(-1), sub(-1), idx(-1) {}
};

// ── 流程命令表（真机易语言的点前缀语法，参考 su-lang-main/modules/flow_commands.py）──
// 前缀匹配（长的在前），ui_flow_role / 隐藏行判定 / 编辑器补全共用同一口径。
static const wchar_t* const kFlowHeadsG[] = {
    L"如果真", L"如果", L"判断开始", L"判断循环首", L"判断",
    L"计次循环首", L"变量循环首", L"循环判断首", L"循环首"
};
static const wchar_t* const kFlowTailsG[] = {
    L"如果真结束", L"如果结束", L"判断结束", L"判断尾",
    L"计次循环尾", L"变量循环尾", L"判断循环尾", L"循环判断尾", L"循环尾"
};
static const wchar_t* const kFlowBranchG[] = { L"否则如果", L"否则", L"默认", L"案例" };

// 去掉前导点/空白后的命令文本
static std::wstring flow_trim(const std::wstring& t)
{
    size_t i = 0;
    while (i < t.size() && (t[i] == L'.' || t[i] == L' ' || t[i] == L'\t')) ++i;
    return t.substr(i);
}
// 取命令名（第一个空白/全角空白/括号之前的部分）
static std::wstring flow_cmd_name(const std::wstring& t)
{
    std::wstring s = flow_trim(t);
    size_t p = s.find_first_of(L" \t（(");
    return p == std::wstring::npos ? s : s.substr(0, p);
}
// 命令文本是否命中前缀表里的某条命令
static bool flow_hit(const wchar_t* const* arr, int n, const std::wstring& t)
{
    std::wstring s = flow_trim(t);
    for (int i = 0; i < n; ++i)
        if (s.compare(0, wcslen(arr[i]), arr[i]) == 0) return true;
    return false;
}
// 块头 → 配套块尾名（如果→如果结束；计次循环首→计次循环尾…）
static std::wstring flow_tail_of(const std::wstring& headCmd)
{
    if (headCmd == L"如果")     return L"如果结束";
    if (headCmd == L"如果真")   return L"如果真结束";
    if (headCmd == L"判断")     return L"判断尾";
    if (headCmd == L"判断开始") return L"判断结束";
    std::wstring s = headCmd;
    if (!s.empty() && s[s.size() - 1] == L'首') s[s.size() - 1] = L'尾';
    return s;
}
// 条件类块头（否则 / 否则如果 / 默认 只在它们里面合法）
static bool flow_is_cond(const std::wstring& name)
{
    return name == L"如果" || name == L"如果真" || name == L"判断" || name == L"判断开始";
}

// 块配对：产出「语句行下标 → 所属轨道号」，给流程线和隐藏行判定共用。
// 规则（与 ui_flow_build 同一套语义）：块头压栈开轨道；缩进退回或显式块尾
// 弹栈。栈帧记录块头行号/层级/命令名。
// 关键与 ui_flow_build 的差异：显式块尾行本身若缩进 ≥ 块头，算「闭合了块」，
// 之后分支/尾行不再属于这个块（否则尾后的普通语句会被当成块内、错误投影）。
struct FlowFrame {
    int lane;          // 轨道号
    int headIdx;       // 块头语句下标
    int headLv;        // 块头缩进层级（弹栈判定用）
    std::wstring name; // 块头命令名
};
static std::vector<int> code_flow_lanes(const std::vector<EStmt>& body,
                                        std::vector<FlowFrame>* openFrames = nullptr)
{
    std::vector<int> lanes(body.size(), -1);
    std::vector<FlowFrame> stack;
    for (size_t i = 0; i < body.size(); ++i) {
        const EStmt& st = body[i];
        // 缩进退回 = 隐式收束（不登记 = 该轨道不再表达）
        while (!stack.empty() && st.indent < stack.back().headLv)
            stack.pop_back();
        if (!st.text.empty() && st.text[0] == L'.') {
            std::wstring nm = flow_cmd_name(st.text);
            bool head = flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), st.text);
            bool tail = flow_hit(kFlowTailsG, (int)(sizeof(kFlowTailsG) / sizeof(kFlowTailsG[0])), st.text);
            bool br   = flow_hit(kFlowBranchG, (int)(sizeof(kFlowBranchG) / sizeof(kFlowBranchG[0])), st.text);
            if (head) {
                int lane = (int)stack.size();
                stack.push_back(FlowFrame{ lane, (int)i, st.indent, nm });
            } else if (tail) {
                if (!stack.empty()) {
                    lanes[i] = stack.back().lane;      // 尾行登记归属
                    if (st.indent <= stack.back().headLv) stack.pop_back();  // 真正闭合
                }
            } else if (br) {
                if (!stack.empty()) lanes[i] = stack.back().lane;   // 主轨道贯穿分支体
            }
        }
    }
    if (openFrames) *openFrames = stack;
    return lanes;
}

// 语句行 → 块范围表（head 行下标 → 该块尾行下标；未闭合块 = body.size()）。
// 隐藏判定、复制/删除的整块展开、光标跨块导航共用一张表，语义不分叉。
static std::vector<int> code_flow_block_ranges(const std::vector<EStmt>& body)
{
    std::vector<int> endAt(body.size(), -1);
    std::vector<FlowFrame> stack;
    for (size_t i = 0; i < body.size(); ++i) {
        const EStmt& st = body[i];
        while (!stack.empty() && st.indent < stack.back().headLv) {
            endAt[stack.back().headIdx] = (int)i;   // 缩进退回：隐式收束到本行
            stack.pop_back();
        }
        if (st.text.empty() || st.text[0] != L'.') continue;
        std::wstring nm = flow_cmd_name(st.text);
        if (flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), st.text))
            stack.push_back(FlowFrame{ (int)stack.size(), (int)i, st.indent, nm });
        else if (flow_hit(kFlowTailsG, (int)(sizeof(kFlowTailsG) / sizeof(kFlowTailsG[0])), st.text)) {
            if (!stack.empty()) { endAt[stack.back().headIdx] = (int)i; stack.pop_back(); }
        }
    }
    while (!stack.empty()) { endAt[stack.back().headIdx] = (int)body.size(); stack.pop_back(); }
    return endAt;
}

// 隐藏行判定用：body[start..end) 内是否存在「缩进严格比 indent 浅」的语句。
// 块尾行自身不算收束者；空语句不算（真机：空行不结束块，块尾之后必须空一行）。
static bool code_flow_closed_at(const std::vector<EStmt>& body, size_t start, size_t end, int indent)
{
    for (size_t k = start; k < end && k < body.size(); ++k) {
        const EStmt& st = body[k];
        if (st.indent >= indent || st.text.empty()) continue;
        if (st.text[0] != L'.') return true;
        if (!flow_hit(kFlowTailsG, (int)(sizeof(kFlowTailsG) / sizeof(kFlowTailsG[0])), st.text)) return true;
    }
    return false;
}

// 结构隐藏行：真机表格里合法配对的「否则」和条件尾不显示文字，由流程线表达。
// 配对 = 该命令被某个合法块头认领：否则/默认 要求所属块头是条件类
// （如果/如果真/判断/判断开始）；否则如果 同样但保留条件文本不隐藏。
// 未配对的（孤立否则、块头不合法的尾）仍显示文字，方便修草稿。
static bool code_stmt_hidden_tail(const std::vector<EStmt>& body, size_t idx)
{
    const EStmt& cur = body[idx];
    if (cur.text.empty() || cur.text[0] != L'.') return false;
    std::wstring c = flow_cmd_name(cur.text);
    bool isBranch   = (c == L"否则" || c == L"默认");
    bool isCondTail = (c == L"如果结束" || c == L"如果真结束" || c == L"判断结束");
    if (!isBranch && !isCondTail) return false;

    // 往回找认领它的块头：与 code_flow_lanes 同一弹栈规则（indent < headLv 即收束）。
    std::vector<FlowFrame> stack;
    for (size_t k = 0; k < idx; ++k) {
        const EStmt& st = body[k];
        while (!stack.empty() && st.indent < stack.back().headLv) stack.pop_back();
        if (st.text.empty() || st.text[0] != L'.') continue;
        std::wstring nm = flow_cmd_name(st.text);
        if (flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), st.text))
            stack.push_back(FlowFrame{ (int)stack.size(), (int)k, st.indent, nm });
        else if (flow_hit(kFlowTailsG, (int)(sizeof(kFlowTailsG) / sizeof(kFlowTailsG[0])), st.text))
            if (!stack.empty() && st.indent <= stack.back().headLv) stack.pop_back();
    }
    if (stack.empty()) return false;
    const FlowFrame& h = stack.back();
    if (cur.indent < h.headLv) return false;      // 本行比块头更浅 = 不是它的尾/分支
    return flow_is_cond(h.name);
}

// 装配当前页签的表格行。渲染（paint_code_table）、命中（code_hit）、
// 提交（code_ed_commit）三处都从这里拿同一份行数据。
// 一条声明行的数据：按列的 CodeField 存，勾选列自动变成 ✓ / 空
struct CodeVals {
    std::wstring v[CFD_MAX];
    CodeVals() {}
    void set(int f, const std::wstring& s) { if (f > 0 && f < CFD_MAX) v[f] = s; }
    void flag(int f, bool on) { set(f, on ? L"1" : L""); }
};

// 表头行：列名直接从列定义取，新增/改名列不用改这里
static void code_push_header(std::vector<CRow>& rows, int tt, int sub, bool sep)
{
    CRow h; h.kind = 0; h.tt = tt; h.dst = code_tbl_dst(tt); h.sub = sub; h.sep = sep;
    for (int k = 0; k < code_col_n(tt); ++k) h.c[k] = code_col(tt, k)->title;
    rows.push_back(h);
}

// 数据行：按列定义把 CodeVals 填进各格（勾选列 → ✓；只读列 → 空）
static void code_push_row(std::vector<CRow>& rows, int tt, int sub, int idx,
                          const CodeVals& vals)
{
    CRow r; r.kind = 1; r.tt = tt; r.dst = code_tbl_dst(tt); r.sub = sub; r.idx = idx;
    for (int k = 0; k < code_col_n(tt); ++k) {
        int f = code_col_field(tt, k);
        if (f == CFD_NONE) continue;
        r.c[k] = code_col_is_check(tt, k) ? (vals.v[f].empty() ? L"" : L"✓") : vals.v[f];
    }
    rows.push_back(r);
}

static void code_rows_build(std::vector<CRow>& rows)
{
    rows.clear();
    int asmIdx = g_a.docTab - 1;
    if (asmIdx < 0 || asmIdx >= (int)g_eAsms.size()) return;
    const EAsm& am = g_eAsms[asmIdx];

    // ① 程序集名表：四列都能点进光标；两个「保留」是只读列
    code_push_header(rows, TT_ASM, -1, false);
    {
        CodeVals v;
        v.set(CFD_NAME, am.name);
        v.set(CFD_REMARK, am.remark);
        code_push_row(rows, TT_ASM, -1, -1, v);
    }
    // ② 程序集变量表（与上一张竖线贯通）
    if (!am.vars.empty()) {
        code_push_header(rows, TT_ASMVAR, -1, false);
        for (size_t i = 0; i < am.vars.size(); ++i) {
            CodeVals v;
            v.set(CFD_NAME, am.vars[i].name);
            v.set(CFD_TYPE, am.vars[i].type);
            v.flag(CFD_ARRAY, am.vars[i].arr);
            v.set(CFD_REMARK, am.vars[i].remark);
            code_push_row(rows, TT_ASMVAR, -1, (int)i, v);
        }
    }
    for (size_t s2 = 0; s2 < am.subs.size(); ++s2) {
        const ESub& sub = am.subs[s2];
        // ③ 子程序表
        code_push_header(rows, TT_SUB, (int)s2, true);
        {
            CodeVals v;
            v.set(CFD_NAME, sub.name);
            v.set(CFD_TYPE, sub.ret);
            v.flag(CFD_PUB, sub.pub);
            v.set(CFD_PKG, sub.pkg);
            v.set(CFD_REMARK, sub.remark);
            code_push_row(rows, TT_SUB, (int)s2, -1, v);
        }
        // ④ 参数表
        if (!sub.args.empty()) {
            code_push_header(rows, TT_PARAM, (int)s2, false);
            for (size_t i = 0; i < sub.args.size(); ++i) {
                const EArg& a = sub.args[i];
                CodeVals v;
                v.set(CFD_NAME, a.name);
                v.set(CFD_TYPE, a.type);
                v.flag(CFD_BYREF, a.byref);
                v.flag(CFD_NULLABLE, a.nullable);
                v.flag(CFD_ARRAY, a.arr);
                v.set(CFD_REMARK, a.remark);
                code_push_row(rows, TT_PARAM, (int)s2, (int)i, v);
            }
        }
        // ⑤ 局部变量表
        if (!sub.locals.empty()) {
            code_push_header(rows, TT_VAR, (int)s2, false);
            for (size_t i = 0; i < sub.locals.size(); ++i) {
                const EArg& v0 = sub.locals[i];
                CodeVals v;
                v.set(CFD_NAME, v0.name);
                v.set(CFD_TYPE, v0.type);
                v.flag(CFD_STATIC, v0.isStatic);
                v.flag(CFD_ARRAY, v0.arr);
                v.set(CFD_REMARK, v0.remark);
                code_push_row(rows, TT_VAR, (int)s2, (int)i, v);
            }
        }
        if (sub.body.empty()) {
            CRow r; r.kind = 2; r.dst = 4; r.sub = (int)s2; r.idx = -1;
            rows.push_back(r);           // 空子程序也给一行空语句行，同易语言
        }
        for (size_t i = 0; i < sub.body.size(); ++i) {
            CRow r; r.kind = 2; r.level = sub.body[i].indent;
            r.dst = 4; r.sub = (int)s2; r.idx = (int)i;
            r.c[0] = sub.body[i].text;
            r.hidden = code_stmt_hidden_tail(sub.body, i);
            r.disp   = !sub.body[i].text.empty() && sub.body[i].text[0] == L'.';
            rows.push_back(r);
        }
    }
}

// 单击勾选格：把对应标志取反（打勾 ↔ 取消），表格重画即可见。
// 行号/列号口径与 code_rows_build 完全一致（r.tt / r.sub / r.idx）。
static void code_toggle_check(int row, int col)
{
    std::vector<CRow> rows; code_rows_build(rows);
    if (row < 0 || row >= (int)rows.size()) return;
    const CRow& r = rows[row];
    if (r.kind != 1 || !code_col_is_check(r.tt, col)) return;
    int ai = g_a.docTab - 1;
    if (ai < 0 || ai >= (int)g_eAsms.size()) return;
    EAsm& am = g_eAsms[ai];
    int f = code_col_field(r.tt, col);
    bool changed = false;
    switch (r.tt) {
    case TT_SUB:                                   // 公开
        if (f == CFD_PUB && r.sub >= 0 && r.sub < (int)am.subs.size()) {
            am.subs[r.sub].pub = !am.subs[r.sub].pub;
            changed = true;
        }
        break;
    case TT_PARAM:                                 // 参考 / 可空 / 数组
        if (r.sub >= 0 && r.sub < (int)am.subs.size() &&
            r.idx >= 0 && r.idx < (int)am.subs[r.sub].args.size()) {
            EArg& a = am.subs[r.sub].args[r.idx];
            if      (f == CFD_BYREF)    { a.byref    = !a.byref;    changed = true; }
            else if (f == CFD_NULLABLE) { a.nullable = !a.nullable; changed = true; }
            else if (f == CFD_ARRAY)    { a.arr      = !a.arr;      changed = true; }
        }
        break;
    case TT_ASMVAR:                                // 程序集变量：数组
        if (f == CFD_ARRAY && r.idx >= 0 && r.idx < (int)am.vars.size()) {
            am.vars[r.idx].arr = !am.vars[r.idx].arr;
            changed = true;
        }
        break;
    case TT_VAR:                                   // 局部变量：静态 / 数组
        if (r.sub >= 0 && r.sub < (int)am.subs.size() &&
            r.idx >= 0 && r.idx < (int)am.subs[r.sub].locals.size()) {
            EArg& v = am.subs[r.sub].locals[r.idx];
            if      (f == CFD_STATIC) { v.isStatic = !v.isStatic; changed = true; }
            else if (f == CFD_ARRAY)  { v.arr      = !v.arr;      changed = true; }
        }
        break;
    }
    if (changed) {
        code_snap_push(false);       // 勾一下也要能撤销
        g_a.form.dirty = true;
    }
}

// ── 几何常量（MECHANICS.md：波段 19px 填充 + 1px 规则线 = 20px 节距；语句行距 18）──
static int  code_row_h()     { return S(24); }   // 声明表行高：字居中，上下各留一点白
static int  code_stmt_h()    { return S(18); }
static int  code_gap()       { return S(10); }
// 代码表格相对视口顶部的留白：表头上面那条 1px 边线要露出来，
// 不能让表格直接顶到面板上沿（绘制 / 命中测试 / 行内编辑几何都读这一个值）
static int  code_table_pad() { return S(1); }
static int  code_lane_step() { return S(22); }   // 一层缩进：连接线 17 + 留白 5


// 滚到第一条语句行所需的像素偏移（--open-code 用：打开就看见流程线）。
// 与 paint_code_table 的行高累加规则保持一致：sep 行先加 GAP，再加行高。
static int code_first_stmt_scroll()
{
    std::vector<CRow> rs;
    code_rows_build(rs);
    int acc = 0;
    for (size_t i = 0; i < rs.size(); ++i) {
        if (rs[i].kind == 2) break;
        if (rs[i].sep) acc += code_gap();
        acc += code_row_h();
    }
    return acc;
}

// 列宽缓存：paint 每帧按内容适配后存这里，code_hit / 编辑框直接用
static int g_codeTW[TT_N][6] = {};   // [表类型][列]
static int g_codeTR[TT_N]    = {};   // 每张声明表的右缘（客户区 x）
static int g_codeStmtW       = 0;    // 语句区文字区宽（含缩进余量）
static int g_codeStmtR       = 0;    // 语句区右缘（客户区 x）
static int g_codeScrollX     = 0;    // 横向滚动（表格超宽时 Shift+滚轮）
// ── 代码页底部横向滚动条 ──────────────────────────────────────────
// 只在内容宽超出视口时出现；尺寸全走 S()（1K/2K/4K 一致），颜色按主题明暗取灰阶。
static int   g_codeMaxScrollX = 0;              // 最大横向滚动量（paint 时更新）
static int   g_codeBarH       = 0;              // 滚动条高度（0 = 不显示）
static RECT  g_codeBarRect    = RECT{ 0, 0, 0, 0 };   // 轨道
static RECT  g_codeBarThumb   = RECT{ 0, 0, 0, 0 };   // 滑块
static bool  g_codeBarDrag    = false;
static int   g_codeBarDragDx  = 0;
static bool  g_codeBarHot     = false;

static void code_scrollbar_paint(HDC dc, const RECT& area)
{
    if (g_codeBarH <= 0 || g_codeMaxScrollX <= 0) {
        g_codeBarRect = RECT{ 0, 0, 0, 0 };
        g_codeBarThumb = RECT{ 0, 0, 0, 0 };
        return;
    }
    int LNW = S(46);
    // area.left 是画布左边（已内缩 3px），行号栏右沿在 area.left + 3 + LNW；
    // 轨道必须从同一条线开始，否则左端会露出 3px 白色底（看着像白块）。
    RECT track = RECT{ area.left + S(3) + LNW, area.bottom, area.right, area.bottom + g_codeBarH };
    g_codeBarRect = track;

    // 配色：跟随主题明暗的灰阶（亮底浅灰、暗底深灰），不用强调色，免得抢眼
    COLORREF cTrack = g_uiDark ? RGB(46, 46, 49)  : RGB(241, 241, 242);
    COLORREF cThumb = g_uiDark ? RGB(92, 92, 97)  : RGB(198, 198, 203);
    COLORREF cLine  = g_uiDark ? RGB(64, 64, 68)  : RGB(226, 226, 229);
    if (g_codeBarDrag || g_codeBarHot) cThumb = g_uiDark ? RGB(120, 120, 126) : RGB(174, 174, 180);

    fill(dc, track, cTrack);
    fill(dc, RECT{ track.left, track.top, track.right, track.top + 1 }, cLine);

    int vw = area.right - (area.left + S(3) + LNW);
    int contentW = vw + g_codeMaxScrollX;
    if (contentW <= 0) return;
    int thumbW = vw * vw / contentW;
    int minW = S(36);
    if (thumbW < minW) thumbW = minW;
    if (thumbW > vw) thumbW = vw;
    int travel = (track.right - track.left) - thumbW;
    int x = track.left + (g_codeMaxScrollX > 0 ? travel * g_codeScrollX / g_codeMaxScrollX : 0);
    RECT th = RECT{ x, track.top + S(3), x + thumbW, track.bottom - S(3) };
    fillR(dc, th, S(3), cThumb);
    g_codeBarThumb = th;
}

// 声明表第 col 列左缘相对表左
static int code_col_x(int tt, int col)
{
    int x = 0;
    for (int k = 0; k < col && k < code_col_n(tt); ++k) x += g_codeTW[tt][k];
    return x;
}

// ── 语句着色分词：关键字深蓝、数字暗红、真假深蓝、注释/字符串绿，其余黑 ──
static bool code_kw_at(const wchar_t* p, int& kwLen)
{
    static const wchar_t* kws[] = {
        // 控制流关键字
        L"计次循环首", L"计次循环尾", L"变量循环首", L"变量循环尾",
        L"判断循环首", L"判断循环尾", L"跳出本次循环", L"跳出循环",
        L"如果真结束", L"如果结束", L"如果真", L"如果", L"否则",
        L"判断", L"返回", L"结束", L"到循环尾", L"继续循环",
        // 核心库命令
        L"信息框", L"调试输出", L"延时", L"处理事件", L"载入",
        L"销毁", L"结束", L"运行", L"执行", L"取文本长度", L"取文本左边",
        L"取文本右边", L"取文本中间", L"到文本", L"到整数"
    };
    for (const wchar_t* kw : kws) {
        size_t n = wcslen(kw);
        if (wcsncmp(p, kw, n) == 0) { kwLen = (int)n; return true; }
    }
    return false;
}
static bool code_kw_ok_next(wchar_t c)   // 关键字后边界：空白/括号/结尾
{
    return c == 0 || c == L' ' || c == L'(' || c == L'（' || c == L')' || c == L'）';
}
static void code_tokenize(const std::wstring& s,
                          std::vector<std::pair<std::wstring, COLORREF>>& out)
{
    out.clear();
    const wchar_t* p = s.c_str();
    // 代码页恒用真机白纸配色，语句着色也固定（不随深浅主题变）
    COLORREF cNorm   = C_INK;
    COLORREF cGreen  = C_GREEN;    // 注释/字符串绿
    COLORREF cNavy   = C_NAVY;     // 关键字蓝
    COLORREF cMaroon = C_MAROON;   // 数字/布尔

    if (*p == L'\'') { out.push_back({s, cGreen}); return; }   // 整行注释
    std::wstring cur;
    auto flush = [&]() {
        if (!cur.empty()) { out.push_back({cur, cNorm}); cur.clear(); }
    };
    wchar_t prev = 0;
    while (*p) {
        if (*p == L'"' || *p == L'“') {         // 字符串（兼容中英文双引号）
            flush();
            std::wstring t; t += *p++;
            wchar_t endQuote = (t[0] == L'“') ? L'”' : L'"';
            while (*p && *p != endQuote && *p != L'"') t += *p++;
            if (*p) t += *p++;
            out.push_back({t, cGreen});
            prev = 0;
            continue;
        }
        if (*p >= L'0' && *p <= L'9') {         // 数字
            flush();
            std::wstring t;
            while (*p >= L'0' && *p <= L'9') t += *p++;
            out.push_back({t, cMaroon});
            prev = L' ';
            continue;
        }
        if ((*p == L'真' || *p == L'假') &&
            (prev == 0 || prev == L' ' || prev == L'（' || prev == L'(') &&
            code_kw_ok_next(p[1])) {            // 真假常量
            flush();
            out.push_back({std::wstring(1, *p), cNavy});
            prev = *p++;
            continue;
        }
        if (*p == L'\'') {                      // 行内注释
            flush();
            out.push_back({std::wstring(p), cGreen});
            return;
        }
        int kwLen = 0;
        if ((prev == 0 || prev == L' ' || prev == L'（' || prev == L'(') &&
            code_kw_at(p, kwLen) && code_kw_ok_next(p[kwLen])) {
            flush();
            out.push_back({std::wstring(p, kwLen), cNavy});
            p += kwLen;
            prev = L' ';
            continue;
        }
        cur += *p++;
        prev = cur.back();
    }
    flush();
}

static void code_scroll_to_row(int targetRow) {
    std::vector<CRow> rows; code_rows_build(rows);
    if (targetRow < 0 || targetRow >= (int)rows.size()) return;
    int targetY = 0; // 和绘制时的初始 Y 偏移一致
    for (int i = 0; i < targetRow; ++i) {
        targetY += (rows[i].sep ? code_gap() : 0) +
                   (rows[i].kind == 2 ? code_stmt_h() : code_row_h());
    }
    int vpHeight = rcCanvas.bottom - rcCanvas.top;
    g_a.codeScroll = targetY - vpHeight / 2; // 让目标行居中
    if (g_a.codeScroll < 0) g_a.codeScroll = 0;
}

// ══════════════════════════════════════════════════════════════════════════
// 通用绘制入口 ── 表格 / 流程线
//
// 约定：本项目里「画表格」「画流程线」只走这两个入口，以后任何新页面要画
// 表格或流程线都直接调 ui_table_draw() / ui_flow_draw()；需要和其它内容
// 逐行交错渲染时，用 ui_table_draw_row() / ui_flow_build()+ui_flow_draw_row()。
// 所有参数（DC、矩形、列宽、行高、文字、字体、颜色、线型、箭头尺寸、轨道
// 步进、命令表、裁剪区）一律由调用方传入；这些函数体内不读取任何全局业务
// 状态（g_p / g_f12 / g_codeTW / S() 都不碰），因此换页面、换皮肤都能复用。
// 只依赖最底层的 GDI 原语：fill / hline / vline / tx / tri_fill / SetPixelV。
// ══════════════════════════════════════════════════════════════════════════

// ────────────────────────────── 表格 ──────────────────────────────
enum { UI_TBL_SOLID = 0, UI_TBL_DOT = 1 };

struct UiTableCell {
    const wchar_t* text;   // 单元格文字（不可为 nullptr，空串传 L""）
    COLORREF       fg;     // 文字色
    HFONT          font;   // 字体
    UINT           align;  // DT_LEFT / DT_CENTER / DT_RIGHT
    COLORREF       bg;     // 该格自己的底色（0 = 跟随行底色；块选区用）
};

struct UiTableRow {
    const UiTableCell* cells;  // 长度必须 == UiTableSpec::colCount
    COLORREF bg;               // 行底色
    bool     header;           // 表头（用 bgHeader 覆盖）
    bool     selected;         // 选中（用 bgSelected 覆盖）
    bool     editing;          // 编辑中（用 bgInput 覆盖，优先级最高）
};

struct UiTableSpec {
    HDC  dc;
    RECT clip;                  // 裁剪区（内部 SaveDC + IntersectClipRect）
    int  left, top, right;     // 表格左沿 / 首行 y / 右沿（末列延展到这里）
    const int* colW;            // 各列宽度（colCount 个）
    int  colCount;
    int  rowH;                  // 行高（整表模式用）
    int  padL, padR;            // 单元格左右内边距
    COLORREF bgHeader;          // 表头底色
    COLORREF bgSelected;        // 选中底色
    COLORREF bgInput;           // 编辑底色
    COLORREF lineColor;         // 格线色
    int  lineStyle;             // UI_TBL_SOLID / UI_TBL_DOT
    int  dotPeriod;             // 点线周期（真机 = 4）
    bool outer;                 // 是否画左右外框
    bool headerTop;             // 表头是否额外画一条顶线
    const UiTableRow* rows;
    int  rowCount;
};

// 画一行：供「表格行与其它内容交错渲染」的页面用，y / rh 由调用方给。
static void ui_table_draw_row(const UiTableSpec& s, int rowIdx, int y, int rh)
{
    if (!s.dc || !s.colW || s.colCount <= 0 || rh <= 0 ||
        rowIdx < 0 || rowIdx >= s.rowCount || !s.rows) return;

    int saved = SaveDC(s.dc);
    IntersectClipRect(s.dc, s.clip.left, s.clip.top, s.clip.right, s.clip.bottom);

    const UiTableRow& r = s.rows[rowIdx];
    COLORREF bg = r.bg;
    if (r.header)   bg = s.bgHeader;
    if (r.selected) bg = s.bgSelected;
    if (r.editing)  bg = s.bgInput;
    fill(s.dc, RECT{ s.left, y, s.right, y + rh - 1 }, bg);

    // 逐格底色（块选区/单格高亮用）：压在整行底色之上、文字之下
    if (r.cells) {
        int cbx = s.left;
        for (int k = 0; k < s.colCount; ++k) {
            int cbx1 = (k < s.colCount - 1) ? cbx + s.colW[k] : s.right;
            if (r.cells[k].bg)
                fill(s.dc, RECT{ cbx, y, cbx1, y + rh - 1 }, r.cells[k].bg);
            cbx = cbx1;
        }
    }

    // 文字：列边界完全由外部传进来的 colW 累加得到
    if (r.cells) {
        int x0 = s.left;
        for (int k = 0; k < s.colCount; ++k) {
            int x1 = (k < s.colCount - 1) ? x0 + s.colW[k] : s.right;
            const UiTableCell& c = r.cells[k];
            if (c.text && *c.text) {
                RECT tr = { x0 + s.padL, y, x1 - s.padR, y + rh - 1 };
                if (tr.right > tr.left) {
                    tx(s.dc, c.text, tr, c.fg, c.font,
                       DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX | DT_NOCLIP | c.align);
                }
            }
            x0 = x1;
        }
    }

    // 格线：实线走 GDI 画笔；点线必须逐点画（PS_DOT 周期对不上真机 4px）
    auto hlineEx = [&](int x1, int x2, int yy) {
        if (x2 <= x1) return;
        if (s.lineStyle == UI_TBL_DOT) {
            int p = s.dotPeriod > 0 ? s.dotPeriod : 4;
            for (int x = x1; x <= x2; x += p) SetPixelV(s.dc, x, yy, s.lineColor);
        } else {
            hline(s.dc, x1, x2, yy, s.lineColor);
        }
    };
    auto vlineEx = [&](int xx, int y1, int y2) {
        if (y2 <= y1) return;
        if (s.lineStyle == UI_TBL_DOT) {
            int p = s.dotPeriod > 0 ? s.dotPeriod : 4;
            for (int yy = y1; yy <= y2; yy += p) SetPixelV(s.dc, xx, yy, s.lineColor);
        } else {
            vline(s.dc, xx, y1, y2, s.lineColor);
        }
    };

    hlineEx(s.left, s.right - 1, y + rh - 1);                      // 行底线
    if (r.header && s.headerTop) hlineEx(s.left, s.right - 1, y);  // 表头顶线
    int cx = s.left;
    for (int k = 1; k < s.colCount; ++k) {
        cx += s.colW[k - 1];
        vlineEx(cx - 1, y, y + rh - 2);                             // 列分隔
    }
    if (s.outer) {
        vlineEx(s.left, y, y + rh - 2);
        vlineEx(s.right - 1, y, y + rh - 2);
    }
    RestoreDC(s.dc, saved);
}

// 一次性画完整张表 —— 以后需要画表格的页面统一调这个。
static void ui_table_draw(const UiTableSpec& s)
{
    for (int i = 0; i < s.rowCount; ++i)
        ui_table_draw_row(s, i, s.top + i * s.rowH, s.rowH);
}

// 跨行选区/撤销快照定义在交互段（paint 之后），绘制与编辑入口先行声明
static bool code_ed_line_in_sel(int i);
static bool code_ed_row_sel_range(int i, int& c0, int& c1);   // 记事本语义：行 i 的选区字符范围
static void code_snap_push(bool mergeable);
static HFONT code_ed_font();

// ───────────────────────────── 流程线 ─────────────────────────────
// 1:1 易语言：灰色点/虚线轨道；块头行 = 横向连接 + 实心右向三角 ▶；
// 块内行 = 每层一条竖虚线贯穿；分支行 = 横线 + 右向三角 ▶；
// 条件尾（如果结束 / 如果真结束 / 判断结束）= 横线 + 中点向下收口 ▼；
// 循环尾（计次循环尾 / 变量循环尾 / 判断尾 …）= 横线 + 右向三角 ▶；
// 没有结束语句的块：在块内最后一条语句处隐式收束，画与块头完全相同的
// 横线 + 右向三角 ▶。真机里这些结束语句本就不显示，靠轨道闭合表达。
// 依据：文档/参考-真机表格规格-MECHANICS.md §6；
//       参考/su-lang-main/ui/flow_guides.py（build_flow_guides 隐式收束）、
//       参考/su-lang-main/ui/code_editor.py（connector arrow 规则）、
//       参考/su-lang-main/modules/flow_commands.py（CONDITIONAL_TAIL / LOOP_TAIL）、
//       参考/su-lang-main/docs/流程线绘制维护.md（隐藏尾节点投影）。
enum {
    UI_FLOW_AUTO      = 0,   // 按 spec.cmds 自动识别角色
    UI_FLOW_BODY      = 1,
    UI_FLOW_START     = 2,
    UI_FLOW_BRANCH    = 3,
    UI_FLOW_TAIL      = 4,   // 块尾：横线 + 右向三角（循环尾等）
    UI_FLOW_TAIL_DOWN = 5    // 条件尾：横线 + 向下收口箭头
};

struct UiFlowCmdSet {
    const wchar_t* const* heads;     int headCount;      // 块头命令（前缀匹配）
    const wchar_t* const* tails;     int tailCount;      // 全部块尾命令
    const wchar_t* const* branches;  int branchCount;    // 分支命令
    const wchar_t* const* downTails; int downTailCount;  // 其中画 ▼ 的条件尾
};

struct UiFlowRow {
    int            y, h;   // 行顶 / 行高（视口坐标，调用方算好）
    int            level;  // 文字缩进层级
    int            role;   // UI_FLOW_*；AUTO 时按 cmds 识别
    const wchar_t* text;   // 语句原文（可带前导 '.'）
    bool           hidden; // 结构隐藏行：不显示文字，只画流程线
};

struct UiFlowSpec {
    HDC  dc;
    RECT clip;                // 裁剪区
    int  trackX;              // 第 0 层轨道 x
    int  textX;               // 第 0 层文字起点 x
    int  laneStep;            // 每嵌套一层轨道/文字右移量（真机 22）
    int  textGap;             // 箭头尖端到文字起点的留白
    int  arrowLen;            // 实心三角边长（0 = 不画箭头）
    int  endStem;             // 条件尾向下收口的纵线长度
    int  exitOffset;          // 偏移出口轨道相对主轨道的 x 偏移（真机 6px）
    COLORREF lineColor;
    int  lineStyle;           // 0 实线 / 1 点线
    int  dashOn, dashOff;     // 竖轨道虚线：亮/暗长度
    int  dotOn,  dotOff;      // 横连点线：亮/暗长度
    const UiFlowCmdSet* cmds; // 命令表（role=AUTO 时用，可为 nullptr）
    const UiFlowRow* rows;
    int  rowCount;
};

// 角色识别：先块尾、再分支、最后块头，避免「如果结束」被当成「如果」。
static int ui_flow_role(const wchar_t* raw, const UiFlowCmdSet& c)
{
    if (!raw) return UI_FLOW_BODY;
    const wchar_t* p = raw;
    while (*p == L'.' || *p == L' ' || *p == L'\t') ++p;
    if (!*p) return UI_FLOW_BODY;
    auto hit = [&](const wchar_t* const* arr, int n) {
        for (int i = 0; i < n; ++i)
            if (wcsncmp(p, arr[i], wcslen(arr[i])) == 0) return true;
        return false;
    };
    if (c.tails && hit(c.tails, c.tailCount)) {
        if (c.downTails && hit(c.downTails, c.downTailCount)) return UI_FLOW_TAIL_DOWN;
        return UI_FLOW_TAIL;
    }
    if (c.branches && hit(c.branches, c.branchCount)) return UI_FLOW_BRANCH;
    if (c.heads    && hit(c.heads,    c.headCount))   return UI_FLOW_START;
    return UI_FLOW_BODY;
}

// 一行上可能同时收束不止一条轨道，逐条记 (轨道, 横线层级)。
struct UiFlowClose { int lane; int level; };

struct UiFlowLayout {
    std::vector<int>                       role;    // 每行最终角色
    std::vector<int>                       lane;    // 每行所属轨道（-1 无）
    std::vector<std::vector<int>>          active;  // 每行要画竖线的主轨道集合
    std::vector<std::vector<int>>          exit;    // 每行要画的偏移出口轨道（lane）
    std::vector<std::vector<UiFlowClose>>  close;   // 本行隐式收束 ▶
    std::vector<std::vector<UiFlowClose>>  entry;   // 隐藏分支入口 ▶（投影到后一可见行）
    std::vector<std::vector<UiFlowClose>>  head;    // 出口轨道头部横线（投影到前一可见行）
    std::vector<int>                       downExit;// 本行 ▼ 所在的出口轨道（-1 无）
    std::vector<int>                       stopLane;// 本行主轨道在中心结束（-1 无）
};

// 块配对 + 隐式收束：压栈/弹栈算出每条轨道的起止行；没有显式结束语句的
// 块在「块内最后一条有文字的语句行」处闭合，收束箭头由 ui_flow_paint 画。
static void ui_flow_build(const UiFlowSpec& s, UiFlowLayout& L)
{
    L.role.assign(s.rowCount, UI_FLOW_BODY);
    L.lane.assign(s.rowCount, -1);
    L.active.assign(s.rowCount, std::vector<int>());
    L.exit.assign(s.rowCount, std::vector<int>());
    L.close.assign(s.rowCount, std::vector<UiFlowClose>());
    L.entry.assign(s.rowCount, std::vector<UiFlowClose>());
    L.head.assign(s.rowCount, std::vector<UiFlowClose>());
    L.downExit.assign(s.rowCount, -1);
    L.stopLane.assign(s.rowCount, -1);

    struct Frame { int lane, level, row; };
    std::vector<Frame> stack;
    auto fill_active = [&](int i) {
        L.active[i].clear();
        for (size_t k = 0; k < stack.size(); ++k) L.active[i].push_back(stack[k].lane);
    };
    // 收束挂到 [fromRow, toRow] 之间最后一条有文字的行（跳过尾部空语句行）。
    auto mark_close = [&](int fromRow, int toRow, int lane, int level) {
        if (s.rowCount <= 0) return;
        int mark = std::min(toRow, s.rowCount - 1);
        if (mark < 0) return;
        while (mark > fromRow &&
               (!s.rows[mark].text || !*s.rows[mark].text)) --mark;
        for (size_t k = 0; k < L.close[mark].size(); ++k)
            if (L.close[mark][k].lane == lane) return;
        L.close[mark].push_back(UiFlowClose{ lane, level });
    };

    for (int i = 0; i < s.rowCount; ++i) {
        const UiFlowRow& r = s.rows[i];
        int role = r.role;
        if (role == UI_FLOW_AUTO && s.cmds) role = ui_flow_role(r.text, *s.cmds);
        if (role < UI_FLOW_BODY || role > UI_FLOW_TAIL_DOWN) role = UI_FLOW_BODY;
        L.role[i] = role;
        int lv = std::max(0, r.level);
        bool isTail = (role == UI_FLOW_TAIL || role == UI_FLOW_TAIL_DOWN);
        bool isHead = (role == UI_FLOW_START);
        bool isBrch = (role == UI_FLOW_BRANCH);

        // 退回外层缩进 = 内层块没有写结束语句，就地隐式收束。
        // 显式尾只弹出层级比自己更深的不匹配块，最后一层留给它配对。
        if (!isBrch) {
            while (!stack.empty()) {
                const Frame& f = stack.back();
                bool deeper = isTail ? (f.level > lv) : (f.level >= lv);
                if (!deeper) break;
                if (isTail && stack.size() == 1) break;
                mark_close(f.row, i - 1, f.lane, f.level + 1);
                stack.pop_back();
            }
        }

        if (isHead) {
            int lane = (int)stack.size();
            stack.push_back(Frame{ lane, lv, i });
            L.lane[i] = lane;
            fill_active(i);                     // 含自身：块头从行中心起
        } else if (isTail) {
            int lane = stack.empty() ? 0 : stack.back().lane;
            if (!stack.empty()) stack.pop_back();
            L.lane[i] = lane;
            fill_active(i);                     // 弹栈后剩下的外层
            L.active[i].push_back(lane);        // 本层只画上半段
        } else {
            L.lane[i] = stack.empty() ? -1 : stack.back().lane;
            fill_active(i);
        }
    }
    // 走到子程序末尾仍未闭合的块：统一在最后一条有文字的语句行收束，
    // 不让虚线一直拖到视口底部。
    while (!stack.empty()) {
        const Frame& f = stack.back();
        mark_close(f.row, s.rowCount - 1, f.lane, f.level + 1);
        stack.pop_back();
    }

    // ── 结构隐藏节点投影 ──────────────────────────────────────────
    // 真机：合法配对的「否则」「如果结束」不显示文字，改由流程线表达。
    // 参考/su-lang-main/docs/流程线绘制维护.md §隐藏"否则"与隐藏条件尾：
    //   · 隐藏「否则」的分支入口 → 投影到下一条可见正文中心，带右向 ▶
    //   · 结束轨道头部右横线   → 「否则」之前最后一条可见正文中心
    //   · 隐藏「如果结束」     → ▼ 连在偏移出口轨道（主轨道 + exitOffset）上
    // 出口轨道从「否则」之前最后一条可见正文起，一直贯穿到隐藏条件尾；
    // 主轨道在分支入口行中心结束。这正是真机截图中「序号1」那条短线与
    // 「序号1的线是从上边序号1哪里绘制下来的」所指的两段线。
    auto visible_before = [&](int i) {
        for (int j = i - 1; j >= 0; --j) if (!s.rows[j].hidden) return j;
        return -1;
    };
    auto visible_after = [&](int i) {
        for (int j = i + 1; j < s.rowCount; ++j) if (!s.rows[j].hidden) return j;
        return -1;
    };
    auto erase_lane = [](std::vector<int>& v, int ln) {
        int w = 0;
        for (size_t k = 0; k < v.size(); ++k) if (v[k] != ln) v[w++] = v[k];
        v.resize((size_t)w);
    };
    auto erase_close = [](std::vector<UiFlowClose>& v, int ln) {
        size_t w = 0;
        for (size_t k = 0; k < v.size(); ++k) if (v[k].lane != ln) v[w++] = v[k];
        v.resize(w);
    };
    for (int i = 0; i < s.rowCount; ++i) {
        if (!s.rows[i].hidden || L.role[i] != UI_FLOW_BRANCH) continue;
        int ln = L.lane[i] >= 0 ? L.lane[i] : 0;
        int pv = visible_before(i), nx = visible_after(i);
        int tail = -1;
        for (int j = i + 1; j < s.rowCount; ++j)
            if ((L.role[j] == UI_FLOW_TAIL || L.role[j] == UI_FLOW_TAIL_DOWN) &&
                L.lane[j] == ln) { tail = j; break; }
        if (tail < 0) tail = s.rowCount - 1;
        int from = (pv >= 0) ? pv : i;
        for (int r = from; r <= tail && r < s.rowCount; ++r)
            L.exit[r].push_back(ln);
        if (pv >= 0) L.head[pv].push_back(UiFlowClose{ ln, s.rows[pv].level });
        if (nx >= 0) {
            L.entry[nx].push_back(UiFlowClose{ ln, s.rows[nx].level });
            L.stopLane[nx] = ln;
            for (int r = nx + 1; r <= tail && r < s.rowCount; ++r) {
                erase_lane(L.active[r], ln);   // 主轨道让位给结束轨道
                erase_close(L.close[r], ln);   // 避免同一层重复画 ▶
            }
        }
        L.downExit[tail] = ln;
    }
}

// 竖轨道：按「绝对 y」取模，保证逐行分段绘制时虚线相位连续。
static void ui_flow_vline(const UiFlowSpec& s, int x, int y0, int y1)
{
    if (y1 < y0) { int t = y0; y0 = y1; y1 = t; }
    if (s.lineStyle == 0) { vline(s.dc, x, y0, y1, s.lineColor); return; }
    int on  = std::max(1, s.dashOn);
    int p   = on + std::max(0, s.dashOff);
    for (int y = y0; y <= y1; ++y)
        if ((y % p) < on) SetPixelV(s.dc, x, y, s.lineColor);
}
// 横向连接：同样按「绝对 x」取模对齐相位。
static void ui_flow_hline(const UiFlowSpec& s, int x0, int x1, int cy)
{
    if (x1 < x0) { int t = x0; x0 = x1; x1 = t; }
    if (s.lineStyle == 0) { hline(s.dc, x0, x1, cy, s.lineColor); return; }
    int on  = std::max(1, s.dotOn);
    int p   = on + std::max(0, s.dotOff);
    for (int x = x0; x <= x1; ++x)
        if ((x % p) < on) SetPixelV(s.dc, x, cy, s.lineColor);
}
static void ui_flow_arrow_right(const UiFlowSpec& s, int tipX, int cy)
{
    int L = s.arrowLen, h = L / 2;
    POINT p[3] = { { tipX, cy }, { tipX - L, cy - h }, { tipX - L, cy + h } };
    tri_fill(s.dc, p, s.lineColor);
}
static void ui_flow_arrow_down(const UiFlowSpec& s, int cx, int tipY)
{
    int L = s.arrowLen, h = L / 2;
    POINT p[3] = { { cx, tipY }, { cx - h, tipY - L }, { cx + h, tipY - L } };
    tri_fill(s.dc, p, s.lineColor);
}
// 右向箭头连接（块头 / 分支 / 循环尾 / 隐式收束共用，形状完全一致）。
static void ui_flow_connector_right(const UiFlowSpec& s, int x0, int x1, int cy)
{
    int shaft = (s.arrowLen > 0) ? x1 - s.arrowLen : x1;
    ui_flow_hline(s, x0, shaft, cy);
    if (s.arrowLen > 0) ui_flow_arrow_right(s, x1, cy);
}

// 横向连接线末端：真机所有横线末端固定在「本层轨道 + 固定长度」，
// 与该行的文字缩进 level 无关（真机「如果」行点线约 24px）。
static int ui_flow_x1(const UiFlowSpec& s, int lane)
{
    return s.textX + lane * s.laneStep - s.textGap;
}

// 条件尾 ▼ 的坐标：隐藏尾在偏移出口轨道上，显式 TAIL_DOWN 在横线中点。
// 「画」与「跨行补画」都走这里，避免两处几何分叉。
static bool ui_flow_down_tip(const UiFlowSpec& s, const UiFlowLayout& L,
                             int i, int& cx, int& tipY)
{
    if (!s.rows || i < 0 || i >= s.rowCount || s.arrowLen <= 0 || s.endStem <= 0)
        return false;
    if (i >= (int)L.role.size() || i >= (int)L.lane.size()) return false;
    tipY = s.rows[i].y + s.rows[i].h / 2 + s.endStem;
    if (i < (int)L.downExit.size() && L.downExit[i] >= 0) {
        cx = s.trackX + L.downExit[i] * s.laneStep + s.exitOffset;
        return true;
    }
    if (L.role[i] == UI_FLOW_TAIL_DOWN && L.lane[i] >= 0) {
        int x0 = s.trackX + L.lane[i] * s.laneStep;
        int x1 = ui_flow_x1(s, L.lane[i]);
        cx = x0 + (x1 - x0) / 2;
        return true;
    }
    return false;
}

// 实际落笔。rowIdx < 0 表示整份一次画完；>=0 只画那一行。
static void ui_flow_paint(const UiFlowSpec& s, const UiFlowLayout& L, int rowIdx)
{
    if (!s.dc || !s.rows || s.rowCount <= 0 || s.laneStep <= 0) return;
    int saved = SaveDC(s.dc);
    IntersectClipRect(s.dc, s.clip.left, s.clip.top, s.clip.right, s.clip.bottom);
    int from = (rowIdx < 0) ? 0 : rowIdx;
    int to   = (rowIdx < 0) ? s.rowCount : std::min(s.rowCount, rowIdx + 1);
    for (int i = from; i < to; ++i) {
        const UiFlowRow& r = s.rows[i];
        // 隐藏结构行零高度：不画自己，投影到相邻可见正文（su-lang 语义）——
        // 否则入口投下一条可见正文中心；条件尾收在上一条可见正文底边。
        if (r.hidden && r.h <= 0) {
            int roleH = (i < (int)L.role.size()) ? (int)L.role[i] : -1;
            bool projBranch = (roleH == UI_FLOW_BRANCH);
            bool projTail   = (roleH == UI_FLOW_TAIL || roleH == UI_FLOW_TAIL_DOWN);
            if (!projBranch && !projTail) continue;
            int t = i;
            if (projBranch) { while (t + 1 < s.rowCount && s.rows[t + 1].h <= 0) ++t; ++t; }
            else            { while (t - 1 >= 0 && s.rows[t - 1].h <= 0) --t; --t; }
            if (t < 0 || t >= s.rowCount || s.rows[t].h <= 0) continue;
            const UiFlowRow& tr = s.rows[t];
            int laneH = (i < (int)L.lane.size()) ? L.lane[i] : -1;
            if (projBranch) {
                // 5) 否则入口 ▶ + 6) 出口轨道头部右横线：投到下一条可见正文中心
                int cy2 = tr.y + tr.h / 2;
                for (size_t q = 0; q < L.entry[i].size(); ++q) {
                    const UiFlowClose& c = L.entry[i][q];
                    ui_flow_connector_right(s, s.trackX + c.lane * s.laneStep,
                                            ui_flow_x1(s, c.lane), cy2);
                }
                for (size_t q = 0; q < L.head[i].size(); ++q) {
                    const UiFlowClose& c = L.head[i][q];
                    ui_flow_hline(s, s.trackX + c.lane * s.laneStep + s.exitOffset,
                                  ui_flow_x1(s, c.lane), cy2);
                }
            }
            if (projTail && laneH >= 0) {
                // 7) 隐藏条件尾 ▼：收口在上一条可见正文底边
                int yb = tr.y + tr.h;
                int x0 = s.trackX + laneH * s.laneStep;
                int x1 = ui_flow_x1(s, laneH);
                bool hasExit = (i < (int)L.downExit.size() && L.downExit[i] >= 0);
                if (hasExit) {
                    int cx = s.trackX + L.downExit[i] * s.laneStep + s.exitOffset;
                    ui_flow_vline(s, cx, r.y, yb);
                    ui_flow_arrow_down(s, cx, yb);
                } else {
                    int cx = x0 + (x1 - x0) / 2;
                    ui_flow_hline(s, x0, x1, r.y);
                    ui_flow_vline(s, cx, r.y, yb);
                    ui_flow_arrow_down(s, cx, yb);
                }
            }
            continue;
        }
        if (r.h <= 0) continue;
        if (r.y + r.h <= s.clip.top || r.y >= s.clip.bottom) continue;
        int y0 = r.y, y1 = r.y + r.h, cy = r.y + r.h / 2;
        int role = (int)L.role[i];
        int lane = (int)L.lane[i];
        bool hasExitTail = (L.downExit[i] >= 0);
        bool hiddenStruct = r.hidden && (role == UI_FLOW_BRANCH || role == UI_FLOW_TAIL);

        // 1) 主轨道：所有活动层贯穿；块头从行中心起，块尾/隐式收束到行中心止。
        //    隐藏分支的入口行主轨道让位给偏移出口轨道，只画上半段。
        for (size_t k = 0; k < L.active[i].size(); ++k) {
            int lv = L.active[i][k];
            int x  = s.trackX + lv * s.laneStep;
            int a = y0, b = y1;
            if (role == UI_FLOW_START && lv == lane) a = cy;
            if ((role == UI_FLOW_TAIL || role == UI_FLOW_TAIL_DOWN) && lv == lane) b = cy;
            for (size_t q = 0; q < L.close[i].size(); ++q)
                if (L.close[i][q].lane == lv) { b = cy; break; }
            if (lv == L.stopLane[i]) b = cy;
            ui_flow_vline(s, x, a, b);
        }

        // 2) 偏移出口轨道：从隐藏「否则」之前最后一条可见正文起，贯穿到
        //    隐藏条件尾；头部从行中心起，尾部到行中心止后接 ▼。
        for (size_t k = 0; k < L.exit[i].size(); ++k) {
            int lv = L.exit[i][k];
            int x  = s.trackX + lv * s.laneStep + s.exitOffset;
            int a = y0, b = y1;
            for (size_t q = 0; q < L.head[i].size(); ++q)
                if (L.head[i][q].lane == lv) { a = cy; break; }
            if (lv == L.downExit[i]) b = cy;
            ui_flow_vline(s, x, a, b);
        }

        // 3) 显式块头 / 分支 / 尾：横线指向语句文字。
        //    结构隐藏行不画常规连接，改由投影行与结束轨道表达。
        if (!hiddenStruct && !hasExitTail &&
            (role == UI_FLOW_START || role == UI_FLOW_BRANCH ||
             role == UI_FLOW_TAIL || role == UI_FLOW_TAIL_DOWN) && lane >= 0) {
            int x0 = s.trackX + lane * s.laneStep;
            int x1 = ui_flow_x1(s, lane);
            if (role == UI_FLOW_TAIL_DOWN) {
                // 条件尾：横线 + 从中点向下收口 + 向下三角 ▼
                ui_flow_hline(s, x0, x1, cy);
                int dcx = 0, dtip = 0;
                if (ui_flow_down_tip(s, L, i, dcx, dtip)) {
                    ui_flow_vline(s, dcx, cy, dtip);
                    ui_flow_arrow_down(s, dcx, dtip);
                }
            } else {
                // 块头 / 分支 / 循环尾：右向三角 ▶
                ui_flow_connector_right(s, x0, x1, cy);
            }
        }

        // 4) 隐式收束：没有结束语句的块，在块内最后一行画与块头同款的 ▶。
        for (size_t q = 0; q < L.close[i].size(); ++q) {
            const UiFlowClose& c = L.close[i][q];
            ui_flow_connector_right(s, s.trackX + c.lane * s.laneStep,
                                    ui_flow_x1(s, c.lane), cy);
        }

        // 5) 隐藏「否则」的分支入口 ▶：投影到下一条可见正文中心。
        //    真机这里没有「否则」两个字，箭头直接指向分支第一条语句。
        for (size_t q = 0; q < L.entry[i].size(); ++q) {
            const UiFlowClose& c = L.entry[i][q];
            ui_flow_connector_right(s, s.trackX + c.lane * s.laneStep,
                                    ui_flow_x1(s, c.lane), cy);
        }

        // 6) 结束轨道头部右横线：投影到「否则」之前最后一条可见正文，
        //    起点是偏移出口轨道、不带箭头（真机标注「序号1」的那段短线）。
        for (size_t q = 0; q < L.head[i].size(); ++q) {
            const UiFlowClose& c = L.head[i][q];
            ui_flow_hline(s, s.trackX + c.lane * s.laneStep + s.exitOffset,
                          ui_flow_x1(s, c.lane), cy);
        }

        // 7) 隐藏条件尾的向下箭头 ▼：连在偏移出口轨道上。
        if (hasExitTail) {
            int dcx = 0, dtip = 0;
            if (ui_flow_down_tip(s, L, i, dcx, dtip)) {
                ui_flow_vline(s, dcx, cy, dtip);
                ui_flow_arrow_down(s, dcx, dtip);
            }
        }
    }
    RestoreDC(s.dc, saved);
}

// 一次性画完整份流程线 —— 以后需要画流程线的页面统一调这个。
static void ui_flow_draw(const UiFlowSpec& s)
{
    UiFlowLayout L;
    ui_flow_build(s, L);
    ui_flow_paint(s, L, -1);
}
// 表格/文字交错渲染时使用：先 ui_flow_build，再逐行调用它。
static void ui_flow_draw_row(const UiFlowSpec& s, const UiFlowLayout& L, int rowIdx)
{
    ui_flow_paint(s, L, rowIdx);
}
// 逐行交错渲染（底色/文字/流程线混在一起画）时的收尾调用。
// ▼ 尖点比行心低 endStem，必然越出本行；下一行铺底色时会把下半截盖掉，
// 看起来像被削平的碗底。所有行画完后补一次，只重画越界的收口竖线与倒三角，
// 几何与 ui_flow_paint 完全一致，不改任何位置。整层一次画完的
// ui_flow_draw() 不存在覆盖问题，无需调用它。
static void ui_flow_draw_tips(const UiFlowSpec& s, const UiFlowLayout& L)
{
    if (!s.dc || !s.rows || s.rowCount <= 0) return;
    int saved = SaveDC(s.dc);
    IntersectClipRect(s.dc, s.clip.left, s.clip.top, s.clip.right, s.clip.bottom);
    for (int i = 0; i < s.rowCount; ++i) {
        const UiFlowRow& r = s.rows[i];
        int bottom = r.y + r.h;
        int cx = 0, tipY = 0;
        if (!ui_flow_down_tip(s, L, i, cx, tipY)) continue;
        if (tipY <= bottom) continue;                       // 未越行，不必补
        if (tipY < s.clip.top || tipY - s.arrowLen > s.clip.bottom) continue;
        // 只需整体重画倒三角：越界的那一截收口竖线本来就落在三角内部
        // （三角顶边 tipY-arrowLen 通常高于行底），重画竖线反而会在尖点
        // 下面拖出一条小尾巴。三角盖上去后尖点自然收拢。
        ui_flow_arrow_down(s, cx, tipY);
    }
    RestoreDC(s.dc, saved);
}

// 行内编辑工具函数定义在「交互」段，绘制在其之前，先给出声明。
static int  code_ed_w(int idx);
static void code_ed_measure();
static int  code_ed_sel_lo();
static int  code_ed_sel_hi();

static void paint_code_table(HDC dc)
{
    int asmIdx = g_a.docTab - 1;
    if (asmIdx < 0 || asmIdx >= (int)g_eAsms.size()) return;

    int oldFontGroup = g_fontGroup;
    font_use(FNT_EDITOR); // 切换到编辑器独立字体

    // 代码页恒用真机白纸配色，不随深浅主题变（2026-11-15 用户确认）。
    const COLORREF PAPER  = C_PAPER;         // 数据行/画布纯白 #FFFFFF
    const COLORREF BLACK  = C_INK;           // 普通文字纯黑
    const COLORREF gridCol= C_LINE;          // 格线深灰实线 #4E4E4E
    const COLORREF laneCol= C_LANE;          // 流程轨道灰
    const COLORREF selCol  = sel_bg_deep();   // 行内字符选区（字反白）
    const COLORREF selLine = sel_bg_soft();   // 整行 / 跨行选带（字不反白）
    const COLORREF caretCol= C_INK;          // 光标黑色

    RECT vp = rcCanvas;
    // 左侧内缩 2px 并留 1px 边界，防止压住属性面板的线；右/上/下留 1px 收边
    vp.left += S(3); 
    vp.right -= 1; vp.bottom -= 1;
    fill(dc, vp, PAPER);

    // ── 先把行装配出来（两遍走：装配 → 适配列宽 → 算总高 → 夹滚动 → 绘制）──
    std::vector<CRow> rows;
    code_rows_build(rows);

    // ── 列宽：动态计算，取每一列中最长文字的实际像素宽度，加上内边距 ──
    // 列宽：各表按内容自适应，但真机程序集名表与程序集变量表竖线贯通、
    // 上下紧贴连成一块，两表逐列取最大值后共用同一套边界。
    int declTotal[TT_N] = { 0, 0, 0, 0, 0 };
    {
        for (int tt = 0; tt < TT_N; ++tt) {
            declTotal[tt] = 0;
            for (int k = 0; k < code_col_n(tt); ++k) {
                int maxW = S(code_col(tt, k)->w);   // 兜底最小宽度
                for (size_t i = 0; i < rows.size(); ++i) {
                    if (rows[i].kind == 2) continue;   // 语句行不属于任何声明表
                    if (rows[i].tt != tt) continue;
                    HFONT f = g_f12;
                    if (rows[i].kind == 0) f = g_f12b; // 表头加粗
                    // 名字列已不再用下划线体，量宽度也用同样的字体，避免列宽和实际渲染差一截
                    int textW = twd(dc, rows[i].c[k].c_str(), f);
                    // 正在这一格打字：按编辑框里的**实时文字**算宽度，
                    // 打一个字这一列就宽一点，后面的列整体右移
                    if (g_codeEdActive && (int)i == g_codeEdRow && k == g_codeEdCol)
                        textW = twd(dc, g_codeEdText.c_str(), f);
                    int margin = (k == 0) ? S(24) : ((rows[i].kind == 0) ? S(32) : S(24));
                    if (textW + margin + S(4) > maxW) maxW = textW + margin + S(4);
                }
                if (k == 0) { int minW = S(100); if (maxW < minW) maxW = minW; }
                g_codeTW[tt][k] = maxW;
                declTotal[tt] += maxW;
            }
        }
        // 程序集名表 + 程序集变量表：逐列取最大，回写两表使竖线对齐
        for (int k = 0; k < code_col_n(TT_ASM); ++k) {
            int m = std::max(g_codeTW[TT_ASM][k], g_codeTW[TT_ASMVAR][k]);
            g_codeTW[TT_ASM][k] = m; g_codeTW[TT_ASMVAR][k] = m;
        }
        for (int tt = 0; tt < TT_N; ++tt) {
            declTotal[tt] = 0;
            for (int k = 0; k < code_col_n(tt); ++k) declTotal[tt] += g_codeTW[tt][k];
        }
    }
    // 语句区：文字随内容走，超长语句撑宽（min 600）
    int stmtW = S(600);
    for (size_t i = 0; i < rows.size(); ++i) {
        const CRow& r = rows[i];
        if (r.kind != 2) continue;
        const wchar_t* t = r.c[0].c_str();
        if (*t == L'.') ++t;                      // 前导点不显示
        int lv = std::max(0, r.level);
        int need = S(20) + lv * code_lane_step() + tw(dc, t, g_f12) + S(10);
        if (need > stmtW) stmtW = need;
    }
    g_codeStmtW = stmtW;

    // 横向滚动：表格总宽超出视口才滚（Shift+滚轮），右缘夹紧
    {
        int contentW = 0;
        for (int tt = 0; tt < TT_N; ++tt) contentW = std::max(contentW, declTotal[tt]);
        contentW = std::max(contentW, g_codeStmtW) + S(46) + S(24);
        g_codeMaxScrollX = std::max(0, contentW - (int)(vp.right - vp.left));
        if (g_codeScrollX < 0) g_codeScrollX = 0;
        if (g_codeScrollX > g_codeMaxScrollX) g_codeScrollX = g_codeMaxScrollX;
        // 内容比视口宽：底部留一条横向滚动条的位置，最后一行不会被它压住
        g_codeBarH = (g_codeMaxScrollX > 0) ? S(12) : 0;
        if (g_codeBarH) vp.bottom -= g_codeBarH;
    }
    // 左侧行号栏：整列固定（不随横向滚动），表格贴在它右边 S(8)。
    // 行号按「装配行」连续编号（声明行、表头行、语句行都算一行），和文件行号语义一致。
    const int LNW = S(46);
    // 把间距从 S(8) 加大到 S(24)，给流程线留出不被行号遮挡的空间
    int tblL = vp.left + LNW + S(24) - g_codeScrollX;
    for (int tt = 0; tt < TT_N; ++tt) g_codeTR[tt] = tblL + declTotal[tt];
    g_codeStmtR = tblL + g_codeStmtW;

    const int GAP = code_gap();
    int contentH = 0;
    for (size_t i = 0; i < rows.size(); ++i)
        contentH += (rows[i].sep ? GAP : 0) +
                    (rows[i].kind == 2 ? code_stmt_h() : code_row_h());
    contentH += S(0);
    g_codeContentH = contentH;
    g_codeViewH    = vp.bottom - vp.top;

    int maxS = std::max(0, contentH - g_codeViewH);
    if (g_a.codeScroll < 0) g_a.codeScroll = 0;
    if (g_a.codeScroll > maxS) g_a.codeScroll = maxS;

    // 行号栏：整列浅灰 + 左右两条深一点的界线
    // 左缘这条正好压在左栏（属性/支持库/程序）的右边界上，两条合成一条，
    // 面板边界就不会单独突兀地戳在那儿；右缘这条是行号栏和代码区的分界。
    fill(dc, RECT{ vp.left, vp.top, vp.left + LNW, vp.bottom }, C_PAPER);
    vline(dc, vp.left, vp.top, vp.bottom, gridCol);              // 与左栏边界重合
    vline(dc, vp.left + LNW - 1, vp.top, vp.bottom, gridCol);     // 右侧分界深一点

    // 裁剪到视口：滚出去的行不画；表格区从行号栏右边开始，横向滚动时不会盖住行号
    int saved = SaveDC(dc);
    IntersectClipRect(dc, vp.left + LNW, vp.top, vp.right, vp.bottom);

    int y = vp.top + code_table_pad() - g_a.codeScroll;

    // ── 流程线：把所有语句行的几何先算出来，交给通用绘制函数做块配对 ──
    // 命令表由本页提供；通用函数不认识任何具体语言，全部参数外部传。
    static const wchar_t* const kFlowHeads[] = {
        L"如果", L"如果真", L"判断", L"判断开始",
        L"计次循环首", L"变量循环首", L"判断循环首", L"循环判断首", L"循环首"
    };
    static const wchar_t* const kFlowTails[] = {
        L"如果结束", L"如果真结束", L"判断结束", L"判断尾",
        L"计次循环尾", L"变量循环尾", L"判断循环尾", L"循环判断尾", L"循环尾"
    };
    static const wchar_t* const kFlowBranches[] = {
        L"否则如果", L"否则", L"默认", L"案例"
    };
    // 条件尾画 ▼，其余块尾（循环尾等）与「没有结束语句」的隐式收束都画 ▶。
    static const wchar_t* const kFlowDownTails[] = {
        L"如果结束", L"如果真结束", L"判断结束"
    };
    UiFlowCmdSet flowCmds = {
        kFlowHeads,    (int)(sizeof(kFlowHeads)    / sizeof(kFlowHeads[0])),
        kFlowTails,    (int)(sizeof(kFlowTails)    / sizeof(kFlowTails[0])),
        kFlowBranches, (int)(sizeof(kFlowBranches) / sizeof(kFlowBranches[0])),
        kFlowDownTails,(int)(sizeof(kFlowDownTails)/ sizeof(kFlowDownTails[0]))
    };

    UiFlowSpec fs = {};
    fs.dc        = dc;
    fs.clip      = RECT{ vp.left + LNW, vp.top, vp.right, vp.bottom };
    fs.trackX    = tblL + S(4);
    fs.textX     = tblL + S(38);   // 轨道→文字 34px：块头横向点线 24px（真机实测）
    fs.exitOffset= S(6);          // 偏移出口轨道（参考项目：当前偏移为 6px）
    fs.laneStep  = code_lane_step();
    fs.textGap   = S(4);
    fs.arrowLen  = std::max(3, S(6));
    fs.endStem   = std::max(6, S(12));
    fs.lineColor = laneCol;
    fs.lineStyle = 1;                                  // 点/虚线（真机）
    fs.dashOn    = std::max(1, S(2)); fs.dashOff = std::max(1, S(2));  // 竖轨 2 亮 2 暗
    fs.dotOn     = 1;                 fs.dotOff  = 2;                   // 横连 1 亮 2 暗
    fs.cmds      = &flowCmds;

    std::vector<UiFlowRow> flowRows;
    {
        int fy = vp.top + code_table_pad() - g_a.codeScroll;
        for (size_t i = 0; i < rows.size(); ++i) {
            const CRow& rr = rows[i];
            if (rr.sep) fy += GAP;
            int rh = (rr.kind == 2) ? code_stmt_h() : code_row_h();
            if (rr.kind == 2 && rr.hidden &&
                !(g_codeEdActive && (int)i == g_codeEdRow))
                rh = 0;   // 结构隐藏行：零高度，线投影到相邻可见行
            if (rr.kind == 2) {
                UiFlowRow fr = {};
                fr.y     = fy;
                fr.h     = rh;
                fr.level = std::max(0, rr.level);
                fr.role  = UI_FLOW_AUTO;
                fr.text  = rr.c[0].c_str();
                fr.hidden= rr.hidden;
                flowRows.push_back(fr);
            }
            fy += rh;
        }
    }
    fs.rows     = flowRows.empty() ? nullptr : &flowRows[0];
    fs.rowCount = (int)flowRows.size();
    UiFlowLayout flowLayout;
    ui_flow_build(fs, flowLayout);

    int flowCursor = 0;
    for (size_t i = 0; i < rows.size(); ++i) {
        const CRow& r = rows[i];
        if (r.sep) y += GAP;    // 表前留白，但行本身照画（表头不能丢）
        int rh = (r.kind == 2) ? code_stmt_h() : code_row_h();
        if (r.kind == 2 && r.hidden) rh = 0;   // 与 flowRows 同规则：隐藏行零高度
        int flowIdx = -1;
        if (r.kind == 2) flowIdx = flowCursor++;
        if (rh == 0) { y += rh; continue; }   // 零高度隐藏行：只推进，不画底色/文字
        if (y + rh >= vp.top && y <= vp.bottom ||
            (rh == 0 && y >= vp.top - S(2) && y <= vp.bottom + S(2))) {
            // 语句行底色/选带在这里画；声明行的填充在下方波段里画（留规则线）
            bool editingThis = (g_codeEdActive && (int)i == g_codeEdRow);
            // 单击只放插入光标，不高亮整行（记事本 / 真机如此）；
            // 只有「按住拖过其它行」建立的行选区才画选带。
            bool inSelRange = false;
            if (g_codeSelRowStart >= 0 && g_codeSelRowEnd >= 0) {
                int rMin = std::min(g_codeSelRowStart, g_codeSelRowEnd);
                int rMax = std::max(g_codeSelRowStart, g_codeSelRowEnd);
                if ((int)i >= rMin && (int)i <= rMax) inSelRange = true;
            }

            // 跨行选区：当前编辑行之外的选区经过行也铺选带（记事本语义：
            // 锚点行=锚点→行尾/行首；焦点行=行首→光标/光标→行尾；中间行整行）
            bool xSel = code_ed_line_in_sel((int)i);
            if (r.kind == 2) {
                // 语句行底色
                fill(dc, RECT{ tblL, y, g_codeStmtR, y + rh }, PAPER);
                // 字符级选区带（跨行拖选时按实际字符范围绘制）
                if (xSel) {
                    int c0 = 0, c1 = 0;
                    if (code_ed_row_sel_range((int)i, c0, c1)) {
                        int lv2 = std::max(0, r.level);
                        int txB2 = tblL + S(38) + lv2 * code_lane_step();
                        std::wstring s = r.c[0];
                        if (!s.empty() && s[0] == L'.') s.erase(0, 1);  // 剥前导点
                        int len = (int)s.size();
                        c0 = std::max(0, std::min(c0, len));
                        c1 = std::max(0, std::min(c1, len));
                        if (c1 > c0) {
                            int w0 = (c0 > 0) ? tw(dc, s.substr(0, (size_t)c0), code_ed_font()) : 0;
                            int w1 = tw(dc, s.substr(0, (size_t)c1), code_ed_font());
                            fill(dc, RECT{ txB2 + w0, y, std::min(txB2 + w1, g_codeStmtR - S(4)), y + rh }, selLine);
                        }
                    }
                }
            } else if (inSelRange && !editingThis && r.kind == 1) {
                // 声明数据行：整行带（行级拖选，比如变量表）。表头不铺，保持标签原样。
                fill(dc, RECT{ tblL, y, g_codeStmtR, y + rh }, selLine);
            }

            // 块选区（鼠标在表格上拖出来的矩形片区）：整格铺色，文字保持原色。
            // 只铺数据行/语句行，表头不铺（表头永远只是标签）。
            if (g_tblSelOn && g_tblSelARow >= 0 && g_tblSelFRow >= 0) {
                int br0 = std::min(g_tblSelARow, g_tblSelFRow);
                int br1 = std::max(g_tblSelARow, g_tblSelFRow);
                if ((int)i >= br0 && (int)i <= br1) {
                    int bc0 = std::min(g_tblSelACol, g_tblSelFCol);
                    int bc1 = std::max(g_tblSelACol, g_tblSelFCol);
                    // 语句行在这里直接铺；声明行/表头交给 ui_table_draw 的逐格底色
                    // （它的整行底色会盖掉这里画的东西，见 cells[k].bg 那段）
                    // 空语句行（子程序末尾那条占位空行）不参与选中，也不画条。
                    if (r.kind == 2 && !r.hidden && !r.c[0].empty()) {
                        int lv2  = std::max(0, r.level);
                        std::wstring t2 = r.c[0];
                        if (!t2.empty() && t2[0] == L'.') t2.erase(0, 1);   // 剥前导点
                        int txB2 = tblL + S(38) + lv2 * code_lane_step();
                        int rx   = txB2 + tw(dc, t2, code_ed_font()) + S(8);
                        if (rx > g_codeStmtR - 1) rx = g_codeStmtR - 1;
                        if (rx < tblL + S(60)) rx = tblL + S(60);
                        fill(dc, RECT{ tblL, y, rx, y + rh }, selLine);
                        outline(dc, RECT{ tblL, y, rx - 1, y + rh - 1 }, RGB(60, 100, 170));
                    }
                }
            }

            if (r.kind == 2) {
                // ── 语句行 ──
                int lv = std::max(0, r.level);
                int txBase = tblL + S(38);
                if (editingThis) {
                    // 编辑态文字必须和非编辑态落在同一个 x；命中/光标/局部重绘都读它
                    g_codeEdTextX = txBase + lv * code_lane_step();
                    g_codeEdTextR = g_codeStmtR - S(4);
                    g_codeEdLineRect = RECT{ tblL, y, g_codeStmtR, y + rh };
                }
                if (r.hidden) g_stmtRowEdit = editingThis;   // 隐藏行：仅编辑态显形
                // 跨行选区带（编辑行=焦点行）：锚点在别的行时，本行画
                // 「行首→光标」（焦点在锚点下方）或「光标→行尾」（焦点在上方）；
                // 行内选区带由下方编辑层统一画（同一套字符边界）。
                if (editingThis && g_edDragStartRow >= 0 && g_edDragStartRow != (int)i) {
                    int c0 = 0, c1 = 0;
                    if (code_ed_row_sel_range((int)i, c0, c1)) {
                        int txB = txBase + lv * code_lane_step();
                        int sa = txB + code_ed_w(c0), sb = txB + code_ed_w(c1);
                        if (sb > sa)
                            fill(dc, RECT{ sa, y, std::min(sb, g_codeStmtR - S(4)), y + rh }, selLine);
                    }
                }

                // 流程线统一交给通用函数（块配对已在循环前算好）；
                // 放在底色之后、文字之前，保证文字永远盖在线上层。
                if (flowIdx >= 0) ui_flow_draw_row(fs, flowLayout, flowIdx);

                // 只有在非编辑状态下，才绘制原有的代码文字；
                // 结构隐藏行（否则/如果结束）不显示文字，只由流程线表达
                if (!editingThis && !(r.hidden && !g_stmtRowEdit)) {
                    const wchar_t* stmt = r.c[0].c_str();
                    if (*stmt == L'.') ++stmt;
                    std::vector<std::pair<std::wstring, COLORREF>> toks;
                    code_tokenize(stmt, toks);
                    int sx = txBase + lv * code_lane_step();
                    int saved2 = SaveDC(dc);
                    IntersectClipRect(dc, tblL, y, g_codeStmtR, y + rh);
                    for (size_t tk = 0; tk < toks.size(); ++tk) {
                        if (sx > g_codeStmtR - S(6)) break;
                        int w = tw(dc, toks[tk].first.c_str(), g_f12);
                        tx(dc, toks[tk].first.c_str(),
                           RECT{ sx, y, sx + w + S(4), y + rh },
                           toks[tk].second, g_f12,
                           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
                        sx += w;
                    }
                    RestoreDC(dc, saved2);
                }
            } else {
                // ── 声明行：统一走通用表格绘制函数 ──
                int tt = r.tt, n = code_col_n(tt);
                int rowR = g_codeTR[tt];
                bool isHdr = (r.kind == 0);
                bool isSel = inSelRange;   // 拖选时整行高亮

                if (editingThis) {
                    int c = std::min(std::max(0, g_codeEdCol), n - 1);
                    int x0 = tblL + code_col_x(tt, c);
                    int x1 = (c < n - 1) ? tblL + code_col_x(tt, c + 1) : rowR;
                    g_codeEdTextX = x0 + S(5);
                    g_codeEdTextR = x1 - S(8);
                    g_codeEdLineRect = RECT{ x0, y, x1, y + rh };
                }

                UiTableCell cells[6] = {};
                for (int k = 0; k < n; ++k) {
                    // 颜色/对齐按「列定义」自动适配：勾选列红字居中，名字/类型蓝，备注绿
                    int fld = code_col_field(tt, k);
                    bool isChk = (!isHdr && code_col_is_check(tt, k));
                    COLORREF tc = BLACK;                 // 真机：普通文字纯黑
                    if (!isHdr) {
                        if (isChk)                              tc = C_REDCHK;
                        else if (fld == CFD_NAME || fld == CFD_TYPE) tc = C_BLUE;
                        else if (fld == CFD_REMARK)             tc = C_GREEN;
                    }
                    // 勾选列的文字留空：勾由下面 code_check_glyph() 自绘，比字体 ✓ 大且清楚
                    cells[k].text  = isChk ? L""
                                            : ((editingThis && k == g_codeEdCol) ? L"" : r.c[k].c_str());
                    cells[k].fg    = tc;
                    cells[k].font  = isHdr ? g_f12b : g_f12;        // 表格不再用下划线字体
                    cells[k].align = isChk ? DT_CENTER : DT_LEFT;
                    cells[k].bg    = 0;
                    // 块选区是按「行」选的：拖过哪些行，这些行**整行**都铺色
                    // （用户要的是整行整行地选，不是只选按下那一列）
                    if (g_tblSelOn && g_tblSelARow >= 0 && g_tblSelFRow >= 0) {
                        int br0 = std::min(g_tblSelARow, g_tblSelFRow);
                        int br1 = std::max(g_tblSelARow, g_tblSelFRow);
                        if ((int)i >= br0 && (int)i <= br1) cells[k].bg = selLine;
                    }
                }
                UiTableRow trow = {};
                trow.cells    = cells;
                trow.bg       = (g_tableBgColor == 0) ? PAPER : g_tableBgColor;
                trow.header   = isHdr;
                trow.selected = isSel;
                trow.editing  = false;

                UiTableSpec ts = {};
                ts.dc         = dc;
                ts.clip       = RECT{ vp.left + LNW, vp.top, vp.right, vp.bottom };
                ts.left       = tblL; ts.top = y; ts.right = rowR;
                ts.colW       = g_codeTW[tt];
                ts.colCount   = n;
                ts.rowH       = rh;
                ts.padL       = S(5); ts.padR = S(8);
                ts.bgHeader   = code_hdr_bg(tt);
                ts.bgSelected = selCol;
                ts.bgInput    = C_PAPER;
                ts.lineColor  = (g_tableLineColor == 0) ? gridCol : g_tableLineColor;
                ts.lineStyle  = UI_TBL_SOLID;
                ts.dotPeriod  = 4;
                ts.outer      = true;
                ts.headerTop  = true;
                ts.rows       = &trow;
                ts.rowCount   = 1;
                ui_table_draw_row(ts, 0, y, rh);

                // 勾选列：自绘对勾（数据行才画；表头只是列名）
                if (!isHdr) {
                    for (int k = 0; k < n; ++k) {
                        if (!code_col_is_check(tt, k)) continue;
                        if (r.c[k].empty()) continue;
                        int x0 = tblL + code_col_x(tt, k);
                        int x1 = (k + 1 < n) ? (tblL + code_col_x(tt, k + 1)) : rowR;
                        code_check_glyph(dc, RECT{ x0, y, x1, y + rh - 1 }, C_REDCHK);
                    }
                }

                // 块选区边框：画在格子之上（含表头），保证「选没选中」一眼可见
                if (g_tblSelOn && g_tblSelARow >= 0 && g_tblSelFRow >= 0) {
                    int br0 = std::min(g_tblSelARow, g_tblSelFRow);
                    int br1 = std::max(g_tblSelARow, g_tblSelFRow);
                    if ((int)i >= br0 && (int)i <= br1) {
                        int bc0 = std::min(g_tblSelACol, g_tblSelFCol);
                        int bc1 = std::max(g_tblSelACol, g_tblSelFCol);
                        COLORREF edge = RGB(60, 100, 170);
                        outline(dc, RECT{ tblL, y, rowR - 1, y + rh - 1 }, edge);
                    }
                }
            }

            // 行内编辑层：文字起点与正常态完全相同，只画一遍。
            // 文字 / 选区 / 光标 / 鼠标命中全部读 g_codeEdCharX 这一套字符边界。
            if (g_codeEdActive && (int)i == g_codeEdRow) {
                int x0 = g_codeEdTextX;
                int xR = g_codeEdTextR;
                if (xR <= x0) xR = x0 + S(60);
                if (g_codeEdCharX.size() != g_codeEdText.size() + 1) code_ed_measure();

                int saved2 = SaveDC(dc);
                IntersectClipRect(dc, x0, y, xR + S(2), y + rh);

                // 1) 选区底色（先于文字）
                int lo = code_ed_sel_lo(), hi = code_ed_sel_hi();
                if (hi > lo) {
                    int sa = x0 + code_ed_w(lo), sb = x0 + code_ed_w(hi);
                    fill(dc, RECT{ sa, y + S(2), sb, y + rh - S(2) }, selCol);
                }

                // 2) 文字着色：声明表按「列的含义」上色（名字/类型蓝、备注绿），
                //    这样备注一打字就是绿的，不用等提交；语句行仍走语法高亮。
                bool declEdit = (g_codeEdRow >= 0 && g_codeEdRow < (int)rows.size() &&
                                 rows[g_codeEdRow].kind == 1);
                COLORREF declFg = BLACK;
                if (declEdit) {
                    int fld = code_col_field(rows[g_codeEdRow].tt, g_codeEdCol);
                    if (fld == CFD_NAME || fld == CFD_TYPE) declFg = C_BLUE;
                    else if (fld == CFD_REMARK)             declFg = C_GREEN;
                }
                std::vector<std::pair<std::wstring, COLORREF>> edToks;
                if (declEdit) edToks.push_back(std::make_pair(g_codeEdText, declFg));
                else          code_tokenize(g_codeEdText, edToks);
                int ci = 0;
                for (size_t tk = 0; tk < edToks.size(); ++tk) {
                    const std::wstring& t = edToks[tk].first;
                    int nch = (int)t.size();
                    int a = x0 + code_ed_w(ci);
                    int b = x0 + code_ed_w(ci + nch);
                    if (a >= xR) break;
                    bool hitSel = (hi > lo) && (ci < hi) && (ci + nch > lo);
                    if (!hitSel) {
                        tx(dc, t.c_str(), RECT{ a, y, b + S(6), y + rh - 1 },
                           edToks[tk].second, g_f12,
                           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOCLIP);
                    } else {
                        // 选区是深底，选中的字必须反白，否则黑字压在深蓝上看不清。
                        // 逐字符画（只影响当前编辑这一行），按字符边界切，中文也准。
                        for (int k = 0; k < nch; ++k) {
                            int ch = ci + k;
                            int ca = x0 + code_ed_w(ch), cb = x0 + code_ed_w(ch + 1);
                            bool on = (ch >= lo && ch < hi);
                            std::wstring one(1, t[k]);
                            tx(dc, one.c_str(), RECT{ ca, y, cb + S(6), y + rh - 1 },
                               on ? RGB(255, 255, 255) : edToks[tk].second, g_f12,
                               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOCLIP);
                        }
                    }
                    ci += nch;
                }

                int caretX = x0 + code_ed_w(g_codeEdCaret);
                // 3) 中文输入法组字串跟在光标后
                if (!g_imeComp.empty())
                    tx(dc, g_imeComp.c_str(),
                       RECT{ caretX, y, xR + S(2), y + rh },
                       RGB(0x33, 0x33, 0x33), g_f12,
                       DT_LEFT | DT_VCENTER | DT_SINGLELINE);
                RestoreDC(dc, saved2);

                // 4) 闪烁插入光标（有选区时常显，落在选区活动端）
                int cw = std::max(1, S(2));
                RECT caretR = RECT{ caretX, y + S(3), caretX + cw, y + rh - S(3) };
                g_codeCaretRect = caretR;
                if (g_codeCaretOn && caretX >= x0 - S(2) && caretX <= xR + S(2))
                    fill(dc, caretR, caretCol);
            }
        }
        y += rh;
    }

    // 条件尾 ▼ 尖端会落到下一行，逐行底色会把尖点盖掉；所有行画完补一次。
    ui_flow_draw_tips(fs, flowLayout);

    RestoreDC(dc, saved);

    // 行号单独一遍（表格区 clip 已恢复，这里只裁到行号栏）：
    // 行号按装配行连续编号，滚动时跟着行走；选中行加深
    {
        int s2 = SaveDC(dc);
        IntersectClipRect(dc, vp.left, vp.top, vp.left + LNW, vp.bottom);
        int ny = vp.top + S(12) + code_table_pad() - g_a.codeScroll;
        int lineNo = 0;
        for (size_t i = 0; i < rows.size(); ++i) {
            if (rows[i].sep) ny += GAP;
            int rh = (rows[i].kind == 2) ? code_stmt_h() : code_row_h();
            // 表格模式（同真机）：永久隐藏的结构行零高度、不占可见编号
            if (rows[i].kind == 2 && rows[i].hidden) rh = 0;
            if (!(rows[i].kind == 2 && rows[i].hidden)) ++lineNo;
            if (ny + rh >= vp.top && ny <= vp.bottom) {
                bool editingNo = (g_codeEdActive && (int)i == g_codeEdRow);
                // 点击不高亮整行：行号栏也不填色，只用数字颜色给一点点定位反馈
                tx(dc, wnum(lineNo > 0 ? lineNo : (int)i + 1),
                   RECT{ vp.left + S(4), ny, vp.left + LNW - S(8), ny + rh },
                   editingNo ? RGB(0x1A, 0x4D, 0x99) : RGB(0x99, 0x99, 0x99),
                   g_f11, DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
            }
            ny += rh;
        }
        RestoreDC(dc, s2);
    }

    code_scrollbar_paint(dc, vp);   // 底部横向滚动条（内容超宽时才画）

    font_use(oldFontGroup); // 恢复原来的字体组
}

// ══════════════════════════════════════════════════════════════════
// 表格代码页交互：命中 / 选中 / 行内编辑 / 提交写回 g_eAsms。
// ══════════════════════════════════════════════════════════════════

static void code_ed_commit(bool apply);
static void code_flow_expand(int asmIdx, int sub, size_t headIdx);
static void code_ed_sync_now();   // 补全块头括号后即时写回+expand（定义在后）
static void code_ed_full_redraw();
static void code_snap_push(bool mergeable);      // 撤销快照（定义在交互段后部）
static void code_undo(); static void code_redo();
static bool code_clip_copy_lines(bool toClipboard);
static void code_clip_cut_lines();
static void code_clip_cut_chars();
static std::wstring code_ed_sel_text();          // 字符选区文本（定义在后）
static bool code_clip_copy_chars();              // 复制字符选区（定义在后）
static bool code_table_context_menu(int mx, int my);   // 表格右键菜单（定义在后）
static void code_clip_paste_into_edit(); static void code_clip_paste_rows();
static void code_clip_delete_selection();
static void code_ed_move_line(int dir, bool keepAnchor);
static void code_ed_set_target(int row, int col);
static void code_ed_open(int row, int col);
static bool code_ed_line_in_sel(int i);
static bool code_ed_line_text(const CRow& r, int& colOut, const wchar_t** txtOut);
static int  code_ed_row_x_to_col(HDC dc, const CRow& row, int col, int txBase, int mx);
static void code_clamp_selection();

// ── 记事本式行内编辑：一套状态、一套坐标、一次绘制 ────────────────────
// 关键：字符边界统一由 g_codeEdCharX 提供，「画文字 / 画选区 / 画光标 /
// 鼠标命中」全部读它，所以点击位置与光标位置永远像素级一致（中文也准）。
static HFONT code_ed_font()
{
    return (g_fontsBuilt && FNT_EDITOR >= 0 && FNT_EDITOR < FNT_N)
           ? g_fontSets[FNT_EDITOR].f[2] : g_f12;
}
static int code_ed_w(int idx)       // 第 idx 个字符边界的像素宽
{
    if (g_codeEdCharX.empty()) return 0;
    if (idx < 0) idx = 0;
    if (idx >= (int)g_codeEdCharX.size()) idx = (int)g_codeEdCharX.size() - 1;
    return g_codeEdCharX[idx];
}
static void code_ed_measure()       // 文本变了就重算字符边界
{
    HDC dc = GetDC(g_hwnd ? g_hwnd : NULL);
    int n = (int)g_codeEdText.size();
    g_codeEdCharX.assign((size_t)n + 1, 0);
    for (int i = 1; i <= n; ++i)
        g_codeEdCharX[i] = tw(dc, g_codeEdText.substr(0, (size_t)i), code_ed_font());
    ReleaseDC(g_hwnd ? g_hwnd : NULL, dc);
    if (g_codeEdCaret < 0) g_codeEdCaret = 0;
    if (g_codeEdCaret > n) g_codeEdCaret = n;
    if (g_codeEdAnchor < 0) g_codeEdAnchor = 0;
    if (g_codeEdAnchor > n) g_codeEdAnchor = n;
}
static int  code_ed_sel_lo() { return std::min(g_codeEdCaret, g_codeEdAnchor); }
static int  code_ed_sel_hi() { return std::max(g_codeEdCaret, g_codeEdAnchor); }
static bool code_ed_has_sel() { return g_codeEdCaret != g_codeEdAnchor; }

// 词字符：字母/数字/下划线 + CJK（易语言命令全是中文，Ctrl+方向键要按词跳）
static bool code_is_word(wchar_t ch)
{
    if (ch == L'_') return true;
    if (iswalnum(ch)) return true;
    if (ch >= 0x2E80 && ch <= 0x9FFF) return true;   // CJK 部首/符号/汉字
    if (ch >= 0xF900 && ch <= 0xFAFF) return true;   // 兼容表意文字
    if ((ch >= 0xFF10 && ch <= 0xFF19) ||            // 全角数字
        (ch >= 0xFF21 && ch <= 0xFF3A) ||            // 全角大写
        (ch >= 0xFF41 && ch <= 0xFF5A)) return true; // 全角小写
    return false;
}

// 是否存在任何选区（行内字符选区 或 跨行选区）
static bool code_ed_any_sel()
{
    if (g_codeEdActive && g_edDragStartRow >= 0 && g_edDragStartRow != g_codeEdRow)
        return true;
    return code_ed_has_sel();
}
// 装配行的可见文本（语句行剥前导点；声明行 = 各列以 Tab 连接）——
// 跨行选区取文本/画带都用它，与 code_clip_copy_lines 同口径。
static std::wstring code_row_plain_text(const CRow& rw)
{
    if (rw.kind == 2) {
        std::wstring s = rw.c[0];
        if (!s.empty() && s[0] == L'.') s.erase(0, 1);
        return s;
    }
    if (rw.kind == 1) {
        int n = code_col_n(rw.tt);
        std::wstring s;
        for (int c = 0; c < n; ++c) { s += rw.c[c]; if (c < n - 1) s += L'\t'; }
        return s;
    }
    return L"";
}
// 记事本语义：第 i 行的选区字符范围 [c0,c1)。
//   锚点行 = 锚点字符→行尾（焦点在下）或 行首→锚点字符（焦点在上）
//   焦点行 = 行首→光标（焦点在下）或 光标→行尾（焦点在上）
//   中间行 = 整行（c1 = 该行文字长度）
// 行内选区（锚点行==焦点行）= [min(锚,光标), max(锚,光标))
// 返回 false = 行 i 不在选区内。声明行/表头行只判"在不在范围内"（整行带）。
static bool code_ed_row_sel_range(int i, int& c0, int& c1)
{
    c0 = c1 = 0;
    if (!g_codeEdActive) return false;
    int fRow = g_codeEdRow;
    std::vector<CRow> rows;
    code_rows_build(rows);
    if (i < 0 || i >= (int)rows.size()) return false;
    if (rows[i].hidden) return false;               // 零高度隐藏行永不带选带
    if (g_edDragStartRow < 0 || g_edDragStartRow == fRow) {
        if (i != fRow) return false;
        c0 = code_ed_sel_lo(); c1 = code_ed_sel_hi();
        return c1 > c0;
    }
    int aRow = g_edDragStartRow;
    int lo = std::min(aRow, fRow), hi = std::max(aRow, fRow);
    if (i < lo || i > hi) return false;
    if (rows[i].kind != 2) { c0 = 0; c1 = INT_MAX; return true; }  // 声明行/表头行：整行带
    int len = (int)code_row_plain_text(rows[i]).size();
    if (i != aRow && i != fRow) { c0 = 0; c1 = len; return len > 0; }
    if (i == aRow) {
        int a = std::max(0, std::min(g_codeSelAChar, len));
        if (fRow > aRow) { c0 = a; c1 = len; }
        else             { c0 = 0; c1 = a; }
    } else {
        int f = std::max(0, std::min(g_codeEdCaret, len));
        if (fRow > aRow) { c0 = 0; c1 = f; }
        else             { c0 = f; c1 = len; }
    }
    return c1 > c0;
}
static std::wstring code_ed_sel_text()
{
    if (g_edDragStartRow >= 0 && g_edDragStartRow != g_codeEdRow) {
        // 跨行选区：锚点行半截 + 中间整行 + 焦点行半截，按行拼 \n
        std::vector<CRow> rows; code_rows_build(rows);
        int aRow = g_edDragStartRow, fRow = g_codeEdRow;
        int lo = std::min(aRow, fRow), hi = std::max(aRow, fRow);
        if (hi >= (int)rows.size()) hi = (int)rows.size() - 1;
        std::wstring out;
        for (int r = lo; r <= hi; ++r) {
            const CRow& rw = rows[r];
            if (rw.hidden) continue;
            if (rw.kind != 2) { out += code_row_plain_text(rw); }
            else {
                std::wstring s = code_row_plain_text(rw);
                int len = (int)s.size();
                if (r == aRow && r != fRow) {
                    int a = std::max(0, std::min(g_codeSelAChar, len));
                    out += (fRow > aRow) ? s.substr(0, (size_t)a) : s.substr((size_t)a);
                } else if (r == fRow && r != aRow) {
                    int f = std::max(0, std::min(g_codeEdCaret, len));
                    out += (fRow > aRow) ? s.substr(0, (size_t)f) : s.substr((size_t)f);
                } else out += s;
            }
            if (r < hi) out += L"\r\n";
        }
        return out;
    }
    int a = code_ed_sel_lo(), b = code_ed_sel_hi();
    if (a == b || a < 0 || b > (int)g_codeEdText.size()) return L"";
    return g_codeEdText.substr((size_t)a, (size_t)(b - a));
}
static void code_ed_sel_erase()     // 删掉选区，光标并到起点（支持跨行合并）
{
    // 声明表（kind==1：程序集名/子程序名/返回值/易包/备注/参数/变量…）永远只按
    // 「本格字符选区」删：拖选留下的跨行锚点一律作废，绝不进入下面的跨行合并 /
    // 删整行分支。否则在备注里拖选一个字按 Delete，删掉的会是代码区的语句行
    // （normRow 曾把声明行的锚点夹到最近语句行，实测每按一次删掉一行）。
    {
        std::vector<CRow> rowsK; code_rows_build(rowsK);
        bool declCell = (g_codeEdRow < 0 || g_codeEdRow >= (int)rowsK.size() ||
                         rowsK[g_codeEdRow].kind != 2);
        if (declCell) {
            g_edDragStartRow = g_edDragCurRow = -1;
            int a = code_ed_sel_lo(), b = code_ed_sel_hi();
            if (a != b) {
                g_codeEdText.erase((size_t)a, (size_t)(b - a));
                g_codeEdCaret = g_codeEdAnchor = a;
                code_ed_measure();
            }
            return;
        }
    }
    if (g_edDragStartRow >= 0 && g_edDragStartRow != g_codeEdRow) {
        std::vector<CRow> rows; code_rows_build(rows);
        int aRow = g_edDragStartRow, fRow = g_codeEdRow;
        int lo = std::min(aRow, fRow), hi = std::max(aRow, fRow);
        if (lo < 0 || hi >= (int)rows.size()) {
            g_edDragStartRow = g_edDragCurRow = -1;
            return;
        }
        // 范围内全是同一子程序的语句行 → 字符级合并（记事本 Delete 选区语义）；
        // 跨了声明行/多个子程序 → 退化为整行删除（借行选区删除，含块展开）
        bool sameSubStmt = true;
        int subNo = rows[lo].sub;
        for (int r = lo; r <= hi; ++r)
            if (!(rows[r].kind == 2 && rows[r].dst == 4 && rows[r].sub == subNo &&
                  rows[r].idx >= 0 && subNo >= 0)) { sameSubStmt = false; break; }
        if (!sameSubStmt) {
            code_ed_commit(false);
            g_codeSelRowStart = lo; g_codeSelRowEnd = hi;
            g_edDragStartRow = g_edDragCurRow = -1;
            code_clip_delete_selection();
            return;
        }
        int a = g_a.docTab - 1;
        if (a < 0 || a >= (int)g_eAsms.size() || subNo >= (int)g_eAsms[a].subs.size()) {
            g_edDragStartRow = g_edDragCurRow = -1;
            return;
        }
        code_snap_push(false);
        ESub& sub = g_eAsms[a].subs[subNo];
        // 两端行文本（剥前导点）：合并 = 锚点行左半 + 焦点行右半（或反之）
        std::wstring sa = code_row_plain_text(rows[lo]);
        std::wstring sf = code_row_plain_text(rows[hi]);
        bool aDot = !sub.body[rows[lo].idx].text.empty() && sub.body[rows[lo].idx].text[0] == L'.';
        int base = rows[lo].idx;
        std::wstring merged;
        int caretAt = 0;
        if (fRow > aRow) {   // 焦点在下：锚点行[0..锚点) + 焦点行[光标..]
            int ac = std::max(0, std::min(g_codeSelAChar, (int)sa.size()));
            int fc = std::max(0, std::min(g_codeEdCaret, (int)sf.size()));
            merged = sa.substr(0, (size_t)ac) + sf.substr((size_t)fc);
            caretAt = ac;
        } else {             // 焦点在上：焦点行[0..光标) + 锚点行[锚点..]
            int ac = std::max(0, std::min(g_codeSelAChar, (int)sa.size()));
            int fc = std::max(0, std::min(g_codeEdCaret, (int)sf.size()));
            merged = sf.substr(0, (size_t)fc) + sa.substr((size_t)ac);
            caretAt = fc;
        }
        // 删掉 lo+1..hi 对应的 body 行（body 下标连续递增，倒序删安全）
        for (int r = hi; r > lo; --r)
            if (rows[r].idx >= 0 && rows[r].idx < (int)sub.body.size() &&
                rows[r].idx != base)
                sub.body.erase(sub.body.begin() + rows[r].idx);
        if (base >= 0 && base < (int)sub.body.size())
            sub.body[base].text = aDot ? (merged.empty() ? L"." : L"." + merged) : merged;
        // 收拾编辑态：焦点回到锚点行，光标落在合并点
        code_ed_commit(false);
        rows.clear(); code_rows_build(rows);
        for (int k = 0; k < (int)rows.size(); ++k)
            if (rows[k].kind == 2 && rows[k].sub == subNo && rows[k].idx == base) {
                code_ed_open(k, 0);
                g_codeEdCaret = std::min(caretAt, (int)g_codeEdText.size());
                g_codeEdAnchor = g_codeEdCaret;
                break;
            }
        g_edDragStartRow = g_edDragCurRow = -1;
        g_codeSelAChar = 0;
        code_ed_full_redraw();
        return;
    }
    int a = code_ed_sel_lo(), b = code_ed_sel_hi();
    if (a == b) return;
    g_codeEdText.erase((size_t)a, (size_t)(b - a));
    g_codeEdCaret = g_codeEdAnchor = a;
    code_ed_measure();
}
// 编辑框当前内容是否为「刚敲完、还没带参数的块头命令」。
// 判据：第一个空格/括号之前的整词 ∈ 块头表。打完命令多敲的空格不算内容；
// 文本里已有括号 = 已经带参数 → 放过（防重复补）。
static bool code_ed_is_fresh_flow_head()
{
    std::wstring s = flow_trim(g_codeEdText);          // 剥前导点/两端空白
    if (s.empty()) return false;
    if (s.find(L'（') != std::wstring::npos || s.find(L'(') != std::wstring::npos)
        return false;                                   // 已有括号 = 不是「刚敲完命令」
    size_t p = s.find(L' ');
    std::wstring name = (p == std::wstring::npos) ? s : s.substr(0, p);
    if (name.empty()) return false;
    if (!flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), name))
        return false;
    if (name != flow_cmd_name(name)) return false;      // 「如果」✅ 「如果真」✅ 「如果x」❌
    return true;
}
// 补 " ()" + 光标进括号 + 写回数据行 expand 配对 + 整窗重绘。
// 所有输入路径（逐字/IME 上屏/粘贴/选中行直接打字）最终都汇到 code_ed_put。
static void code_ed_flow_autocomplete()
{
    if (!code_ed_is_fresh_flow_head()) return;
    while (!g_codeEdText.empty() &&
           (g_codeEdText.back() == L' ' || g_codeEdText.back() == L'\t'))
        g_codeEdText.pop_back();
    g_codeEdText += L" ()";
    g_codeEdCaret = (int)g_codeEdText.size() - 1;      // 光标进括号： 如果 (|)
    g_codeEdAnchor = g_codeEdCaret;
    code_ed_sync_now();        // 写回数据 + expand（幂等：已有尾不重插）
    code_ed_full_redraw();     // 新行/轨道立刻可见
}
static void code_ed_put(const std::wstring& t)   // 替换选区 / 在光标处插入
{
    code_ed_sel_erase();
    // 粘贴多行时只取第一行，单元格编辑不接受换行
    std::wstring v = t;
    size_t nl = v.find_first_of(L"\r\n");
    if (nl != std::wstring::npos) v.resize(nl);
    code_snap_push(true);          // 打字可合并撤销
    g_codeEdText.insert((size_t)g_codeEdCaret, v);
    g_codeEdCaret += (int)v.size();
    g_codeEdAnchor = g_codeEdCaret;
    code_ed_flow_autocomplete();   // 真机：打完块头命令当刻补 () 并画完整流程线
    code_ed_measure();
}
static void code_ed_caret_reset()  // 光标动一下：立即常显 + 重启闪烁
{
    g_codeCaretOn = true;
    if (g_hwnd) {
        KillTimer(g_hwnd, TIMER_CODE_CARET);
        SetTimer(g_hwnd, TIMER_CODE_CARET, 500, NULL);
    }
}
static void code_ed_invalidate()   // 只失效当前编辑行（WM_PAINT 走局部快路径）
{
    if (!g_hwnd) return;
    RECT r = g_codeEdLineRect;
    RECT lim = rcCanvas;
    r.left   = std::max(r.left,   lim.left);
    r.top    = std::max(r.top,    lim.top);
    r.right  = std::min(r.right,  lim.right);
    r.bottom = std::min(r.bottom, lim.bottom);
    if (r.right <= r.left || r.bottom <= r.top) {
        g_codeDirtyValid = false;
        InvalidateRect(g_hwnd, NULL, FALSE);
        return;
    }
    g_codeDirtyRect  = r;
    g_codeDirtyValid = true;
    InvalidateRect(g_hwnd, &r, FALSE);
}
static void code_ed_full_redraw()  // 结构可能变了（提交 / 换行）：整窗刷新
{
    g_codeDirtyValid = false;
    if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
}
static int code_ed_x_to_caret(int mx)   // 点哪插哪：取最近的字符边界
{
    int dx = mx - g_codeEdTextX;
    int n = (int)g_codeEdText.size();
    if (g_codeEdCharX.size() != (size_t)n + 1) code_ed_measure();
    int best = 0, bestD = INT_MAX;
    for (int i = 0; i <= n; ++i) {
        int d = std::abs(code_ed_w(i) - dx);
        if (d < bestD) { bestD = d; best = i; }
    }
    return best;
}
static void code_ed_clip_set(const std::wstring& text)
{
    if (text.empty() || !OpenClipboard(g_hwnd)) return;
    EmptyClipboard();
    size_t sz = (text.size() + 1) * sizeof(wchar_t);
    HGLOBAL h = GlobalAlloc(GMEM_MOVEABLE, sz);
    if (h) {
        LPWSTR p = (LPWSTR)GlobalLock(h);
        wcscpy_s(p, text.size() + 1, text.c_str());
        GlobalUnlock(h);
        SetClipboardData(CF_UNICODETEXT, h);
    }
    CloseClipboard();
}
static std::wstring code_ed_clip_get()
{
    std::wstring out;
    if (!OpenClipboard(g_hwnd)) return out;
    HANDLE h = GetClipboardData(CF_UNICODETEXT);
    if (h) {
        LPWSTR p = (LPWSTR)GlobalLock(h);
        if (p) { out = p; GlobalUnlock(h); }
    }
    CloseClipboard();
    return out;
}
static void code_ed_copy(bool cut)
{
    // 记事本口径：有选区=选区内容；无选区=整行
    std::wstring t = code_ed_any_sel() ? code_ed_sel_text() : g_codeEdText;
    code_ed_clip_set(t);
    if (cut) {
        if (code_ed_any_sel()) { code_ed_sel_erase(); return; }
        // 无选区剪切 = 清空本行（记事本剪整行；表格里保住空语句行骨架）
        if (!g_codeEdText.empty()) {
            code_snap_push(false);
            g_codeEdText.clear();
            g_codeEdCaret = g_codeEdAnchor = 0;
            code_ed_measure();
        }
    }
}
static void code_ed_select_all()
{
    g_codeEdAnchor = 0;
    g_codeEdCaret  = (int)g_codeEdText.size();
}
// 编辑行几何：与 paint_code_table / code_hit 使用完全相同的 tblL、行高累加。
static void code_ed_update_geometry()
{
    g_codeEdLineRect = RECT{ 0, 0, 0, 0 };
    if (!g_codeEdActive) return;
    std::vector<CRow> rows; code_rows_build(rows);
    if (g_codeEdRow < 0 || g_codeEdRow >= (int)rows.size()) return;
    RECT vp = rcCanvas;
    vp.left += S(3); vp.right -= 1; vp.bottom -= 1 + g_codeBarH;
    int tblL = vp.left + S(46) + S(24) - g_codeScrollX;
    int y = vp.top + code_table_pad() - g_a.codeScroll;
    for (size_t i = 0; i < rows.size() && (int)i <= g_codeEdRow; ++i) {
        if (rows[i].sep) y += code_gap();
        int rh = (rows[i].kind == 2) ? code_stmt_h() : code_row_h();
        if ((int)i == g_codeEdRow) {
            const CRow& r = rows[i];
            // 列宽缓存由 paint_code_table 填充；冷启动第一帧前可能是 0，
            // 用画布右缘兜底，保证「点击定位 / 局部重绘」不依赖先画过一帧。
            int stmtR = (g_codeStmtR > tblL) ? g_codeStmtR : vp.right - S(4);
            if (r.kind == 2) {
                int lv = std::max(0, r.level);
                g_codeEdTextX = tblL + S(38) + lv * code_lane_step();
                g_codeEdTextR = stmtR - S(4);
                g_codeEdLineRect = RECT{ tblL, y, stmtR, y + rh };
            } else {
                int tt = r.tt, n = code_col_n(tt);
                int c = std::min(std::max(0, g_codeEdCol), n - 1);
                int x0 = tblL + code_col_x(tt, c);
                int x1 = (c < n - 1) ? tblL + code_col_x(tt, c + 1) : g_codeTR[tt];
                if (x1 <= x0) x1 = vp.right - S(4);
                g_codeEdTextX = x0 + S(5);
                g_codeEdTextR = x1 - S(8);
                g_codeEdLineRect = RECT{ x0, y, x1, y + rh };
            }
            return;
        }
        y += rh;
    }
}
// 文本或光标变化后统一走这里：重算边界 + 重置闪烁 + 只刷当前行。
// 编辑中「即时写回」：每改一个字就把编辑框内容落到 g_eAsms，
// 不用等鼠标点别处 / 失焦再提交。只处理声明表（表格里的名字、类型、备注），
// 语句行仍然在提交时写回 —— 那边写着写着会触发块结构展开，不能边打边改结构。
static void code_ed_apply_live()
{
    if (!g_codeEdActive || g_codeEdRow < 0) return;
    std::vector<CRow> rows; code_rows_build(rows);
    if (g_codeEdRow >= (int)rows.size()) return;
    const CRow& r = rows[g_codeEdRow];
    if (r.kind != 1) return;                        // 只做声明表
    if (code_col_is_check(r.tt, g_codeEdCol)) return;   // 勾选列不是文本
    if (code_col_is_lock(r.tt, g_codeEdCol))  return;   // 「保 留」列只读
    int f = code_col_field(r.tt, g_codeEdCol);
    if (f == CFD_NONE) return;
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size()) return;
    EAsm& am = g_eAsms[a];
    const std::wstring& t = g_codeEdText;

    switch (r.tt) {
    case TT_ASM:
        if      (f == CFD_NAME)   am.name   = t;
        else if (f == CFD_REMARK) am.remark = t;
        break;
    case TT_ASMVAR:
        if (r.idx >= 0 && r.idx < (int)am.vars.size()) {
            EArg& v = am.vars[r.idx];
            if      (f == CFD_NAME)   v.name   = t;
            else if (f == CFD_TYPE)   v.type   = t;
            else if (f == CFD_REMARK) v.remark = t;
        }
        break;
    case TT_SUB:
        if (r.sub >= 0 && r.sub < (int)am.subs.size()) {
            ESub& sb = am.subs[r.sub];
            if      (f == CFD_NAME)   sb.name   = t;
            else if (f == CFD_TYPE)   sb.ret    = t;
            else if (f == CFD_PKG)    sb.pkg    = t;
            else if (f == CFD_REMARK) sb.remark = t;
        }
        break;
    case TT_PARAM:
        if (r.sub >= 0 && r.sub < (int)am.subs.size() && r.idx >= 0 &&
            r.idx < (int)am.subs[r.sub].args.size()) {
            EArg& v = am.subs[r.sub].args[r.idx];
            if      (f == CFD_NAME)   v.name   = t;
            else if (f == CFD_TYPE)   v.type   = t;
            else if (f == CFD_REMARK) v.remark = t;
        }
        break;
    case TT_VAR:
        if (r.sub >= 0 && r.sub < (int)am.subs.size() && r.idx >= 0 &&
            r.idx < (int)am.subs[r.sub].locals.size()) {
            EArg& v = am.subs[r.sub].locals[r.idx];
            if      (f == CFD_NAME)   v.name   = t;
            else if (f == CFD_TYPE)   v.type   = t;
            else if (f == CFD_REMARK) v.remark = t;
        }
        break;
    }
    g_a.form.dirty = true;
}

// 光标跑到视口外时，把横向滚动跟过去（打字时可编辑区自动跟着走）
static void code_ed_ensure_visible()
{
    if (!g_codeEdActive || g_codeMaxScrollX <= 0) return;
    RECT vp = rcCanvas;
    vp.left += S(3) + S(46);       // 行号栏右侧
    vp.right -= S(8);
    int cx = g_codeEdTextX + code_ed_w(g_codeEdCaret);
    int ns = g_codeScrollX;
    if (cx > vp.right)     ns += cx - vp.right;
    else if (cx < vp.left) ns -= vp.left - cx;
    else return;
    if (ns < 0) ns = 0;
    if (ns > g_codeMaxScrollX) ns = g_codeMaxScrollX;
    if (ns != g_codeScrollX) {
        g_codeScrollX = ns;
        code_ed_update_geometry();
    }
}

// 拖选时鼠标顶到左右边缘：按步长连续横滚，让后面的字跟着出来
static void code_ed_autoscroll(int mx)
{
    if (g_codeMaxScrollX <= 0) return;
    RECT vp = rcCanvas;
    vp.left += S(3) + S(46);
    vp.right -= S(8);
    int step = S(20);
    int ns = g_codeScrollX;
    if (mx > vp.right)      ns += step;
    else if (mx < vp.left)  ns -= step;
    else return;
    if (ns < 0) ns = 0;
    if (ns > g_codeMaxScrollX) ns = g_codeMaxScrollX;
    if (ns != g_codeScrollX) {
        g_codeScrollX = ns;
        code_ed_update_geometry();
        if (g_hwnd) InvalidateRect(g_hwnd, &rcCanvas, FALSE);
    }
}

static void code_ed_changed(bool resetBlink = true)
{
    code_ed_apply_live();          // 输入即生效（不用等失焦）
    code_ed_measure();
    code_ed_update_geometry();
    code_ed_ensure_visible();      // 打到这里已经超出可视宽度：横向滚动跟过去
    if (resetBlink) code_ed_caret_reset();
    // 只有**文字真的变了**才判断要不要整窗：声明格的列宽随字数变，后面的列要一起右移。
    // 光标闪烁走的是 code_ed_invalidate()（局部），不会再整表重绘 —— 点击时不再闪。
    bool declEdit = false;
    if (g_codeEdActive) {
        std::vector<CRow> rows; code_rows_build(rows);
        if (g_codeEdRow >= 0 && g_codeEdRow < (int)rows.size())
            declEdit = (rows[g_codeEdRow].kind == 1);
    }
    if (declEdit) {
        g_codeDirtyValid = false;
        if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
    } else {
        code_ed_invalidate();
    }
}

// 进入行内编辑：取该格当前文字填进编辑框，光标落到末尾。
// 声明行按各表的可编辑列（code_col_editable）放行；语句行整行一个编辑目标。
static void code_ed_open(int row, int col)
{
    std::vector<CRow> rows; code_rows_build(rows);
    if (row < 0 || row >= (int)rows.size()) return;
    const CRow& r = rows[row];
    if (r.kind == 0) return;                        // 表头只是标签：不给光标、不给输入
    if (r.kind == 1 && !code_col_editable(r.tt, col)) return;
    g_codeEdReadOnly = (r.kind == 1 && code_col_is_lock(r.tt, col));
    g_codeEdActive = true;
    g_codeEdRow = row;
    g_codeEdCol = col;
    const wchar_t* src = (col < (int)6) ? r.c[col].c_str() : L"";
    if (r.kind == 2) {
        src = r.c[0].c_str();
        if (*src == L'.') ++src;   // 控制流前导点是语法标记，编辑框里不显示
    }
    g_codeEdText = src;
    g_codeEdCaret  = (int)g_codeEdText.size();
    g_codeEdAnchor = g_codeEdCaret;
    g_imeComp.clear();
    code_ed_measure();
    code_ed_update_geometry();
    code_ed_caret_reset();
}

// 把编辑框当前文本即时写回数据行（保持编辑态）：敲块头补 () 后立刻 expand
// 需要数据层同步，否则 expand 看到的是旧文本。写回规则与 commit 一致。
static void code_ed_sync_now()
{
    if (!g_codeEdActive || g_codeEdRow < 0) return;
    std::vector<CRow> rows; code_rows_build(rows);
    if (g_codeEdRow >= (int)rows.size()) return;
    const CRow& r = rows[g_codeEdRow];
    if (r.kind != 2 || r.dst != 4 || r.sub < 0 || r.idx < 0) return;
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size() || r.sub >= (int)g_eAsms[a].subs.size()) return;
    ESub& sub = g_eAsms[a].subs[r.sub];
    if (r.idx >= (int)sub.body.size()) return;
    EStmt& st = sub.body[r.idx];
    std::wstring out = g_codeEdText;
    if (out.empty()) return;
    if (!st.text.empty() && st.text[0] == L'.' && out[0] != L'.') out.insert(out.begin(), L'.');
    if (out == st.text) return;
    st.text = out;
    if (st.text[0] == L'.' &&
        flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), st.text))
        code_flow_expand(a, r.sub, (size_t)r.idx);
}

// 收编辑。apply=true 把编辑框文字写回数据（改哪格落到装配行带的
// dst/tt/sub/idx 字段上）；false 只收不写。提交完重选回这一行。
static void code_ed_commit(bool apply)
{
    if (!g_codeEdActive) return;
    g_codeEdActive = false;
    g_codeEdDrag   = false;
    g_codeCaretOn  = true;
    g_imeComp.clear();
    if (g_hwnd) KillTimer(g_hwnd, TIMER_CODE_CARET);
    int row = g_codeEdRow;
    g_codeSelRow = row;
    // 提交会改写语句文本、流程线可能随之变化：必须整窗重画一次。
    code_ed_full_redraw();
    if (!apply) return;
    std::vector<CRow> rows; code_rows_build(rows);
    if (row < 0 || row >= (int)rows.size()) return;
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size()) return;
    const CRow& r = rows[row];
    EAsm& am = g_eAsms[a];
    const std::wstring& t = g_codeEdText;
    if (r.kind == 2) {                                   // 语句行：写回语句文本
        if (r.dst != 4 || r.sub < 0 || r.sub >= (int)am.subs.size()) return;
        ESub& sub = am.subs[r.sub];
        if (r.idx >= 0 && r.idx < (int)sub.body.size()) {
            EStmt& st = sub.body[r.idx];
            // 控制流语句在 .e 源里带前导 '.'（语法标记），编辑框里没显示它，
            // 提交时补回去，别把语法弄丢
            st.text = (!st.text.empty() && st.text[0] == L'.' &&
                       !t.empty() && t[0] != L'.') ? L"." + t : t;
            // 真机行为：块头语句一成立（提交/回车/失焦任一路径）立即补齐
            // 配对结构（如果→否则+如果结束；循环头→尾），流程线随之完整画出。
            if (!st.text.empty() && st.text[0] == L'.' &&
                flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), st.text))
                code_flow_expand(a, r.sub, (size_t)r.idx);
        } else if (r.idx < 0 && !t.empty()) {
            EStmt st; st.text = t; st.indent = 0;   // 空子程序占位行：输入即新语句
            sub.body.push_back(st);
            if (st.text[0] == L'.' &&
                flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), st.text))
                code_flow_expand(a, r.sub, sub.body.size() - 1);
        }
        return;
    }
    if (r.kind != 1) return;
    // 按列定义里的 CodeField 写回（不再用列号硬编码，加列只改结构体）
    int f = code_col_field(r.tt, g_codeEdCol);
    if (f == CFD_NONE) return;                       // 保留列：不落数据
    switch (r.tt) {
    case TT_ASM:
        if      (f == CFD_NAME)   am.name   = t;
        else if (f == CFD_REMARK) am.remark = t;
        break;
    case TT_ASMVAR:
        if (r.idx >= 0 && r.idx < (int)am.vars.size()) {
            EArg& v = am.vars[r.idx];
            if      (f == CFD_NAME)   v.name   = t;
            else if (f == CFD_TYPE)   v.type   = t;
            else if (f == CFD_REMARK) v.remark = t;
        }
        break;
    case TT_SUB:
        if (r.sub >= 0 && r.sub < (int)am.subs.size()) {
            ESub& sub = am.subs[r.sub];
            if      (f == CFD_NAME)   sub.name   = t;
            else if (f == CFD_TYPE)   sub.ret    = t;
            else if (f == CFD_PKG)    sub.pkg    = t;   // 易包：文本列
            else if (f == CFD_REMARK) sub.remark = t;
        }
        break;
    case TT_PARAM:
        if (r.sub >= 0 && r.sub < (int)am.subs.size() && r.idx >= 0 &&
            r.idx < (int)am.subs[r.sub].args.size()) {
            EArg& a = am.subs[r.sub].args[r.idx];
            if      (f == CFD_NAME)   a.name   = t;
            else if (f == CFD_TYPE)   a.type   = t;
            else if (f == CFD_REMARK) a.remark = t;
        }
        break;
    case TT_VAR:
        if (r.sub >= 0 && r.sub < (int)am.subs.size() && r.idx >= 0 &&
            r.idx < (int)am.subs[r.sub].locals.size()) {
            EArg& v = am.subs[r.sub].locals[r.idx];
            if      (f == CFD_NAME)   v.name   = t;
            else if (f == CFD_TYPE)   v.type   = t;
            else if (f == CFD_REMARK) v.remark = t;
        }
        break;
    }
}

// ── 敲流程块头 + 回车：自动把本层块与下层块的流程骨架全部画出来 ──────
// 真机行为（参考 su-lang-main/ui/code_editor.py::_insert_flow_pair，骨架按
// 易语言表格编辑器习惯补齐）：
//   如果        →  如果 ()      ← 光标回到这里填条件
//                    （否则/如果结束 由骨架生成，配对后隐藏成流程线）
//   计次循环首  →  计次循环首 (10, 计次)
//                    计次循环尾 ()
// 已存在配套块尾的行不重复生成（幂等，防按多次回车叠出重复结束行）。
static int flow_find_pair(const std::vector<EStmt>& body, size_t headIdx)
{
    if (headIdx >= body.size()) return -1;
    int hv = body[headIdx].indent;
    std::wstring name = flow_cmd_name(body[headIdx].text);
    std::wstring tail = flow_tail_of(name);
    for (size_t k = headIdx + 1; k < body.size(); ++k) {
        const EStmt& st = body[k];
        if (st.indent < hv) break;          // 退回外层 = 块已隐式收束
        if (st.indent == hv && !st.text.empty() && st.text[0] == L'.' &&
            flow_cmd_name(st.text) == tail) return (int)k;
    }
    return -1;
}
static void code_flow_expand(int asmIdx, int sub, size_t headIdx)
{
    if (asmIdx < 0 || asmIdx >= (int)g_eAsms.size()) return;
    if (sub < 0 || sub >= (int)g_eAsms[asmIdx].subs.size()) return;
    std::vector<EStmt>& body = g_eAsms[asmIdx].subs[sub].body;
    if (headIdx >= body.size()) return;
    const std::wstring& t = body[headIdx].text;
    if (t.empty() || t[0] != L'.') return;
    if (!flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), t)) return;
    if (flow_find_pair(body, headIdx) >= 0) return;   // 已有配套尾
    std::wstring name = flow_cmd_name(t);
    std::wstring tail = flow_tail_of(name);
    if (tail == name) return;
    int lv = body[headIdx].indent;
    // 真机块尾 () 规则（Elang-Skills 实测）：如果结束/如果真结束/判断结束不带括号，
    // 判断尾/循环类尾必须带 ()。
    bool paren = !(name == L"如果" || name == L"如果真" || name == L"判断开始");
    size_t ins = headIdx + 1;
    if (name == L"如果")   body.insert(body.begin() + ins++, EStmt(L".否则", lv));
    if (name == L"判断" || name == L"判断开始")
        body.insert(body.begin() + ins++, EStmt(L".默认", lv + 1));
    body.insert(body.begin() + ins, EStmt(L"." + tail + (paren ? L" ()" : L""), lv));
}
// 删掉块头行 = 整个块一起删（真机语义：块是一体的，不会给你留孤儿）。
// 从块头删到配套块尾（含）；块尾缺失就删到隐式收束处。
static int code_flow_remove_block(std::vector<EStmt>& body, size_t headIdx)
{
    if (headIdx >= body.size()) return 0;
    const std::wstring& t = body[headIdx].text;
    if (t.empty() || t[0] != L'.') return 0;
    if (!flow_hit(kFlowHeadsG, (int)(sizeof(kFlowHeadsG) / sizeof(kFlowHeadsG[0])), t)) return 0;
    int hv = body[headIdx].indent;
    std::wstring tail = flow_tail_of(flow_cmd_name(t));
    size_t last = headIdx;
    for (size_t k = headIdx + 1; k < body.size(); ++k) {
        const EStmt& st = body[k];
        if (st.indent < hv) break;
        bool isTail = (st.indent == hv && !st.text.empty() && st.text[0] == L'.' &&
                       flow_cmd_name(st.text) == tail);
        last = k;
        if (isTail) break;                    // 配套块尾也删掉（含在本块内）
    }
    body.erase(body.begin() + headIdx, body.begin() + last + 1);
    return (int)(last - headIdx + 1);
}

// 命中测试：和 paint_code_table 完全同一套几何（共享列宽缓存），点哪算哪。
// colOut：声明行 = 列 0..n-1；语句行恒 0。
static bool code_hit(int mx, int my, int& rowOut, int& colOut)
{
    std::vector<CRow> rows; code_rows_build(rows);
    if (rows.empty()) return false;
    RECT vp = rcCanvas;
    vp.left += S(3);                 // 与 paint_code_table 完全一致（原来差 3px，点击就偏）
    vp.right -= 1; vp.bottom -= 1 + g_codeBarH;
    int tblL = vp.left + S(46) + S(24) - g_codeScrollX;
    int y = vp.top + code_table_pad() - g_a.codeScroll;
    for (size_t i = 0; i < rows.size(); ++i) {
        if (rows[i].sep) y += code_gap();
        int rh = (rows[i].kind == 2) ? code_stmt_h() : code_row_h();
        int rowRi = (rows[i].kind == 2) ? g_codeStmtR : g_codeTR[rows[i].tt];
        // 首帧 paint_code_table 还没跑过时列宽缓存是 0，用画布右缘兜底，
        // 否则自验/冷启动的第一次点击会命中不到任何行。
        if (rowRi <= tblL) rowRi = vp.right;
        if (my >= y && my < y + rh && mx >= tblL && mx < rowRi) {
            rowOut = (int)i;
            colOut = 0;
            if (rows[i].kind == 1) {
                int tt = rows[i].tt, n = code_col_n(tt);
                for (int k = n - 1; k >= 1; --k)
                    if (mx >= tblL + code_col_x(tt, k)) { colOut = k; break; }
            }
            return true;
        }
        y += rh;
    }
    return false;
}

// 宽松命中：点在表格的空白处（右侧、下方、表头上方）也能落到最近的行列。
// 拖选整张表时，起手和收手常常落在空白上，严格命中会直接放弃。
static bool code_hit_clamped(int mx, int my, int& rowOut, int& colOut)
{
    if (code_hit(mx, my, rowOut, colOut)) return true;
    std::vector<CRow> rows; code_rows_build(rows);
    if (rows.empty()) return false;

    RECT vp = rcCanvas;
    vp.left += S(3); vp.right -= 1; vp.bottom -= 1 + g_codeBarH;
    int tblL = vp.left + S(46) + S(24) - g_codeScrollX;
    int y = vp.top + code_table_pad() - g_a.codeScroll;

    int hitRow = -1, hitY = y;
    for (size_t i = 0; i < rows.size(); ++i) {
        if (rows[i].sep) y += code_gap();
        int rh = (rows[i].kind == 2) ? code_stmt_h() : code_row_h();
        if (my < y + rh) { hitRow = (int)i; hitY = y; break; }
        y += rh;
    }
    if (hitRow < 0) {                        // 表格下方空白：贴到最后一行
        hitRow = (int)rows.size() - 1;
    }
    rowOut = hitRow;
    colOut = 0;
    const CRow& r = rows[hitRow];
    if (r.kind == 1) {
        int tt = r.tt, n = code_col_n(tt);
        int x = mx - tblL;
        int col = n - 1;                       // 默认最后一列（点在表格右侧空白）
        for (int k = 0; k < n; ++k) {
            int x1 = (k + 1 < n) ? code_col_x(tt, k + 1)
                                 : (code_col_x(tt, k) + g_codeTW[tt][k]);
            if (x < x1) { col = k; break; }
        }
        if (x < 0) col = 0;
        colOut = col;
    }
    (void)hitY;
    return true;
}

// ── 撤销/重做：整份快照栈（简单可靠优先，规模大了再换 diff 快照）────
static long long code_now_ms() { return (long long)GetTickCount64(); }

// 数据指纹：把程序集 / 全局变量 / 工程名全量摊成一个串，用来判断「数据有没有变」。
// 分隔符用控制字符，正常文本里不会出现；字段一个不落，勾选位也要进去。
static std::wstring code_data_key()
{
    std::wstring k;
    k.reserve(1024);
    k += g_projName; k += L'\x1';
    auto argKey = [&](const EArg& v) {
        k += v.name; k += L'\x2'; k += v.type; k += L'\x2'; k += v.remark; k += L'\x2';
        k += v.arr      ? L'1' : L'0';
        k += v.byref    ? L'1' : L'0';
        k += v.nullable ? L'1' : L'0';
        k += v.isStatic ? L'1' : L'0';
        k += L'\x1';
    };
    for (const EArg& v : g_eGlobals) argKey(v);
    for (const EAsm& a : g_eAsms) {
        k += a.name; k += L'\x2'; k += a.remark; k += L'\x1';
        for (const EArg& v : a.vars) argKey(v);
        for (const ESub& s : a.subs) {
            k += s.name; k += L'\x2'; k += s.ret; k += L'\x2';
            k += s.remark; k += L'\x2'; k += s.pkg; k += L'\x2';
            k += s.pub ? L'1' : L'0'; k += L'\x1';
            for (const EArg& v : s.args)   argKey(v);
            for (const EArg& v : s.locals) argKey(v);
            for (const EStmt& st : s.body) {
                k += st.text; k += L'\x2';
                k += std::to_wstring(st.indent); k += L'\x1';
            }
        }
    }
    return k;
}

// 工程换了（新建 / 打开 / 导入 / 自验重建）：历史作废，基线等下一次动作重新抓，
// 免得把「换工程」当成一次可撤销的修改，按 Ctrl+Z 把旧工程数据塞回来。
static void code_snap_reset()
{
    g_undoStack.clear();
    g_redoStack.clear();
    g_undoMerging   = false;
    g_snapPending   = false;
    g_snapKnownInit = false;
    g_snapKnownKey.clear();
    g_snapKnown     = CodeSnap{};
}

// 对齐基线：数据没变就什么都不做；变了但已经有显式快照记过账，只更新基线；
// 变了且没人记账（漏网的修改路径）→ 把「改动前」压一份进栈，撤销一定撤得掉。
static void code_snap_auto()
{
    std::wstring cur = code_data_key();
    if (!g_snapKnownInit) {
        g_snapKnownInit = true;
        g_snapKnownKey  = cur;
        g_snapKnown     = CodeSnap{ g_eAsms, g_eGlobals, g_projName, code_now_ms() };
        g_snapPending   = false;
        return;
    }
    if (cur == g_snapKnownKey) return;
    if (!g_snapPending) {
        if (g_undoStack.size() >= 100) g_undoStack.erase(g_undoStack.begin());
        g_undoStack.push_back(CodeSnap{ g_snapKnown.asms, g_snapKnown.globals,
                                        g_snapKnown.projName, code_now_ms() });
        g_redoStack.clear();
        g_undoMerging = false;
    }
    g_snapPending  = false;
    g_snapKnownKey = cur;
    g_snapKnown    = CodeSnap{ g_eAsms, g_eGlobals, g_projName, code_now_ms() };
}

static void code_snap_push(bool mergeable)
{
    long long now = code_now_ms();
    // 连续打字合并：同一次编辑动作、且距上次入栈 <600ms → 覆盖栈顶
    if (mergeable && g_undoMerging && !g_undoStack.empty() &&
        now - g_undoLastPush < 600) {
        g_undoStack.back().t = now;
        g_undoLastPush = now;
        g_snapPending = true;      // 合并也算已记账，自动兜底别再补一份
        return;
    }
    if (g_undoStack.size() >= 100)
        g_undoStack.erase(g_undoStack.begin());
    g_undoStack.push_back(CodeSnap{ g_eAsms, g_eGlobals, g_projName, now });
    g_redoStack.clear();
    g_undoMerging = mergeable;
    g_undoLastPush = now;
    g_snapPending = true;
}
static void code_clamp_selection()
{
    std::vector<CRow> rows; code_rows_build(rows);
    int n = (int)rows.size();
    if (g_codeEdRow >= n)  g_codeEdRow  = n - 1;
    if (g_codeSelRow >= n) g_codeSelRow = n - 1;
    if (g_codeEdRow  < 0)  g_codeEdRow  = 0;
    if (g_codeSelRow < 0)  g_codeSelRow = 0;
    if (n == 0) { g_codeEdRow = g_codeSelRow = -1; }
    g_edDragStartRow = g_edDragCurRow = -1;
    if (g_codeEdRow >= 0 && g_codeEdRow < n) code_ed_open(g_codeEdRow, g_codeEdCol);
}
static void code_undo()
{
    // 注意：这里不跑 code_snap_auto()。撤销入口会先 code_ed_commit(true) 把
    // 编辑缓冲落盘，那时数据又变了一次；若在此处补快照，栈顶会变成「当前状态」，
    // 撤销就看着像没反应。基线对齐统一放在动作入口（on_key / on_char / 菜单 / 工具栏）。
    if (g_undoStack.empty()) return;
    g_redoStack.push_back(CodeSnap{ g_eAsms, g_eGlobals, g_projName, code_now_ms() });
    CodeSnap s = std::move(g_undoStack.back()); g_undoStack.pop_back();
    g_eAsms = std::move(s.asms); g_eGlobals = std::move(s.globals); g_projName = std::move(s.projName);
    g_undoMerging = false;
    code_clamp_selection();
    code_ed_full_redraw();
    // 恢复出来的数据就是新基线，别把「撤销动作本身」当成下一次可撤销的修改
    g_snapKnownInit = true;
    g_snapKnownKey  = code_data_key();
    g_snapKnown     = CodeSnap{ g_eAsms, g_eGlobals, g_projName, code_now_ms() };
    g_snapPending   = false;
}
static void code_redo()
{
    if (g_redoStack.empty()) return;
    g_undoStack.push_back(CodeSnap{ g_eAsms, g_eGlobals, g_projName, code_now_ms() });
    CodeSnap s = std::move(g_redoStack.back()); g_redoStack.pop_back();
    g_eAsms = std::move(s.asms); g_eGlobals = std::move(s.globals); g_projName = std::move(s.projName);
    g_undoMerging = false;
    code_clamp_selection();
    code_ed_full_redraw();
    g_snapKnownInit = true;
    g_snapKnownKey  = code_data_key();
    g_snapKnown     = CodeSnap{ g_eAsms, g_eGlobals, g_projName, code_now_ms() };
    g_snapPending   = false;
}

// 主菜单 / 工具栏的撤销、重做：do_action 在文件前部，看不到这里的编辑态，
// 用这两个包装函数转发（先对齐基线 → 落当前格 → 走代码页自己的栈）。
static void code_undo_from_action()
{
    code_snap_auto();
    if (g_codeEdActive) code_ed_commit(true);
    code_undo();
}
static void code_redo_from_action()
{
    code_snap_auto();
    if (g_codeEdActive) code_ed_commit(true);
    code_redo();
}

// ── 跨行选区判定（拖选经过的行）────────────────────────────────
// 返回 true = 第 i 行处于跨行选区内（绘制要铺底色）。
static bool code_ed_line_in_sel(int i)
{
    if (!g_codeEdActive || g_edDragStartRow < 0) return false;
    std::vector<CRow> rows; code_rows_build(rows);
    if (i < 0 || i >= (int)rows.size() || rows[i].hidden) return false;
    // 拖选起止规范化：跳过隐藏行（零高度行），保证起点/终点落在真实可见行
    int a = g_edDragStartRow, b = g_edDragCurRow;
    int lo = std::min(a, b), hi = std::max(a, b);
    while (lo <= hi && rows[lo].hidden) ++lo;
    while (hi >= lo && rows[hi].hidden) --hi;
    if (lo >= hi) return false;
    return i >= lo && i <= hi;
}
// 取某装配行的「编辑格」文本（kind=2 语句 / kind=1 数据格），供跨行拖选绘制。
static bool code_ed_line_text(const CRow& r, int& colOut, const wchar_t** txtOut)
{
    if (r.kind == 2) { colOut = 0; *txtOut = r.c[0].c_str(); return true; }
    if (r.kind == 1) { colOut = r.dst == 1 ? 1 : g_codeEdCol;
        if (colOut >= code_col_n(r.tt)) colOut = 0;
        *txtOut = r.c[colOut].c_str(); return true; }
    return false;
}
// 鼠标在 (my) 对应的行上取字符列：复用 code_ed_x_to_caret 的思路，
// 但该行不是编辑行时按「该行文字 + 当前字体」现场量。
static int code_ed_row_x_to_col(HDC dc, const CRow& row, int col, int txBase, int mx)
{
    std::wstring s = row.c[col];
    int lo = 0, hi = (int)s.size();
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        int w = tw(dc, s.substr(0, (size_t)mid), code_ed_font());
        if (txBase + w <= mx) lo = mid; else hi = mid - 1;
    }
    return lo;
}

// 把 (row,col) 格子的编辑文本换成目标行：保持光标列尽量不跳。
static void code_ed_set_target(int row, int col)
{
    std::vector<CRow> rows; code_rows_build(rows);
    if (row < 0 || row >= (int)rows.size()) return;
    const CRow& r = rows[row];
    int c = col;
    if (r.kind == 1) { if (c >= code_col_n(r.tt)) c = 0; }
    else             { c = 0; }
    code_ed_open(row, c);
}
// 跨行移动光标：dir=±1；keepAnchor=false 收起选区。
// 从编辑行出发向上/下，找到下一条「可编辑目标行」（语句行或数据行）。
static void code_ed_move_line(int dir, bool keepAnchor)
{
    std::vector<CRow> rows; code_rows_build(rows);
    if (g_codeEdRow < 0 || rows.empty()) return;
    int x = g_codeEdTextX + code_ed_w(g_codeEdCaret);   // 目标行保持视觉列
    int r = g_codeEdRow + dir;
    while (r >= 0 && r < (int)rows.size()) {
        const CRow& t = rows[r];
        if ((t.kind == 2 && !t.hidden) || t.kind == 1) {
            int col = g_codeEdCol;
            int keepCol = g_codeEdCaret;
            code_ed_commit(true);
            code_ed_open(r, col);
            // 按视觉列对齐：在目标行上找最近的字符边界
            HDC dc = GetDC(g_hwnd);
            if (dc) {
                int want = x;
                int best = 0, bestD = 0x7fffffff;
                for (int k = 0; k <= (int)g_codeEdText.size(); ++k) {
                    int w = tw(dc, g_codeEdText.substr(0, (size_t)k), code_ed_font());
                    int d = abs(g_codeEdTextX + w - want);
                    if (d < bestD) { bestD = d; best = k; }
                }
                ReleaseDC(g_hwnd, dc);
                keepCol = best;
            } else {
                keepCol = std::min(keepCol, (int)g_codeEdText.size());
            }
            g_codeEdCaret = std::max(0, std::min((int)g_codeEdText.size(), keepCol));
            if (!keepAnchor) g_codeEdAnchor = g_codeEdCaret;
            (void)keepAnchor;
            code_ed_changed(false);
            return;
        }
        r += dir;
    }
}

// ── 剪贴板（S1）：跨行复制/剪切/粘贴/多选删除 ───────────────────
static void code_clip_expand(int& rMin, int& rMax, const std::vector<CRow>& rows)
{
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size() || g_eAsms[a].subs.empty()) return;
    const std::vector<EStmt>& body = g_eAsms[a].subs[0].body;
    std::vector<int> endAt = code_flow_block_ranges(body);
    for (int rr = rMin; rr <= rMax && rr < (int)rows.size(); ++rr) {
        const CRow& rw = rows[rr];
        if (rw.kind != 2 || rw.idx < 0 || rw.idx >= (int)body.size()) continue;
        if (endAt[rw.idx] < 0) continue;
        for (int t = rr; t < (int)rows.size(); ++t)
            if (rows[t].kind == 2 && rows[t].idx == endAt[rw.idx]) { if (t > rMax) rMax = t; break; }
    }
}
static bool code_clip_copy_lines(bool toClipboard)
{
    std::vector<CRow> rows; code_rows_build(rows);
    if (rows.empty()) return false;
    int rMin, rMax;
    if (g_codeEdActive && g_edDragStartRow >= 0 && g_edDragCurRow >= 0) {
        rMin = std::min(g_edDragStartRow, g_edDragCurRow);
        rMax = std::max(g_edDragStartRow, g_edDragCurRow);
    } else if (g_codeSelRowStart >= 0 && g_codeSelRowEnd >= 0) {
        rMin = std::min(g_codeSelRowStart, g_codeSelRowEnd);
        rMax = std::max(g_codeSelRowStart, g_codeSelRowEnd);
    } else if (g_codeEdActive) {
        rMin = rMax = g_codeEdRow;
    } else {
        rMin = rMax = g_codeSelRow;
    }
    if (rMin < 0) rMin = 0;
    if (rMax >= (int)rows.size()) rMax = (int)rows.size() - 1;
    code_clip_expand(rMin, rMax, rows);
    std::wstring txt;
    for (int r = rMin; r <= rMax; ++r) {
        const CRow& rw = rows[r];
        if (rw.kind == 0) continue;
        // 语句行剥控制流前导点，但保留行首空格/缩进（和块复制同一口径）
        txt += code_row_plain_text(rw);
        txt += L'\n';
    }
    if (txt.empty()) return false;
    if (toClipboard) {
        if (!OpenClipboard(g_hwnd)) return true;
        EmptyClipboard();
        size_t by = (txt.size() + 1) * sizeof(wchar_t);
        HGLOBAL hg = GlobalAlloc(GMEM_MOVEABLE, by);
        if (hg) { memcpy(GlobalLock(hg), txt.c_str(), by); GlobalUnlock(hg); SetClipboardData(CF_UNICODETEXT, hg); }
        CloseClipboard();
    }
    return true;
}
static void code_clip_delete_selection()
{
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size()) return;
    std::vector<CRow> rows; code_rows_build(rows);
    if (rows.empty()) return;
    int rMin = std::min(g_codeSelRowStart, g_codeSelRowEnd);
    int rMax = std::max(g_codeSelRowStart, g_codeSelRowEnd);
    if (rMin < 0) rMin = 0;
    if (rMax >= (int)rows.size()) rMax = (int)rows.size() - 1;
    code_clip_expand(rMin, rMax, rows);
    code_snap_push(false);
    // 第一遍：块头 → 整块删（remove_block 自带配对尾与隐藏结构）
    ESub& sub = g_eAsms[a].subs[0];
    for (int r = rMax; r >= rMin; --r) {
        const CRow& rw = rows[r];
        if (rw.kind == 2 && rw.idx >= 0 && rw.idx < (int)sub.body.size())
            code_flow_remove_block(sub.body, (size_t)rw.idx);
    }
    // 第二遍：重建行表，按当前行号倒序删剩余单行（非块头的普通行）
    rows.clear(); code_rows_build(rows);
    for (int r = rMax; r >= rMin && r < (int)rows.size(); --r) {
        const CRow& rw = rows[r];
        if (rw.kind == 2 && rw.idx >= 0 && rw.sub >= 0 &&
            rw.sub < (int)g_eAsms[a].subs.size() &&
            rw.idx < (int)g_eAsms[a].subs[rw.sub].body.size()) {
            auto& bb = g_eAsms[a].subs[rw.sub].body;
            bb.erase(bb.begin() + rw.idx);
        }
    }
    if (!g_eAsms[a].subs.empty() && g_eAsms[a].subs[0].body.empty())
        g_eAsms[a].subs[0].body.push_back(EStmt(L"", 0));   // 真机：删空也留一条空语句
    g_codeSelRowStart = g_codeSelRowEnd = -1;
    g_codeSelRow = 0;
    if (g_codeEdActive) code_ed_commit(false);
    code_ed_full_redraw();
}
static void code_clip_cut_lines()
{
    code_clip_copy_lines(true);
    if (g_codeEdActive && g_edDragStartRow >= 0 && g_edDragCurRow >= 0 &&
        g_edDragStartRow != g_edDragCurRow) {
        int rMin = std::min(g_edDragStartRow, g_edDragCurRow);
        int rMax = std::max(g_edDragStartRow, g_edDragCurRow);
        code_ed_commit(false);
        g_codeSelRowStart = rMin; g_codeSelRowEnd = rMax;
        code_clip_delete_selection();
    } else if (g_codeEdActive) {
        // 编辑态单行剪切：整行清空为空语句（等价删行保骨架）
        int a = g_a.docTab - 1;
        std::vector<CRow> rows; code_rows_build(rows);
        if (a >= 0 && g_codeEdRow < (int)rows.size()) {
            const CRow& r = rows[g_codeEdRow];
            if (r.kind == 2 && r.dst == 4 && r.sub >= 0 && r.idx >= 0 &&
                r.sub < (int)g_eAsms[a].subs.size() &&
                r.idx < (int)g_eAsms[a].subs[r.sub].body.size()) {
                code_snap_push(false);
                g_eAsms[a].subs[r.sub].body[r.idx].text = L"";
                g_codeEdText.clear(); g_codeEdCaret = g_codeEdAnchor = 0;
                code_ed_measure(); code_ed_changed();
            }
        }
    } else if (g_codeSelRowStart >= 0 && g_codeSelRowEnd >= 0) {
        code_clip_delete_selection();
    }
}
// 复制「字符选区」（含跨行选择）：右键菜单的「复制」和 Ctrl+C 同口径
static bool code_clip_copy_chars()
{
    if (!g_codeEdActive) return false;
    std::wstring t = code_ed_sel_text();
    if (t.empty()) return false;
    if (!OpenClipboard(g_hwnd)) return false;
    EmptyClipboard();
    size_t by = (t.size() + 1) * sizeof(wchar_t);
    HGLOBAL hg = GlobalAlloc(GMEM_MOVEABLE, by);
    if (hg) {
        memcpy(GlobalLock(hg), t.c_str(), by);
        GlobalUnlock(hg);
        SetClipboardData(CF_UNICODETEXT, hg);
    }
    CloseClipboard();
    return true;
}
static void code_clip_cut_chars()
{
    if (!g_codeEdActive || !code_ed_has_sel()) return;
    std::wstring t = code_ed_sel_text();
    if (t.empty()) return;
    if (OpenClipboard(g_hwnd)) {
        EmptyClipboard();
        size_t by = (t.size() + 1) * sizeof(wchar_t);
        HGLOBAL hg = GlobalAlloc(GMEM_MOVEABLE, by);
        if (hg) { memcpy(GlobalLock(hg), t.c_str(), by); GlobalUnlock(hg); SetClipboardData(CF_UNICODETEXT, hg); }
        CloseClipboard();
    }
    code_snap_push(false);
    code_ed_sel_erase();
    code_ed_changed();
}
static std::wstring code_clip_get_text()
{
    std::wstring out;
    if (!OpenClipboard(g_hwnd)) return out;
    if (IsClipboardFormatAvailable(CF_UNICODETEXT)) {
        HANDLE h = GetClipboardData(CF_UNICODETEXT);
        if (h) {
            const wchar_t* p = (const wchar_t*)GlobalLock(h);
            if (p) { out = p; GlobalUnlock(h); }
        }
    }
    CloseClipboard();
    return out;
}
static void code_clip_paste_into_edit()
{
    if (!g_codeEdActive) return;
    std::wstring t = code_clip_get_text();
    if (t.empty()) return;
    size_t nl = t.find_first_of(L"\r\n");
    if (nl == std::wstring::npos) {
        code_ed_put(t);           // 单行：走打字通道（自动补全同样生效）
        return;
    }
    code_snap_push(false);
    size_t i1 = t.find_first_of(L"\r\n");
    std::wstring first = t.substr(0, i1);
    std::wstring rest = t.substr(i1);
    size_t j = rest.find_first_not_of(L"\r\n");
    rest = (j == std::wstring::npos) ? L"" : rest.substr(j);
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size()) return;
    std::vector<CRow> rows; code_rows_build(rows);
    if (g_codeEdRow >= (int)rows.size()) return;
    const CRow& r = rows[g_codeEdRow];
    if (!(r.kind == 2 && r.dst == 4 && r.sub >= 0 && r.idx >= 0 &&
          r.sub < (int)g_eAsms[a].subs.size() &&
          r.idx < (int)g_eAsms[a].subs[r.sub].body.size())) return;
    ESub& sub = g_eAsms[a].subs[r.sub];
    bool wasDot = !sub.body[r.idx].text.empty() && sub.body[r.idx].text[0] == L'.';
    std::wstring head = g_codeEdText;
    size_t cut = (size_t)std::max(0, std::min(g_codeEdCaret, (int)head.size()));
    std::wstring merged = head.substr(0, cut) + first + head.substr(cut);
    sub.body[r.idx].text = (!merged.empty() && wasDot && merged[0] != L'.') ? L"." + merged : merged;
    std::vector<std::wstring> lines;
    std::wstring cur;
    for (wchar_t ch : rest) {
        if (ch == L'\r' || ch == L'\n') {
            lines.push_back(cur);
            cur.clear();
        } else {
            cur += ch;
        }
    }
    if (!cur.empty() || (!rest.empty() && (rest.back() == L'\r' || rest.back() == L'\n')))
        lines.push_back(cur);
    int at = r.idx + 1;
    for (auto& ln : lines) {
        bool dot = !ln.empty() && ln[0] == L'.';
        sub.body.insert(sub.body.begin() + at, EStmt(dot || !wasDot ? ln : L"." + ln, sub.body[r.idx].indent));
        ++at;
    }
    code_ed_commit(false);
    rows.clear(); code_rows_build(rows);
    for (int k = 0; k < (int)rows.size(); ++k)
        if (rows[k].kind == 2 && rows[k].sub == r.sub && rows[k].idx == r.idx) {
            g_codeSelRow = k; code_ed_open(k, 0);
            int nc = (int)(std::min(g_codeEdText.size(), (size_t)std::min((int)cut + (int)first.size(), 0x7ffffffe)));
            g_codeEdCaret = nc; g_codeEdAnchor = nc;
            break;
        }
    code_ed_full_redraw();
}
static void code_clip_paste_rows() { code_clip_paste_into_edit(); }

// ══════════════════════════════════════════════════════════════════
// 块选区（鼠标在表格上拖出的矩形片区）的复制 / 剪切 / 粘贴
// ══════════════════════════════════════════════════════════════════
static bool code_block_range(int& r0, int& r1, int& c0, int& c1)
{
    if (!g_tblSelOn || g_tblSelARow < 0 || g_tblSelFRow < 0) return false;
    r0 = std::min(g_tblSelARow, g_tblSelFRow);
    r1 = std::max(g_tblSelARow, g_tblSelFRow);
    c0 = std::min(g_tblSelACol, g_tblSelFCol);
    c1 = std::max(g_tblSelACol, g_tblSelFCol);
    return true;
}

static void clip_put_text(const std::wstring& txt)
{
    if (txt.empty() || !OpenClipboard(g_hwnd)) return;
    EmptyClipboard();
    size_t by = (txt.size() + 1) * sizeof(wchar_t);
    HGLOBAL hg = GlobalAlloc(GMEM_MOVEABLE, by);
    if (hg) {
        memcpy(GlobalLock(hg), txt.c_str(), by);
        GlobalUnlock(hg);
        SetClipboardData(CF_UNICODETEXT, hg);
    }
    CloseClipboard();
}

// 块 → 文本：列之间 Tab，行之间 CRLF（粘回 Excel / 易语言都能认）
static bool code_clip_copy_block()
{
    int r0, r1, c0, c1;
    if (!code_block_range(r0, r1, c0, c1)) return false;
    std::vector<CRow> rows; code_rows_build(rows);
    if (rows.empty()) return false;
    if (r0 < 0) r0 = 0;
    if (r1 >= (int)rows.size()) r1 = (int)rows.size() - 1;
    std::wstring out;
    for (int r = r0; r <= r1; ++r) {
        const CRow& rw = rows[r];
        if (rw.kind == 0) continue;                 // 表头不参与
        // 语句行用 code_row_plain_text：剥掉控制流前导点，但**原样保留行首空格/缩进**；
        // 空行也照原样输出（只输出换行），这样复制出来的行结构和表格里一模一样。
        out += code_row_plain_text(rw);
        out += L"\r\n";
    }
    if (out.empty()) return false;
    clip_put_text(out);
    return true;
}

static void code_clip_cut_block()
{
    int r0, r1, c0, c1;
    if (!code_block_range(r0, r1, c0, c1)) return;
    code_clip_copy_block();
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size()) return;
    std::vector<CRow> rows; code_rows_build(rows);
    EAsm& am = g_eAsms[a];
    code_snap_push(false);
    for (int r = r0; r <= r1 && r < (int)rows.size(); ++r) {
        const CRow& rw = rows[r];
        if (rw.kind == 2) {
            if (rw.c[0].empty()) continue;          // 空行本来就没内容
            if (rw.sub >= 0 && rw.sub < (int)am.subs.size() &&
                rw.idx >= 0 && rw.idx < (int)am.subs[rw.sub].body.size())
                am.subs[rw.sub].body[rw.idx].text.clear();
            continue;
        }
        if (rw.kind != 1) continue;
        int n = code_col_n(rw.tt);
        for (int c = 0; c < n; ++c) {              // 整行
            if (code_col_is_check(rw.tt, c) || code_col_is_lock(rw.tt, c)) continue;
            int f = code_col_field(rw.tt, c);
            switch (rw.tt) {
            case TT_ASM:
                if (f == CFD_NAME)        am.name.clear();
                else if (f == CFD_REMARK) am.remark.clear();
                break;
            case TT_ASMVAR:
                if (rw.idx >= 0 && rw.idx < (int)am.vars.size()) {
                    EArg& v = am.vars[rw.idx];
                    if      (f == CFD_NAME)   v.name.clear();
                    else if (f == CFD_TYPE)   v.type.clear();
                    else if (f == CFD_REMARK) v.remark.clear();
                }
                break;
            case TT_SUB:
                if (rw.sub >= 0 && rw.sub < (int)am.subs.size()) {
                    ESub& sb = am.subs[rw.sub];
                    if      (f == CFD_NAME)   sb.name.clear();
                    else if (f == CFD_TYPE)   sb.ret.clear();
                    else if (f == CFD_PKG)    sb.pkg.clear();
                    else if (f == CFD_REMARK) sb.remark.clear();
                }
                break;
            case TT_PARAM:
                if (rw.sub >= 0 && rw.sub < (int)am.subs.size() && rw.idx >= 0 &&
                    rw.idx < (int)am.subs[rw.sub].args.size()) {
                    EArg& v = am.subs[rw.sub].args[rw.idx];
                    if      (f == CFD_NAME)   v.name.clear();
                    else if (f == CFD_TYPE)   v.type.clear();
                    else if (f == CFD_REMARK) v.remark.clear();
                }
                break;
            case TT_VAR:
                if (rw.sub >= 0 && rw.sub < (int)am.subs.size() && rw.idx >= 0 &&
                    rw.idx < (int)am.subs[rw.sub].locals.size()) {
                    EArg& v = am.subs[rw.sub].locals[rw.idx];
                    if      (f == CFD_NAME)   v.name.clear();
                    else if (f == CFD_TYPE)   v.type.clear();
                    else if (f == CFD_REMARK) v.remark.clear();
                }
                break;
            }
        }
    }
    g_tblSelOn = false;
    g_a.form.dirty = true;
    code_ed_full_redraw();
}

// 把一段文本写进某一格（只写可写列）；成功返回 true
static bool code_set_cell_text(EAsm& am, const CRow& rw, int c, const std::wstring& v)
{
    if (rw.kind == 2) {
        if (rw.sub < 0 || rw.sub >= (int)am.subs.size() || rw.idx < 0 ||
            rw.idx >= (int)am.subs[rw.sub].body.size()) return false;
        EStmt& st = am.subs[rw.sub].body[rw.idx];
        bool dot = !st.text.empty() && st.text[0] == L'.';
        st.text = (dot && !v.empty() && v[0] != L'.') ? (L"." + v) : v;
        return true;
    }
    if (rw.kind != 1) return false;
    int n = code_col_n(rw.tt);
    if (c < 0 || c >= n) return false;
    if (code_col_is_check(rw.tt, c) || code_col_is_lock(rw.tt, c)) return false;
    int f = code_col_field(rw.tt, c);
    switch (rw.tt) {
    case TT_ASM:
        if (f == CFD_NAME)        { am.name = v;   return true; }
        if (f == CFD_REMARK)      { am.remark = v; return true; }
        break;
    case TT_ASMVAR:
        if (rw.idx >= 0 && rw.idx < (int)am.vars.size()) {
            EArg& a = am.vars[rw.idx];
            if (f == CFD_NAME)        { a.name = v;   return true; }
            if (f == CFD_TYPE)        { a.type = v;   return true; }
            if (f == CFD_REMARK)      { a.remark = v; return true; }
        }
        break;
    case TT_SUB:
        if (rw.sub >= 0 && rw.sub < (int)am.subs.size()) {
            ESub& sb = am.subs[rw.sub];
            if (f == CFD_NAME)        { sb.name = v;   return true; }
            if (f == CFD_TYPE)        { sb.ret = v;    return true; }
            if (f == CFD_PKG)         { sb.pkg = v;    return true; }
            if (f == CFD_REMARK)      { sb.remark = v; return true; }
        }
        break;
    case TT_PARAM:
        if (rw.sub >= 0 && rw.sub < (int)am.subs.size() && rw.idx >= 0 &&
            rw.idx < (int)am.subs[rw.sub].args.size()) {
            EArg& a = am.subs[rw.sub].args[rw.idx];
            if (f == CFD_NAME)        { a.name = v;   return true; }
            if (f == CFD_TYPE)        { a.type = v;   return true; }
            if (f == CFD_REMARK)      { a.remark = v; return true; }
        }
        break;
    case TT_VAR:
        if (rw.sub >= 0 && rw.sub < (int)am.subs.size() && rw.idx >= 0 &&
            rw.idx < (int)am.subs[rw.sub].locals.size()) {
            EArg& a = am.subs[rw.sub].locals[rw.idx];
            if (f == CFD_NAME)        { a.name = v;   return true; }
            if (f == CFD_TYPE)        { a.type = v;   return true; }
            if (f == CFD_REMARK)      { a.remark = v; return true; }
        }
        break;
    }
    return false;
}

// 剪贴板文本 → 从块左上角（或当前编辑格）开始逐格填
static void code_clip_paste_block()
{
    std::wstring t = code_clip_get_text();
    if (t.empty()) return;
    int r0 = -1, r1 = -1, c0 = 0, c1 = 0;
    bool hasBlock = code_block_range(r0, r1, c0, c1);
    if (!hasBlock) {
        if (!g_codeEdActive) return;
        r0 = g_codeEdRow; c0 = g_codeEdCol;
    } else {
        c0 = 0;                                    // 块选是整行：从第 1 列开始铺
    }
    int a = g_a.docTab - 1;
    if (a < 0 || a >= (int)g_eAsms.size()) return;

    // 拆成行列
    std::vector<std::vector<std::wstring> > grid;
    std::vector<std::wstring> line;
    std::wstring cur;
    for (size_t i = 0; i <= t.size(); ++i) {
        wchar_t ch = (i < t.size()) ? t[i] : L'\n';
        if (ch == L'\r') continue;
        if (ch == L'\t') { line.push_back(cur); cur.clear(); continue; }
        if (ch == L'\n') { line.push_back(cur); cur.clear(); grid.push_back(line); line.clear(); continue; }
        cur += ch;
    }
    if (grid.empty()) return;

    std::vector<CRow> rows; code_rows_build(rows);
    if (rows.empty()) return;
    EAsm& am = g_eAsms[a];
    code_snap_push(false);
    bool any = false;
    for (size_t gi = 0; gi < grid.size(); ++gi) {
        int rr = r0 + (int)gi;
        if (rr < 0 || rr >= (int)rows.size()) break;
        for (size_t cj = 0; cj < grid[gi].size(); ++cj) {
            int cc = c0 + (int)cj;
            if (code_set_cell_text(am, rows[rr], cc, grid[gi][cj])) any = true;
        }
    }
    if (!any) return;
    g_a.form.dirty = true;
    g_tblSelOn = false;
    code_ed_full_redraw();
}


// 单击：选中并直接进入编辑状态，提供丝滑的文本编辑体验
static void code_click(int mx, int my)
{
    // 如果正在编辑，先提交当前的修改，然后继续向下执行，以实现单点切换
    if (g_codeEdActive) { code_ed_commit(true); }
    
    int row, col;
    if (!code_hit(mx, my, row, col)) { 
        g_codeSelRow = -1; 
        return; 
    }
    
    g_codeSelRow = row;
    g_codeSelCol = col;
    
    // 直接进入编辑状态
    code_ed_open(row, col);
    InvalidateRect(g_hwnd, NULL, FALSE);
}

// 双击：进入该格行内编辑，并**选中这一格的全部文字**（可直接 Ctrl+C / 右键复制）。
static void code_dblclick(int mx, int my)
{
    if (g_codeEdActive) code_ed_commit(true);
    int row, col;
    if (!code_hit(mx, my, row, col)) return;
    {
        // 表头：双击也不许选中文本 / 给光标（只是列名标签）
        std::vector<CRow> rows; code_rows_build(rows);
        if (row >= 0 && row < (int)rows.size() && rows[row].kind == 0) return;
    }
    g_codeSelRow = row;
    g_codeSelCol = col;
    code_ed_open(row, col);
    if (g_codeEdActive && !g_codeEdReadOnly) {
        g_codeEdAnchor = 0;
        g_codeEdCaret  = (int)g_codeEdText.size();
        g_codeEdDrag   = false;
        g_edDragStartRow = g_edDragCurRow = -1;
        code_ed_caret_reset();
        code_ed_invalidate();
    } else if (g_codeEdActive) {
        // 只读格（「保 留」列）也允许整格选中，方便复制
        g_codeEdAnchor = 0;
        g_codeEdCaret  = (int)g_codeEdText.size();
        g_codeEdDrag   = false;
        code_ed_invalidate();
    }
}

// 代码页右键菜单：编辑器**任何位置**都能弹（表格、空白、行号栏都行）。
// 右键只负责弹菜单：不改选区、不进编辑 —— 免得「右键顺手把文字选中」。
static bool code_table_context_menu(int mx, int my)
{
    int br0, br1, bc0, bc1;
    bool blk      = code_block_range(br0, br1, bc0, bc1);      // 有块选区（拖选表格）
    bool hasSel   = g_codeEdActive && !code_ed_sel_text().empty();
    bool writable = g_codeEdActive && !g_codeEdReadOnly;      // 「保 留」列只读：只许复制
    bool clipTxt  = IsClipboardFormatAvailable(CF_UNICODETEXT) != FALSE;

    g_codeMenuEn[0] = blk || hasSel;                           // 复制
    g_codeMenuEn[1] = blk || (hasSel && writable);             // 剪切
    g_codeMenuEn[2] = (blk || writable) && clipTxt;            // 粘贴
    g_codeMenuEn[3] = !g_undoStack.empty();                    // 撤销（没有历史时置灰）
    g_codeMenuEn[4] = code_tab_active();                       // 全选（整个代码页）

    g_codeMenuPos   = POINT{ mx, my };                         // 跟随鼠标坐标
    g_codeMenuHot   = -1;
    g_codeMenuOpen  = true;
    code_menu_layout();                                        // 先把命中区算好
    // 菜单开着时停掉行内光标闪烁：那一下会触发「只重绘编辑行」的快路径，
    // 快路径只画表格、不画菜单，会把压在文字上的菜单盖掉（用户看到的就是菜单跑到文字下面）。
    if (g_hwnd) KillTimer(g_hwnd, TIMER_CODE_CARET);
    g_outMenuOpen = false;                                     // 与其它弹层互斥
    g_a.outMenu   = -1;
    if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
    return true;
}

// 关菜单：刷掉菜单占的那块，并把行内光标闪烁恢复回来
static void code_menu_close()
{
    if (!g_codeMenuOpen) return;
    g_codeMenuOpen = false;
    g_codeMenuHot  = -1;
    if (g_hwnd) {
        InvalidateRect(g_hwnd, &g_codeMenuRect, FALSE);
        if (g_codeEdActive) code_ed_caret_reset();
    }
}

// 整个代码页全选：当前程序集页的所有表格行 + 所有语句行，整行高亮。
// 跟「从表头往下拉」用的是同一套块选区，所以空语句行不选中、复制保留空格换行。
// 右键菜单「全选」/ Ctrl+A / 主菜单「全选」都走这里，不再只选鼠标所在那一格。
static void code_select_all_page()
{
    if (!code_tab_active()) { do_action(L"select_all"); return; }
    std::vector<CRow> rows; code_rows_build(rows);
    if (rows.empty()) return;
    if (g_codeEdActive) code_ed_commit(true);      // 先落当前格，别留半截字符选区
    g_codeEdAnchor = g_codeEdCaret = 0;
    g_codeEdDrag   = false;
    g_edDragStartRow = g_edDragCurRow  = -1;
    g_codeSelRowStart = g_codeSelRowEnd = -1;      // 整页统一走块选，不并用行选区
    g_tblSelOn     = true;
    g_tblSelARow   = 0;
    g_tblSelFRow   = (int)rows.size() - 1;
    g_tblSelACol   = 0;
    g_tblSelFCol   = 5;                            // 覆盖最大列数（块选按整行铺色）
    g_tblDragging  = false;
    g_tblPressPend = false;
    if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
}

static void code_menu_select_all()
{
    code_select_all_page();
}

// 执行菜单项（先关菜单，再动作）
static void code_menu_exec(int i)
{
    code_menu_close();
    int br0, br1, bc0, bc1;
    bool blk = code_block_range(br0, br1, bc0, bc1);
    if (i == 0)      { if (blk) code_clip_copy_block();  else code_clip_copy_chars(); }
    else if (i == 1) { if (blk) code_clip_cut_block();   else code_clip_cut_chars(); }
    else if (i == 2) { if (blk) code_clip_paste_block(); else code_clip_paste_into_edit(); }
    else if (i == 3) {                                     // 撤销：与 Ctrl+Z 同一条路
        code_snap_auto();              // 先对齐基线，再落编辑缓冲
        if (g_codeEdActive) code_ed_commit(true);
        if (code_tab_active()) code_undo(); else do_undo();
    }
    else if (i == 4) code_menu_select_all();
    if (g_hwnd) {
        SetFocus(g_hwnd);
        InvalidateRect(g_hwnd, NULL, FALSE);
    }
}

// ── 网点层缓存 ─────────────────────────────────────────────
// 点阵每帧要画 (宽/间距)×(高/间距) 个小方块（880×220 的窗体 8 DIP 间距＝ 3000 多个），
// 拖动时每帧重画这些把小方块是卡顿的主因。这里把整片网点存成位图，参数不变就只贴图。
static HBITMAP g_dotBmp = NULL;
static HDC     g_dotDC  = NULL;
static int     g_dotW = 0, g_dotH = 0;
static int     g_dotKey[7] = { -1, -1, -1, -1, -1, -1, -1 };

static void dot_cache_free()
{
    if (g_dotDC)  { DeleteDC(g_dotDC);      g_dotDC  = NULL; }
    if (g_dotBmp) { DeleteObject(g_dotBmp); g_dotBmp = NULL; }
    g_dotW = g_dotH = 0;
    for (int i = 0; i < 7; ++i) g_dotKey[i] = -1;
}

// 在 (0,0)~(w,h) 里铺点阵，返回位图；参数没变就直接复用
static void dot_layer_build(HDC ref, int w, int h, int gszW, int gszH, float z,
                            float sc, COLORREF surf, COLORREF dotc)
{
    int key[7] = { w, h, gszW, gszH, (int)(z * 100), (int)(sc * 100), (int)surf };
    bool same = (g_dotDC && g_dotW == w && g_dotH == h);
    for (int i = 0; same && i < 7; ++i) if (g_dotKey[i] != key[i]) same = false;
    if (same) return;

    dot_cache_free();
    if (w <= 0 || h <= 0) return;
    g_dotDC  = CreateCompatibleDC(ref);
    g_dotBmp = CreateCompatibleBitmap(ref, w, h);
    if (!g_dotDC || !g_dotBmp) { dot_cache_free(); return; }
    SelectObject(g_dotDC, g_dotBmp);
    for (int i = 0; i < 7; ++i) g_dotKey[i] = key[i];
    g_dotW = w; g_dotH = h;

    RECT all = RECT{ 0, 0, w, h };
    FillRect(g_dotDC, &all, br(surf));
    int stepX = (int)S(gszW * z);
    int stepY = (int)S(gszH * z);
    if (stepX < 3) stepX = 3;
    if (stepY < 3) stepY = 3;
    int dw = (int)S(1.0f);
    if (dw < 1) dw = 1;
    HBRUSH bd = br(dotc);
    for (int py = 0; py < h; py += stepY)
        for (int px = 0; px < w; px += stepX) {
            RECT r = RECT{ px, py, px + dw, py + dw };
            FillRect(g_dotDC, &r, bd);
        }
}


// ── 拖动虚影（跟易语言一样）─────────────────────────────────
// 易语言拖组件时并不实时重画组件，只甩一个虚线框跟着鼠标；松手才真正落位重画。
// 这样每帧只需要"反色画一个矩形"，无论窗体多大都是零成本，甩再快也不掉帧。
static RECT g_ghi   = RECT{ 0, 0, 0, 0 };
static bool g_ghiOn = false;
static bool g_hideDragCtl = false;   // 拖动中不画被拖的组件（只留虚影）
static float g_dragDxf = 0, g_dragDyf = 0;
static std::vector<RECT> g_ghiRects;
static int g_ghiSnapX = -1, g_ghiSnapY = -1;

static void ghost_line(HDC dc, const RECT& r)
{
    int sav = SaveDC(dc);
    SetROP2(dc, R2_NOTXORPEN);                 // 反色：同一个矩形画两次＝擦干净
    int th = (int)(g_snapLineW * g_s + 0.5f); if (th < 1) th = 1;
    HPEN p = CreatePen(PS_DOT, th, g_p.snapLine);
    HGDIOBJ op = SelectObject(dc, p);
    HGDIOBJ ob = SelectObject(dc, GetStockObject(NULL_BRUSH));
    Rectangle(dc, r.left, r.top, r.right, r.bottom);
    SelectObject(dc, ob);
    SelectObject(dc, op);
    DeleteObject(p);
    RestoreDC(dc, sav);
}

// 更新虚影：先擦旧的，再画新的（nr 为空＝只擦）
static void ghost_update(RECT nr)
{
    if (!g_hwnd) return;
    if (g_ghiOn) {
        HDC dc = GetDC(g_hwnd);
        ghost_line(dc, g_ghi);
        ReleaseDC(g_hwnd, dc);
        g_ghiOn = false;
    }
    if (nr.right > nr.left && nr.bottom > nr.top) {
        HDC dc = GetDC(g_hwnd);
        ghost_line(dc, nr);
        ReleaseDC(g_hwnd, dc);
        g_ghi    = nr;
        g_ghiOn  = true;
    }
}

// 专用的屏幕绘制辅助线（异或画法，不闪烁）
static void ghost_snap_line(HDC dc, int x1, int y1, int x2, int y2) {
    int sav = SaveDC(dc);
    SetROP2(dc, R2_NOTXORPEN);
    int th = (int)(g_snapLineW * g_s + 0.5f); if (th < 1) th = 1;
    HPEN p = CreatePen(PS_SOLID, th, g_p.snapLine);
    HGDIOBJ op = SelectObject(dc, p);
    MoveToEx(dc, x1, y1, NULL);
    LineTo(dc, x2, y2);
    SelectObject(dc, op);
    DeleteObject(p);
    RestoreDC(dc, sav);
}

// 终极拖拽更新：多组件、带辅助线、原组件不动
static void ghost_update_with_snap(const std::vector<RECT>& newRects) {
    if (!g_hwnd) return;
    HDC dc = GetDC(g_hwnd);
    
    // 1. 擦除旧的虚影和辅助线
    for (const RECT& r : g_ghiRects) ghost_line(dc, r);
    g_ghiRects.clear();
    g_ghiOn = false;
    
    RECT fr = form_rect();
    float k = g_a.zoom * g_s;
    int top = fr.top + (int)(g_a.form.caption * k + 0.5f);
    int bot = fr.bottom;
    
    if (g_ghiSnapX != -1) { ghost_snap_line(dc, g_ghiSnapX, top, g_ghiSnapX, bot); g_ghiSnapX = -1; }
    if (g_ghiSnapY != -1) { ghost_snap_line(dc, fr.left, g_ghiSnapY, fr.right, g_ghiSnapY); g_ghiSnapY = -1; }

    // 2. 画新的边框虚影
    for (const RECT& r : newRects) {
        if (r.right > r.left && r.bottom > r.top) {
            ghost_line(dc, r);
            g_ghiRects.push_back(r);
        }
    }
    g_ghiOn = !g_ghiRects.empty();

    // 3. 画新的辅助线
    if (g_showSnapLine) {
        if (g_snapXOn) {
            g_ghiSnapX = (int)(g_formX + g_snapX * k + 0.5f);
            if (g_ghiSnapX > fr.left && g_ghiSnapX < fr.right)
                ghost_snap_line(dc, g_ghiSnapX, top, g_ghiSnapX, bot);
            else g_ghiSnapX = -1;
        }
        if (g_snapYOn) {
            g_ghiSnapY = (int)(g_formY + (g_a.form.caption + g_snapY) * k + 0.5f);
            if (g_ghiSnapY > top && g_ghiSnapY < bot)
                ghost_snap_line(dc, fr.left, g_ghiSnapY, fr.right, g_ghiSnapY);
            else g_ghiSnapY = -1;
        }
    }
    ReleaseDC(g_hwnd, dc);
}

// 松手时彻底清理屏幕上的残留
static void ghost_clean_all() {
    if (!g_hwnd) return;
    HDC dc = GetDC(g_hwnd);
    for (const RECT& r : g_ghiRects) ghost_line(dc, r);
    g_ghiRects.clear();
    g_ghiOn = false;
    if (g_ghiSnapX != -1) {
        RECT fr = form_rect();
        int top = fr.top + (int)(g_a.form.caption * g_a.zoom * g_s + 0.5f);
        int bot = fr.bottom;
        ghost_snap_line(dc, g_ghiSnapX, top, g_ghiSnapX, bot);
        g_ghiSnapX = -1;
    }
    if (g_ghiSnapY != -1) {
        RECT fr = form_rect();
        ghost_snap_line(dc, fr.left, g_ghiSnapY, fr.right, g_ghiSnapY);
        g_ghiSnapY = -1;
    }
    ReleaseDC(g_hwnd, dc);
}

// 8 个选中手柄：白底 → accent 描边 → 正中 accent 实心小方块。
// 单选和多选的每个成员都用这一份 —— 多选时每个选中的组件各自带 8 个手柄，
// 不画把大家连在一起的整组大框（那个大框会"吞掉"夹在中间没选中的组件）。
static void sel_handles_draw(HDC dc, RECT r)
{
    int hs = S(6) / 2 + 3;
    int hx[8] = { r.left, RCX(r), r.right, r.left, r.right, r.left, RCX(r), r.right };
    int hy[8] = { r.top, r.top, r.top, RCY(r), RCY(r), r.bottom, r.bottom, r.bottom };
    for (int h = 0; h < 8; ++h) {
        RECT hr;
        hr.left = hx[h] - hs; hr.top = hy[h] - hs;
        hr.right = hx[h] + hs; hr.bottom = hy[h] + hs;
        // 底色跟主题走：原来写死纯白，浅色皮肤下白手柄贴在白窗体上几乎看不见
        fill(dc, hr, g_p.accentSubtle);
        outline_w(dc, hr, g_p.accent, S(1));
        // 白方块正中再点一个实心小方块：白底 → 蓝描边 → 蓝芯。
        // 原来纯白的一块，在浅色窗体和灰画布上远看只是个亮点，八个点
        // 各自为政、也看不出属于哪个选中框；加个蓝芯之后抓手感和归属都清楚了。
        // 芯占外框直径的 6 成：100% 时 12px 框配 6px 芯、3px 白边。
        int ih = (hs * 3) / 5;
        if (ih < 2) ih = 2;
        fill(dc, RECT{ hx[h] - ih, hy[h] - ih, hx[h] + ih, hy[h] + ih }, g_p.accent);
    }
}

// 设计窗口的包裹手柄：画满 8 个点（和组件手柄同款），但只有右中(4)/下中(6)/右下(7)
// 能拖 —— 窗口在画布 0 位置，左边和上边往外拉会超出画布，角只开放右下。
// 不能拖的点用淡色空心画，表示这里不支持，省得用户去试。
static void form_handles_draw(HDC dc, RECT f)
{
    int hs = S(6) / 2 + 3;
    int cx = (f.left + f.right) / 2, cy = (f.top + f.bottom) / 2;
    int off = hs; // 圆心外移，手柄完全在边缘外侧包裹
    int hx[8] = { f.left - off, cx, f.right + off, f.left - off, f.right + off, f.left - off, cx, f.right + off };
    int hy[8] = { f.top - off, f.top - off, f.top - off, cy, cy, f.bottom + off, f.bottom + off, f.bottom + off };
    for (int h = 0; h < 8; ++h) {
        bool on = (h == 4 || h == 6 || h == 7);
        RECT hr = RECT{ hx[h] - hs, hy[h] - hs, hx[h] + hs, hy[h] + hs };
        if (on) {
            fill(dc, hr, g_p.accentSubtle);
            outline_w(dc, hr, g_p.accent, S(1));
            int ih = (hs * 3) / 5; if (ih < 2) ih = 2;
            fill(dc, RECT{ hx[h] - ih, hy[h] - ih, hx[h] + ih, hy[h] + ih }, g_p.accent);
        } else {
            fill(dc, hr, g_p.elevated);
            outline_w(dc, hr, g_p.textFaint, S(1));
        }
    }
}

// 当前拖动的虚影矩形（客户区像素）
static RECT drag_ghost_rect()
{
    if (g_a.drag == DFormResize) return form_rect();
    if (g_a.drag == DMarquee) {
        RECT r = RECT{ g_a.dragCtlFrom.left, g_a.dragCtlFrom.top,
                       g_a.dragCtlFrom.right, g_a.dragCtlFrom.bottom };
        if (r.right < r.left) std::swap(r.left, r.right);
        if (r.bottom < r.top) std::swap(r.top, r.bottom);
        return r;
    }
    return RECT{ 0, 0, 0, 0 };
}



// 控件层（控件 + 悬停 + 选中框 + 窗体边框）。onlySel=true 时只画选中的那几个，
// 拖动时用得上：底图已经贴回来了，只需把正在动的组件补上去。
static void paint_ctl_layer(HDC dc, bool onlySel)
{
    // 裁剪到窗体客户区：超出窗体的组件部分被遮住，拉大窗口后又能看到
    RECT fr = form_rect();
    int capPx = (int)(g_a.form.caption * g_a.zoom * g_s + 0.5f);
    RECT cli = RECT{ fr.left, fr.top + capPx, fr.right, fr.bottom };
    int saved = SaveDC(dc);
    IntersectClipRect(dc, cli.left, cli.top, cli.right, cli.bottom);

    for (size_t i = 0; i < g_a.form.ctl.size(); ++i) {
        const Ctl& c = g_a.form.ctl[i];
        if (!c.visible) continue;
        if (onlySel && !is_sel((int)i)) continue;
        if (!onlySel && g_hideDragCtl && is_sel((int)i)) continue;  // 抓底图时先不画被拖的
        ctl_draw(dc, c, ctl_rect(c));
    }

    if (!onlySel) {
        // 悬停虚线
        if (g_a.hoverCtl >= 0 && g_a.hoverCtl < (int)g_a.form.ctl.size() &&
            !is_sel(g_a.hoverCtl))
            dash_rect(dc, ctl_rect(g_a.form.ctl[g_a.hoverCtl]), g_p.accent, S(1));
    }

    // 选中框 + 8 手柄：单选和多选都用同一套画法 —— 每个选中的组件各画自己的框、
    // 自己的 8 个手柄（多选时不再有把大家连起来的整组大框：那个大框会把夹在
    // 中间、其实没选中的组件一起圈进去，看着就像把人家也选上了）。
    bool skipSel = (!onlySel && g_hideDragCtl);      // 抓底图时不留旧位置的选中框
    if (!skipSel) {
        for (size_t k = 0; k < g_a.sel.size(); ++k) {
            int i = g_a.sel[k];
            if (i < 0 || i >= (int)g_a.form.ctl.size()) continue;
            RECT cr = ctl_rect(g_a.form.ctl[i]);
            // 拖动中画虚线框（易语言设计器同款），静止时画实线框：
            // 虚线框 + accent（跟主题）能明确区分「正在拖」和「只是选中」。
            outline_w(dc, cr, g_p.accent, S(1));
            sel_handles_draw(dc, cr);
        }
    }

    RestoreDC(dc, saved); // 退出组件裁剪，恢复整个画布的 DC

    if (!onlySel) {
        // 窗体边框：先来一圈实描边，没选中控件时再叠一层 accent
        RECT b = form_rect();
        // 跟主题走：原来按 g_theme 二分硬编码，四套自定义皮肤全走错色
        outline(dc, b, mixc(g_p.canvas, g_p.text, 0.45f));
        if (g_a.sel.empty()) {
            // 选中窗口（没选组件）时的蓝框：原来只有 1px，150% 缩放下细得跟
            // 窗体自身的描边分不出来。改成 S(2) 粗，从原位置往外一圈圈加宽
            // （往里加会压住窗体里的标题栏）。
            int bw = S(2); if (bw < 2) bw = 2;
            RECT o = b;
            for (int i = 0; i < bw; ++i) {
                outline(dc, o, g_p.accent);
                InflateRect(&o, 1, 1);
            }
            // 窗口自己的 8 个包裹点（可拖的只有右中/下中/右下）
            form_handles_draw(dc, b);
        }
    }
}

// 虚线矩形：按像素画短杠。不用 PS_DOT 画笔的原因是它在 150% 缩放下
// 只剩几个几乎看不见的点，框选拖起来像没画。任何 DPI 下都用同一套短杠。
static void dash_frame(HDC dc, RECT r, COLORREF c, int dash = 4, int gap = 4, int th = 1)
{
    if (r.right <= r.left || r.bottom <= r.top) return;
    if (dash < 1) dash = 1;
    if (gap  < 1) gap  = 1;
    // 四条边各自按短杠铺满；角上双向补齐，保证四角是实心的，不像断了线
    for (int x = r.left; x < r.right; x += dash + gap) {
        int xe = std::min(x + dash, (int)r.right);
        fill(dc, RECT{ x, r.top, xe, r.top + th }, c);
        fill(dc, RECT{ x, r.bottom - th, xe, r.bottom }, c);
    }
    for (int y = r.top; y < r.bottom; y += dash + gap) {
        int ye = std::min(y + dash, (int)r.bottom);
        fill(dc, RECT{ r.left, y, r.left + th, ye }, c);
        fill(dc, RECT{ r.right - th, y, r.right, ye }, c);
    }
}

// 框选的橡皮筋：只画一圈虚线框（不填充、不带计数标签 —— 框住几个组件，
// 松手后成员上的描边自然看得出来）。
// 画布整画和拖动覆盖层走的都是这一个函数，别在两边各写一份。
//
// 不走 GDI+ 的 alpha 填充：覆盖层画在 SetViewportOrgEx 偏移过的离屏 DC 上，
// GDI+ 不认 viewport 偏移（会画到错误的坐标去），所以这里全用 GDI。
static void marquee_draw(HDC dc, RECT band)
{
    if (band.right <= band.left || band.bottom <= band.top) return;
    int th = S(2); if (th < 1) th = 1;
    dash_frame(dc, band, g_p.accent, S(4), S(3), th);
}

static void paint_canvas(HDC dc)
{
    fill(dc, rcCanvas, g_p.canvas);
    // 画布左右两条竖线：1px 的分隔线不画出来，面板就像粘在一起。
    // rcSplitL / rcSplitR 本来就是拖动热区，拿它当线用正好。
    if (rcSplitL.right > rcSplitL.left) fill(dc, rcSplitL, g_p.split);
    if (rcSplitR.right > rcSplitR.left) fill(dc, rcSplitR, g_p.split);

    // 代码页签激活时，画布区域整个让给表格代码编辑器：
    // 设计器不画，后面的命中/交互也进不来（点击处单独挡了）。
    if (code_tab_active()) {
        paint_code_table(dc);
        return;
    }

    // 窗体/组件允许比画布大（拖到外面继续变大是正常需求），但只能画在画布里面：
    // 不裁的话窗体和组件会盖到右侧组件箱、底部提示面板上，看着像"画布破了"。
    // 裁掉之后超出部分仍在数据里，把画布区拉大（拖分栏、拉窗口）就能重新看到。
    int savedClip = SaveDC(dc);
    IntersectClipRect(dc, rcCanvas.left, rcCanvas.top, rcCanvas.right, rcCanvas.bottom);

    RECT cc = canvas_content();
    float z = g_a.zoom;

    // 上/左两条标尺去掉了：它们只是把画布往里挤 20px，
    // 尺寸信息在右上角浮层里一直有（W × H · 缩放 · 网格），不需要再占地方。
    // 十字准心线挪到函数最后画（要在窗体和组件之上，否则窗体一盖就看不见了）。

    // 窗体阴影：原来是一块近乎纯黑的实心矩形，偏移 4 DIP 后在右侧/底部露出
    // 一整圈黑粗边（浅色主题尤其扎眼）。改成 1 DIP 的柔和灰影，跟着主题走；
    // 窗体本身靠 1px 描边 + 灰画布/白窗体的对比分界。
    RECT f = form_rect();
    RECT sh = f;
    OffsetRect(&sh, S(1), S(1));
    // 跟主题走：暗肤压暗、浅肤压深，四套自定义皮肤不再用错色
    fill(dc, sh, mixc(g_p.canvas, g_uiDark ? RGB(0,0,0) : RGB(255,255,255), 0.22f));

    // 窗体标题条（高 28*zoom）：图标 + 标题 + 系统按钮。
    // 窗体是设计器自绘的模拟窗体（不是支持库里的窗口），标题栏按钮按窗口属性
    // 「控制按钮 / 最大化按钮 / 最小化按钮」显示——和 yc 的设计器一个路子。
    RECT cap = f;
    cap.bottom = cap.top + (int)S(g_a.form.caption * z);
    fill(dc, cap, g_p.formCaption);
    int capH = cap.bottom - cap.top;
    COLORREF capTx = g_uiDark ? RGB(0xFF, 0xFF, 0xFF) : RGB(0x1F, 0x1F, 0x1F);

    // 绘制图标
    std::wstring iconPath = form_prop(L"图标", L"");
    if (!iconPath.empty() && iconPath != L"（无）") {
        static std::wstring lastIconPath;
        static HICON hIcon = NULL;
        if (lastIconPath != iconPath) {
            if (hIcon) { DestroyIcon(hIcon); hIcon = NULL; }
            lastIconPath = iconPath;
            hIcon = (HICON)LoadImageW(NULL, iconPath.c_str(), IMAGE_ICON, S(16), S(16), LR_LOADFROMFILE);
        }
        if (hIcon) {
            int ix = cap.left + S(8);
            int iy = cap.top + (capH - S(16)) / 2;
            DrawIconEx(dc, ix, iy, hIcon, S(16), S(16), 0, NULL, DI_NORMAL);
        }
    }
    
    // 标题为空时不画字，整条标题栏就是空的；属性里填了才显示。

    // 右侧系统按钮：关闭 → 最大化 → 最小化（从左往右排，靠右对齐）
    bool ctrl = form_prop(L"控制按钮", L"真") != L"假";
    bool bMax = ctrl && form_prop(L"最大化按钮", L"真") != L"假";
    bool bMin = ctrl && form_prop(L"最小化按钮", L"真") != L"假";
    POINT mp; mouse_now(&mp);
    int bw = S(34);
    int bx = cap.right;
    if (ctrl && capH >= S(18)) {
        for (int k = 0; k < 3; ++k) {
            bool on = (k == 0) || (k == 1 ? bMax : bMin);
            if (on) {
                RECT br = RECT{ bx - bw, cap.top, bx, cap.bottom };
                int cx = (br.left + br.right) / 2, cy = (br.top + br.bottom) / 2;
                // 悬停热区：鼠标压上去就整块变色。
                // 关闭＝系统同款红底白叉（任何皮肤下都认得出来）；
                // 最大化/最小化＝按标题栏底色亮度提亮/压暗一档 ——
                // 深色皮肤变亮灰、浅色皮肤变深灰，切皮肤一样看得见。
                // 只认本窗口在前台时的悬停，别在别的窗口盖着时也亮。
                bool hot = in(br, mp.x, mp.y) && (g_offscreen || GetActiveWindow() == GetForegroundWindow());
                if (g_offscreen && g_fakeCapHot == k) hot = true;   // 截图自验
                COLORREF glyph = capTx;
                if (hot) {
                    if (k == 0) { fill(dc, br, RGB(0xE8, 0x11, 0x23)); glyph = RGB(0xFF, 0xFF, 0xFF); }
                    else        { fill(dc, br, tint_step(g_p.formCaption, 0.22f)); }
                }
                HGDIOBJ op = SelectObject(dc, pen(glyph));
                if (k == 0) {                       // 关闭 ×
                    MoveToEx(dc, cx - S(4), cy - S(4), NULL);
                    LineTo(dc, cx + S(4), cy + S(4));
                    MoveToEx(dc, cx + S(4), cy - S(4), NULL);
                    LineTo(dc, cx - S(4), cy + S(4));
                } else if (k == 1) {                // 最大化 □
                    HGDIOBJ ob = SelectObject(dc, GetStockObject(NULL_BRUSH));
                    Rectangle(dc, cx - S(4), cy - S(4), cx + S(4), cy + S(4));
                    SelectObject(dc, ob);
                } else {                            // 最小化 —
                    MoveToEx(dc, cx - S(5), cy + S(4), NULL);
                    LineTo(dc, cx + S(5), cy + S(4));
                }
                SelectObject(dc, op);
                bx = br.left;
            }
        }
    }

    if (!g_a.form.title.empty()) {
        RECT capT = cap;
        capT.left  = cap.left + S(8);
        if (!iconPath.empty() && iconPath != L"（无）") {
            capT.left += S(20); // 给图标留出空间
        }
        capT.right = bx - S(4);
        tx(dc, g_a.form.title, capT, capTx, g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    }

    // 客户区
    RECT cl = f;
    cl.top = cap.bottom;
    
    // 1. 读取窗口底色并填充
    std::wstring bgColStr;
    if (g_a.form.props.count(L"底色")) bgColStr = g_a.form.props[L"底色"];
    else if (g_a.form.props.count(L"背景颜色")) bgColStr = g_a.form.props[L"背景颜色"];
    else if (g_propOverride.count(L"底色")) bgColStr = g_propOverride[L"底色"];
    else if (g_propOverride.count(L"背景颜色")) bgColStr = g_propOverride[L"背景颜色"];
    
    COLORREF formBg = build_color(bgColStr);
    if (formBg == CLR_INVALID) formBg = g_p.formSurface;
    fill(dc, cl, formBg);

    // 2. 读取窗口底图并使用 GDI+ 绘制（支持 png/bmp/jpg）
    std::wstring bgPic = form_prop(L"底图", L"");
    bool hasBgPic = false;
    if (!bgPic.empty() && bgPic != L"（无）") {
        Gdiplus::Bitmap* cBmp = get_cached_bitmap(bgPic);
        if (cBmp) {
            Gdiplus::Graphics gfx(dc);
            gfx.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBilinear);
            gfx.SetClip(Gdiplus::Rect(cl.left, cl.top, cl.right - cl.left, cl.bottom - cl.top));
            
            std::wstring modeStr = form_prop(L"底图方式", L"0");
            int mode = 0;
            if (modeStr == L"图片平铺" || modeStr == L"1") mode = 1;
            else if (modeStr == L"居中" || modeStr == L"2") mode = 2;
            else if (modeStr == L"拉伸" || modeStr == L"3") mode = 3;
            
            int bw = cBmp->GetWidth(), bh = cBmp->GetHeight();
            int cw = cl.right - cl.left, ch = cl.bottom - cl.top;
            
            if (mode == 0) { // 居左上
                gfx.DrawImage(cBmp, cl.left, cl.top, bw, bh);
            } else if (mode == 1) { // 平铺
                Gdiplus::TextureBrush brush(cBmp, Gdiplus::WrapModeTile);
                gfx.FillRectangle(&brush, cl.left, cl.top, cw, ch);
            } else if (mode == 2) { // 居中
                int x = cl.left + (cw - bw) / 2;
                int y = cl.top + (ch - bh) / 2;
                gfx.DrawImage(cBmp, x, y, bw, bh);
            } else if (mode == 3) { // 拉伸
                gfx.DrawImage(cBmp, cl.left, cl.top, cw, ch);
            }
            hasBgPic = true; // 底图成功画上去了，标记一下
        }
    }

    // 网点：跟易语言一样只铺点阵（缓存在位图里，每帧只贴图，拖动才不卡）
    // 注意：如果画了底图，绝对不能再画网点，否则 BitBlt 会直接盖死底图！
    if (g_a.form.gridOn && !hasBgPic) {
        int gsz  = (int)g_a.form.grid;
        int gszY = (int)g_a.form.gridY;
        if (gsz  < 2) gsz  = 8;
        if (gszY < 2) gszY = gsz;
        int cwPx = (int)S(g_a.form.cw  * z);
        int chPx = (int)S((g_a.form.ch - g_a.form.caption) * z);
        if (cwPx > 0 && chPx > 0) {
            dot_layer_build(dc, cwPx, chPx, gsz, gszY, z, g_s,
                            formBg, RGB(0xC9, 0xC9, 0xCE));
            if (g_dotDC)
                BitBlt(dc, cl.left, cl.top, cwPx, chPx, g_dotDC, 0, 0, SRCCOPY);
        }
    }

        paint_ctl_layer(dc, false);

    // 框选拖动中的橡皮筋（走整画布重绘的兜底路径时也要能看到框）
    if (g_a.drag == DMarquee) marquee_draw(dc, drag_ghost_rect());


    // 画布右上角的 W × H / 缩放 / 网格 浮层已经挪到文档页签栏右侧，
    // 画布保持干净，也不会再探出边界压住组件箱。

    // 十字准心线：必须画在窗体和组件之后（最上层），否则窗体的白底一盖就没了。
    // 用深一档的虚线色而不是 accent，免得跟选中框、对齐辅助线混在一起。
    // 拖动隐身期间（g_hideDragCtl）不画：拖动起手要抓一张「干净」的底图，
    // 那张底图会被贴一整场，准心线要是画进去就会冻在屏幕上不动。
    if (g_showGuide && !g_hideDragCtl && !g_hideGuide && in(cc, mp.x, mp.y)) {
        int gw = (int)(g_guideW * g_s + 0.5f); if (gw < 1) gw = 1;
        int gx = mp.x - gw / 2;
        int gy = mp.y - gw / 2;
        fill(dc, RECT{ gx, cc.top, gx + gw, cc.bottom }, g_p.guideLine);
        fill(dc, RECT{ cc.left, gy, cc.right, gy + gw }, g_p.guideLine);
    }
    RestoreDC(dc, savedClip);
}

// ══════════════════════════════════════════════════════════════════
// 资源表页：双击程序树的「资源表」跳转到这（易语言就是这个交互——
// 资源默认不摆进树里，双击节点打开表才看得到）。
// 表里列出声音 / 图片资源；没有资源时给默认的两行占位
// （同易语言空项目的资源表：一行「声音...」一行「图片或图片组...」）。
// ══════════════════════════════════════════════════════════════════
static RECT g_resRect  = RECT{ 0, 0, 0, 0 };   // 面板矩形（面板内点击不落到画布）
static RECT g_resClose = RECT{ 0, 0, 0, 0 };   // × 关闭按钮热区

static void paint_res_table(HDC dc)
{
    int w = S(520), h = S(380);
    int x = rcCanvas.left + ((rcCanvas.right - rcCanvas.left) - w) / 2;
    int y = rcCanvas.top  + ((rcCanvas.bottom - rcCanvas.top) - h) / 2;
    RECT pop = RECT{ x, y, x + w, y + h };
    g_resRect = pop;

    // 软阴影（同向导面板：5 层低透明度矩形逐层外扩）
    {
        Graphics g2(dc);
        g2.SetSmoothingMode(SmoothingModeAntiAlias);
        for (int i = 5; i >= 1; --i) {
            RECT sr = pop;
            OffsetRect(&sr, 0, S(i));
            InflateRect(&sr, S(i * 2), S(i * 2));
            SolidBrush sb(Color(26 - i * 4, 0, 0, 0));
            g2.FillRectangle(&sb, Rect(sr.left, sr.top, sr.right - sr.left, sr.bottom - sr.top));
        }
    }
    fillR(dc, pop, 8, g_p.elevated);
    outlineR(dc, pop, 8, g_p.border);

    // 表头：标题行 + × 关闭
    RECT head = RECT{ pop.left, pop.top, pop.right, pop.top + S(34) };
    fillR(dc, head, 8, g_p.panel);          // 顶部圆角，底下会盖回直角
    fill(dc, RECT{ head.left, head.bottom - S(8), head.right, head.bottom }, g_p.panel);
    outlineR(dc, pop, 8, g_p.border);
    hline(dc, head.left, head.right, head.bottom, g_p.borderSoft);
    ico(dc, "tree.field", RECT{ head.left + S(12), head.top + S(9), head.left + S(28), head.top + S(25) });
    tx(dc, L"资源表", RECT{ head.left + S(34), head.top, head.right - S(40), head.bottom },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    {
        RECT cb = RECT{ head.right - S(30), head.top + S(7), head.right - S(10), head.top + S(27) };
        POINT mp; mouse_now(&mp);
        if (in(cb, mp.x, mp.y)) fillR(dc, cb, 4, g_p.hover);
        g_resClose = cb;
        ico(dc, "cmd.close", RECT{ cb.left + S(5), cb.top + S(5), cb.right - S(5), cb.bottom - S(5) });
    }

    // 行清单：资源表页跟易语言一样只给默认两行——一个声音、一个图片或图片组。
    // 具体资源文件不往这里摆。
    struct ResRow { const wchar_t* name; const char* icon; };
    static const ResRow rows[2] = { { L"声音...", "tree.property" },
                                    { L"图片或图片组...", "ctl.picture" } };

    int ry = head.bottom + S(4);
    POINT mp; mouse_now(&mp);
    for (int i = 0; i < 2 && ry + S(26) <= pop.bottom - S(6); ++i) {
        RECT rr = RECT{ pop.left + S(8), ry, pop.right - S(8), ry + S(26) };
        if (in(rr, mp.x, mp.y)) fillR(dc, rr, 3, g_p.hover);
        ico(dc, rows[i].icon, RECT{ rr.left + S(10), ry + S(5), rr.left + S(26), ry + S(21) });
        tx(dc, rows[i].name, RECT{ rr.left + S(32), ry, rr.right - S(8), rr.bottom },
           g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        ry += S(26);
    }
}

// 控件矢量绘制（§5.11 简化矢量）
static COLORREF parse_color_str(const std::wstring& s, COLORREF def) {
    if (s.empty() || s[0] != L'#') return def;
    unsigned int rr = 0, gg = 0, bb = 0;
    if (swscanf_s(s.c_str() + 1, L"%02x%02x%02x", &rr, &gg, &bb) == 3) return RGB(rr, gg, bb);
    return def;
}

static void ctl_draw(HDC dc, const Ctl& c, RECT r);

// 根据组件属性生成字体（隔离全局 UI 设置）
static HFONT get_ctl_font(const Ctl& c, bool forceBold = false) {
    std::wstring face = bp(c.props, L"字体", L"");
    int fsize = bpi(c.props, L"字号", 9);
    bool bold = bpt(c.props, L"字体加粗", false) || forceBold;
    bool undl = bpt(c.props, L"字体下划线", false);
    if (fsize < 6 || fsize > 72) fsize = 9;
    if (!face.empty()) {
        size_t cm = face.find(L',');
        if (cm != std::wstring::npos) {
            int fs = _wtoi(face.c_str() + cm + 1);
            if (fs >= 6 && fs <= 72) fsize = fs;
            face = face.substr(0, cm);
        }
    } else {
        face = L"Microsoft YaHei UI";
    }
    float px = (float)fsize * 4.0f / 3.0f;
    return mkfont(px, bold, face.c_str(), undl);
}

static LPCTSTR get_ctl_cursor(const Ctl& c) {
    std::wstring curStr = bp(c.props, L"鼠标指针", L"");
    if (curStr.empty() || curStr == L"0" || curStr == L"默认型" || curStr == L"标准箭头") return IDC_ARROW;
    if (curStr == L"1" || curStr == L"I型文本" || curStr == L"I 型") return IDC_IBEAM;
    if (curStr == L"2" || curStr == L"等待") return IDC_WAIT;
    if (curStr == L"3" || curStr == L"十字" || curStr == L"十字型") return IDC_CROSS;
    if (curStr == L"4" || curStr == L"手型") return IDC_HAND;
    if (curStr == L"5" || curStr == L"禁止") return IDC_NO;
    if (curStr == L"6" || curStr == L"四向移动") return IDC_SIZEALL;
    if (curStr == L"7" || curStr == L"左右箭头" || curStr == L"水平缩放") return IDC_SIZEWE;
    if (curStr == L"8" || curStr == L"上下箭头" || curStr == L"垂直缩放") return IDC_SIZENS;
    if (curStr == L"9" || curStr == L"斜向缩放1") return IDC_SIZENWSE;
    if (curStr == L"10" || curStr == L"斜向缩放2") return IDC_SIZENESW;
    if (curStr == L"11" || curStr == L"向上箭头") return IDC_UPARROW;
    return IDC_ARROW;
}

static void ctl_draw(HDC dc, const Ctl& c, RECT r)
{
    COLORREF line = RGB(0xAC, 0xAC, 0xB4);
    COLORREF white = RGB(0xFF, 0xFF, 0xFF);
    COLORREF ink = RGB(0x1D, 0x1D, 0x22);

    // ── 统一解析组件自定义属性（底色、文本颜色、边框）──
    // 根据组件类型给不同的默认底色
    COLORREF defBg = white;
    if (KINDS[c.kind].draw == KButton) defBg = RGB(0xE1, 0xE1, 0xE1);
    else if (KINDS[c.kind].draw == KGroup) defBg = g_p.formSurface;
    else if (KINDS[c.kind].draw == KPanel) defBg = RGB(0xF5, 0xF5, 0xF7);
    
    COLORREF cBg = build_color(bp(c.props, L"底色", bp(c.props, L"背景颜色", L"")));
    if (cBg == CLR_INVALID) cBg = defBg;
    
    COLORREF cFg = build_color(bp(c.props, L"文本颜色", bp(c.props, L"前景颜色", L"")));
    if (cFg == CLR_INVALID) cFg = ink;

    // 处理“禁止”属性：禁用状态下文字变灰，背景微暗
    bool isDisabled = bpt(c.props, L"禁止", !c.enabled);
    if (isDisabled) {
        cFg = RGB(0xA0, 0xA0, 0xA0); // 禁用文字灰
        cBg = mixc(cBg, RGB(240, 240, 240), 0.3f); // 背景微灰
    }
    
    // 解析边框属性：如果为 "0" 或 "无边框"，则不画边框
    std::wstring borderStr = bp(c.props, L"边框", L"");
    bool noBorder = (borderStr == L"0" || borderStr == L"无边框");

    // ── 统一解析对齐方式（兼容易语言各种叫法）──
    UINT alignH = DT_CENTER;
    std::wstring hAlign = bp(c.props, L"横向对齐方式", bp(c.props, L"对齐方式", L"1"));
    if (hAlign.find(L"左边") != std::wstring::npos || hAlign == L"0" || hAlign == L"左对齐") alignH = DT_LEFT;
    else if (hAlign.find(L"右边") != std::wstring::npos || hAlign == L"2" || hAlign == L"右对齐") alignH = DT_RIGHT;

    UINT alignV = DT_VCENTER;
    std::wstring vAlign = bp(c.props, L"纵向对齐方式", L"1");
    if (vAlign.find(L"顶边") != std::wstring::npos || vAlign == L"0" || vAlign == L"顶对齐") alignV = DT_TOP;
    else if (vAlign.find(L"底边") != std::wstring::npos || vAlign == L"2" || vAlign == L"底对齐") alignV = DT_BOTTOM;

    UINT dtFormat = alignH | alignV | DT_SINGLELINE | DT_NOPREFIX;

    // 非可视组件（定时器 / 通用对话框 / 数据库…）：易语言在设计器里画成一个
    // 带图标和名称的小方块，这里照做。高度不够时只画图标，不硬挤文字。
    if (KINDS[c.kind].nonvis) {
        fillR(dc, r, 3, RGB(0xF3, 0xF3, 0xF7));
        outlineR(dc, r, 3, RGB(0xB8, 0xB8, 0xC0));
        int ics = S(20);
        int ix = RCX(r), top = r.top + S(4);
        HFONT hf = get_ctl_font(c);
        if (top + ics + S(14) <= r.bottom) {
            RECT ir = RECT{ ix - ics / 2, top, ix + ics / 2, top + ics };
            ico_raw(dc, KINDS[c.kind].icon, ir);
            RECT nr = RECT{ r.left + 2, ir.bottom + S(1), r.right - 2, r.bottom };
            tx(dc, KINDS[c.kind].name, nr, RGB(0x5A, 0x5A, 0x64), hf,
               DT_CENTER | DT_TOP | DT_SINGLELINE);
            DeleteObject(hf);
        } else {
            RECT ir = RECT{ ix - ics / 2, RCY(r) - ics / 2, ix + ics / 2, RCY(r) + ics / 2 };
            ico_raw(dc, KINDS[c.kind].icon, ir);
            DeleteObject(hf);
        }
        return;
    }
    HFONT hf = get_ctl_font(c);
    HFONT hfb = get_ctl_font(c, true);

    switch (KINDS[c.kind].draw) {
    case KButton: {
        fillR(dc, r, noBorder ? 0 : 3, cBg);
        if (!noBorder) {
            // 经典 3D 凸起效果：左上亮，右下暗
            hline(dc, r.left, r.right - 1, r.top, RGB(255, 255, 255));
            vline(dc, r.left, r.top, r.bottom - 1, RGB(255, 255, 255));
            hline(dc, r.left, r.right - 1, r.bottom - 1, RGB(128, 128, 128));
            vline(dc, r.right - 1, r.top, r.bottom - 1, RGB(128, 128, 128));
            // 外圈再套一圈普通边框
            outlineR(dc, r, 3, line);
        }
        tx(dc, c.caption, r, cFg, hf, dtFormat);
        break;
    }
    case KText: {
        fill(dc, r, cBg);
        if (!noBorder) {
            // 经典 3D 凹陷效果：左上暗，右下亮
            hline(dc, r.left, r.right - 1, r.top, RGB(128, 128, 128));
            vline(dc, r.left, r.top, r.bottom - 1, RGB(128, 128, 128));
            hline(dc, r.left, r.right - 1, r.bottom - 1, RGB(255, 255, 255));
            vline(dc, r.right - 1, r.top, r.bottom - 1, RGB(255, 255, 255));
            outline(dc, r, line);
        }
        RECT t = r; t.left += S(4);
        std::wstring s = c.caption.empty() ? L"" : c.caption;
        // 编辑框默认靠左，但如果设置了对齐方式，就按属性走
        UINT edtFmt = DT_LEFT | DT_VCENTER | DT_SINGLELINE;
        if (alignH != DT_LEFT) edtFmt = dtFormat; 
        tx(dc, s, t, cFg, hf, edtFmt);
        break;
    }
    case KLabel: {
        if (cBg != white) fill(dc, r, cBg); // 标签通常无背景，但如果填了底色就画
        tx(dc, c.caption, r, cFg, hf, dtFormat);
        break;
    }
    case KGroup: {
        outline(dc, r, line);
        RECT t = R((float)(r.left + S(8)) / g_s, (float)(r.top - S(6)) / g_s, 80, 14);
        fill(dc, t, g_p.formSurface);
        tx(dc, c.caption, t, ink, hf, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        break;
    }
    case KCheck: {
        RECT b = R((float)(r.left + S(2)) / g_s, (float)(RCY(r) - S(6)) / g_s, 13, 13);
        fill(dc, b, white);
        outline(dc, b, line);
        HGDIOBJ op = SelectObject(dc, pen(ink));
        MoveToEx(dc, b.left + S(3), RCY(b), NULL);
        LineTo(dc, b.left + S(6), b.bottom - S(4));
        LineTo(dc, b.right - S(3), b.top + S(3));
        SelectObject(dc, op);
        RECT t = r; t.left = b.right + S(6);
        tx(dc, c.caption, t, cFg, hf, dtFormat);
        break;
    }
    case KRadio: {
        int rad = S(6);
        HGDIOBJ ob = SelectObject(dc, br(white));
        HGDIOBJ op = SelectObject(dc, pen(line));
        Ellipse(dc, r.left + S(2), RCY(r) - rad, r.left + S(2) + rad * 2, RCY(r) + rad);
        SelectObject(dc, op);
        SelectObject(dc, ob);
        RECT t = r; t.left = r.left + S(20);
        tx(dc, c.caption, t, cFg, hf, dtFormat);
        break;
    }
    case KListBox:
    case KList:
    case KListView:
    case KTree:
    case KGrid: {
        fill(dc, r, cBg);
        outline(dc, r, line);
        int rowH = S(18);
        int y = r.top;
        const wchar_t* items[4] = { L"项目一", L"项目二", L"项目三", L"项目四" };
        for (int i = 0; i < 4 && y + rowH <= r.bottom; ++i) {
            if (i == 1) fill(dc, RECT{ r.left + 1, y, r.right - 1, y + rowH }, g_p.accentSubtle);
            if (KINDS[c.kind].draw == KGrid || KINDS[c.kind].draw == KList) {
                hline(dc, r.left + 1, r.right - 1, y + rowH, RGB(0xE6, 0xE6, 0xE8));
                vline(dc, r.left + S(72), y, y + rowH, RGB(0xE6, 0xE6, 0xE8));
            }
            if (KINDS[c.kind].draw == KTree) {
                int ind = S(10 + i * 10);
                vline(dc, r.left + ind - S(4), y + rowH / 2 - S(3), y + rowH / 2 + S(3), line);
                hline(dc, r.left + ind - S(4), r.left + ind, y + rowH / 2, line);
            }
            tx(dc, items[i], RECT{ r.left + (KINDS[c.kind].draw == KTree ? S(16 + i * 10) : S(6)), y,
                                   r.right - S(8), y + rowH },
               ink, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
            y += rowH;
        }
        break;
    }
    case KCombo: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        RECT b = r; b.left = b.right - S(18);
        fill(dc, b, RGB(0xE8, 0xE8, 0xEA));
        if (!noBorder) vline(dc, b.left, b.top, b.bottom, line);
        HGDIOBJ op = SelectObject(dc, pen(cFg));
        int ax = RCX(b), ay = RCY(r);
        MoveToEx(dc, ax - S(4), ay - S(2), NULL); LineTo(dc, ax, ay + S(3)); LineTo(dc, ax + S(4), ay - S(2));
        SelectObject(dc, op);
        tx(dc, c.caption, RECT{ r.left + S(4), r.top, r.right - S(20), r.bottom },
           cFg, hf, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        break;
    }
    case KPicture: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        std::wstring picPath = bp(c.props, L"图片", bp(c.props, L"图片路径", L""));
        if (!picPath.empty() && picPath != L"（无）") {
            Gdiplus::Bitmap* bmp = get_cached_bitmap(picPath);
            if (bmp) {
                Gdiplus::Graphics gfx(dc);
                gfx.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic);
                gfx.DrawImage(bmp, Gdiplus::Rect(r.left, r.top, r.right - r.left, r.bottom - r.top));
                break;
            }
        }
        // 没有图片时画个占位叉
        HGDIOBJ op = SelectObject(dc, pen(RGB(0xC8, 0xC8, 0xCC)));
        MoveToEx(dc, r.left + 1, r.top + 1, NULL); LineTo(dc, r.right - 1, r.bottom - 1);
        MoveToEx(dc, r.right - 1, r.top + 1, NULL); LineTo(dc, r.left + 1, r.bottom - 1);
        SelectObject(dc, op);
        break;
    }
    case KPanel: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        tx(dc, c.caption, RECT{ r.left + S(6), r.top + S(2), r.right, r.top + S(20) },
           cFg, hf, DT_LEFT | DT_TOP | DT_SINGLELINE);
        break;
    }
    case KProgress: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        RECT f2 = r; f2.right = r.left + (int)((r.right - r.left) * 0.4f);
        InflateRect(&f2, -S(1), -S(1));
        fill(dc, f2, RGB(0x3F, 0xB9, 0x50));
        break;
    }
    // 定时器归到非可视组件，统一由上面的 nonvis 分支画，这里不再单独处理
    case KStatusBar: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        if (!noBorder) vline(dc, r.left + S(72), r.top + 1, r.bottom - 1, RGB(0xD8, 0xD8, 0xDE));
        tx(dc, c.caption.empty() ? L"就绪" : c.caption,
           RECT{ r.left + S(6), r.top, r.left + S(70), r.bottom },
           cFg, hf, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        break;
    }
    case KToolBar: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        for (int i = 0; i < 4; ++i) {
            int bx = r.left + S(6) + i * S(26);
            if (bx + S(18) > r.right - S(2)) break;
            RECT b = RECT{ bx, RCY(r) - S(9), bx + S(18), RCY(r) + S(9) };
            fillR(dc, b, 3, RGB(0xE6, 0xE6, 0xEA));
            outlineR(dc, b, 3, RGB(0xD2, 0xD2, 0xD8));
        }
        break;
    }
    case KScrollBar: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        HGDIOBJ op = SelectObject(dc, pen(RGB(0x74, 0x74, 0x7C)));
        MoveToEx(dc, RCX(r) - S(4), r.top + S(8), NULL);
        LineTo(dc, RCX(r), r.top + S(4));
        LineTo(dc, RCX(r) + S(4), r.top + S(8));
        MoveToEx(dc, RCX(r) - S(4), r.bottom - S(8), NULL);
        LineTo(dc, RCX(r), r.bottom - S(4));
        LineTo(dc, RCX(r) + S(4), r.bottom - S(8));
        SelectObject(dc, op);
        RECT th = RECT{ r.left + S(2), r.top + S(22),
                        r.right - S(2), r.top + S(22) + (r.bottom - r.top) / 3 };
        if (th.bottom > r.bottom - S(20)) th.bottom = r.bottom - S(20);
        fillR(dc, th, 3, RGB(0xCE, 0xCE, 0xD6));
        break;
    }
    case KSlider: {
        int t = RCY(r);
        RECT track = RECT{ r.left, t - S(2), r.right, t + S(2) };
        fill(dc, track, RGB(0xE2, 0xE2, 0xE8));
        outline(dc, track, RGB(0xCA, 0xCA, 0xD2));
        int kx = r.left + (r.right - r.left) / 4;
        RECT kh = RECT{ kx - S(5), t - S(8), kx + S(5), t + S(8) };
        fillR(dc, kh, 2, RGB(0xF7, 0xF7, 0xFB));
        outlineR(dc, kh, 2, RGB(0xA6, 0xA6, 0xB0));
        break;
    }
    case KDate: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        RECT b = r; b.left = b.right - S(18);
        fill(dc, b, RGB(0xE8, 0xE8, 0xEB));
        vline(dc, b.left, b.top + 1, b.bottom - 1, line);
        HGDIOBJ op = SelectObject(dc, pen(ink));
        int ax = RCX(b), ay = RCY(r);
        MoveToEx(dc, ax - S(4), ay - S(2), NULL);
        LineTo(dc, ax, ay + S(3));
        LineTo(dc, ax + S(4), ay - S(2));
        SelectObject(dc, op);
        tx(dc, L"2026-11-07", RECT{ r.left + S(5), r.top, b.left - S(2), r.bottom },
           cFg, hf, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        break;
    }
    case KCalendar: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        RECT t = r; t.bottom = t.top + S(22);
        fill(dc, t, RGB(0xEC, 0xEC, 0xEF));
        hline(dc, t.left, t.right, t.bottom - 1, line);
        tx(dc, L"2026 年 11 月", t, cFg, hf, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        int cw = (r.right - r.left) / 7;
        if (cw > 0) {
            const wchar_t* wd[7] = { L"日", L"一", L"二", L"三", L"四", L"五", L"六" };
            for (int i = 0; i < 7; ++i) {
                tx(dc, wd[i], RECT{ r.left + i * cw, t.bottom, r.left + (i + 1) * cw,
                                    t.bottom + S(16) },
                   RGB(0x70, 0x70, 0x7A), g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
            }
            for (int row = 0; row < 5; ++row) {
                int yy = t.bottom + S(18) + row * S(18);
                if (yy + S(14) > r.bottom - S(2)) break;
                for (int col = 0; col < 7; ++col) {
                    RECT q = RECT{ r.left + col * cw + S(5), yy,
                                   r.left + (col + 1) * cw - S(5), yy + S(14) };
                    fill(dc, q, RGB(0xF3, 0xF3, 0xF6));
                }
            }
        }
        break;
    }
    case KRichEdit: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        int y = r.top + S(7);
        for (int i = 0; i < 8 && y + S(3) < r.bottom - S(3); ++i) {
            int w = (r.right - r.left) - S(10) - (i % 3 == 2 ? S(56) : 0);
            hline(dc, r.left + S(5), r.left + w, y, RGB(0xD6, 0xD6, 0xDC));
            y += S(11);
        }
        break;
    }
    case KShapeBtn: {
        fillR(dc, r, noBorder ? 0 : 3, cBg);
        if (!noBorder) outlineR(dc, r, 3, line);
        tx(dc, c.caption.empty() ? L"图形按钮" : c.caption, r, cFg, hf,
           DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        break;
    }
    case KColorPick: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        RECT sw = RECT{ r.left + S(3), r.top + S(3), r.left + S(19), r.bottom - S(3) };
        fill(dc, sw, RGB(0x3A, 0x7B, 0xD5));
        if (!noBorder) outline(dc, sw, RGB(0x90, 0x90, 0x9A));
        tx(dc, L"颜色", RECT{ sw.right + S(5), r.top, r.right - S(16), r.bottom },
           cFg, hf, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        HGDIOBJ op = SelectObject(dc, pen(cFg));
        int ax = r.right - S(9), ay = RCY(r);
        MoveToEx(dc, ax - S(3), ay - S(2), NULL);
        LineTo(dc, ax, ay + S(2));
        LineTo(dc, ax + S(3), ay - S(2));
        SelectObject(dc, op);
        break;
    }
    case KFontPick: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        tx(dc, L"A", RECT{ r.left + S(4), r.top, r.left + S(20), r.bottom },
           cFg, hfb, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        tx(dc, L"宋体 9", RECT{ r.left + S(22), r.top, r.right - S(16), r.bottom },
           cFg, hf, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        HGDIOBJ op = SelectObject(dc, pen(cFg));
        int ax = r.right - S(9), ay = RCY(r);
        MoveToEx(dc, ax - S(3), ay - S(2), NULL);
        LineTo(dc, ax, ay + S(2));
        LineTo(dc, ax + S(3), ay - S(2));
        SelectObject(dc, op);
        break;
    }
    case KAnim: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        HGDIOBJ ob = SelectObject(dc, br(RGB(0x9A, 0x9A, 0xA4)));
        HGDIOBJ op2 = SelectObject(dc, GetStockObject(NULL_PEN));
        POINT pts[3];
        pts[0].x = RCX(r) - S(4); pts[0].y = RCY(r) - S(8);
        pts[1].x = RCX(r) - S(4); pts[1].y = RCY(r) + S(8);
        pts[2].x = RCX(r) + S(8); pts[2].y = RCY(r);
        Polygon(dc, pts, 3);
        SelectObject(dc, op2);
        SelectObject(dc, ob);
        break;
    }
    case KArtBoard: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        HGDIOBJ op = SelectObject(dc, pen(RGB(0xC2, 0xC2, 0xCA)));
        MoveToEx(dc, r.left + S(8), r.bottom - S(8), NULL);
        LineTo(dc, r.left + S(40), RCY(r) - S(10));
        LineTo(dc, r.left + S(66), RCY(r) + S(8));
        LineTo(dc, r.right - S(8), r.top + S(12));
        SelectObject(dc, op);
        break;
    }
    case KTab: {
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        RECT t = r; t.bottom = t.top + S(22);
        fill(dc, t, RGB(0xEC, 0xEC, 0xEE));
        const wchar_t* names[3] = { L"选择夹1", L"选择夹2", L"选择夹3" };
        int x = r.left + S(4);
        for (int i = 0; i < 3; ++i) {
            int w = tw(dc, names[i], hf) + S(16);
            RECT tr2 = RECT{ x, r.top + S(2), x + w, r.top + S(22) };
            if (i == 0) { fill(dc, tr2, RGB(0xF7, 0xF7, 0xF9)); outline(dc, tr2, line); }
            tx(dc, names[i], tr2, ink, hf, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
            x += w;
        }
        break;
    }
    default:
        fill(dc, r, cBg);
        if (!noBorder) outline(dc, r, line);
        break;
    }
    DeleteObject(hf);
    DeleteObject(hfb);
}

// ══════════════════════════════════════════════════════════════════
// 弹出菜单
// ══════════════════════════════════════════════════════════════════

static const int POP_ITEM = 26;
static const int POP_SEP = 9;

static int popup_width(HDC dc, const std::vector<MItem>& items)
{
    int w = 0;
    for (size_t i = 0; i < items.size(); ++i) {
        if (items[i].sep) continue;
        int n = tw(dc, mtext(items[i]), g_f13);
        int s = items[i].sc.empty() ? 0 : tw(dc, items[i].sc, g_f11) + S(28);
        int extra = items[i].kids.empty() ? 0 : S(18);
        w = std::max(w, n + s + extra);
    }
    return w + S(40);
}

static void popup_draw(HDC dc, const std::vector<MItem>& items, int x, int y,
                       int hot, int& outW, int& outH, RECT* outRect)
{
    int w = popup_width(dc, items);
    int h = S(6);
    for (size_t i = 0; i < items.size(); ++i)
        h += items[i].sep ? S(POP_SEP) : S(POP_ITEM);
    h += S(6);

    RECT r = R((float)x / g_s, (float)y / g_s, (float)w / g_s, (float)h / g_s);
    if (r.right > g_w - S(4)) { r.right = g_w - S(4); r.left = r.right - w; }
    if (r.bottom > g_h - S(4)) { r.top = g_h - S(4) - h; r.bottom = g_h - S(4); }

    fill(dc, r, g_p.popup);
    outline(dc, r, g_p.border);

    int iy = r.top + S(6);
    for (size_t i = 0; i < items.size(); ++i) {
        const MItem& m = items[i];
        if (m.sep) {
            hline(dc, r.left + S(12), r.right - S(12), iy + S(POP_SEP) / 2, g_p.borderSoft);
            iy += S(POP_SEP);
            continue;
        }
        RECT ir = RECT{ r.left + S(4), iy, r.right - S(4), iy + S(POP_ITEM) };
        bool on = (hot == (int)i);
        if (on && !m.off) fill(dc, ir, g_p.hover);

        COLORREF fg = m.off ? g_p.textFaint : g_p.text;
        // 勾
        if (!m.chk.empty()) {
            bool cs = chk_state(m.chk);
            if (cs) {
                HGDIOBJ op = SelectObject(dc, pen(g_p.accent));
                int cx = ir.left + S(12), cy = RCY(ir);
                MoveToEx(dc, cx - S(4), cy, NULL);
                LineTo(dc, cx - S(1), cy + S(4));
                LineTo(dc, cx + S(5), cy - S(4));
                SelectObject(dc, op);
            }
        }
        tx(dc, mtext(m), RECT{ ir.left + S(20), ir.top, ir.right - S(60), ir.bottom },
           fg, g_f13, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        if (!m.sc.empty()) {
            tx(dc, m.sc, RECT{ ir.right - S(150), ir.top, ir.right - S(20), ir.bottom },
               m.off ? g_p.textFaint : g_p.textDim, g_f11,
               DT_RIGHT | DT_VCENTER | DT_SINGLELINE);
        }
        if (!m.kids.empty()) {
            HGDIOBJ op = SelectObject(dc, pen(fg));
            int ax = ir.right - S(14), ay = RCY(ir);
            MoveToEx(dc, ax - S(2), ay - S(4), NULL);
            LineTo(dc, ax + S(3), ay);
            LineTo(dc, ax - S(2), ay + S(4));
            SelectObject(dc, op);
        }
        iy += S(POP_ITEM);
    }
    outW = r.right - r.left;
    outH = r.bottom - r.top;
    if (outRect) *outRect = r;
}

static void paint_popups(HDC dc)
{
    if (g_a.menuTop < 0 || g_a.menuTop >= (int)g_menu.size()) return;

    RECT mr = g_menuRects[g_a.menuTop];
    int x = mr.left;
    int y = mr.bottom;
    int w = 0, h = 0;
    popup_draw(dc, g_menu[g_a.menuTop].kids, x, y, g_a.menuHot, w, h, &g_a.popupRect);

    g_a.subRect = RECT{ 0, 0, 0, 0 };
    if (g_a.menuHot >= 0 && g_a.menuHot < (int)g_menu[g_a.menuTop].kids.size()) {
        const MItem& m = g_menu[g_a.menuTop].kids[g_a.menuHot];
        if (!m.kids.empty()) {
            int iy = g_a.popupRect.top + S(6);
            for (int i = 0; i < g_a.menuHot; ++i)
                iy += g_menu[g_a.menuTop].kids[i].sep ? S(POP_SEP) : S(POP_ITEM);
            int w2 = 0, h2 = 0;
            popup_draw(dc, m.kids, g_a.popupRect.right - S(4), iy,
                       g_a.menuSubHot, w2, h2, &g_a.subRect);
        }
    }
}

// ══════════════════════════════════════════════════════════════════
// 提示条
// ══════════════════════════════════════════════════════════════════

static void paint_toast(HDC dc)
{
    if (g_a.toast.empty()) return;
    if (GetTickCount() - g_a.toastAt > g_toastMs) { g_a.toast.clear(); return; }

    // 全用像素算：fillR / tx / tw 收的都是像素矩形。
    // 上一版把像素宽高又除以 g_s 交给 R()（那是 DIP→像素的换算），
    // 结果框和文字各算一套，文字被挤出框外、右边还多出一块黑边。
    std::wstring text = g_a.toast;
    for (size_t i = 0; i < text.size(); ++i) if (text[i] == L'\n') text[i] = L' ';   // 单行

    const int padX = S(16), gap = S(12), h = S(34);
    int w = tw(dc, text, g_f12) + padX * 2 + gap;
    int x = (g_w - w) / 2;
    int y = g_h - h - S(54);

    RECT r = { x, y, x + w, y + h };          // 像素矩形，不再过 R()
    fillR(dc, r, S(9), g_p.elevated);
    outlineR(dc, r, S(9), g_toastErr ? RGB(198, 84, 72) : g_p.split);

    int cx = x + padX, cy = y + h / 2;         // 左侧状态点
    RECT dot = { cx, cy - S(3), cx + S(6), cy + S(3) };
    fillR(dc, dot, S(3), g_toastErr ? RGB(216, 92, 78) : g_p.accent);

    RECT tr = { cx + gap, y, x + w - padX, y + h };
    tx(dc, text, tr, g_p.text, g_f12,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
}

// 工具条按钮的悬停提示：贴在按钮正下方，出右边界就往左挪，出下边界就翻到上方
// 提示条的取用：token < 10000 走工具条按钮表，>= 10000 走独立提示表。
// 两张表分开是因为工具条那张按下会派发动作，提示表只负责显示。
static const TbHit* tip_get(int token)
{
    if (token < 0) return NULL;
    if (token >= 10000) {
        int k = token - 10000;
        return (k < (int)g_tipHits.size()) ? &g_tipHits[k] : NULL;
    }
    return (token < (int)g_tbHits.size()) ? &g_tbHits[token] : NULL;
}

// 属性悬停气泡
static void paint_prop_tip(HDC dc)
{
    if (g_propHoverIdx < 0) return;
    
    std::wstring txt;
    if (!g_propHoverType.empty()) txt += L"数据类型：" + g_propHoverType + L" ";
    if (!g_propHoverDesc.empty()) txt += g_propHoverDesc;
    if (txt.empty()) return;
    
    // 每次动态读取设置里的字体和字号，现场生成，确保“设置”里改完立刻生效
    HFONT tipFont = mkfont((float)g_fontCfg[FNT_UI].size, false, font_face_name(g_fontCfg[FNT_UI].face));
    HGDIOBJ oldFont = SelectObject(dc, tipFont);
    
    // 计算气泡宽高（单行）
    RECT calc = { 0, 0, 0, 0 };
    DrawTextW(dc, txt.c_str(), -1, &calc, DT_CALCRECT | DT_LEFT | DT_SINGLELINE | DT_NOPREFIX);
    
    int w = calc.right + S(24);
    int h = calc.bottom + S(16);
    
    // 计算位置（鼠标下方偏右一点，约半个格子）
    int x = g_propHoverPos.x + S(10);
    int y = g_propHoverPos.y + S(12);
    if (x + w > g_w - S(10)) x = g_propHoverPos.x - w - S(10);
    if (y + h > g_h - S(10)) y = g_propHoverPos.y - h - S(10);
    
    RECT r = { x, y, x + w, y + h };
    // 画阴影和主体
    fillR(dc, RECT{ r.left - S(1), r.top - S(1), r.right + S(1), r.bottom + S(1) }, 5, g_p.frame);
    fillR(dc, r, 4, g_p.elevated);
    outlineR(dc, r, 4, g_p.border);
    
    // 画文字（单行居中，强制高对比度确保清晰可见）
    RECT tr = { r.left + S(12), r.top, r.right - S(12), r.bottom };
    COLORREF tipTextColor = g_uiDark ? RGB(255, 255, 255) : RGB(0x1F, 0x1F, 0x1F);
    tx(dc, txt, tr, tipTextColor, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
    
    SelectObject(dc, oldFont); // 恢复 DC 原字体
    DeleteObject(tipFont);     // 销毁临时字体对象，防 GDI 泄漏
}

static void paint_tooltip(HDC dc)
{
    if (!g_a.tbTipOn) return;
    if (g_a.menuTop >= 0) return;              // 菜单展开时不叠提示
    const TbHit* ph = tip_get(g_a.tbTipIdx);
    if (!ph) return;
    const TbHit& h = *ph;
    if (h.tip.empty()) return;

    RECT a = h.r;
    int w = tw(dc, h.tip, g_f12) + S(22);
    int hh = S(26);
    int x = RCX(a) - w / 2;
    if (x < S(4)) x = S(4);
    if (x + w > g_w - S(4)) x = g_w - S(4) - w;
    int y = a.bottom + S(6);
    if (y + hh > g_h - S(4)) y = a.top - S(6) - hh;

    RECT r = RECT{ x, y, x + w, y + hh };
    // 外面先垫一圈更深的底色当阴影：暗色下 elevated(#2B) 和工具条(#26) 只差
    // 五级，不垫这一圈提示会糊在工具条里看不出边界。
    fillR(dc, RECT{ r.left - S(1), r.top - S(1), r.right + S(1), r.bottom + S(1) },
          6, g_p.frame);
    fillR(dc, r, 5, g_p.elevated);
    outlineR(dc, r, 5, g_p.border);
    tx(dc, h.tip, r, g_p.text, g_f12, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
}

// 日志链接悬停气泡：提示"双击打开所在目录 / 打开链接"
static void paint_log_link_tip(HDC dc)
{
    if (!g_a.showBottom || !g_a.showOutput) return;
    if (g_a.outTab > 1) return;
    if (g_logDragging) return;
    if (g_outListRect.right <= g_outListRect.left) return;
    POINT mp; mouse_now(&mp);
    if (!in(g_outListRect, mp.x, mp.y)) return;
    LogPos p = log_pos_at(mp.x, mp.y);
    if (p.row < 0 || p.row >= (int)g_a.log.size()) return;

    std::wstring target = extract_path_or_url(g_a.log[p.row].text);
    if (target.empty()) return;

    std::wstring tip;
    if (target.compare(0, 7, L"http://") == 0 || target.compare(0, 8, L"https://") == 0 ||
        target.compare(0, 6, L"ftp://") == 0)
        tip = L"双击打开链接";
    else {
        DWORD attr = GetFileAttributesW(target.c_str());
        if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_DIRECTORY))
            tip = L"双击打开目录";
        else
            tip = L"双击打开所在目录";
    }

    int w = tw(dc, tip, g_f12) + S(22);
    int hh = S(26);
    int x = mp.x + S(14);
    if (x + w > g_w - S(4)) x = mp.x - w - S(10);
    int y = mp.y + S(18);
    if (y + hh > g_h - S(4)) y = mp.y - hh - S(12);

    RECT r = RECT{ x, y, x + w, y + hh };
    fillR(dc, RECT{ r.left - S(1), r.top - S(1), r.right + S(1), r.bottom + S(1) }, 6, g_p.frame);
    fillR(dc, r, 5, g_p.elevated);
    outlineR(dc, r, 5, g_p.border);
    tx(dc, tip, r, g_p.text, g_f12, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
}

// ══════════════════════════════════════════════════════════════════
// 设置面板（左侧栏底部齿轮 → 居中弹层）
//   面板里改的是草稿；「应用」只预览（立即生效、不落盘、不关面板），
//   「确定」才应用 + 保存 + 关闭，「取消」/×/ESC 回滚预览。
// ══════════════════════════════════════════════════════════════════

static void font_combo_refilter();
static void settings_pick_image();
static void settings_pick_folder();

// 输入框数字解析：取前导数字，空/非法退回默认值，再夹进范围
static int set_parse_int(const std::wstring& s, int def, int lo, int hi)
{
    std::wstring t;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] >= L'0' && s[i] <= L'9') t += s[i];
        else break;
    }
    if (t.empty()) return std::max(lo, std::min(hi, def));
    int v = _wtoi(t.c_str());
    return std::max(lo, std::min(hi, v));
}

static void settings_open()
{
    font_popups_close();
    g_setInvalid[0] = g_setInvalid[1] = g_setInvalid[2] = g_setInvalid[3] = false;
    g_a.menuTop = -1; g_a.menuSub = -1; g_a.menuHot = -1; g_a.menuSubHot = -1;
    g_outMenuOpen = false; g_a.outMenu = -1;
    g_aiMenu = false; g_eventMenu = false; g_propComboIdx = -1;
    lib_menu_close();
    g_settingsTab = 0;
    for (int g = 0; g < FNT_N; ++g) {
        g_fontBackup[g] = g_fontCfg[g];
        g_fontDraft[g]  = g_fontCfg[g];
    }
    g_themeModeBackup  = g_themeMode;   g_themeModeDraft  = g_themeMode;
    g_themeStyleBackup = g_themeStyle;  g_themeStyleDraft = g_themeStyle;
    comp_load();                       // 编译器设置：ini → 草稿（面板显示用）
    for (int lv = 0; lv < 4; ++lv) g_logColDraft[lv] = g_logCol[lv];
    g_logTimeDraft = g_logTime;
    g_logFmtDraft  = g_logFmt;
    g_tipModeDraft = g_tipMode;
    for (int r2 = 0; r2 < TR_ROLE_N; ++r2) g_tipColDraft[r2] = g_tipCol[r2];
    g_gridColDraft = g_gridCol;
    g_gridWDraft   = g_gridW;
    g_gridStyleDraft = g_gridStyle;
    g_tipFaceDraft = g_tipFace;
    g_tipSizeStrDraft = wnum(g_tipSize);
    g_tipBoldDraft = g_tipBold;
    g_cmdListWDraft  = g_cmdListW > 0 ? 1 : 0;
    {
        wchar_t wb[16] = { 0 };
        if (g_cmdListW > 0) wsprintfW(wb, L"%d", g_cmdListW);
        g_cmdListWStr = wb;
    }
    g_maxBackupCountBackup = g_maxBackupCount;
    g_maxBackupCountDraft  = g_maxBackupCount;
    g_backupAutoSave = g_autoSave;      g_draftAutoSave   = g_autoSave;
    g_backupAutoBackup = g_autoBackup;  g_draftAutoBackup = g_autoBackup;
    g_backupAutoSaveOnRun = g_autoSaveOnRun; g_draftAutoSaveOnRun = g_autoSaveOnRun;
    g_backupAutoBackupOnRun = g_autoBackupOnRun; g_draftAutoBackupOnRun = g_autoBackupOnRun;
    g_backupAutoSaveOnCompile = g_autoSaveOnCompile; g_draftAutoSaveOnCompile = g_autoSaveOnCompile;
    g_backupAutoBackupOnCompile = g_autoBackupOnCompile; g_draftAutoBackupOnCompile = g_autoBackupOnCompile;
    g_backupUseProjNameAsExe = g_useProjNameAsExe; g_draftUseProjNameAsExe = g_useProjNameAsExe;
    g_backupAutoVersion = g_autoVersion; g_draftAutoVersion = g_autoVersion;
    g_backupGuide = g_showGuide;        g_draftGuide      = g_showGuide;
    g_backupSnapLine = g_showSnapLine;  g_draftSnapLine   = g_showSnapLine;
    g_backupSnapLineW = wnum_f(g_snapLineW); g_draftSnapLineW = g_backupSnapLineW;
    g_backupGuideW = wnum_f(g_guideW);       g_draftGuideW = g_backupGuideW;
    g_backupGrid = g_a.form.gridOn;     g_draftGrid       = g_a.form.gridOn;
    g_backupSnap = g_a.form.snap;       g_draftSnap       = g_a.form.snap;
    g_backupToolbar = g_a.showToolbar;  g_draftToolbar    = g_a.showToolbar;
    g_backupStatus = g_a.showStatus;    g_draftStatus     = g_a.showStatus;
    g_backupSaveSec = wnum(g_autoSaveSec);     g_draftSaveSec   = wnum(g_autoSaveSec);
    g_backupBackupSec = wnum(g_autoBackupSec); g_draftBackupSec = wnum(g_autoBackupSec);
    g_backupBgInt = wnum(g_bgRotateSec);       g_draftBgInt     = wnum(g_bgRotateSec);
    g_backupGridSize = wnum((int)g_a.form.grid); g_draftGridSize = wnum((int)g_a.form.grid);
    g_backupGridSizeY = wnum((int)g_a.form.gridY); g_draftGridSizeY = wnum((int)g_a.form.gridY);
    g_backupNewW = wnum(g_newWinW);               g_draftNewW = wnum(g_newWinW);
    g_backupNewH = wnum(g_newWinH);               g_draftNewH = wnum(g_newWinH);
    g_backupBgImage = g_bgImage;    g_draftBgImage  = g_bgImage;
    g_backupBgFolder = g_bgFolder;  g_draftBgFolder = g_bgFolder;
    g_backupBgFill = g_bgFill;      g_draftBgFill   = g_bgFill;
    g_backupBgAlpha = g_bgAlpha;    g_draftBgAlpha  = g_bgAlpha;
    sounds_refresh();               // 重新扫 sounds 文件夹（可能放了新 wav）
    for (int k = 0; k < 3; ++k) {
        g_sndBackup[k] = g_sndName[k];
        g_sndDraft[k]  = g_sndName[k];
    }
    g_sndDD = -1;
    g_setEditFocus = -1;
    g_settingsX = -9999; g_settingsY = -9999; // 每次打开都回到居中默认位
    g_settingsApplied = false;
    g_settingsOpen = true;
}

static void settings_apply(bool save)
{
    font_popups_close();
    set_edit_close();          // 先提交并销毁原生输入框，否则草稿里的值会漏掉
    g_setEditFocus = -1;
    // 必填校验：四个数字框（轮播间隔/保存/备份/网格）空着就不应用，标红提示
    std::wstring* req[4] = { &g_draftBgInt, &g_draftSaveSec, &g_draftBackupSec, &g_draftGridSize };
    bool bad = false;
    for (int i = 0; i < 4; ++i) {
        g_setInvalid[i] = req[i]->empty();
        if (g_setInvalid[i]) bad = true;
    }
    if (bad) {
        if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
        return;                     // 不应用、不保存，原设置保持不动
    }
    for (int g = 0; g < FNT_N; ++g) g_fontCfg[g] = g_fontDraft[g];
    g_themeMode  = g_themeModeDraft;
    g_themeStyle = g_themeStyleDraft;
    g_maxBackupCount = g_maxBackupCountDraft;
    if (g_maxBackupCount < 1) g_maxBackupCount = 1;
    if (g_maxBackupCount > 100) g_maxBackupCount = 100;
    g_autoSave   = g_draftAutoSave;
    g_autoBackup = g_draftAutoBackup;
    g_autoSaveOnRun = g_draftAutoSaveOnRun;
    g_autoBackupOnRun = g_draftAutoBackupOnRun;
    g_autoSaveOnCompile = g_draftAutoSaveOnCompile;
    g_autoBackupOnCompile = g_draftAutoBackupOnCompile;
    g_useProjNameAsExe = g_draftUseProjNameAsExe;
    g_autoVersion      = g_draftAutoVersion;
    g_autoSaveSec = set_parse_int(g_draftSaveSec, g_autoSaveSec, 1, 86400);
    g_autoBackupSec = set_parse_int(g_draftBackupSec, g_autoBackupSec, 1, 86400);
    g_showGuide  = g_draftGuide;
    g_showSnapLine = g_draftSnapLine;
    g_snapLineW = (float)_wtof(g_draftSnapLineW.c_str());
    if (g_snapLineW < 1.0f) g_snapLineW = 1.0f;
    g_guideW = (float)_wtof(g_draftGuideW.c_str());
    if (g_guideW < 1.0f) g_guideW = 1.0f;
    g_draftSnapLineW = wnum_f(g_snapLineW);
    g_draftGuideW = wnum_f(g_guideW);
    g_a.form.gridOn = g_draftGrid;
    g_a.form.snap   = g_draftSnap;
    g_a.form.grid   = (float)set_parse_int(g_draftGridSize,  (int)g_a.form.grid,  2, 64);
    g_a.form.gridY  = (float)set_parse_int(g_draftGridSizeY, (int)g_a.form.gridY, 2, 64);
    g_newWinW = set_parse_int(g_draftNewW, g_newWinW, 120, 4000);
    g_newWinH = set_parse_int(g_draftNewH, g_newWinH, 80, 3000);
    // 立刻写回 ini：网格属于"全局设置"，新建窗口/重启都要沿用
    ui_put(L"grid_size", (int)g_a.form.grid);
    ui_put(L"grid",      g_a.form.gridOn ? 1 : 0);
    ui_put(L"snap",      g_a.form.snap ? 1 : 0);
    g_a.showToolbar = g_draftToolbar;
    g_a.showStatus  = g_draftStatus;
    g_bgImage    = g_draftBgImage;
    g_bgFolder   = g_draftBgFolder;
    g_bgFill     = std::max(0, std::min(2, g_draftBgFill));
    g_bgRotateSec = set_parse_int(g_draftBgInt, g_bgRotateSec, 5, 86400);
    g_bgAlpha    = std::max(0, std::min(100, g_draftBgAlpha));
    g_bgLastRotate = 0;          // 轮播重新计时
    g_bgIdx = 0;
    // 输入框内容规范化成生效值，避免草稿里留着越界数字
    g_draftSaveSec = wnum(g_autoSaveSec);
    g_draftBackupSec = wnum(g_autoBackupSec);
    g_draftBgInt = wnum(g_bgRotateSec);
    g_draftGridSize  = wnum((int)g_a.form.grid);
    g_draftGridSizeY = wnum((int)g_a.form.gridY);
    g_draftNewW = wnum(g_newWinW);
    g_draftNewH = wnum(g_newWinH);
    g_draftBgAlpha = g_bgAlpha;
    for (int k = 0; k < 3; ++k) g_sndName[k] = g_sndDraft[k];   // 提示音选择跟着草稿走
    g_compMode = g_compModeDraft;                               // 编译器设置
    g_compPath = g_compPathDraft;
    g_buildMode = g_buildModeDraft;
    g_buildArch = g_buildArchDraft;
    g_buildOutDir = g_buildOutDirDraft;
    for (int lv = 0; lv < 4; ++lv) g_logCol[lv] = g_logColDraft[lv];
    g_logTime = g_logTimeDraft;
    g_logFmt  = g_logFmtDraft.empty() ? std::wstring(L"H:mm:ss  fff") : g_logFmtDraft;
    g_tipMode = g_tipModeDraft;                       // 提示页：文本 / 表格
    for (int r2 = 0; r2 < TR_ROLE_N; ++r2) g_tipCol[r2] = g_tipColDraft[r2];
    g_gridCol = g_gridColDraft;
    g_gridW   = g_gridWDraft;
    g_gridStyle = g_gridStyleDraft;
    // 表格字体：字号 8~32，字体族空则回落默认；改完立即重建字体（表格尺寸随之变）
    {
        int sz = _wtoi(g_tipSizeStrDraft.c_str());
        if (sz < 8)  sz = 8;
        if (sz > 32) sz = 32;
        g_tipSize = sz;
        g_tipFace = g_tipFaceDraft.empty() ? L"Microsoft YaHei UI" : g_tipFaceDraft;
        g_tipBold = g_tipBoldDraft;
        tip_fonts_build();
    }
    g_cmdListW  = g_cmdListWStr.empty() ? 0 : _wtoi(g_cmdListWStr.c_str());
    theme_refresh();
    fonts_rebuild();
    if (save) {
        ui_save(true);             // 「确定」强制写盘，不受签名比对限制
        g_settingsApplied = false;
        g_settingsOpen = false;
    } else {
        g_settingsApplied = true;
    }
    if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
}

static void settings_cancel();   // 前向声明
static void settings_cancel()
{
    font_popups_close();
    set_edit_close();
    if (g_settingsApplied) {      // 把「应用」过的预览还原成打开面板前的样子
        for (int g = 0; g < FNT_N; ++g) g_fontCfg[g] = g_fontBackup[g];
        g_themeMode  = g_themeModeBackup;
        g_themeStyle = g_themeStyleBackup;
        g_buildMode  = g_buildModeBackup;
        g_buildArch  = g_buildArchBackup;
        g_buildOutDir = g_buildOutDirBackup;
        g_maxBackupCount = g_maxBackupCountBackup;
        g_autoSave   = g_backupAutoSave;
        g_autoBackup = g_backupAutoBackup;
        g_autoSaveOnRun = g_backupAutoSaveOnRun;
        g_autoBackupOnRun = g_backupAutoBackupOnRun;
        g_autoSaveOnCompile = g_backupAutoSaveOnCompile;
        g_autoBackupOnCompile = g_backupAutoBackupOnCompile;
        g_showGuide  = g_backupGuide;
        g_showSnapLine = g_backupSnapLine;
        g_draftSnapLineW = g_backupSnapLineW;
        g_snapLineW = (float)_wtof(g_backupSnapLineW.c_str());
        g_draftGuideW = g_backupGuideW;
        g_guideW = (float)_wtof(g_backupGuideW.c_str());
        g_a.form.gridOn = g_backupGrid;
        g_a.form.snap   = g_backupSnap;
        g_a.form.grid   = (float)set_parse_int(g_backupGridSize, 8, 2, 64);
        g_a.form.gridY  = (float)set_parse_int(g_backupGridSizeY, (int)g_a.form.grid, 2, 64);
        g_newWinW = set_parse_int(g_backupNewW, 880, 120, 4000);
        g_newWinH = set_parse_int(g_backupNewH, 250, 80, 3000);
        g_a.showToolbar = g_backupToolbar;
        g_a.showStatus  = g_backupStatus;
        g_autoSaveSec   = set_parse_int(g_backupSaveSec, 30, 1, 86400);
        g_autoBackupSec = set_parse_int(g_backupBackupSec, 60, 1, 86400);
        g_bgImage  = g_backupBgImage;
        g_bgFolder = g_backupBgFolder;
        g_bgFill   = g_backupBgFill;
        g_bgAlpha  = g_backupBgAlpha;
        g_bgLastRotate = 0;
        g_bgIdx = 0;
        for (int k = 0; k < 3; ++k) g_sndName[k] = g_sndBackup[k];   // 提示音选择一起回滚
        theme_refresh();
        fonts_rebuild();
    }
    g_settingsOpen = false;
    g_settingsApplied = false;
    if (g_hwnd) InvalidateRect(g_hwnd, NULL, FALSE);
}

// 备份目录：程序目录\backup\<项目名>\ —— 固定位置，不看 ini，换机器也能找到
static std::wstring backup_dir_for(const std::wstring& proj)
{
    std::wstring d = exe_dir() + L"\\backup\\" + (proj.empty() ? std::wstring(L"_启动窗口") : proj);
    return d;
}

static void settings_action(int id)
{
    if (id == 4 || id == 5 || id == 6) { g_setBtnDown = id; return; }   // 等弹起
    if (id == 1) { settings_cancel(); return; }   // 标题栏 ×（这个保持按下即关）
    if (id >= 20 && id < 20 + SETTINGS_TABS) { g_settingsTab = id - 20; g_setEditFocus = -1; set_edit_close(); g_tsDD = -1; return; }
        if (id == 800 || id == 801 || id == 802) { 
            POINT pt; GetCursorPos(&pt); ScreenToClient(g_hwnd, &pt);
            g_colorPickerOpen = true; 
            g_colorPickerAnchor = RECT{ pt.x, pt.y, pt.x + S(120), pt.y + S(28) }; 
            g_colorPickerName = (id == 800) ? L"__TAB_LINE__" : (id == 801 ? L"__TAB_BG__" : L"__TAB_HDR__"); 
            return; 
        }
    if (id == 4) { settings_apply(false); return; }          // 应用＝预览
    if (id == 5) { settings_apply(true); return; }           // 确定＝保存
    if (id == 7) {                                          // 恢复默认（仅草稿）
        for (int g = 0; g < FNT_N; ++g) {
            g_fontDraft[g].size  = 12;
            g_fontDraft[g].face  = font_face_index(
                g == FNT_OUTPUT ? DEFAULT_MONO_FACE : DEFAULT_UI_FACE);
            g_fontDraft[g].color = 0;
        }
        g_themeModeDraft  = 0;
        g_themeStyleDraft = g_theme ? 1 : 0;
        g_draftAutoSave = true; g_draftAutoBackup = true;
        g_draftSaveSec = L"30"; g_draftBackupSec = L"60";
        g_draftBgInt = L"300"; g_draftGridSize = L"8";
        g_draftBgImage.clear(); g_draftBgFolder.clear(); g_draftBgAlpha = 20;
        g_draftBgFill = 1;
        g_compModeDraft = 0; g_compPathDraft.clear();   // 编译方式回默认：自动
        g_logTimeDraft = false;                         // 日志回默认：不带时间、标准四色
        g_logFmtDraft  = L"H:mm:ss  fff";
        g_tipModeDraft = 1;                             // 提示表格回默认：表格 + 标准配色
        g_gridColDraft = RGB(0x52, 0x5B, 0x68);
        g_gridWDraft   = 1;
        g_gridStyleDraft = 0;
        g_tipFaceDraft = L"Microsoft YaHei UI";
        g_tipSizeStrDraft = L"12";
        g_tipBoldDraft = false;
        g_cmdListWDraft  = 0; g_cmdListWStr.clear();
        for (int r2 = 0; r2 < TR_ROLE_N; ++r2) g_tipColDraft[r2] = g_tipCol[r2];
        g_logColDraft[0] = RGB( 70, 130, 235);
        g_logColDraft[1] = RGB( 48, 164, 108);
        g_logColDraft[2] = RGB(214, 146,  32);
        g_logColDraft[3] = RGB(228,  74,  74);
        g_draftGuide = false; g_draftSnapLine = false;
        g_draftGrid = true; g_draftSnap = true;
        g_draftGridSizeY = L"8"; g_draftNewW = L"880"; g_draftNewH = L"250";
        g_draftToolbar = true; g_draftStatus = true;
        g_setInvalid[0] = g_setInvalid[1] = g_setInvalid[2] = g_setInvalid[3] = false;
        font_popups_close();
        return;
    }
    // 主题卡片：选一套具体皮肤（明暗由皮肤自己定，跟随系统自动关掉）
    if (id >= 210 && id < 210 + THEME_N) {
        int s = id - 210;
        g_themeStyleDraft = s;
        g_themeModeDraft  = THEME_DARK[s] ? 2 : 1;
        return;
    }
    if (id == 220) {                       // 跟随系统外观
        g_themeModeDraft = 0;
        g_themeStyleDraft = g_theme ? 1 : 0;
        return;
    }
    // 日志页：520＝输出加时间开关；525＝格式下拉；526＝格式输入框；
    //         540..542＝三组预设；530+lv*10+k＝第 lv 级的第 k 个预设色
    if (id == 520) { g_logTimeDraft = !g_logTimeDraft; return; }
    if (id == 525) { g_tsDD = (g_tsDD >= 0) ? -1 : 0; g_setEditFocus = -1; return; }
    // 提示表格页：527 文本 / 528 表格；560+k 表格线色；570+k 线粗；580+role*10+k 文字色
    if (id == 527 || id == 528) { g_tipModeDraft = id - 527; return; }
    if (id >= 560 && id < 568) { g_gridColDraft = LOG_SWATCH[id - 560]; return; }
    if (id == 690) { g_cmdListWDraft = 0; g_cmdListWStr.clear(); return; }
    if (id == 691) { g_setEditFocus = 6; return; }
    if (id >= 570 && id < 573) { g_gridWDraft = id - 569; return; }
    if (id >= 573 && id < 577) { g_gridStyleDraft = id - 573; return; }
    if (id == 578) { g_tipBoldDraft = !g_tipBoldDraft; return; }   // 加粗
    if (id == 579) { set_edit_open(579, g_tipSizeBox, g_tipSizeStrDraft, true); return; }   // 字号：真输入框
    if (id == 580) { set_edit_open(580, g_tipFaceBox, g_tipFaceDraft, false); return; }  // 字体族：真输入框
    if (id >= 588 && id < 588 + 60) {
        int role = (id - 580) / 10, k = (id - 580) % 10;
        if (role >= 1 && role < TR_ROLE_N && k < 8) g_tipColDraft[role] = LOG_SWATCH[k];
        return;
    }
    if (id == 526) { g_setEditFocus = 5; g_tsDD = -1; return; }
    if (id >= 540 && id < 544) {
        g_logFmtDraft = TS_PRESETS[id - 540];
        g_tsDD = -1;
        return;
    }
    if (id >= 530 && id < 530 + 40) {
        int lv = (id - 530) / 10, k = (id - 530) % 10;
        if (lv < 4 && k < 8) g_logColDraft[lv] = LOG_SWATCH[k];
        return;
    }
    // 编译页：0=自动 1=浏览；502＝弹文件对话框选编译器
    if (id == 500 || id == 501) { g_compModeDraft = id - 500; return; }
    if (id == 507) {
        BROWSEINFOW bi = { 0 };
        bi.lpszTitle = L"选择编译输出目录";
        bi.ulFlags = BIF_RETURNONLYFSDIRS | BIF_NEWDIALOGSTYLE;
        LPITEMIDLIST pidl = SHBrowseForFolderW(&bi);
        if (pidl) {
            wchar_t path[MAX_PATH] = { 0 };
            SHGetPathFromIDListW(pidl, path);
            g_buildOutDirDraft = path;
            CoTaskMemFree(pidl);
        }
        return;
    }
    if (id == 502) {
        wchar_t f[1024] = { 0 };
        if (!g_compPathDraft.empty()) lstrcpynW(f, g_compPathDraft.c_str(), 1024);
        OPENFILENAMEW o = { 0 };
        o.lStructSize = sizeof(o);
        o.hwndOwner   = g_hwnd;
        o.lpstrFilter = L"编译器 (clang.exe; g++.exe)\0clang.exe;g++.exe\0所有程序 (*.exe)\0*.exe\0\0";
        o.lpstrFile    = f;
        o.nMaxFile     = 1024;
        o.Flags        = OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST | OFN_NOCHANGEDIR;
        o.lpstrTitle   = L"选择编译器（clang.exe 或 g++.exe）";
        if (GetOpenFileNameW(&o)) {
            g_compPathDraft = f;
            g_compModeDraft = 1;      // 选了文件就切到浏览模式
        }
        return;
    }
    // 各种开关（草稿）
    if (id == 300) { g_draftAutoSave   = !g_draftAutoSave;   return; }
    if (id == 301) { g_draftAutoBackup = !g_draftAutoBackup; return; }
    if (id == 434) { set_edit_open(14, g_numBoxes[14], wnum(g_maxBackupCountDraft), true); return; }
    if (id == 320) { g_draftAutoSaveOnRun = !g_draftAutoSaveOnRun; return; }
    if (id == 321) { g_draftAutoBackupOnRun = !g_draftAutoBackupOnRun; return; }
    if (id == 322) { g_draftAutoSaveOnCompile = !g_draftAutoSaveOnCompile; return; }
    if (id == 323) { g_draftAutoBackupOnCompile = !g_draftAutoBackupOnCompile; return; }
    if (id == 508) { g_draftUseProjNameAsExe = !g_draftUseProjNameAsExe; return; }
    if (id == 509) { g_draftAutoVersion = !g_draftAutoVersion; return; }
    if (id == 302) { g_draftGuide      = !g_draftGuide;      return; }
    if (id == 307) { g_draftSnapLine   = !g_draftSnapLine;   return; }
    if (id == 303) { g_draftGrid       = !g_draftGrid;       return; }
    if (id == 304) { g_draftSnap       = !g_draftSnap;       return; }
    if (id == 305) { g_draftToolbar    = !g_draftToolbar;    return; }
    if (id == 306) { g_draftStatus     = !g_draftStatus;     return; }
    // 数字输入框：点开＝弹原生输入框（弹起才提交）
    if (id >= 404 && id <= 407) {
        int fo = id - 403;
        set_edit_open(fo, g_numBoxes[fo], num_draft(fo) ? *num_draft(fo) : L"", true);
        return;
    }
    if (id == 430 || id == 431 || id == 432 || id == 433 || id == 434) {
        int fo = (id == 430 ? 9 : id == 431 ? 10 : id == 432 ? 11 : id == 433 ? 12 : 13);
        set_edit_open(fo, g_numBoxes[fo], num_draft(fo) ? *num_draft(fo) : L"", true);
        return;
    }
    // 背景：选图 / 选文件夹 / 清除
    if (id == 400) { settings_pick_image(); return; }
    if (id == 401) { settings_pick_folder(); return; }
    if (id == 402) {
        g_draftBgImage.clear();
        g_draftBgFolder.clear();
        return;
    }
    // 背景填充方式：0 拉伸 1 等比铺满 2 等比完整
    if (id >= 410 && id <= 412) { g_draftBgFill = id - 410; return; }
    if (id == 310) {                       // 打开备份目录
        std::wstring d = backup_dir_for(g_projName);
        CreateDirectoryW(d.c_str(), NULL);
        ShellExecuteW(NULL, L"open", d.c_str(), NULL, NULL, SW_SHOWNORMAL);
        return;
    }

    if (id == 311) {                       // 各面板宽度恢复默认
        for (int i = 0; i < 3; ++i) g_leftWPage[i] = 264;
        for (int i = 0; i < 2; ++i) g_rightWPage[i] = 288;
        g_a.bottomH = 200;
        return;
    }
    if (id >= 100 && id < 100 + FNT_N * 10) {
        int g = (id - 100) / 10, k = (id - 100) % 10;
        if (g < 0 || g >= FNT_N) return;
        if (k == 2) {               // 字体族输入框：聚焦并弹出候选列表，敲关键字实时过滤
            g_fontSizeDD = -1; g_fontColDD = -1; g_sndDD = -1;
            g_fontComboGroup = g;
            g_fontComboQuery.clear();
            font_combo_refilter();
            g_fontComboScroll = std::max(0, g_fontDraft[g].face - FONT_COMBO_ROWS / 2);
        }
        else if (k == 4) {          // 字号下拉
            g_fontComboGroup = -1; g_fontComboQuery.clear(); g_fontColDD = -1; g_sndDD = -1;
            g_fontSizeDD = g_fontSizeDD == g ? -1 : g;
        }
        else if (k == 5) {          // 颜色下拉
            g_fontComboGroup = -1; g_fontComboQuery.clear(); g_fontSizeDD = -1; g_sndDD = -1;
            g_fontColDD = g_fontColDD == g ? -1 : g;
        }
    }
    // 提示音：430+k 开下拉，440+k 试听草稿里选的那份
    if (id >= 430 && id <= 432) {
        font_popups_close();
        int k = id - 430;
        g_sndDD = (g_sndDD == k) ? -1 : k;
        return;
    }
    if (id >= 440 && id <= 442) {
        int k = id - 440;
        std::wstring keep = g_sndName[k];
        g_sndName[k] = g_sndDraft[k];
        sound_play(k);
        g_sndName[k] = keep;
        return;
    }
}

static void settings_click(int mx, int my)
{
    // 上一次按了但没等到弹起（例如鼠标移出窗口）：这次按下作废它
    g_setBtnDown = -1;
    g_setPend.kind = -1;
    // 表格字体候选列表：点中直接选、点框本身保持、点别处收起
    if (g_tipFacePopRect.right > g_tipFacePopRect.left) {
        for (size_t i = 0; i < g_tipFaceHits.size(); ++i)
            if (in(g_tipFaceHits[i].first, mx, my)) {
                g_setPend = SetPend{ 5, -1, g_tipFaceHits[i].second, g_tipFaceHits[i].first };
                return;
            }
        if (in(g_tipFaceBox, mx, my)) return;
        g_setEditFocus = -1;
        // 落到列表外面：继续按普通点击处理（可能是别的控件）
    }
    // 声音下拉开着时优先吃掉点击：选一项 / 点外部只关下拉
    if (g_sndDD >= 0 && g_sndDD <= 2) {
        for (size_t i = 0; i < g_sndHits.size(); ++i)
            if (in(g_sndHits[i].first, mx, my)) {
                g_setPend = SetPend{ 1, g_sndDD, g_sndHits[i].second, g_sndHits[i].first };
                return;
            }
        RECT& ed = g_sndBtn[g_sndDD];
        if (ed.right > ed.left && in(ed, mx, my)) return;   // 点按钮本身＝保持开着
        g_sndDD = -1;
        return;
    }
    // 三个字体弹层（候选列表 / 字号 / 颜色）开着时优先吃掉点击：
    // 点中选项直接生效；点弹层外只关弹层，不关设置面板
    if (g_fontComboGroup >= 0) {              // 字体族候选列表
        for (size_t i = 0; i < g_fontComboHits.size(); ++i)
            if (in(g_fontComboHits[i].first, mx, my)) {
                g_setPend = SetPend{ 2, g_fontComboGroup, g_fontComboHits[i].second, g_fontComboHits[i].first };
                return;
            }
        RECT& ed = g_fontFaceBtn[g_fontComboGroup];   // 点输入框＝继续输入，不关
        if (ed.right > ed.left && in(ed, mx, my)) return;
        font_popups_close();
        return;
    }
    if (g_fontSizeDD >= 0) {                  // 字号下拉
        for (size_t i = 0; i < g_fontSizeHits.size(); ++i)
            if (in(g_fontSizeHits[i].first, mx, my)) {
                g_setPend = SetPend{ 3, g_fontSizeDD, g_fontSizeHits[i].second, g_fontSizeHits[i].first };
                return;
            }
        g_fontSizeDD = -1;
        return;
    }
    if (g_fontColDD >= 0) {                   // 颜色下拉：点到哪个色块立即选中
        for (size_t i = 0; i < g_fontColHits.size(); ++i)
            if (in(g_fontColHits[i].first, mx, my)) {
                g_setPend = SetPend{ 4, g_fontColDD, g_fontColHits[i].second, g_fontColHits[i].first };
                return;
            }
        g_fontColDD = -1;
        return;
    }
    for (size_t i = 0; i < g_settingsHits.size(); ++i)
        if (in(g_settingsHits[i].first, mx, my)) {
            int id = g_settingsHits[i].second;
            // 点别的控件先收输入焦点：原生 EDIT 必须真销毁，只清 focus 会让它残留在面板上
            if (id < 404 || id > 407) { g_setEditFocus = -1; set_edit_close(); }
            if (id == 4 || id == 5 || id == 6) g_setBtnDown = id;   // 只是按下视觉
            g_setPend = SetPend{ 0, id, -1, g_settingsHits[i].first };   // 弹起才生效
            return;
        }
    if (!in(g_settingsPanel, mx, my)) settings_cancel();   // 点面板外＝取消
    // 标题栏或面板空白处按住＝拖动移动窗口（× / 控件上面已经提前 return 了）
    g_a.drag = DSetMove;
    g_a.dragFrom = POINT{ mx, my };
    g_settingsX0 = g_settingsPx;           // 拖动期间的位置基准，避免逐帧累加
    g_settingsY0 = g_settingsPy;
    g_settingsX = g_settingsPx / g_s;
    g_settingsY = g_settingsPy / g_s;
}

static void settings_button(HDC dc, RECT r, const wchar_t* s, POINT mp,
                            bool primary, int id)
{
    bool hot = in(r, mp.x, mp.y);
    bool down = (g_setBtnDown == id);        // 按住时压一下，给个反馈
    COLORREF acc = g_p.accent;
    COLORREF accDown = RGB((int)(GetRValue(acc) * 0.78), (int)(GetGValue(acc) * 0.78),
                           (int)(GetBValue(acc) * 0.78));
    fillR(dc, r, 4, primary ? (down ? accDown : acc)
                            : (down ? g_p.input : (hot ? g_p.hover : g_p.elevated)));
    outlineR(dc, r, 4, primary ? g_p.accent : g_p.border);
    tx(dc, s, r, primary ? RGB(255,255,255) : (hot ? g_p.text : g_p.textDim),
       g_f12, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    g_settingsHits.push_back(std::make_pair(r, id));
}

// 复选行：方框 + 文字，整行都可点
static void settings_check(HDC dc, RECT box, const wchar_t* label, bool on,
                           POINT mp, int id)
{
    // 行宽必须把文字整段算进去：以前只加了 tw+10，文字从方框右边再挪 8 起步，
    // 结果最后两个字被裁掉（「显示工具条」只显示成「显示工具」）。
    RECT row = RECT{ box.left - S(4), box.top - S(4),
                     box.right + S(8) + tw(dc, label, g_f12) + S(8), box.bottom + S(4) };
    bool hot = in(row, mp.x, mp.y);
    if (hot) fillR(dc, row, 3, g_p.hover);
    fillR(dc, box, 3, on ? g_p.accent : (hot ? g_p.hover : g_p.input));
    outlineR(dc, box, 3, (on || hot) ? g_p.accent : g_p.border);
    if (on) {
        HPEN op = (HPEN)SelectObject(dc, pen(RGB(255, 255, 255)));
        int x0 = box.left + S(4), y0 = RCY(box);
        MoveToEx(dc, x0, y0, NULL);
        LineTo(dc, x0 + S(3), y0 + S(4));
        LineTo(dc, x0 + S(9), y0 - S(5));
        SelectObject(dc, op);
    }
    tx(dc, label, RECT{ box.right + S(8), box.top - S(4), row.right, box.bottom + S(4) },
       hot ? g_p.text : g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    g_settingsHits.push_back(std::make_pair(row, id));
}

// 界面设置 → 字体：5 个区域各一行，字号 −/+、字体族、字体颜色
static void settings_fonts(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"字体设置", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"分别设置各区域字体；点「应用」预览，「确定」保存",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    int y = b.top + S(52);
    for (int g = 0; g < FNT_N; ++g) {
        tx(dc, FONT_GROUP_NAMES[g], RECT{ b.left, y, b.left + S(140), y + S(22) },
           g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        tx(dc, FONT_GROUP_DESC[g], RECT{ b.left, y + S(22), b.left + S(140), y + S(42) },
           g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

        int x = b.left + S(140), cy = y + S(4), h = S(24);

        // 字体族：页内输入框，点进去敲关键字，候选列表实时跟出来
        RECT face = RECT{ x, cy, x + S(136), cy + h };
        bool foc = (g_fontComboGroup == g);
        bool fhot = foc || in(face, mp.x, mp.y);
        fillR(dc, face, 4, foc ? g_p.elevated : (fhot ? g_p.hover : g_p.input));
        outlineR(dc, face, 4, foc ? g_p.accent : g_p.border);
        if (foc) {   // 聚焦：显示敲进去的关键字（空则占位提示），带光标；输入法组字内容灰色跟着显示
            bool empty = g_fontComboQuery.empty();
            std::wstring shown = empty ? L"输入关键字筛选字体…" : g_fontComboQuery;
            int qw = tw(dc, shown, g_f12);
            tx(dc, shown, RECT{ face.left + S(6), face.top, face.right - S(6), face.bottom },
               empty ? g_p.textFaint : g_p.text, g_f12,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            if (!g_imeComp.empty())   // 组字中的拼音/候选串，灰色显示在关键字后面
                tx(dc, g_imeComp,
                   RECT{ face.left + S(6) + qw + S(2), face.top, face.right - S(6), face.bottom },
                   g_p.textFaint, g_f12,
                   DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            int cw = qw + tw(dc, g_imeComp, g_f12);   // 光标跟在关键字/组字串后面
            int cx = face.left + S(6) + cw + 1;
            if (cx < face.right - S(4))
                vline(dc, cx, face.top + S(4), face.bottom - S(4), g_p.accent);
        } else {     // 没聚焦：显示当前字体名
            tx(dc, font_face_name(g_fontDraft[g].face),
               RECT{ face.left + S(6), face.top, face.right - S(6), face.bottom },
               fhot ? g_p.text : g_p.textDim, g_f12,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        }
        g_settingsHits.push_back(std::make_pair(face, 100 + g * 10 + 2));
        g_fontFaceBtn[g] = face;

        // 字号：下拉按钮，点开选一档
        RECT sizeb = RECT{ face.right + S(6), cy, face.right + S(56), cy + h };
        bool shot2 = in(sizeb, mp.x, mp.y) || g_fontSizeDD == g;
        fillR(dc, sizeb, 4, g_fontSizeDD == g ? g_p.elevated : (shot2 ? g_p.hover : g_p.input));
        outlineR(dc, sizeb, 4, g_fontSizeDD == g ? g_p.accent : g_p.borderSoft);
        tx(dc, wnum(g_fontDraft[g].size),
           RECT{ sizeb.left + S(4), sizeb.top, sizeb.left + S(34), sizeb.bottom },
           g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        tx(dc, L"▾", RECT{ sizeb.left + S(32), sizeb.top, sizeb.right - S(2), sizeb.bottom },
           g_p.textDim, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        g_settingsHits.push_back(std::make_pair(sizeb, 100 + g * 10 + 4));

        // 颜色：下拉按钮，点开色卡点一下就选中
        RECT col = RECT{ sizeb.right + S(6), cy, sizeb.right + S(104), cy + h };
        bool chot = in(col, mp.x, mp.y) || g_fontColDD == g;
        fillR(dc, col, 4, g_fontColDD == g ? g_p.elevated : (chot ? g_p.hover : g_p.input));
        outlineR(dc, col, 4, g_fontColDD == g ? g_p.accent : g_p.borderSoft);
        int ci = g_fontDraft[g].color;
        COLORREF cc = ci ? FONT_COLORS[ci].c : g_p.text;
        RECT sw = RECT{ col.left + S(6), col.top + S(5), col.left + S(18), col.bottom - S(5) };
        fillR(dc, sw, 2, cc);
        outlineR(dc, sw, 2, g_p.border);
        tx(dc, FONT_COLORS[ci].name,
           RECT{ col.left + S(22), col.top, col.right - S(14), col.bottom },
           g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        tx(dc, L"▾", RECT{ col.right - S(14), col.top, col.right - S(2), col.bottom },
           g_p.textDim, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        g_settingsHits.push_back(std::make_pair(col, 100 + g * 10 + 5));

        if (g < FNT_N - 1) hline(dc, b.left, b.right, y + S(48), g_p.borderSoft);
        y += S(54);
    }
}

// 字体名小写化：只处理 ASCII，中文字体名本来就没有大小写
static std::wstring low_ascii(const std::wstring& s)
{
    std::wstring r = s;
    for (size_t i = 0; i < r.size(); ++i)
        if (r[i] >= L'A' && r[i] <= L'Z') r[i] = (wchar_t)(r[i] - L'A' + L'a');
    return r;
}

// 按输入框里的关键字重建候选表（子串匹配，中英文都认）
static void font_combo_refilter()
{
    g_fontComboList.clear();
    std::wstring q = low_ascii(g_fontComboQuery);
    for (int i = 0; i < font_face_count(); ++i) {
        if (q.empty() || low_ascii(g_fontFaces[i]).find(q) != std::wstring::npos)
            g_fontComboList.push_back(i);
    }
    g_fontComboScroll = 0;
}

// 弹层锚定：贴着控件下方展开，放不下就翻上去，最后保证留在面板内
static RECT font_popup_place(RECT anchor, int w, int h)
{
    int px = anchor.left;
    if (px + w > g_settingsPanel.right - S(8)) px = g_settingsPanel.right - S(8) - w;
    if (px < g_settingsPanel.left + S(8)) px = g_settingsPanel.left + S(8);
    int py = anchor.bottom + S(2);
    if (py + h > g_settingsPanel.bottom - S(8)) py = anchor.top - h - S(2);
    if (py < g_settingsPanel.top + S(8)) py = g_settingsPanel.top + S(8);
    return RECT{ px, py, px + w, py + h };
}
static void font_popup_frame(HDC dc, RECT pop)
{
    RECT sh = pop; OffsetRect(&sh, 0, S(3));
    fill(dc, sh, g_p.frame);
    fillR(dc, pop, 5, g_p.elevated);
    outlineR(dc, pop, 5, g_p.accent);
}

// 三个字体弹层：候选列表（页内输入框过滤）/ 字号 / 颜色，同一时间只开一个
static void settings_font_popups(HDC dc, POINT mp)
{
    g_fontComboHits.clear();
    g_fontSizeHits.clear();
    g_fontColHits.clear();
    g_fontComboRect = RECT{ 0, 0, 0, 0 };
    g_fontSizeRect  = RECT{ 0, 0, 0, 0 };
    g_fontColRect   = RECT{ 0, 0, 0, 0 };
    if (!g_settingsOpen) return;

    if (g_fontComboGroup >= 0 && g_fontComboGroup < FNT_N) {   // 字体族候选列表
        int total = (int)g_fontComboList.size();
        int maxTop = std::max(0, total - FONT_COMBO_ROWS);
        if (g_fontComboScroll < 0) g_fontComboScroll = 0;
        if (g_fontComboScroll > maxTop) g_fontComboScroll = maxTop;

        const RECT& anchor = g_fontFaceBtn[g_fontComboGroup];
        int rowH = S(24), w = S(252);
        int ph = S(4) + rowH * FONT_COMBO_ROWS + S(4);
        RECT pop = font_popup_place(anchor, w, ph);
        g_fontComboRect = pop;
        font_popup_frame(dc, pop);

        int y = pop.top + S(4);
        if (total == 0) {
            tx(dc, L"没有匹配的字体", RECT{ pop.left + S(8), y, pop.right - S(8), y + rowH },
               g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        }
        for (int i = 0; i < FONT_COMBO_ROWS; ++i) {
            int pos = g_fontComboScroll + i;
            if (pos >= total) break;
            int idx = g_fontComboList[pos];
            RECT r = RECT{ pop.left + S(4), y, pop.right - S(4), y + rowH };
            bool hot = in(r, mp.x, mp.y);
            bool cur = (g_fontDraft[g_fontComboGroup].face == idx);
            if (cur) fillR(dc, r, 3, g_p.accentSubtle);
            else if (hot) fillR(dc, r, 3, g_p.hover);
            tx(dc, g_fontFaces[idx],
               RECT{ r.left + S(8), r.top, r.right - S(20), r.bottom },
               (cur || hot) ? g_p.text : g_p.textDim, g_f12,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            if (cur)
                tx(dc, L"✓", RECT{ r.right - S(20), r.top, r.right - S(2), r.bottom },
                   g_p.accent, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
            g_fontComboHits.push_back(std::make_pair(r, idx));
            y += rowH;
        }
        if (maxTop > 0 && total > FONT_COMBO_ROWS) {
            int track = rowH * FONT_COMBO_ROWS;
            int thumbH = std::max(S(16), track * FONT_COMBO_ROWS / total);
            int ty = pop.top + S(4) + (track - thumbH) * g_fontComboScroll / maxTop;
            fill(dc, RECT{ pop.right - S(7), ty, pop.right - S(4), ty + thumbH }, g_p.accent);
        }
        return;    // 同一时间只画一个弹层
    }

    if (g_fontSizeDD >= 0 && g_fontSizeDD < FNT_N) {           // 字号下拉
        const RECT& anchor = g_fontFaceBtn[g_fontSizeDD];
        // 锚到该组的字号按钮位置：从输入框右边推出同一坐标
        RECT sizeb = RECT{ anchor.right + S(6), anchor.top,
                           anchor.right + S(56), anchor.bottom };
        int rowH = S(24), w = S(76);
        int ph = S(4) + rowH * FONT_SIZE_N + S(4);
        RECT pop = font_popup_place(sizeb, w, ph);
        g_fontSizeRect = pop;
        font_popup_frame(dc, pop);

        int y = pop.top + S(4);
        int cur = g_fontDraft[g_fontSizeDD].size;
        for (int i = 0; i < FONT_SIZE_N; ++i) {
            RECT r = RECT{ pop.left + S(4), y, pop.right - S(4), y + rowH };
            bool hot = in(r, mp.x, mp.y);
            bool on = (FONT_SIZES[i] == cur);
            if (on) fillR(dc, r, 3, g_p.accentSubtle);
            else if (hot) fillR(dc, r, 3, g_p.hover);
            tx(dc, wnum(FONT_SIZES[i]),
               RECT{ r.left + S(10), r.top, r.right - S(20), r.bottom },
               (on || hot) ? g_p.text : g_p.textDim, g_f12,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE);
            if (on)
                tx(dc, L"✓", RECT{ r.right - S(20), r.top, r.right - S(2), r.bottom },
                   g_p.accent, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
            g_fontSizeHits.push_back(std::make_pair(r, FONT_SIZES[i]));
            y += rowH;
        }
        return;
    }

    if (g_fontColDD >= 0 && g_fontColDD < FNT_N) {             // 颜色下拉：色卡网格
        const RECT& anchor = g_fontFaceBtn[g_fontColDD];
        RECT colb = RECT{ anchor.right + S(62), anchor.top,
                          anchor.right + S(110), anchor.bottom };
        int cell = S(56), gap = S(4), pad = S(6);
        int w = pad * 2 + cell * 3 + gap * 2;
        int h = pad * 2 + cell * 3 + gap * 2;
        RECT pop = font_popup_place(colb, w, h);
        g_fontColRect = pop;
        font_popup_frame(dc, pop);

        int cur = g_fontDraft[g_fontColDD].color;
        for (int i = 0; i < FONT_COLOR_N; ++i) {
            int r = i / 3, c = i % 3;
            RECT rc = RECT{ pop.left + pad + c * (cell + gap),
                            pop.top + pad + r * (cell + gap),
                            pop.left + pad + c * (cell + gap) + cell,
                            pop.top + pad + r * (cell + gap) + cell };
            bool hot = in(rc, mp.x, mp.y);
            bool on = (i == cur);
            if (on) { fillR(dc, rc, 4, g_p.accentSubtle); outlineR(dc, rc, 4, g_p.accent); }
            else { fillR(dc, rc, 4, hot ? g_p.hover : g_p.input); outlineR(dc, rc, 4, g_p.border); }
            COLORREF cc = i ? FONT_COLORS[i].c : g_p.text;   // 0＝跟随主题
            RECT sw = RECT{ rc.left + S(10), rc.top + S(6), rc.right - S(10), rc.top + S(30) };
            fillR(dc, sw, 3, cc);
            outlineR(dc, sw, 3, g_p.border);
            tx(dc, FONT_COLORS[i].name,
               RECT{ rc.left + S(2), rc.top + S(32), rc.right - S(2), rc.bottom - S(2) },
               (on || hot) ? g_p.text : g_p.textDim, g_f11,
               DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            g_fontColHits.push_back(std::make_pair(rc, i));
        }
    }
}

// 主题外观：跟随系统 + 6 套配色卡片（每张卡片直接展示这套色的窗口/面板/强调色）
static void settings_theme(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"主题外观", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"挑一套配色；跟随系统会随 Windows 的浅色/深色自动切换",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    // 跟随系统
    RECT fr = RECT{ b.left, b.top + S(50), b.right, b.top + S(74) };
    settings_check(dc, RECT{ fr.left, fr.top + S(4), fr.left + S(16), fr.top + S(20) },
                   L"跟随系统外观", g_themeModeDraft == 0, mp, 220);

    int top = b.top + S(84);
    int gap = S(10);
    int cw = (b.right - b.left - gap) / 2;
    int chh = S(78);
    for (int i = 0; i < THEME_N; ++i) {
        int col = i % 2, row = i / 2;
        RECT r = RECT{ b.left + col * (cw + gap), top + row * (chh + gap),
                       b.left + col * (cw + gap) + cw, top + row * (chh + gap) + chh };
        const ThemeDef& t = g_themes[i];
        bool on = (g_themeStyleDraft == i && g_themeModeDraft != 0);
        bool hot = in(r, mp.x, mp.y);
        if (on) fillR(dc, r, 6, g_p.accentSubtle);
        else fillR(dc, r, 6, hot ? g_p.hover : g_p.panel);
        outlineR(dc, r, 6, on ? g_p.accent : g_p.border);

        // 三块色卡：窗口底 / 面板 / 强调色。暗色主题上直接铺原色，能一眼看出色调
        RECT s1 = RECT{ r.left + S(10), r.top + S(10), r.left + S(34), r.top + S(34) };
        RECT s2 = RECT{ s1.right + S(4), s1.top, s1.right + S(28), s1.bottom };
        RECT s3 = RECT{ s2.right + S(4), s1.top + S(6), s2.right + S(22), s1.bottom - S(6) };
        fillR(dc, s1, 3, t.custom ? t.window : (t.dark ? RGB(0x1C,0x1C,0x1C) : RGB(0xE8,0xEA,0xED)));
        fillR(dc, s2, 3, t.custom ? t.panel  : (t.dark ? RGB(0x28,0x28,0x28) : RGB(0xF4,0xF5,0xF7)));
        fillR(dc, s3, 3, t.custom ? t.accent : (t.dark ? RGB(0x91,0x84,0xEE) : RGB(0x56,0x49,0xB0)));
        outlineR(dc, s1, 3, g_p.border);
        outlineR(dc, s2, 3, g_p.border);

        tx(dc, t.name, RECT{ s3.right + S(10), r.top + S(8), r.right - S(8), r.top + S(30) },
           g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        tx(dc, t.tip, RECT{ s3.right + S(10), r.top + S(30), r.right - S(8), r.bottom - S(6) },
           g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        g_settingsHits.push_back(std::make_pair(r, 210 + i));
    }
    std::wstring cur = std::wstring(L"当前生效：") + g_themes[g_themeStyle < THEME_N ? g_themeStyle : 0].name +
                       std::wstring(L"（") + THEME_MODE_NAMES[g_themeMode < 3 ? g_themeMode : 0] + L"）";
    tx(dc, cur, RECT{ b.left, b.bottom - S(22), b.right, b.bottom },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
}

// 一行「标签 + 可编辑数字输入框」：点输入框获得焦点，只收数字，应用时生效。
// 框里只放数字，单位（秒 / DIP）画在框外面，免得退格删数字时把单位也带着晕。
static void settings_numrow(HDC dc, RECT b, int y, const wchar_t* label,
                            const std::wstring& val, int focusId,
                            const wchar_t* unit, const wchar_t* hint, POINT mp)
{
    tx(dc, label, RECT{ b.left, y, b.left + S(110), y + S(24) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    RECT box = RECT{ b.left + S(116), y, b.left + S(180), y + S(26) };
    bool act = (g_setEditFocus == focusId);
    bool bad = (focusId >= 1 && focusId <= 4 && g_setInvalid[focusId - 1]);
    bool hot = in(box, mp.x, mp.y);
    fillR(dc, box, 3, act ? g_p.elevated : (hot ? g_p.hover : g_p.input));
    // 标红优先：空着点了应用，红框 + 红字提示，改过内容才消
    outlineR(dc, box, 3, bad ? RGB(0xE8,0x6C,0x6C) : (act ? g_p.accent : g_p.borderSoft));
    bool empty = val.empty();
    if (!empty)
        tx(dc, val, RECT{ box.left + S(8), box.top, box.right - S(8), box.bottom },
           g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    else if (!act)   // 空框（没在输入）：灰色占位提醒要填
        tx(dc, L"必填", RECT{ box.left + S(8), box.top, box.right - S(8), box.bottom },
           bad ? RGB(0xE8,0x6C,0x6C) : g_p.textFaint, g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    if (act) {   // 输入光标（空框时贴在最左）
        int cw = tw(dc, empty ? L"" : val, g_f12);
        int cx = box.left + S(8) + cw + 1;
        if (cx < box.right - S(6))
            vline(dc, cx, box.top + S(4), box.bottom - S(4), g_p.accent);
    }
    // 单位画在框外
    tx(dc, unit, RECT{ box.right + S(6), y, box.right + S(6) + S(40), y + S(24) },
       g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    if (bad)         // 标红时提示被红色「必须输入」顶掉，更醒目
        tx(dc, L"⚠ 必须输入", RECT{ box.right + S(50), y, b.right, y + S(24) },
           RGB(0xE8,0x6C,0x6C), g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    else if (hint && hint[0])
        tx(dc, hint, RECT{ box.right + S(50), y, b.right, y + S(24) },
           g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    // focusId 1..4 → 命中 id 404..407；9/10/11（网点间隔高/新建窗宽高）→ 430..432
    int hitId = 0;
    if (focusId >= 1 && focusId <= 4) hitId = 403 + focusId;
    else if (focusId == 9)  hitId = 430;
    else if (focusId == 10) hitId = 431;
    else if (focusId == 11) hitId = 432;
    else if (focusId == 12) hitId = 433;
    else if (focusId == 13) hitId = 434;
    else if (focusId == 14) hitId = 435;
    if (hitId) g_settingsHits.push_back(std::make_pair(box, hitId));
    g_numBoxes[focusId] = box;
}

// 编辑器：自动保存 / 自动备份，间隔都按秒手填
static void settings_editor(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"编辑器", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"间隔直接在框里填数字（按秒），点「应用」生效",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    int y = b.top + S(56);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"代码自动保存", g_draftAutoSave, mp, 300);
    tx(dc, L"到点且有改动才写回工程，不用每次按 Ctrl+S",
       RECT{ b.left + S(24), y + S(18), b.right, y + S(36) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    y += S(48);
    settings_numrow(dc, b, y, L"自动保存间隔", g_draftSaveSec, 2, L" 秒",
                    L"例：30 就是半分钟一次", mp);
    y += S(44);

    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"代码自动备份", g_draftAutoBackup, mp, 301);
    tx(dc, L"到点在备份目录留一份带时间戳的副本，改坏了能翻回去",
       RECT{ b.left + S(24), y + S(18), b.right, y + S(36) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    y += S(48);
    settings_numrow(dc, b, y, L"自动备份间隔", g_draftBackupSec, 3, L" 秒",
                    L"和保存分开计时，互不影响", mp);
    y += S(38);
    settings_numrow(dc, b, y, L"最多保留备份份数", wnum(g_maxBackupCountDraft), 14, L" 份",
                    L"超过此数量的旧备份将自动删除", mp);
    y += S(38);

    // 运行/编译前自动保存与备份
    tx(dc, L"运行/编译前自动保存与备份", RECT{ b.left, y, b.right, y + S(20) },
       g_p.accent, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    y += S(22);
    int halfW = (b.right - b.left) / 2;
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"运行前保存", g_draftAutoSaveOnRun, mp, 320);
    settings_check(dc, RECT{ b.left + halfW, y, b.left + halfW + S(16), y + S(16) },
                   L"运行前备份", g_draftAutoBackupOnRun, mp, 321);
    y += S(24);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"编译前保存", g_draftAutoSaveOnCompile, mp, 322);
    settings_check(dc, RECT{ b.left + halfW, y, b.left + halfW + S(16), y + S(16) },
                   L"编译前备份", g_draftAutoBackupOnCompile, mp, 323);
    y += S(32);

    settings_button(dc, RECT{ b.left, y, b.left + S(112), y + S(28) },
                    L"打开备份目录", mp, false, 310);
    tx(dc, L"按项目名和时间戳生成多份备份，存放在程序目录的 backup 文件夹下",
       RECT{ b.left + S(124), y, b.right, y + S(28) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
}

// 设计器：参考线 / 网格与吸附 / 新建窗口
static void settings_designer(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"设计器", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"画布上的对齐辅助与网格",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);

    int y = b.top + S(44);
    // 分组标题
    auto group = [&](const wchar_t* name) {
        tx(dc, name, RECT{ b.left, y, b.right, y + S(20) },
           g_p.accent, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        y += S(20);
    };

    // ── 参考线 ──
    group(L"参考线");
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"显示组件布局辅助线", g_draftSnapLine, mp, 307);
    y += S(22);
    settings_numrow(dc, b, y, L"  线宽", g_draftSnapLineW, 12, L"px",
                    L"1080P/2K 默认 1.0，4K 默认 1.5", mp);
    y += S(32);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"显示十字准心线", g_draftGuide, mp, 302);
    y += S(22);
    settings_numrow(dc, b, y, L"  线宽", g_draftGuideW, 13, L"px",
                    L"跟随主题颜色的十字线粗细", mp);
    y += S(32);
    // 线宽预览：按草稿值画一小段十字（颜色取当前皮肤），改数字/点应用立刻看得见粗细。
    // 画布上那条准心线只在鼠标位于画布内时才画，面板开着时看不到，所以这里补一块样张。
    {
        float dw = (float)_wtof(g_draftGuideW.c_str());
        if (dw < 1.0f) dw = 1.0f;
        int lw = (int)(dw * S(1) + 0.5f); if (lw < 1) lw = 1;
        RECT pv = RECT{ b.left, y, b.left + S(228), y + S(30) };
        fillR(dc, pv, 3, g_p.canvas);
        outlineR(dc, pv, 3, g_p.borderSoft);
        int cx = (pv.left + pv.right) / 2, cy = (pv.top + pv.bottom) / 2;
        fill(dc, RECT{ cx - lw / 2, pv.top + S(3), cx - lw / 2 + lw, pv.bottom - S(3) }, g_p.guideLine);
        fill(dc, RECT{ pv.left + S(3), cy - lw / 2, pv.right - S(3), cy - lw / 2 + lw }, g_p.guideLine);
        tx(dc, L"线宽预览", RECT{ pv.right + S(8), y, b.right, y + S(30) },
           g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        y += S(36);
    }

    // ── 网格与吸附 ──
    group(L"网格与吸附");
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"显示网点", g_draftGrid, mp, 303);
    y += S(22);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"对齐到网点", g_draftSnap, mp, 304);
    y += S(22);
    settings_numrow(dc, b, y, L"网点间隔-宽", g_draftGridSize, 4, L" DIP",
                    L"横向点位间距，易语言默认 8", mp);
    y += S(32);
    settings_numrow(dc, b, y, L"网点间隔-高", g_draftGridSizeY, 9, L" DIP",
                    L"纵向点位间距，可与宽不同", mp);
    y += S(32);

    // ── 新建窗口 ──
    group(L"新建窗口");
    settings_numrow(dc, b, y, L"宽度", g_draftNewW, 10, L" DIP",
                    L"「文件→新建」时用的默认宽，易语言默认 880", mp);
    y += S(32);
    settings_numrow(dc, b, y, L"高度", g_draftNewH, 11, L" DIP",
                    L"「文件→新建」时用的默认高，易语言默认 250", mp);
}

// 设置里挑背景图 / 背景文件夹
static void settings_pick_image()
{
    wchar_t buf[MAX_PATH] = { 0 };
    OPENFILENAMEW ofn;
    ZeroMemory(&ofn, sizeof(ofn));
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = g_hwnd;
    ofn.lpstrFilter = L"图片文件\0*.png;*.jpg;*.jpeg;*.bmp;*.gif\0所有文件\0*.*\0";
    ofn.lpstrFile = buf;
    ofn.nMaxFile = MAX_PATH;
    ofn.Flags = OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST;
    if (GetOpenFileNameW(&ofn)) g_draftBgImage = buf;
}

static void settings_pick_folder()
{
    BROWSEINFOW bi;
    ZeroMemory(&bi, sizeof(bi));
    bi.hwndOwner = g_hwnd;
    bi.lpszTitle = L"选择背景图片文件夹（轮播）";
    bi.ulFlags = BIF_RETURNONLYFSDIRS | BIF_NEWDIALOGSTYLE;
    LPITEMIDLIST pidl = SHBrowseForFolderW(&bi);
    if (!pidl) return;
    wchar_t buf[MAX_PATH] = { 0 };
    if (SHGetPathFromIDListW(pidl, buf)) g_draftBgFolder = buf;
    CoTaskMemFree(pidl);
}

