static void settings_bg(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"背景图片", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"壁纸盖在主界面上面一层；文件夹和图片同填时优先轮播文件夹",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    int y = b.top + S(52);
    // 单张图片
    tx(dc, L"图片文件", RECT{ b.left, y, b.left + S(96), y + S(28) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    RECT ib = RECT{ b.left + S(100), y, b.right - S(104), y + S(28) };
    fillR(dc, ib, 4, g_p.input);
    outlineR(dc, ib, 4, g_p.borderSoft);
    tx(dc, g_draftBgImage.empty() ? L"（未设置）" : g_draftBgImage,
       RECT{ ib.left + S(8), ib.top, ib.right - S(8), ib.bottom },
       g_draftBgImage.empty() ? g_p.textFaint : g_p.textDim, g_f11,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_PATH_ELLIPSIS);
    settings_button(dc, RECT{ b.right - S(96), y, b.right, y + S(28) },
                    L"选择图片…", mp, false, 400);
    y += S(38);

    // 轮播文件夹
    tx(dc, L"文件夹", RECT{ b.left, y, b.left + S(96), y + S(28) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    RECT fb = RECT{ b.left + S(100), y, b.right - S(104), y + S(28) };
    fillR(dc, fb, 4, g_p.input);
    outlineR(dc, fb, 4, g_p.borderSoft);
    tx(dc, g_draftBgFolder.empty() ? L"（未设置）" : g_draftBgFolder,
       RECT{ fb.left + S(8), fb.top, fb.right - S(8), fb.bottom },
       g_draftBgFolder.empty() ? g_p.textFaint : g_p.textDim, g_f11,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_PATH_ELLIPSIS);
    settings_button(dc, RECT{ b.right - S(96), y, b.right, y + S(28) },
                    L"选择文件夹…", mp, false, 401);
    y += S(38);

    settings_button(dc, RECT{ b.left, y, b.left + S(96), y + S(26) },
                    L"清除背景", mp, false, 402);
    // 填充方式三选：拉伸 / 等比铺满（裁边） / 等比完整（居中）
    tx(dc, L"填充方式", RECT{ b.left + S(108), y, b.left + S(172), y + S(26) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    {
        static const wchar_t* fn[3] = { L"拉伸", L"等比铺满", L"等比完整" };
        int fx = b.left + S(176);
        for (int i = 0; i < 3; ++i) {
            int wgt = (i == 0) ? S(52) : S(76);
            settings_button(dc, RECT{ fx, y, fx + wgt, y + S(26) }, fn[i], mp,
                            g_draftBgFill == i, 410 + i);
            fx += wgt + S(6);
        }
    }
    y += S(42);

    settings_numrow(dc, b, y, L"轮播间隔", g_draftBgInt, 1, L" 秒",
                    L"每张图停留的时间，最短 5 秒", mp);
    y += S(48);

    // 不透明度滑块：100 格，拖动实时生效
    tx(dc, L"不透明度", RECT{ b.left, y, b.left + S(110), y + S(22) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    int pct = std::max(0, std::min(100, g_draftBgAlpha));
    tx(dc, wnum(pct) + L"%", RECT{ b.left + S(116), y, b.left + S(180), y + S(22) },
       g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"拖动实时生效，越低越透、文字越清楚",
       RECT{ b.left + S(186), y, b.right, y + S(22) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    RECT track = RECT{ b.left, y + S(28), b.left + S(320), y + S(38) };
    g_bgSliderTrack = track;
    fillR(dc, track, 4, g_p.input);
    outlineR(dc, track, 4, g_p.borderSoft);
    if (pct > 0) {
        RECT done = RECT{ track.left, track.top,
                          track.left + (int)((track.right - track.left) * pct / 100.0f + 0.5f),
                          track.bottom };
        fillR(dc, done, 4, g_p.accent);
    }
    int thx = track.left + (int)((track.right - track.left - S(12)) * pct / 100.0f + 0.5f);
    RECT thumb = RECT{ thx, track.top - S(5), thx + S(12), track.bottom + S(5) };
    bool thot = in(thumb, mp.x, mp.y) || in(track, mp.x, mp.y);
    fillR(dc, thumb, 6, thot ? g_p.accent : g_p.elevated);
    outlineR(dc, thumb, 6, thot ? g_p.accent : g_p.border);
}

// 提示音：错误 / 警告 / 正确三种，各选 sounds 文件夹里的一个 wav
static const wchar_t* SND_LABELS[3] = { L"错误提示音", L"警告提示音", L"正确提示音" };
static const wchar_t* SND_DESCS[3] = {
    L"校验失败、名称非法这类错误提示时播放",
    L"没选中文字、漏填内容这类警告提示时播放",
    L"保存成功、项目创建完成这类结果提示时播放"
};
static void settings_sound(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"提示音", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"三种提示各选一个音；wav 文件放进程序目录的 sounds 文件夹就能在下拉里选到",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    int y = b.top + S(52);
    for (int k = 0; k < 3; ++k) {
        tx(dc, SND_LABELS[k], RECT{ b.left, y, b.left + S(140), y + S(24) },
           g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        tx(dc, SND_DESCS[k], RECT{ b.left, y + S(24), b.left + S(140), y + S(44) },
           g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

        // 下拉：列出 sounds 文件夹里的 wav
        RECT dd = RECT{ b.left + S(150), y, b.left + S(310), y + S(26) };
        bool hot = in(dd, mp.x, mp.y) || g_sndDD == k;
        fillR(dc, dd, 4, g_sndDD == k ? g_p.elevated : (hot ? g_p.hover : g_p.input));
        outlineR(dc, dd, 4, g_sndDD == k ? g_p.accent : g_p.borderSoft);
        tx(dc, g_sndDraft[k],
           RECT{ dd.left + S(8), dd.top, dd.right - S(18), dd.bottom },
           g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        tx(dc, L"▾", RECT{ dd.right - S(18), dd.top, dd.right - S(2), dd.bottom },
           g_p.textDim, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        g_settingsHits.push_back(std::make_pair(dd, 430 + k));
        g_sndBtn[k] = dd;

        // 试听：直接播草稿里选的这份
        settings_button(dc, RECT{ dd.right + S(8), y, dd.right + S(68), y + S(26) },
                        L"试听", mp, false, 440 + k);
        tx(dc, std::wstring(L"声音来自 sounds\\") + g_sndDraft[k],
           RECT{ dd.right + S(80), y, b.right, y + S(26) },
           g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

        if (k < 2) hline(dc, b.left, b.right, y + S(40), g_p.borderSoft);
        y += S(54);
    }
}

// 设置 → 日志：时间开关 + 四级颜色（点色块直接改，草稿，确定后写 ini）
static void settings_log(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"日志输出", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"一个出口管两个页面：提示页放环境自检和命令说明，输出页只放调试过程",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    int y = b.top + S(52);

    // ① 是否输出时间（勾选框，只管输出页）
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"输出时间（只加在输出页，提示页永远不加）",
                   g_logTimeDraft, mp, 520);

    // ② 时间格式：输入框 + 下拉（三组预设）
    y += S(30);
    tx(dc, L"时间格式", RECT{ b.left, y, b.left + S(76), y + S(26) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    RECT box = RECT{ b.left + S(84), y, b.left + S(84) + S(240), y + S(26) };
    bool act = (g_setEditFocus == 5);
    fillR(dc, box, 3, act ? g_p.elevated : (in(box, mp.x, mp.y) ? g_p.hover : g_p.input));
    outlineR(dc, box, 3, act ? g_p.accent : g_p.borderSoft);
    tx(dc, g_logFmtDraft.empty() ? L"（点右边选，或在这里直接输入）" : g_logFmtDraft,
       RECT{ box.left + S(8), box.top, box.right - S(8), box.bottom },
       g_logFmtDraft.empty() ? g_p.textFaint : g_p.text, g_f12,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    if (act) {
        int cw = tw(dc, g_logFmtDraft, g_f12);
        int cx = box.left + S(8) + cw + 1;
        if (cx < box.right - S(6)) vline(dc, cx, box.top + S(4), box.bottom - S(4), g_p.accent);
    }
    g_settingsHits.push_back(std::make_pair(box, 526));   // 526 → 编辑焦点 5（见 settings_action）

    RECT dd = RECT{ box.right + S(6), y, box.right + S(66), y + S(26) };
    bool dhot = in(dd, mp.x, mp.y) || g_tsDD >= 0;
    fillR(dc, dd, 3, g_tsDD >= 0 ? g_p.elevated : (dhot ? g_p.hover : g_p.input));
    outlineR(dc, dd, 3, g_tsDD >= 0 ? g_p.accent : g_p.borderSoft);
    tx(dc, L"预设 ▾", RECT{ dd.left, dd.top, dd.right, dd.bottom },
       g_p.text, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    g_tsBtn = dd;
    g_settingsHits.push_back(std::make_pair(dd, 525));

    // ③ 详细说明：怎么拼格式串
    y += S(34);
    const wchar_t* help[7] = {
        L"怎么填：把下面这些占位符按需要拼起来，其它字符原样输出（冒号、横杠、空格都可）。",
        L"  yyyy 四位年    yy 两位年        MM 两位月    M 月",
        L"  dd 两位日      d 日             HH 两位时    H 时（24 小时制）",
        L"  mm 两位分      m 分             ss 两位秒    s 秒",
        L"  fff 三位毫秒   ff 两位毫秒      f 一位毫秒（毫秒最小到 1 毫秒）",
        L"例：yyyy-MM-dd HH:mm:ss → 2026-11-08 20:36:28",
        L"例：HH:mm:ss.fff → 20:36:28.517      例：MM-dd HH:m:s → 11-08 20:36:28"
    };
    for (int k = 0; k < 7; ++k) {
        tx(dc, help[k], RECT{ b.left, y + k * S(18), b.right, y + k * S(18) + S(18) },
           k == 0 ? g_p.textDim : g_p.textFaint, g_f11,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    }
    y += S(18) * 7 + S(6);

    // ④ 四级颜色
    const wchar_t* lvName[4] = { L"正常", L"成功", L"警告", L"错误" };
    for (int lv = 0; lv < 4; ++lv) {
        tx(dc, lvName[lv], RECT{ b.left, y, b.left + S(56), y + S(24) },
           g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        for (int k = 0; k < 8; ++k) {
            RECT sw = RECT{ b.left + S(64) + k * S(28), y + S(2),
                            b.left + S(64) + k * S(28) + S(22), y + S(24) };
            fillR(dc, sw, 4, LOG_SWATCH[k]);
            bool on = (g_logColDraft[lv] == LOG_SWATCH[k]);
            outlineR(dc, sw, 4, on ? g_p.accent : (in(sw, mp.x, mp.y) ? g_p.text : g_p.borderSoft));
            if (on) outlineR(dc, RECT{ sw.left - S(2), sw.top - S(2), sw.right + S(2), sw.bottom + S(2) },
                             6, g_p.accent);
            g_settingsHits.push_back(std::make_pair(sw, 530 + lv * 10 + k));
        }
        fillR(dc, RECT{ b.left + S(64) + 8 * S(28) + S(8), y + S(2),
                        b.left + S(64) + 8 * S(28) + S(88), y + S(24) }, 4, g_logColDraft[lv]);
        y += S(32);
    }

    // ⑤ 预设下拉弹层（画在本页最上层）
    if (g_tsDD >= 0) {
        int rowH = S(24), ph = S(6) + rowH * TS_PRESET_N;
        RECT pop = RECT{ g_tsBtn.left, g_tsBtn.bottom + S(2),
                         g_tsBtn.left + S(200), g_tsBtn.bottom + S(2) + ph };
        fillR(dc, pop, 4, g_p.elevated);
        outlineR(dc, pop, 4, g_p.accent);
        for (int k = 0; k < TS_PRESET_N; ++k) {
            RECT r = RECT{ pop.left + S(4), pop.top + S(3) + k * rowH, pop.right - S(4), pop.top + S(3) + (k + 1) * rowH };
            bool hot = in(r, mp.x, mp.y);
            if (hot) fillR(dc, r, 3, g_p.hover);
            tx(dc, TS_PRESETS[k], RECT{ r.left + S(6), r.top, r.right, r.bottom },
               hot ? g_p.text : g_p.textDim, g_f11,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE);
            g_settingsHits.insert(g_settingsHits.begin(), std::make_pair(r, 540 + k));
        }
    }
}

// 设置 → 提示表格：输出方式（文本/表格）、表格线颜色与粗细、六类文字颜色
// 按关键字重建表格字体的候选列表（子串匹配，中英文都认）
static void tip_face_refilter()
{
    g_tipFaceList.clear();
    std::wstring q = g_tipFaceAll ? std::wstring() : low_ascii(g_tipFaceDraft);
    for (int i = 0; i < font_face_count(); ++i) {
        if (q.empty() || low_ascii(g_fontFaces[i]).find(q) != std::wstring::npos)
            g_tipFaceList.push_back(i);
    }
    if (g_tipFaceScroll < 0) g_tipFaceScroll = 0;
}

static void settings_tiptab(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"提示页输出方式", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"点支持库、点命令时提示页怎么画：纯文本，还是带表格线的表格",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    int y = b.top + S(52);
    settings_button(dc, RECT{ b.left, y, b.left + S(88), y + S(28) },
                    L"文本输出", mp, g_tipModeDraft == 0, 527);
    settings_button(dc, RECT{ b.left + S(96), y, b.left + S(184), y + S(28) },
                    L"表格输出", mp, g_tipModeDraft == 1, 528);
    tx(dc, g_tipModeDraft == 1 ? L"当前：表格（宽度自适应面板，可拖宽拖窄）"
                               : L"当前：纯文本（每行一条，不画表格）",
       RECT{ b.left + S(196), y, b.right, y + S(28) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);

    // 表格线
    y += S(44);
    tx(dc, L"表格线颜色", RECT{ b.left, y, b.left + S(96), y + S(24) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    for (int k = 0; k < 8; ++k) {
        RECT sw = RECT{ b.left + S(104) + k * S(28), y + S(2),
                        b.left + S(104) + k * S(28) + S(22), y + S(24) };
        fillR(dc, sw, 4, LOG_SWATCH[k]);
        bool on = (g_gridColDraft == LOG_SWATCH[k]);
        outlineR(dc, sw, 4, on ? g_p.accent : (in(sw, mp.x, mp.y) ? g_p.text : g_p.borderSoft));
        if (on) outlineR(dc, RECT{ sw.left - S(2), sw.top - S(2), sw.right + S(2), sw.bottom + S(2) },
                         6, g_p.accent);
        g_settingsHits.push_back(std::make_pair(sw, 560 + k));
    }
    fillR(dc, RECT{ b.left + S(104) + 8 * S(28) + S(8), y + S(2),
                    b.left + S(104) + 8 * S(28) + S(88), y + S(24) }, 4, g_gridColDraft);

    y += S(34);
    tx(dc, L"表格线粗细", RECT{ b.left, y, b.left + S(96), y + S(24) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    const wchar_t* wname[3] = { L"1 像素", L"2 像素", L"3 像素" };
    for (int k = 0; k < 3; ++k) {
        settings_button(dc, RECT{ b.left + S(104) + k * S(78), y, b.left + S(104) + k * S(78) + S(70), y + S(26) },
                        wname[k], mp, g_gridWDraft == k + 1, 570 + k);
    }

    // 表格线样式：实线 / 虚线 / 点线 / 点划线，每项里直接画一条预览线
    y += S(30);
    tx(dc, L"表格线样式", RECT{ b.left, y, b.left + S(96), y + S(24) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    for (int k = 0; k < 4; ++k) {
        RECT bb = RECT{ b.left + S(104) + k * S(96), y, b.left + S(104) + k * S(96) + S(88), y + S(26) };
        bool on = (g_gridStyleDraft == k);
        bool hov = in(bb, mp.x, mp.y);
        fillR(dc, bb, 3, on ? g_p.elevated : (hov ? g_p.hover : g_p.input));
        outlineR(dc, bb, 3, on ? g_p.accent : g_p.borderSoft);
        // 预览线
        int lw = g_gridWDraft < 1 ? 1 : g_gridWDraft;
        LOGBRUSH pb; pb.lbStyle = BS_SOLID; pb.lbColor = g_gridColDraft; pb.lbHatch = 0;
        DWORD pst = (k == 1) ? PS_DASH : (k == 2) ? PS_DOT : (k == 3) ? PS_DASHDOT : PS_SOLID;
        HPEN pv = (lw == 1) ? CreatePen(pst, 1, g_gridColDraft)
                            : ExtCreatePen(PS_GEOMETRIC | pst | PS_ENDCAP_FLAT | PS_JOIN_MITER,
                                           lw, &pb, 0, NULL);
        HGDIOBJ po = SelectObject(dc, pv);
        int ty2 = bb.top + S(11);
        MoveToEx(dc, bb.left + S(10), ty2, NULL);
        LineTo(dc, bb.left + S(58), ty2);
        SelectObject(dc, po);
        DeleteObject(pv);
        tx(dc, GRID_STYLE_NAME[k], RECT{ bb.left + S(60), bb.top, bb.right - S(4), bb.bottom },
           on ? g_p.text : g_p.textDim, g_f11,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        g_settingsHits.push_back(std::make_pair(bb, 573 + k));
    }

    // ── 表格字体：字体族 / 字号 / 加粗（整张表格跟着变）──
    y += S(32);
    tx(dc, L"表格字体", RECT{ b.left, y, b.left + S(96), y + S(24) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);

    // 字体族输入框
    RECT fbox = RECT{ b.left + S(104), y, b.left + S(316), y + S(26) };
    bool fact = (g_setEditFocus == 8);
    bool fhot = in(fbox, mp.x, mp.y);
    fillR(dc, fbox, 3, fact ? g_p.elevated : (fhot ? g_p.hover : g_p.input));
    outlineR(dc, fbox, 3, fact ? g_p.accent : g_p.borderSoft);
    tx(dc, g_tipFaceDraft.empty() ? L"字体名，例如 Microsoft YaHei UI" : g_tipFaceDraft,
       RECT{ fbox.left + S(8), fbox.top, fbox.right - S(8), fbox.bottom },
       g_tipFaceDraft.empty() ? g_p.textFaint : g_p.text, g_f12,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    if (fact) {
        int cw = tw(dc, g_tipFaceDraft, g_f12);
        int cx = fbox.left + S(8) + cw + 1;
        if (cx < fbox.right - S(6)) vline(dc, cx, fbox.top + S(4), fbox.bottom - S(4), g_p.accent);
    }
    g_settingsHits.push_back(std::make_pair(fbox, 580));
    g_tipFaceBox = fbox;
    if (g_setEdit && g_setEditId == 580)
        MoveWindow(g_setEdit, fbox.left, fbox.top, fbox.right - fbox.left, fbox.bottom - fbox.top, TRUE);
    if (g_setEdit && g_setEditId >= 1 && g_setEditId <= 13 && g_numBoxes.count(g_setEditId)) {
        RECT nb = g_numBoxes[g_setEditId];
        MoveWindow(g_setEdit, nb.left, nb.top, nb.right - nb.left, nb.bottom - nb.top, TRUE);
    }

    // 字号输入框
    RECT sbox = RECT{ fbox.right + S(16), y, fbox.right + S(64), y + S(26) };
    bool sact = (g_setEditFocus == 7);
    bool shot2 = in(sbox, mp.x, mp.y);
    fillR(dc, sbox, 3, sact ? g_p.elevated : (shot2 ? g_p.hover : g_p.input));
    outlineR(dc, sbox, 3, sact ? g_p.accent : g_p.borderSoft);
    tx(dc, g_tipSizeStrDraft.empty() ? L"12" : g_tipSizeStrDraft,
       RECT{ sbox.left + S(8), sbox.top, sbox.right - S(8), sbox.bottom },
       g_p.text, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    g_settingsHits.push_back(std::make_pair(sbox, 579));
    g_tipSizeBox = sbox;
    if (g_setEdit && g_setEditId == 579)
        MoveWindow(g_setEdit, sbox.left, sbox.top, sbox.right - sbox.left, sbox.bottom - sbox.top, TRUE);
    tx(dc, L"号", RECT{ sbox.right + S(6), y, sbox.right + S(28), y + S(26) },
       g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);

    // 加粗勾选
    RECT cbx = RECT{ sbox.right + S(40), y + S(3), sbox.right + S(60), y + S(23) };
    fillR(dc, cbx, 3, g_tipBoldDraft ? g_p.accent : g_p.input);
    outlineR(dc, cbx, 3, g_tipBoldDraft ? g_p.accent : g_p.borderSoft);
    if (g_tipBoldDraft) {
        HPEN cp = CreatePen(PS_SOLID, 2, RGB(0xFF, 0xFF, 0xFF));
        HGDIOBJ cop = SelectObject(dc, cp);
        MoveToEx(dc, cbx.left + S(4), cbx.top + S(9), NULL);
        LineTo(dc, cbx.left + S(8), cbx.bottom - S(5));
        LineTo(dc, cbx.right - S(4), cbx.top + S(5));
        SelectObject(dc, cop);
        DeleteObject(cp);
    }
    tx(dc, L"加粗", RECT{ cbx.right + S(8), y, cbx.right + S(64), y + S(26) },
       in(cbx, mp.x, mp.y) ? g_p.text : g_p.textDim, g_f12,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    g_settingsHits.push_back(std::make_pair(RECT{ cbx.left, y, cbx.right + S(60), y + S(26) }, 578));

    // 实时预览：同一行右侧，按草稿字体画（行高跟着字号变，看不见 S 缩放的就不用管）
    {
        int psz = _wtoi(g_tipSizeStrDraft.c_str());
        if (psz < 8)  psz = 8;
        if (psz > 32) psz = 32;
        const wchar_t* pf = g_tipFaceDraft.empty() ? L"Microsoft YaHei UI" : g_tipFaceDraft.c_str();
        HFONT pv = mkfont((float)psz, g_tipBoldDraft, pf);
        HFONT po = (HFONT)SelectObject(dc, pv);
        int px = cbx.right + S(76);
        if (px < b.right - S(80))
            tx(dc, L"预览：载入 逻辑型 载入指定的窗口，成功返回真",
               RECT{ px, y - S(4), b.right, y + S(30) },
               g_p.textDim, pv, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        SelectObject(dc, po);
        DeleteObject(pv);
    }

    // 命令列表宽度（0＝自动；多条命令并排时才用，编辑器阶段接上）
    y += S(36);
    tx(dc, L"命令列表宽度", RECT{ b.left, y, b.left + S(96), y + S(24) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    settings_button(dc, RECT{ b.left + S(104), y, b.left + S(184), y + S(26) },
                    L"自动", mp, g_cmdListWDraft == 0, 690);
    RECT wbox = RECT{ b.left + S(196), y, b.left + S(268), y + S(26) };
    bool wact = (g_setEditFocus == 6);
    fillR(dc, wbox, 3, wact ? g_p.elevated : (in(wbox, mp.x, mp.y) ? g_p.hover : g_p.input));
    outlineR(dc, wbox, 3, wact ? g_p.accent : g_p.borderSoft);
    std::wstring wval = g_cmdListWStr.empty() ? L"" : g_cmdListWStr;
    tx(dc, wval.empty() ? L"像素" : wval, RECT{ wbox.left + S(8), wbox.top, wbox.right - S(8), wbox.bottom },
       wval.empty() ? g_p.textFaint : g_p.text, g_f12,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    g_settingsHits.push_back(std::make_pair(wbox, 691));
    tx(dc, g_cmdListWDraft == 0 ? L"自动＝按最长命令名的宽度" : L"固定像素宽",
       RECT{ wbox.right + S(8), y, b.right, y + S(26) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);

    // 六类文字颜色
    y += S(42);
    tx(dc, L"文字颜色", RECT{ b.left, y, b.right, y + S(22) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    y += S(24);
    for (int role = 1; role < TR_ROLE_N; ++role) {     // 0 正文不单列
        if (role == TR_VAR) continue;                  // 变量：命令表格里没有这个角色，不设
        tx(dc, TR_NAME[role], RECT{ b.left, y, b.left + S(64), y + S(22) },
           g_p.textDim, g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        for (int k = 0; k < 8; ++k) {
            RECT sw = RECT{ b.left + S(72) + k * S(26), y + S(2),
                            b.left + S(72) + k * S(26) + S(20), y + S(22) };
            fillR(dc, sw, 4, LOG_SWATCH[k]);
            bool on = (g_tipColDraft[role] == LOG_SWATCH[k]);
            outlineR(dc, sw, 4, on ? g_p.accent : (in(sw, mp.x, mp.y) ? g_p.text : g_p.borderSoft));
            if (on) outlineR(dc, RECT{ sw.left - S(2), sw.top - S(2), sw.right + S(2), sw.bottom + S(2) },
                             6, g_p.accent);
            g_settingsHits.push_back(std::make_pair(sw, 580 + role * 10 + k));
        }
        fillR(dc, RECT{ b.left + S(72) + 8 * S(26) + S(8), y + S(2),
                        b.left + S(72) + 8 * S(26) + S(84), y + S(22) }, 4, g_tipColDraft[role]);
        y += S(26);
    }

    // ── 表格字体：候选列表（读本机已装字体，输入关键字即时过滤）──
    g_tipFaceHits.clear();
    g_tipFacePopRect = RECT{ 0, 0, 0, 0 };
    bool faceListOpen = (g_setEditFocus == 8) || (g_setEdit && g_setEditId == 580);
    if (faceListOpen && g_tipFaceBox.right > g_tipFaceBox.left) {
        tip_face_refilter();
        int total = (int)g_tipFaceList.size();
        int rows  = g_tipFaceRows;
        int rowH  = S(24);
        int popW  = S(252);
        int popH  = S(6) + rowH * rows + S(6);
        RECT pop  = font_popup_place(g_tipFaceBox, popW, popH);
        g_tipFacePopRect = pop;
        font_popup_frame(dc, pop);
        int maxTop = std::max(0, total - rows);
        if (g_tipFaceScroll > maxTop) g_tipFaceScroll = maxTop;
        if (total == 0) {
            tx(dc, L"没找到这个字体", RECT{ pop.left + S(10), pop.top, pop.right - S(10), pop.top + rowH },
               g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        }
        int yy = pop.top + S(6);
        for (int r = 0; r < rows; ++r) {
            int idx = g_tipFaceScroll + r;
            if (idx >= total) break;
            int fi = g_tipFaceList[idx];
            RECT rr = RECT{ pop.left + S(4), yy, pop.right - S(4), yy + rowH };
            bool hot = in(rr, mp.x, mp.y);
            if (hot) fillR(dc, rr, 3, g_p.hover);
            bool cur = (!g_tipFaceDraft.empty() && g_fontFaces[fi] == g_tipFaceDraft);
            tx(dc, g_fontFaces[fi], RECT{ rr.left + S(8), rr.top, rr.right - S(8), rr.bottom },
               cur ? g_p.accent : g_p.text, cur ? g_f12b : g_f12,
               DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
            g_tipFaceHits.push_back(std::make_pair(rr, fi));
            yy += rowH;
        }
        tx(dc, wnum(total) + L" 个字体 · 滚轮翻", RECT{ pop.left + S(8), pop.bottom - S(18), pop.right - S(8), pop.bottom - S(2) },
           g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    }
}

// 设置 → 编译：两种模式（自动只认 IDE 安装目录 / 浏览自己指）
static void settings_compiler(HDC dc, RECT b, POINT mp)
{
    comp_load();   // 打开面板时同步一次真实设置，草稿不会停在旧值

    tx(dc, L"编译器", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"自动＝只在本程序安装目录里找（环境\\llvm\\bin），不会用系统里别的编译器",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    // 模式：两个分段按钮
    int y = b.top + S(54);
    tx(dc, L"方式", RECT{ b.left, y, b.left + S(76), y + S(28) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    const wchar_t* modes[2] = { L"自动", L"浏览指定" };
    for (int i = 0; i < 2; ++i) {
        RECT r = RECT{ b.left + S(84) + i * S(96), y, b.left + S(84) + (i + 1) * S(96) - S(6), y + S(28) };
        bool on = (g_compModeDraft == i);
        bool hot = in(r, mp.x, mp.y);
        fillR(dc, r, 4, on ? g_p.accentSubtle : (hot ? g_p.hover : g_p.input));
        outlineR(dc, r, 4, on ? g_p.accent : g_p.borderSoft);
        tx(dc, modes[i], RECT{ r.left, r.top, r.right, r.bottom },
           on ? g_p.text : g_p.textDim, g_f12, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        g_settingsHits.push_back(std::make_pair(r, 500 + i));
    }

    // 路径行：浏览模式可编辑（点「浏览…」选文件），自动模式灰掉
    y += S(40);
    bool autoMode = (g_compModeDraft == 0);
    tx(dc, L"编译器", RECT{ b.left, y, b.left + S(76), y + S(28) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    RECT box = RECT{ b.left + S(84), y, b.left + S(84) + S(300), y + S(28) };
    fillR(dc, box, 4, g_p.input);
    outlineR(dc, box, 4, g_p.borderSoft);
    std::wstring shown;
    if (autoMode) {
        std::wstring f = comp_auto_find();
        shown = f.empty() ? L"（安装目录下没找到编译器）" : f;
    } else {
        shown = g_compPathDraft.empty() ? L"（还没选）" : g_compPathDraft;
    }
    tx(dc, shown, RECT{ box.left + S(8), box.top, box.right - S(8), box.bottom },
       autoMode ? g_p.textDim : g_p.text, g_f11,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_PATH_ELLIPSIS | DT_NOPREFIX);
    settings_button(dc, RECT{ box.right + S(8), y, box.right + S(88), y + S(28) },
                    L"浏览…", mp, false, 502);

    // 实际生效的那个（自动/浏览都可能回落，直接告诉用户最终用哪个）
    y += S(36);
    std::wstring eff = comp_resolve();
    tx(dc, eff.empty() ? L"当前：没有可用编译器" : (L"当前使用：" + eff),
       RECT{ b.left, y, b.right, y + S(22) },
       eff.empty() ? g_p.textFaint : g_p.textDim, g_f11,
       DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_PATH_ELLIPSIS | DT_NOPREFIX);

    // 输出目录
    y += S(36);
    tx(dc, L"输出目录", RECT{ b.left, y, b.left + S(76), y + S(28) },
       g_p.text, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    RECT box2 = RECT{ b.left + S(84), y, b.left + S(84) + S(300), y + S(28) };
    fillR(dc, box2, 4, g_p.input);
    outlineR(dc, box2, 4, g_p.borderSoft);
    std::wstring shownDir = g_buildOutDirDraft.empty() ? L"(默认: 项目目录\\build)" : g_buildOutDirDraft;
    tx(dc, shownDir, RECT{ box2.left + S(8), box2.top, box2.right - S(8), box2.bottom },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_PATH_ELLIPSIS | DT_NOPREFIX);
    settings_button(dc, RECT{ box2.right + S(8), y, box2.right + S(88), y + S(28) },
                    L"浏览…", mp, false, 507);

    // ── 产物命名与版本号 ──
    y += S(44);
    tx(dc, L"产物命名与版本号", RECT{ b.left, y, b.right, y + S(20) },
       g_p.accent, g_f12b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    y += S(24);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"用项目名作为软件名", g_draftUseProjNameAsExe, mp, 508);
    tx(dc, L"开启后输出 <项目名>.exe，关闭则固定为 app.exe",
       RECT{ b.left + S(24), y + S(18), b.right, y + S(36) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
    y += S(48);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"版本号自动递增", g_draftAutoVersion, mp, 509);
    tx(dc, L"每次编译最后一段 +1，满 99 进位，存项目目录 version.txt",
       RECT{ b.left + S(24), y + S(18), b.right, y + S(36) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
}

// 声音下拉弹层：sounds 文件夹里的 wav 清单，点一个就选中
static void settings_snd_popup(HDC dc, POINT mp)
{
    g_sndHits.clear();
    g_sndRect = RECT{ 0, 0, 0, 0 };
    if (!g_settingsOpen || g_sndDD < 0 || g_sndDD > 2) return;

    const RECT& anchor = g_sndBtn[g_sndDD];
    int rowH = S(24);
    int rows = std::max(1, std::min((int)g_sndFiles.size(), 8));
    int w = S(200), ph = S(4) + rowH * rows + S(4);
    RECT pop = font_popup_place(anchor, w, ph);
    g_sndRect = pop;
    font_popup_frame(dc, pop);

    int y = pop.top + S(4);
    if (g_sndFiles.empty()) {
        tx(dc, L"sounds 文件夹里没有 wav 文件",
           RECT{ pop.left + S(8), y, pop.right - S(8), y + rowH },
           g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        return;
    }
    for (int i = 0; i < rows; ++i) {
        RECT r = RECT{ pop.left + S(4), y, pop.right - S(4), y + rowH };
        bool hot = in(r, mp.x, mp.y);
        bool cur = (g_sndDraft[g_sndDD] == g_sndFiles[i]);
        if (cur) fillR(dc, r, 3, g_p.accentSubtle);
        else if (hot) fillR(dc, r, 3, g_p.hover);
        tx(dc, g_sndFiles[i],
           RECT{ r.left + S(8), r.top, r.right - S(20), r.bottom },
           (cur || hot) ? g_p.text : g_p.textDim, g_f12,
           DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
        if (cur)
            tx(dc, L"✓", RECT{ r.right - S(20), r.top, r.right - S(2), r.bottom },
               g_p.accent, g_f11, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
        g_sndHits.push_back(std::make_pair(r, i));
        y += rowH;
    }
}

// 面板与布局
static void settings_panels(HDC dc, RECT b, POINT mp)
{
    tx(dc, L"面板与布局", RECT{ b.left, b.top, b.right, b.top + S(24) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    tx(dc, L"左侧程序/支持库/属性、右侧组件箱/AI 的宽度各自记住，互不影响",
       RECT{ b.left, b.top + S(24), b.right, b.top + S(44) },
       g_p.textDim, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);

    int y = b.top + S(56);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"显示工具条", g_draftToolbar, mp, 305);
    y += S(40);
    settings_check(dc, RECT{ b.left, y, b.left + S(16), y + S(16) },
                   L"显示状态栏", g_draftStatus, mp, 306);
    y += S(50);
    settings_button(dc, RECT{ b.left, y, b.left + S(128), y + S(28) },
                    L"重置面板宽度", mp, false, 311);
    tx(dc, L"左栏 " + wnum(g_leftWPage[0]) + L" / " + wnum(g_leftWPage[1]) + L" / " +
            wnum(g_leftWPage[2]) + L"    右栏 " + wnum(g_rightWPage[0]) + L" / " +
            wnum(g_rightWPage[1]) + L"    输出 " + wnum(g_a.bottomH),
       RECT{ b.left, y + S(34), b.right, y + S(56) },
       g_p.textFaint, g_f11, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS);
}

static void paint_settings(HDC dc)
{
    g_settingsHits.clear();
    g_settingsGrip = RECT{ 0, 0, 0, 0 };
    g_bgSliderTrack = RECT{ 0, 0, 0, 0 };
    g_settingsTitle = RECT{ 0, 0, 0, 0 };
    if (!g_settingsOpen) return;

    int availW = (int)((g_w - S(24)) / g_s), availH = (int)((g_h - S(24)) / g_s);
    int W = std::max(560, std::min(g_settingsW, availW));
    int H = std::max(400, std::min(g_settingsH, availH));
    // 记住了位置就按记忆的位置摆，没有就居中；再夹回屏幕内
    int px, py;
    if (g_settingsX >= 0) px = S(g_settingsX);
    else px = (g_w - S(W)) / 2;
    if (g_settingsY >= 0) py = S(g_settingsY);
    else py = (g_h - S(H)) / 2;
    px = std::max(S(4), std::min(px, g_w - S(8) - S(W)));
    py = std::max(S(4), std::min(py, g_h - S(8) - S(H)));
    g_settingsPx = (float)px;
    g_settingsPy = (float)py;
    RECT pop = R((float)px / g_s, (float)py / g_s, W, H);
    g_settingsPanel = pop;

    RECT sh = pop; OffsetRect(&sh, 0, S(4));
    fill(dc, sh, g_p.frame);
    fillR(dc, pop, 8, g_p.elevated);
    outlineR(dc, pop, 8, g_p.border);

    POINT mp; mouse_now(&mp);
    tx(dc, L"设置", RECT{ pop.left + S(16), pop.top + S(8),
                          pop.right - S(50), pop.top + S(42) },
       g_p.text, g_f13b, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    RECT closeBtn = RECT{ pop.right - S(40), pop.top + S(10),
                          pop.right - S(12), pop.top + S(38) };
    settings_button(dc, closeBtn, L"×", mp, false, 1);
    // 标题栏热区：按住空白处就能拖动窗口（× 已单独命中，不会误触）
    g_settingsTitle = RECT{ pop.left, pop.top, pop.right, pop.top + S(46) };
    g_settingsClose = closeBtn;
    hline(dc, pop.left + S(12), pop.right - S(12), pop.top + S(46), g_p.borderSoft);

    // 左侧分类导航：分类短，后面加设置也不用把面板拉长
    RECT nav = RECT{ pop.left + S(12), pop.top + S(56),
                     pop.left + S(140), pop.bottom - S(58) };
    const wchar_t* tabs[SETTINGS_TABS] = {
        L"字体", L"主题外观", L"编辑器", L"设计器", L"面板与布局", L"背景", L"提示音", L"编译", L"日志", L"提示表格", L"表格设置"
    };
    for (int i = 0; i < SETTINGS_TABS; ++i) {
        RECT r = RECT{ nav.left, nav.top + S(4) + i * S(36), nav.right,
                       nav.top + S(4) + (i + 1) * S(36) - S(2) };
        bool hot = in(r, mp.x, mp.y);
        if (g_settingsTab == i) fillR(dc, r, 4, g_p.accentSubtle);
        else if (hot) fillR(dc, r, 4, g_p.hover);
        if (g_settingsTab == i)
            fill(dc, RECT{ r.left, r.top + S(6), r.left + S(2), r.bottom - S(6) }, g_p.accent);
        tx(dc, tabs[i], RECT{ r.left + S(12), r.top, r.right - S(6), r.bottom },
           (g_settingsTab == i || hot) ? g_p.text : g_p.textDim,
           g_f12, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
        g_settingsHits.push_back(std::make_pair(r, 20 + i));
    }
    vline(dc, nav.right + S(7), nav.top, nav.bottom, g_p.borderSoft);

    RECT body = RECT{ nav.right + S(20), nav.top,
                      pop.right - S(16), pop.bottom - S(58) };
    if (g_settingsTab == 0)      settings_fonts(dc, body, mp);
    else if (g_settingsTab == 1) settings_theme(dc, body, mp);
    else if (g_settingsTab == 2) settings_editor(dc, body, mp);
    else if (g_settingsTab == 3) settings_designer(dc, body, mp);
    else if (g_settingsTab == 4) settings_panels(dc, body, mp);
    else if (g_settingsTab == 5) settings_bg(dc, body, mp);
    else if (g_settingsTab == 6) settings_sound(dc, body, mp);
    else if (g_settingsTab == 7) settings_compiler(dc, body, mp);
    else if (g_settingsTab == 9) settings_tiptab(dc, body, mp);
    else if (g_settingsTab == 10) settings_table(dc, body, mp);
    else                         settings_log(dc, body, mp);

    hline(dc, pop.left + S(12), pop.right - S(12), pop.bottom - S(50), g_p.borderSoft);
    settings_button(dc, RECT{ pop.left + S(16), pop.bottom - S(42),
                              pop.left + S(112), pop.bottom - S(14) },
                    L"恢复默认", mp, false, 7);
    const wchar_t* lbl[3] = { L"取消", L"应用", L"确定" };
    const int ids[3] = { 6, 4, 5 };
    for (int i = 0; i < 3; ++i) {
        int w = S(76), gap = S(8);
        int left = pop.right - S(16) - (3 - i) * (w + gap);
        settings_button(dc, RECT{ left, pop.bottom - S(42),
                                 left + w, pop.bottom - S(14) },
                        lbl[i], mp, i == 2, ids[i]);
    }

    // 右下角拖动改尺寸：三条斜线，热区比图形大一圈
    RECT grip = RECT{ pop.right - S(18), pop.bottom - S(18), pop.right - S(2), pop.bottom - S(2) };
    g_settingsGrip = grip;
    for (int k = 0; k < 3; ++k) {
        int off = S(4) + k * S(4);
        HPEN op = (HPEN)SelectObject(dc, pen(in(grip, mp.x, mp.y) ? g_p.accent : g_p.textFaint));
        MoveToEx(dc, grip.right - off, grip.bottom - S(2), NULL);
        LineTo(dc, grip.right - S(2), grip.bottom - off);
        SelectObject(dc, op);
    }

    settings_font_popups(dc, mp);   // 字体三弹层画在面板最上层
    settings_snd_popup(dc, mp);     // 声音下拉弹层（同一时间互斥）
}

