static int hit_handle(RECT r, int x, int y)
{
    int hs = S(6) / 2 + 4;
    int hx[8] = { r.left, RCX(r), r.right, r.left, r.right, r.left, RCX(r), r.right };
    int hy[8] = { r.top, r.top, r.top, RCY(r), RCY(r), r.bottom, r.bottom, r.bottom };
    for (int h = 0; h < 8; ++h) {
        if (abs(x - hx[h]) <= hs && abs(y - hy[h]) <= hs) return h;
    }
    return -1;
}

static int hit_control(int x, int y)
{
    for (int i = (int)g_a.form.ctl.size() - 1; i >= 0; --i) {
        const Ctl& c = g_a.form.ctl[i];
        if (!c.visible) continue;
        if (in(ctl_rect(c), x, y)) return i;
    }
    return -1;
}

static void close_menu()
{
    g_a.menuTop = -1;
    g_a.menuSub = -1;
    g_a.menuHot = -1;
    g_a.menuSubHot = -1;
}

// ── 菜单的悬停行为（P3：悬停展开） ────────────────────────────────
// 关着的时候：指针停在标题上满 MENU_HOVER_MS 才展开。留这一小段延时，
//   是因为标题栏同时也整条是拖动区，鼠标只是路过（去点最小化/关闭）时
//   不该弹出一个菜单。
// 已经展开的时候：横向滑到别的标题立刻换菜单，不用再点一下——这才是
//   用户说的「全部要点击才能展开」的反面。
static const UINT_PTR TIMER_MENU_HOVER = 1;
static const UINT     MENU_HOVER_MS    = 140;

// 指针落在第几个顶级菜单标题上，-1 不在任何标题上
static int menu_at(int x, int y)
{
    for (size_t i = 0; i < g_menuRects.size(); ++i)
        if (in(g_menuRects[i], x, y)) return (int)i;
    return -1;
}

// 展开某一项，并清掉上一项残留的高亮与弹出矩形
static void menu_open(int i)
{
    g_a.menuTop = i;
    g_a.menuSub = -1;
    g_a.menuHot = -1;
    g_a.menuSubHot = -1;
    g_a.popupRect = RECT{ 0, 0, 0, 0 };
    g_a.subRect = RECT{ 0, 0, 0, 0 };
}

static void menu_hover_reset()
{
    g_a.menuHoverTop = -1;
    g_a.menuHoverMute = -1;
    KillTimer(g_hwnd, TIMER_MENU_HOVER);
}

// ── 工具条悬停提示（Tooltip） ──────────────────────────────────────
// 整个界面都是自绘的，这里也自绘：单独弹一个系统 tooltip 窗口颜色会和
// 暗色主题打架，位置和 DPI 也得另算一遍。
static const UINT_PTR TIMER_TB_TIP = 2;
static const UINT     TB_TIP_MS    = 550;
static const UINT_PTR TIMER_AUTOSAVE = 3;   // 每 30 秒检查一次「到点没有」
static const UINT_PTR TIMER_TOAST    = 7;   // 气泡到点自动消失
static const UINT_PTR TIMER_WIZ_GLOW = 5;   // 启动向导发光字呼吸动画，50ms 一帧
// 悬停重绘节流的补帧定时器：指针停下时补最后一帧，防止高亮停在旧画面上
static const UINT_PTR TIMER_HOVER_LATE = 6;
static const UINT_PTR TIMER_TIPBAR = 9;    // 提示表滚动条 hover 加宽的过渡帧
static DWORD g_lastHoverPaint = 0;          // 上次悬停重绘的时刻（节流用）

static int tb_hit_at(int x, int y)
{
    for (size_t i = 0; i < g_tbHits.size(); ++i)
        if (in(g_tbHits[i].r, x, y)) return (int)i;
    return -1;
}

// 悬停目标：先工具条按钮，再独立提示表（组件箱模式钮 / 设计器箭头）
static int tip_token_at(int x, int y)
{
    int i = tb_hit_at(x, y);
    if (i >= 0) return i;
    for (size_t k = 0; k < g_tipHits.size(); ++k)
        if (in(g_tipHits[k].r, x, y)) return 10000 + (int)k;
    return -1;
}

// 提示计时器是否在跑。KillTimer 之后必须清掉，否则同一按钮上「提示被点掉后再也弹不出」。
static bool g_tipArmed = false;

static void tb_tip_hide()
{
    KillTimer(g_hwnd, TIMER_TB_TIP);
    g_tipArmed = false;
    g_a.tbTipOn = false;
    g_a.tbTipIdx = -1;
}

// 指针换了按钮（或离开工具条）：当前提示立刻收掉，并重新开始计时。
// 同一按钮上也要判「计时器还在不在」：点一下按钮会把提示收掉，但指针仍停在原按钮里，
// 少了这一步就再也弹不出来 —— 用户要的「静止的时候也要有提示」就是这种情况。
static void tb_tip_track(int x, int y)
{
    int idx = tip_token_at(x, y);
    if (idx == g_a.tbHotIdx && (idx < 0 || g_a.tbTipOn || g_tipArmed)) return;
    if (idx != g_a.tbHotIdx) tb_tip_hide();
    g_a.tbHotIdx = idx;
    if (idx >= 0 && !g_a.tbTipOn) {
        SetTimer(g_hwnd, TIMER_TB_TIP, TB_TIP_MS, NULL);
        g_tipArmed = true;
    }
}

